    from (select coalesce(public.config_jsonb('startups', '{training,costCentsByTier}'), '[]'::jsonb) as c,
                 coalesce(public.config_jsonb('startups', '{training,wageRaiseBpsByTier}'), '[]'::jsonb) as r) x;
