-- ===== idempotent copy of migrations/20261124000200_m4c_friends.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4c · 0200 · Friends (ADR-084)
-- =============================================================================
-- RPCs on the existing table public.friendships (one row per unordered pair):
--   get_friends()                                     -> FRIENDS
--   send_friend_request(request_id, nickname)         -> FRIENDS (a counter request accepts at once)
--   respond_friend_request(request_id, nickname, accept) -> FRIENDS (decline deletes the request)
--   remove_friend(request_id, nickname)               -> FRIENDS (friendship or own open request)
-- FRIENDS = {friends: [{nickname, level, since}], incoming: [{nickname, level, at}], outgoing: [{nickname, level, at}]}
-- Errors: player_not_found (unknown nickname), invalid_argument (self, no open request, bad input), rate_limited.
-- In-app notifications: friend_request (to the addressee), friend_accepted (to the requester).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Notification type for an accepted request
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('friend_accepted', 'social', 'Freundschaft angenommen', 'Jemand hat deine Freundschaftsanfrage angenommen.',
        'notif_friend', true, false, false, 275)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- FRIENDS from the point of view of p_player (deactivated players are left out)
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at)) order by lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;
comment on function public.friends_json(uuid) is
  'FRIENDS of a player (ADR-084): friends by nickname, incoming and outgoing open requests newest first.';

-- The other player of a friends RPC: active, found by nickname (case-insensitive, as get_player_card)
create or replace function public.friend_target(p_player uuid, p_nickname text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_nickname is null or char_length(btrim(p_nickname)) = 0 or char_length(p_nickname) > 64 then
    perform public.api_error('invalid_argument');
  end if;
  select x.id into v_id from public.profiles x where lower(x.nickname) = lower(btrim(p_nickname)) and not x.is_deactivated;
  if v_id is null then
    perform public.api_error('player_not_found');
  end if;
  if v_id = p_player then
    perform public.api_error('invalid_argument');
  end if;
  return v_id;
end;
$$;

-- In-app notification, unless the player switched the type off (missing preference: the type's default)
create or replace function public.friend_notify(p_player uuid, p_type text, p_title text, p_from_nickname text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.notification_types t where t.key = p_type) then
    return;
  end if;
  if not coalesce((select np.in_app_enabled from public.notification_preferences np
                    where np.player_id = p_player and np.type_key = p_type),
                  (select t.default_in_app from public.notification_types t where t.key = p_type), true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, p_type, p_title, p_from_nickname, jsonb_build_object('nickname', p_from_nickname),
          '/players/' || p_from_nickname, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. RPCs
-- ---------------------------------------------------------------------------
create or replace function public.get_friends()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.friends_json(public.require_player());
end;
$$;
comment on function public.get_friends() is 'RPC: FRIENDS of the caller (ADR-084).';

-- A request; if the other player already asked me, this accepts it. Friends or an open own request: nothing happens.
-- A declined row may be requested again.
create or replace function public.send_friend_request(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  v_nick   text;
  f        public.friendships;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'send_friend_request');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  -- both players in a fixed order: one pair, one writer at a time
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  select p.nickname into v_me from public.profiles p where p.id = v_player;
  select p.nickname into v_nick from public.profiles p where p.id = v_other;
  select * into f from public.friendships x
   where least(x.requester_id, x.addressee_id) = least(v_player, v_other)
     and greatest(x.requester_id, x.addressee_id) = greatest(v_player, v_other);
  if f.id is null then
    insert into public.friendships (requester_id, addressee_id, status, request_id)
    values (v_player, v_other, 'pending', p_request_id);
    perform public.friend_notify(v_other, 'friend_request', v_me || ' möchte mit dir befreundet sein.', v_me,
                                 'friend_request:' || p_request_id::text);
  elsif f.status = 'pending' and f.requester_id = v_other then
    -- counter request: friends at once
    update public.friendships set status = 'accepted', responded_at = now(), updated_at = now() where id = f.id;
    perform public.friend_notify(v_other, 'friend_accepted', v_me || ' hat deine Freundschaftsanfrage angenommen.', v_me,
                                 'friend_accepted:' || p_request_id::text);
  elsif f.status = 'declined' then
    update public.friendships
       set requester_id = v_player, addressee_id = v_other, status = 'pending', request_id = p_request_id,
           responded_at = null, created_at = now(), updated_at = now()
     where id = f.id;
    perform public.friend_notify(v_other, 'friend_request', v_me || ' möchte mit dir befreundet sein.', v_me,
                                 'friend_request:' || p_request_id::text);
  end if;
  -- accepted, own open request or blocked: nothing to do
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.send_friend_request(uuid, text) is
  'RPC: friend request to a player by nickname (ADR-084); a counter request accepts. Errors player_not_found, invalid_argument.';

-- Only the addressee of an open request; declining deletes it
create or replace function public.respond_friend_request(p_request_id uuid, p_nickname text, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  f        public.friendships;
begin
  v_player := public.require_player();
  if p_request_id is null or p_accept is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'respond_friend_request');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  select * into f from public.friendships x
   where x.requester_id = v_other and x.addressee_id = v_player and x.status = 'pending';
  if f.id is null then
    perform public.api_error('invalid_argument');
  end if;
  if p_accept then
    update public.friendships set status = 'accepted', responded_at = now(), updated_at = now() where id = f.id;
    select p.nickname into v_me from public.profiles p where p.id = v_player;
    perform public.friend_notify(v_other, 'friend_accepted', v_me || ' hat deine Freundschaftsanfrage angenommen.', v_me,
                                 'friend_accepted:' || p_request_id::text);
  else
    delete from public.friendships where id = f.id;
  end if;
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.respond_friend_request(uuid, text, boolean) is
  'RPC: accept or decline (deletes) an open friend request from a player (ADR-084). Errors player_not_found, invalid_argument.';

-- Ends a friendship or withdraws the own open request; anything else: nothing happens
create or replace function public.remove_friend(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'remove_friend');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  perform 1 from public.profiles p where p.id in (v_player, v_other) order by p.id for update;
  delete from public.friendships x
   where least(x.requester_id, x.addressee_id) = least(v_player, v_other)
     and greatest(x.requester_id, x.addressee_id) = greatest(v_player, v_other)
     and (x.status = 'accepted' or (x.status = 'pending' and x.requester_id = v_player));
  return public.request_complete(v_player, p_request_id, public.friends_json(v_player));
end;
$$;
comment on function public.remove_friend(uuid, text) is
  'RPC: ends a friendship or withdraws the own open friend request (ADR-084). Error player_not_found.';

-- ---------------------------------------------------------------------------
-- D. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.friends_json(uuid)', 'public.friend_target(uuid, text)', 'public.friend_notify(uuid, text, text, text, text)',
    'public.get_friends()', 'public.send_friend_request(uuid, text)', 'public.respond_friend_request(uuid, text, boolean)',
    'public.remove_friend(uuid, text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_friends()', 'public.send_friend_request(uuid, text)', 'public.respond_friend_request(uuid, text, boolean)',
    'public.remove_friend(uuid, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261125000100_m4d_player_tags.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4d · 0100 · Player tags, lookalike-free names, player search (ADR-085)
-- =============================================================================
-- profiles.tag: permanent, globally unique 4-character tag (alphabet without 0/O/1/I), shown as "#K7Q2";
--   set by a column default on every insert, backfilled for existing players, kept on nickname change and reset.
-- name_key(nickname): lower case, umlauts/accents folded, leet digits mapped, underscores removed (no collapsing of
--   repeated letters). A new or changed nickname with the key of another player's nickname is name_taken; the
--   sign-up suffix loop avoids keys as well. Existing duplicates stay (non-unique index on the key).
-- player_by_handle(text): active player by nickname (case-insensitive), else by tag ("#K7Q2" / "k7q2").
-- New RPC:
--   search_players(query) -> {players: [{nickname, tag, level, avatar_key}]} (at most 8)
-- New field `tag` in: get_player_card, get_my_portfolio, FRIENDS entries (friends/incoming/outgoing),
--   get_rich_list entries (null for tycoons). get_player_card and the friends RPCs also accept a tag.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Player tag
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists tag text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_tag_format' and conrelid = 'public.profiles'::regclass) then
    alter table public.profiles add constraint profiles_tag_format check (tag ~ '^[A-HJ-NP-Z2-9]{4}$');
  end if;
end;
$$;

-- A random free tag (32^4 = 1 048 576 tags); the unique index catches the rare race of two sign-ups.
create or replace function public.new_player_tag()
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  c_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_tag      text;
begin
  for i in 1..100 loop
    select string_agg(substr(c_alphabet, 1 + floor(random() * 32)::integer, 1), '') into v_tag from generate_series(1, 4);
    if not exists (select 1 from public.profiles p where p.tag = v_tag) then
      return v_tag;
    end if;
  end loop;
  raise exception 'could not generate a unique player tag' using errcode = 'NX007';
end;
$$;
comment on function public.new_player_tag() is 'Internal: a random unused player tag (ADR-085); default of profiles.tag.';

-- backfill row by row: every statement sees the tags handed out before it
do $$
declare
  r record;
begin
  for r in select p.id from public.profiles p where p.tag is null order by p.created_at, p.id loop
    update public.profiles set tag = public.new_player_tag() where id = r.id;
  end loop;
end;
$$;

alter table public.profiles alter column tag set default public.new_player_tag();
alter table public.profiles alter column tag set not null;
create unique index if not exists profiles_tag_uq on public.profiles (tag);
comment on column public.profiles.tag is 'Permanent public player tag, 4 characters from A-Z/2-9 without I and O, shown as #K7Q2 (ADR-085).';

-- ---------------------------------------------------------------------------
-- B. Name key (lookalikes) and lookup by nickname or tag
-- ---------------------------------------------------------------------------
-- "M1ra", "mi_ra", "MÍRA" -> "mira"; "Matthias" and "Mathias" stay different. Indexed below: changing
-- name_normalize or this function needs a reindex of profiles_name_key_idx.
create or replace function public.name_key(p_text text)
returns text
language sql
immutable
set search_path = ''
as $$
  select replace(public.name_normalize(p_text, true), '_', '');
$$;
comment on function public.name_key(text) is 'Internal: lookalike key of a nickname (ADR-085); two players must not share one.';

create index if not exists profiles_name_key_idx on public.profiles (public.name_key(nickname));

-- Active player by nickname (case-insensitive) or, if no nickname matches, by tag ("#K7Q2", "k7q2"); else NULL.
create or replace function public.player_by_handle(p_handle text)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select x.id from public.profiles x
      where lower(x.nickname) = lower(btrim(coalesce(p_handle, ''))) and not x.is_deactivated),
    (select x.id from public.profiles x
      where x.tag = upper(regexp_replace(btrim(coalesce(p_handle, '')), '^#', '')) and not x.is_deactivated));
$$;
comment on function public.player_by_handle(text) is 'Internal: active player by nickname, else by tag (ADR-085).';

-- ---------------------------------------------------------------------------
-- C. Names: lookalikes are taken (name_violation as in M2 plus the key check)
-- ---------------------------------------------------------------------------
create or replace function public.name_violation(p_name text, p_kind text default 'player', p_exclude uuid default null)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_names  jsonb := coalesce(public.config_jsonb('names'), '{}'::jsonb);
  v_min    integer;
  v_max    integer;
  v_full   text;
  v_tokens text[];
  v_raw    text[];
  v_cat    text;
begin
  if p_kind = 'company' then
    v_min := 3; v_max := 30;
  else
    v_min := public.cfg_num(v_names, '{minLength}', 3)::integer;
    v_max := public.cfg_num(v_names, '{maxLength}', 20)::integer;
  end if;
  if p_name is null or char_length(p_name) < v_min then
    return 'name_too_short';
  end if;
  if char_length(p_name) > v_max then
    return 'name_too_long';
  end if;
  if p_kind = 'company' then
    if p_name !~ '^[A-Za-zÄÖÜäöüßÀ-ÿ0-9 &.''-]+$' or p_name <> btrim(p_name) or p_name ~ '  ' then
      return 'name_invalid_chars';
    end if;
  elsif p_name !~ '^[A-Za-z0-9_]+$' then
    return 'name_invalid_chars';
  end if;

  v_full := public.name_letters(p_name);
  select coalesce(array_agg(regexp_replace(t, '(.)\1+', '\1', 'g')), '{}') into v_tokens
    from regexp_split_to_table(public.name_normalize(p_name, true), '[^a-z]+') t where t <> '';
  select coalesce(array_agg(m[1]), '{}') into v_raw
    from regexp_matches(public.name_normalize(p_name, false), '([a-z]+|[0-9]+)', 'g') m;
  if v_full = '' then
    return 'name_invalid_chars';
  end if;

  select t.category into v_cat
    from public.blocked_name_terms t
   where (t.match_mode = 'substring' and strpos(v_full, t.term) > 0)
      or (t.match_mode = 'token' and (t.term = v_full or t.term = any (v_tokens) or t.term = any (v_raw)))
      or (t.match_mode = 'code' and t.term = any (v_raw))
   order by (t.category = 'reserved'), t.term
   limit 1;
  if v_cat is not null then
    return case when v_cat = 'reserved' then 'name_reserved' else 'name_profanity' end;
  end if;

  -- dynamic reserved names: AI tycoons, AI companies (with and without legal form), tickers, index keys
  if exists (select 1 from public.rich_tycoons ty where public.name_letters(ty.name) = v_full
                or (char_length(public.name_letters(ty.name)) >= 5 and strpos(v_full, public.name_letters(ty.name)) > 0))
     or exists (select 1 from public.companies c
                 where c.is_ai and c.id is distinct from p_exclude
                   and (public.name_letters(c.name) = v_full
                        or (char_length(public.name_letters(regexp_replace(c.name, '\s+(AG|SE|GmbH|KG)$', '', 'i'))) >= 5
                            and strpos(v_full, public.name_letters(regexp_replace(c.name, '\s+(AG|SE|GmbH|KG)$', '', 'i'))) > 0)))
     or exists (select 1 from public.securities s
                 where lower(s.ticker) = any (v_raw) or lower(s.ticker) = lower(p_name)
                    or public.name_letters(s.ticker) = v_full)
     or exists (select 1 from public.indices i where lower(i.key) = any (v_raw) or public.name_letters(i.key) = v_full) then
    return 'name_reserved';
  end if;

  if p_kind = 'company' then
    if exists (select 1 from public.companies c where lower(c.name) = lower(p_name) and c.id is distinct from p_exclude) then
      return 'name_taken';
    end if;
  elsif exists (select 1 from public.profiles p
                 where (lower(p.nickname) = lower(p_name) or public.name_key(p.nickname) = public.name_key(p_name))
                   and p.id is distinct from p_exclude) then
    -- also lookalikes (ADR-085): same name key as another player's nickname
    return 'name_taken';
  end if;
  return null;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. Sign-up (handle_new_user as in M2; the suffix loop also avoids lookalikes)
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta            jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_code            text  := nullif(upper(btrim(coalesce(v_meta ->> 'invite_code', ''))), '');
  v_invite_required boolean := public.config_boolean('auth', '{inviteRequired}', true);
  v_age_required    boolean := public.config_boolean('auth', '{ageConfirmationRequired}', true);
  v_age_confirmed   boolean := lower(coalesce(v_meta ->> 'age_confirmed', 'false')) in ('true', '1', 'yes');
  v_start_cents     bigint  := greatest(public.config_bigint('economy', '{startingCapitalCents}', 1000000), 0);
  v_vault_hours     double precision := greatest(0, least(
                        public.config_double('economy', '{vaultInitialHours}', 2),
                        public.config_double('economy', '{vaultCapHours}', 8)));
  v_max_len         integer := public.config_double('names', '{maxLength}', 20)::integer;
  v_invite          public.invite_codes;
  v_base            text;
  v_nickname        text;
  v_reason          text;
  v_attempt         integer := 0;
begin
  -- 18+ confirmation ---------------------------------------------------------
  if v_age_required and not v_age_confirmed then
    raise exception 'age confirmation (18+) is required' using errcode = 'NX007';
  end if;

  -- invite code ---------------------------------------------------------------
  if v_code is not null then
    select i.* into v_invite from public.invite_codes i where i.code = v_code for update;
    if not found
       or not v_invite.is_active
       or (v_invite.expires_at is not null and v_invite.expires_at <= now())
       or v_invite.used_count >= v_invite.max_uses then
      if v_invite_required then
        raise exception 'invite code is invalid, expired or used up' using errcode = 'NX005';
      end if;
      v_code := null;
    end if;
  elsif v_invite_required then
    raise exception 'an invite code is required' using errcode = 'NX005';
  end if;

  -- nickname: cleaned as before, forbidden names are rejected (the client
  -- pre-checks with check_nickname), taken names and lookalikes of taken names
  -- (same name key, ADR-085) get a numeric suffix; the tag comes from the column default
  v_base := left(regexp_replace(coalesce(v_meta ->> 'nickname', ''), '[^A-Za-z0-9_]', '', 'g'), v_max_len);
  if length(v_base) < 3 then
    v_base := 'Trader';
    v_nickname := v_base || (floor(random() * 90000) + 10000)::integer::text;
  else
    v_reason := public.name_violation(v_base, 'player');
    if v_reason in ('name_profanity', 'name_reserved') then
      perform public.api_error(v_reason);
    end if;
    v_nickname := v_base;
  end if;
  while exists (select 1 from public.profiles p
                 where lower(p.nickname) = lower(v_nickname) or public.name_key(p.nickname) = public.name_key(v_nickname)) loop
    v_attempt := v_attempt + 1;
    if v_attempt > 20 then
      raise exception 'could not generate a unique nickname' using errcode = 'NX007';
    end if;
    v_nickname := left(v_base, 15) || (floor(random() * 90000) + 10000)::integer::text;
  end loop;

  -- player rows ----------------------------------------------------------------
  insert into public.profiles (id, nickname) values (new.id, v_nickname);
  insert into public.player_private (player_id, age_confirmed_at)
  values (new.id, case when v_age_confirmed then now() end);
  insert into public.player_settings (player_id) values (new.id);
  insert into public.vaults (player_id, accrual_started_at)
  values (new.id, public.game_now() - make_interval(secs => v_vault_hours * 3600));
  insert into public.login_streaks (player_id) values (new.id);

  insert into public.player_unlocks (player_id, unlock_key)
  select new.id, u.key from public.unlocks u where u.level <= 1;

  insert into public.notification_preferences (player_id, type_key, in_app_enabled, push_enabled)
  select new.id, t.key, t.default_in_app, t.default_push from public.notification_types t;

  -- ledger: cash + reserve account, starting capital from the state -----------
  insert into public.ledger_accounts (kind, owner_player_id, label) values ('player_cash', new.id, 'Cash');
  insert into public.ledger_accounts (kind, owner_player_id, label)
  values ('player_reserve', new.id, 'Reserved (orders, subscriptions, margin)');

  if v_start_cents > 0 then
    perform public.state_payout(new.id, v_start_cents, 0, 'starting_capital', 'Starting capital',
                                'profile', new.id, 'starting_capital:' || new.id::text);
  end if;

  -- consume the invite ---------------------------------------------------------
  if v_code is not null then
    update public.invite_codes set used_count = used_count + 1 where code = v_code;
    insert into public.invite_code_redemptions (code, player_id) values (v_code, new.id);
  end if;

  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- E. Player card (as in M3d plus tag; also found by tag)
-- ---------------------------------------------------------------------------
create or replace function public.get_player_card(p_nickname text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  p      public.profiles;
  v_job  jsonb;
begin
  perform public.require_player();
  select * into p from public.profiles x where x.id = public.player_by_handle(p_nickname);
  if p.id is null then
    perform public.api_error('player_not_found');
  end if;
  select jsonb_build_object('company_name', c.name, 'title_key', j.title_key, 'title', case when j.title_key is null then j.title end,
                            'tier', j.tier, 'since', j.started_at)
    into v_job
    from public.player_jobs j join public.companies c on c.id = j.company_id
   where j.player_id = p.id and j.status = 'active';
  return jsonb_build_object(
    'nickname',        p.nickname,
    'tag',             p.tag,
    'avatar_key',      p.avatar_key,
    'level',           p.level,
    'rank',            public.player_rich_rank(p.id),
    'net_worth_cents', public.player_net_worth_cents(p.id),
    'streak_days',     public.player_streak_days(p.id),
    'skills_learned',  (select count(*) from public.player_skills s where s.player_id = p.id)::integer,
    'branch_scores',   public.player_branch_scores(p.id),
    'top_skills',      coalesce((select jsonb_agg(jsonb_build_object('key', x.skill_key, 'tier', x.tier) order by x.tier desc, x.learned_at)
                                   from (select s.skill_key, s.learned_at, (public.skill_node(s.skill_key) ->> 'tier')::integer as tier
                                           from public.player_skills s where s.player_id = p.id
                                          order by 3 desc nulls last, s.learned_at limit 3) x), '[]'::jsonb),
    'job',             v_job,
    'company',         (select jsonb_build_object('name', c.name, 'ticker', c.ticker)
                          from public.player_companies pc join public.companies c on c.id = pc.company_id
                         where pc.founder_id = p.id and pc.status = 'active'),
    'member_since',    p.created_at);
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Portfolio (as in M3g plus the own tag)
-- ---------------------------------------------------------------------------
create or replace function public.get_my_portfolio()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player    uuid;
  v_cash      bigint;
  v_reserved  bigint;
  v_positions jsonb;
  v_value     bigint;
  v_bid_value bigint;
  v_orders    jsonb;
  v_trades    jsonb;
  v_prof      public.profiles;
  v_priv      public.player_private;
  v_level     jsonb;
  v_days      double precision := public.config_double('names', '{nicknameChangeDays}', 60);
  v_today     date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_streak    integer;
  ls          public.login_streaks;
begin
  v_player := public.require_player();
  select * into v_priv from public.player_private where player_id = v_player;
  select coalesce(sum(a.balance_cents) filter (where a.kind = 'player_cash'), 0),
         coalesce(sum(a.balance_cents) filter (where a.kind = 'player_reserve'), 0)
    into v_cash, v_reserved
    from public.ledger_accounts a where a.owner_player_id = v_player;

  select coalesce(jsonb_agg(jsonb_build_object(
           'ticker', x.ticker, 'name', x.name, 'kind', x.kind, 'quantity_e6', x.quantity_e6,
           'reserved_quantity_e6', x.reserved_quantity_e6, 'avg_price_e4', x.avg_entry_price_e4,
           'last_price_e4', x.last_price_e4, 'market_value_cents', x.mv, 'cost_basis_cents', x.cost_basis_cents,
           'unrealized_pnl_cents', x.mv - x.cost_basis_cents, 'realized_pnl_cents', x.realized_pnl_cents,
           'change_bps', x.change_bps, 'opened_at', x.opened_at)
           order by x.mv desc), '[]'::jsonb),
         coalesce(sum(x.mv), 0)::bigint,
         coalesce(sum(x.bv), 0)::bigint
    into v_positions, v_value, v_bid_value
    from (select s.ticker, s.name, s.kind, p.quantity_e6, p.reserved_quantity_e6, p.avg_entry_price_e4, p.cost_basis_cents,
                 p.realized_pnl_cents, p.opened_at, q.last_price_e4, q.change_bps,
                 public.value_cents(p.quantity_e6, q.last_price_e4) as mv,
                 public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)) as bv
            from public.positions p
            join public.securities s on s.id = p.security_id
            join public.security_quotes q on q.security_id = p.security_id
           where p.player_id = v_player and p.status = 'open' and p.quantity_e6 > 0) x;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id, 'ticker', s.ticker, 'side', o.side, 'type', o.type, 'quantity_e6', o.quantity_e6,
           'filled_quantity_e6', o.filled_quantity_e6, 'limit_price_e4', o.limit_price_e4, 'status', o.status,
           'reserved_cents', o.reserved_cents, 'created_at', o.created_at)
           order by o.created_at desc), '[]'::jsonb)
    into v_orders
    from public.orders o join public.securities s on s.id = o.security_id
   where o.player_id = v_player and o.status in ('open', 'partially_filled');

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'ticker', t.ticker, 'side', t.side, 'quantity_e6', t.quantity_e6, 'price_e4', t.price_e4,
           'gross_cents', t.gross_cents, 'fee_cents', t.fee_cents, 'tax_cents', t.tax_cents,
           'realized_pnl_cents', t.realized_pnl_cents, 'xp_awarded', t.xp_awarded, 'executed_at', t.executed_at)
           order by t.executed_at desc), '[]'::jsonb)
    into v_trades
    from (select tr.*, s.ticker from public.trades tr join public.securities s on s.id = tr.security_id
           where tr.player_id = v_player and tr.executed_at > coalesce(v_priv.account_reset_at, '-infinity'::timestamptz)
           order by tr.executed_at desc limit 50) t;

  select * into v_prof from public.profiles where id = v_player;
  select * into ls from public.login_streaks where player_id = v_player;
  v_level := public.level_progress(v_prof.xp_total);
  v_streak := case when ls.last_login_day >= v_today - 1 then ls.current_streak
                   when ls.last_login_day = v_today - 2 and ls.freeze_tokens > 0 then ls.current_streak
                   else 0 end;

  return jsonb_build_object(
    'cash_cents',            v_cash,
    'reserved_cents',        v_reserved,
    'positions_value_cents', v_value,
    'total_cents',           v_cash + v_reserved + v_value,
    'net_worth_cents',       v_cash + v_reserved + v_bid_value,
    'loss_pot_cents',        coalesce(v_priv.tax_loss_pot_cents, 0),
    'vault',                 public.vault_status(v_player) - 'accrued_seconds' - 'base_rate_cents_per_hour',
    'positions',             v_positions,
    'open_orders',           v_orders,
    'recent_trades',         v_trades,
    'level',                 v_prof.level,
    'xp_total',              v_prof.xp_total,
    'xp_into_level',         (v_level ->> 'xp_into_level')::bigint,
    'xp_for_next',           (v_level ->> 'xp_for_next')::bigint,
    'tutorial_completed',    v_priv.tutorial_completed_at is not null,
    'nickname',              v_prof.nickname,
    'tag',                   v_prof.tag,
    'nickname_change_available_at',
                             case when v_prof.nickname_changed_at is null
                                    or v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) <= now() then null
                                  else v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) end,
    'missions_claimable',    (select count(*) from public.player_missions m
                               where m.player_id = v_player and m.status = 'completed'
                                 and (m.expires_at is null or m.expires_at > public.game_now()))::integer,
    'streak_days',           coalesce(v_streak, 0),
    'avatar_key',            coalesce(v_prof.avatar_key, 'rookie'),
    'skill_points_free',     coalesce((select sp.free_points from public.player_skill_points sp where sp.player_id = v_player), 0),
    'daily_reward_claimable', not exists (select 1 from public.daily_reward_claims c
                                           where c.player_id = v_player
                                             and c.claim_day = (public.game_now() at time zone 'Europe/Berlin')::date),
    'company_value_cents',   public.player_company_value_cents(v_player),
    'debt_cents',            public.player_debt_cents(v_player),
    'debt_withholding_bps',  public.config_double('startups', '{insolvency,loanWithholdingBps}', 5000)::integer,
    'founding_locked_until', case when v_prof.founding_locked_until > now() then v_prof.founding_locked_until end,
    'server_time',           public.game_now());
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Rich list (as in M2b plus tag for players, null for tycoons)
-- ---------------------------------------------------------------------------
create or replace function public.get_rich_list(p_limit integer default 100, p_offset integer default 0, p_scope text default 'all')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_limit   integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_offset  integer := greatest(coalesce(p_offset, 0), 0);
  v_scope   text := coalesce(p_scope, 'all');
  v_now     timestamptz := public.game_now();
  v_snap    timestamptz;
  v_out     jsonb;
begin
  v_player := public.require_player();
  if v_scope not in ('all', 'players') then
    perform public.api_error('invalid_argument');
  end if;
  -- the latest snapshot that is at least 24 h old
  select max(s.taken_at) into v_snap from public.rich_list_snapshots s where s.taken_at <= v_now - interval '24 hours';

  with lst as materialized (
    select e.entity_kind, e.entity_id, e.name, e.description, e.net_worth_cents,
           case when v_scope = 'players' then e.rank_players else e.rank_all end as rnk,
           case when s.net_worth_cents > 0 then round((e.net_worth_cents - s.net_worth_cents) * 10000.0 / s.net_worth_cents)::integer end as change_bps,
           case when s.entity_id is not null
                then (case when v_scope = 'players' then s.rank_players else s.rank_all end)
                   - (case when v_scope = 'players' then e.rank_players else e.rank_all end) end as rank_change
      from public.rich_list_entries() e
      left join public.rich_list_snapshots s on s.taken_at = v_snap and s.entity_kind = e.entity_kind and s.entity_id = e.entity_id
     where v_scope = 'all' or e.entity_kind = 'player'
  ), me as (
    select * from lst where entity_kind = 'player' and entity_id = v_player
  )
  select jsonb_build_object(
           'server_time', v_now,
           'total', (select count(*) from lst),
           'entries', (select coalesce(jsonb_agg(jsonb_build_object(
                          'rank', x.rnk, 'kind', x.entity_kind, 'id', x.entity_id, 'name', x.name, 'description', x.description,
                          'net_worth_cents', x.net_worth_cents, 'change_24h_bps', x.change_bps, 'rank_change_24h', x.rank_change,
                          'is_me', x.entity_kind = 'player' and x.entity_id = v_player,
                          'avatar_key', case when x.entity_kind = 'player'
                                             then (select pr.avatar_key from public.profiles pr where pr.id = x.entity_id)
                                             else public.tycoon_avatar_key(x.entity_id) end,
                          'tag', case when x.entity_kind = 'player'
                                      then (select pr.tag from public.profiles pr where pr.id = x.entity_id) end) order by x.rnk), '[]'::jsonb)
                         from (select * from lst order by rnk offset v_offset limit v_limit) x),
           'me', (select jsonb_build_object(
                           'rank', m.rnk, 'net_worth_cents', m.net_worth_cents,
                           'next', (select jsonb_build_object('rank', n.rnk, 'name', n.name, 'gap_cents', n.net_worth_cents - m.net_worth_cents)
                                      from lst n where n.rnk = m.rnk - 1))
                    from me m))
    into v_out;
  return v_out;
end;
$$;

-- ---------------------------------------------------------------------------
-- H. Friends: entries carry the tag, the other player is also found by tag
-- ---------------------------------------------------------------------------
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at)) order by lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;
comment on function public.friends_json(uuid) is
  'FRIENDS of a player (ADR-084, tag ADR-085): friends by nickname, incoming and outgoing open requests newest first.';

-- The other player of a friends RPC: active, found by nickname (case-insensitive) or tag
create or replace function public.friend_target(p_player uuid, p_nickname text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_nickname is null or char_length(btrim(p_nickname)) = 0 or char_length(p_nickname) > 64 then
    perform public.api_error('invalid_argument');
  end if;
  v_id := public.player_by_handle(p_nickname);
  if v_id is null then
    perform public.api_error('player_not_found');
  end if;
  if v_id = p_player then
    perform public.api_error('invalid_argument');
  end if;
  return v_id;
end;
$$;

comment on function public.send_friend_request(uuid, text) is
  'RPC: friend request to a player by nickname or tag (ADR-084/085); a counter request accepts. Errors player_not_found, invalid_argument.';

-- ---------------------------------------------------------------------------
-- I. Player search (top search bar)
-- ---------------------------------------------------------------------------
-- Query trimmed, one leading '#' dropped; under 2 characters: no result. A valid tag puts its player first, then
-- nicknames (case-insensitive): exact, prefix, contains; each group by level desc, nickname. At most 8.
create or replace function public.search_players(p_query text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q    text := regexp_replace(btrim(coalesce(p_query, '')), '^#', '');
  v_like text;
  v_out  jsonb;
begin
  perform public.require_player();
  if char_length(v_q) < 2 or char_length(v_q) > 64 then
    return jsonb_build_object('players', '[]'::jsonb);
  end if;
  v_q := lower(v_q);
  -- user input is a LIKE literal: escape the wildcards and the escape character
  v_like := replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_');
  select coalesce(jsonb_agg(jsonb_build_object('nickname', x.nickname, 'tag', x.tag, 'level', x.level,
                                               'avatar_key', x.avatar_key)
                            order by x.grp, x.level desc, lower(x.nickname), x.nickname), '[]'::jsonb)
    into v_out
    from (select p.nickname, p.tag, p.level, p.avatar_key,
                 case when p.tag = upper(v_q) then 0
                      when lower(p.nickname) = v_q then 1
                      when lower(p.nickname) like v_like || '%' escape '\' then 2
                      else 3 end as grp
            from public.profiles p
           where not p.is_deactivated
             and (p.tag = upper(v_q) or lower(p.nickname) like '%' || v_like || '%' escape '\')
           order by grp, p.level desc, lower(p.nickname), p.nickname
           limit 8) x;
  return jsonb_build_object('players', v_out);
end;
$$;
comment on function public.search_players(text) is
  'RPC: player search by tag or nickname (exact, prefix, contains), at most 8 (ADR-085).';

-- ---------------------------------------------------------------------------
-- J. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.new_player_tag()', 'public.name_key(text)', 'public.player_by_handle(text)', 'public.search_players(text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.search_players(text) to authenticated;
end;
$$;
-- ===== idempotent copy of migrations/20261126000100_m4e_founder_payout.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4e · 0100 · Automatic CEO payout (ADR-086)
-- =============================================================================
-- Mirrors src/lib/sim/startup.ts (isValidFounderPayout, founderPayoutCents):
--   player_companies.founder_payout_bps  share of the hourly profit, whole steps of
--                                        startups.founderPayout.stepBps from 0 to maxBps
--   payout = min(floor(profit × bps / 10 000), free cash)   only for a positive profit;
--            free cash = company cash − open bills (unpaid_cents) after the hour's own bookings
--            (the same rule as company_withdraw and expand_company)
-- player_company_close_hour books the payout after all other bookings of the hour exactly like
-- company_withdraw: company cash → founder's player_cash (kind 'transfer'), then loan_withhold on
-- the founder's income. profit_cents stays unchanged (a transfer, not a cost); the amount is stored
-- in player_company_hours.founder_payout_cents. Idempotent per (company, hour) like the rest of the hour.
-- New RPC set_founder_payout(request_id, bps) → {company}. COMPANY: founder_payout_bps,
-- live.founder_payout_per_hour_cents, live.today_founder_payout_cents, hours[].founder_payout_cents.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists founder_payout_bps integer not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_founder_payout_bps_check'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_founder_payout_bps_check
      check (founder_payout_bps between 0 and 10000);
  end if;
end;
$$;
comment on column public.player_companies.founder_payout_bps is
  'Share of every profitable operating hour paid to the founder automatically (ADR-086), 0..10000 bps.';
grant select (founder_payout_bps) on public.player_companies to authenticated;

alter table public.player_company_hours add column if not exists founder_payout_cents bigint not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_company_hours_founder_payout_check'
                    and conrelid = 'public.player_company_hours'::regclass) then
    alter table public.player_company_hours add constraint player_company_hours_founder_payout_check
      check (founder_payout_cents >= 0);
  end if;
end;
$$;
comment on column public.player_company_hours.founder_payout_cents is
  'Automatic CEO payout of the hour (ADR-086): from the company cash to the founder; not part of profit_cents.';

-- ---------------------------------------------------------------------------
-- B. One operating hour as in M4c, then the CEO payout
-- ---------------------------------------------------------------------------

create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_owed    bigint;
  v_free    bigint;
  v_payout  bigint := 0;
  v_bps     integer;
  v_until   timestamptz;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision;
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level) / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  v_cogs := round((v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  v_fixed := round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  v_owed := pc.unpaid_cents + v_unpaid - v_settle;

  -- automatic CEO payout (ADR-086, founderPayoutCents): after the hour's own bookings, a share of a positive profit
  -- (rounded down) moves from the company cash to the founder's private cash like company_withdraw, never more than
  -- the free cash (cash minus open bills). A transfer, not a cost: profit_cents stays as computed above.
  v_bps := least(10000, greatest(0, coalesce(pc.founder_payout_bps, 0)));
  if v_profit > 0 and v_bps > 0 then
    select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
    v_payout := least(v_profit * v_bps / 10000, greatest(0, coalesce(v_free, 0)));
  end if;
  if v_payout > 0 then
    perform public.lock_player_accounts(pc.founder_id);
    perform public.ledger_transfer(v_acc, public.ledger_player_account(pc.founder_id, 'player_cash'), v_payout, 'transfer',
                                   'CEO-Auszahlung ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':payout', pc.founder_id);
    perform public.loan_withhold(pc.founder_id, v_payout, k || ':payout');
  end if;

  update public.player_companies
     set unpaid_cents = v_owed,
         distress = v_owed > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents, founder_payout_cents)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit, v_payout);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid,
                            'founder_payout_cents', v_payout);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083) and pays '
  'the automatic CEO payout (ADR-086); idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- C. COMPANY: payout share, payout of the last hour and of the day
-- ---------------------------------------------------------------------------
create or replace function public.company_live_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_day     timestamptz := ((public.game_now() at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin';
  v_qid     bigint := (public.current_game_quarter()).id;
  v_rev     bigint;
  v_profit  bigint;
  v_trev    bigint;
  v_tprofit bigint;
  v_qrev    bigint;
  v_qprofit bigint;
  v_tpay    bigint;
  h         public.player_company_hours;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  v_rev := h.revenue_cents;
  v_profit := h.profit_cents;
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0), coalesce(sum(x.founder_payout_cents), 0)
    into v_trev, v_tprofit, v_tpay
    from public.player_company_hours x
   where x.company_id = p_company and x.hour_start >= v_day
     and x.hour_start < ((v_day at time zone 'Europe/Berlin') + interval '1 day') at time zone 'Europe/Berlin';
  select coalesce(sum(x.revenue_cents), 0), coalesce(sum(x.profit_cents), 0) into v_qrev, v_qprofit
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = v_qid;
  return jsonb_build_object(
    'last_hour_at', pc.last_hour_at,
    'revenue_per_hour_cents', coalesce(v_rev, 0),
    'profit_per_hour_cents', coalesce(v_profit, 0),
    'pay_factor_bps', pc.pay_factor_bps,
    'today_revenue_cents', v_trev,
    'today_profit_cents', v_tprofit,
    'quarter_revenue_cents', v_qrev,
    'quarter_profit_cents', v_qprofit,
    -- the last closed hour in detail (ADR-083: profit coach)
    'contract_revenue_per_hour_cents', coalesce(h.contract_revenue_cents, 0),
    'demand_per_hour_cents', coalesce(h.demand_cents, 0),
    'capacity_per_hour_cents', coalesce(h.capacity_cents, 0),
    'fixed_per_hour_cents', coalesce(h.fixed_cents, 0),
    'ai_wages_per_hour_cents', coalesce(h.ai_wages_paid_cents, 0),
    'marketing_per_hour_cents', coalesce(h.marketing_cents, 0),
    -- ADR-086: automatic CEO payout of the last closed hour and of the Berlin day
    'founder_payout_per_hour_cents', coalesce(h.founder_payout_cents, 0),
    'today_founder_payout_cents', v_tpay);
end;
$$;
comment on function public.company_live_json(uuid) is
  'COMPANY.live: last closed hour (with its details, ADR-083, and the CEO payout, ADR-086), Berlin day and running quarter of a player company (ADR-072).';

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'contract_revenue_cents', x.contract_revenue_cents,
                                               'profit_cents', x.profit_cents,
                                               'founder_payout_cents', x.founder_payout_cents) order by x.hour_start), '[]'::jsonb)
    from (select h.hour_start, h.revenue_cents, h.contract_revenue_cents, h.profit_cents, h.founder_payout_cents from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;
comment on function public.company_hours_json(uuid) is 'COMPANY.hours: the last 24 closed operating hours, oldest first.';

-- company_state as in M4c plus the CEO payout share (ADR-086)
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
  v_mf     double precision;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  -- the estimate describes the market the company reaches (ADR-083)
  v_mf := public.company_market_factor(pc.tier, pc.expansion_level);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents * v_mf
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents * v_mf
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', public.company_max_employees(p_company),
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', round((v_team ->> 'capacity_cents')::bigint * public.company_capacity_factor(pc.expansion_level))::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 6),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object(
         'banner', pc.banner,
         -- ADR-083: price strategy, contract work, expansion
         'price_level', pc.price_level,
         'contract_work', pc.contract_work,
         'expansion_level', pc.expansion_level,
         'can_expand', public.company_can_expand(pc.tier),
         'expansion_cost_cents', case when public.company_can_expand(pc.tier)
                                      then public.company_expansion_cost_cents(pc.expansion_level) end,
         'market_factor', round(v_mf::numeric, 4),
         -- ADR-086: share of the hourly profit paid to the founder automatically
         'founder_payout_bps', pc.founder_payout_bps);
end;
$$;

-- ---------------------------------------------------------------------------
-- D. RPC: payout share (founder only)
-- ---------------------------------------------------------------------------
create or replace function public.set_founder_payout(p_request_id uuid, p_bps integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_step    integer := greatest(1, public.config_double('startups', '{founderPayout,stepBps}', 500)::integer);
  v_max     integer := least(10000, public.config_double('startups', '{founderPayout,maxBps}', 10000)::integer);
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_bps is null or p_bps < 0 or p_bps > v_max or p_bps % v_step <> 0 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_founder_payout');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies set founder_payout_bps = p_bps where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.set_founder_payout(uuid, integer) is
  'RPC (founder): share of the hourly profit paid out automatically, whole steps of startups.founderPayout (ADR-086); '
  'errors company_not_found, invalid_argument.';

-- ---------------------------------------------------------------------------
-- E. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.player_company_close_hour(uuid, timestamptz)', 'public.company_live_json(uuid)', 'public.company_hours_json(uuid)',
    'public.company_state(uuid)', 'public.set_founder_payout(uuid, integer)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.set_founder_payout(uuid, integer) to authenticated;
end;
$$;
-- ===== idempotent copy of migrations/20261127000100_m4f_social.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4f · 0100 · Friends feed and in-app notifications (ADR-088)
-- =============================================================================
-- Feed items are written by AFTER triggers on the tables of the existing write paths, so no
-- RPC changes its behaviour (a rolled back action leaves no item). Kinds and payloads
-- (the client renders the German text from kind + payload):
--   level_up {level}                     profiles.level reaches a multiple of social.feed.levelEvery
--   big_trade {ticker, security_name, profit_cents, profit_bps}
--                                        trades: a fill that realises ≥ bigTradeMinProfitCents and ≥ bigTradeMinBps
--   company_founded {name, tier}         player_companies insert
--   company_upgraded {name, tier}        player_companies.tier changes (not to 'ag')
--   company_ipo {name, ticker}           player_companies.tier becomes 'ag' (IPO subscription ended listed)
--   company_expanded {name, level}       player_companies.expansion_level rises
--   art_won {title, code, price_cents}   artwork_sales insert ≥ artMinPriceCents (gallery and player auctions)
--   art_created {title, code}            artworks insert of a player artwork
--   home_bought {tier}                   player_homes.tier set / changed
--   car_bought {car_key, price_cents}    player_cars insert ≥ carMinPriceCents
--   job_started {company_name, title, title_key}  player_jobs insert from a signed contract
--   streak {days}                        login_streaks.current_streak reaches a value of streakMilestones
--   friends_now {other_nickname}         friendships pending → accepted (one item per side)
--   league_won {week_start, growth_bps}  posted by league_close (migration 0200)
-- Reactions: feed_reactions (one per item and player), RPC react_feed toggles.
-- RPCs: get_feed(before, limit) -> {items: [FEED_ITEM], next_before}, react_feed(request_id, item_id) -> {item},
--       get_notifications(limit) -> {items, unread}, mark_notifications_read(ids) -> {unread}.
-- Notifications (in-app, preferences respected): feed_reaction, art_outbid, job_application (league_result: 0200).
-- Error: feed_item_not_found (react_feed on an item that does not exist or is not visible).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.feed_items add column if not exists dedupe_key text;
create unique index if not exists feed_items_dedupe_uq on public.feed_items (dedupe_key);
create index if not exists feed_items_actor_id_idx on public.feed_items (actor_id, id desc);
comment on column public.feed_items.dedupe_key is 'Optional unique key: the same event never posts twice (ADR-088).';

create table if not exists public.feed_reactions (
  item_id    bigint not null references public.feed_items (id) on delete cascade,
  player_id  uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (item_id, player_id)
);
alter table public.feed_reactions enable row level security;
create index if not exists feed_reactions_player_idx on public.feed_reactions (player_id);
revoke all on public.feed_reactions from public, anon, authenticated;
grant all on public.feed_reactions to service_role;
comment on table public.feed_reactions is 'One reaction ("gefällt mir") per feed item and player (ADR-088). Internal (RPCs).';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('feed_reaction', 'social', 'Reaktion im Feed', 'Jemand hat auf deinen Beitrag im Freundes-Feed reagiert.',
        'notif_feed', true, false, false, 285),
       ('league_result', 'social', 'Liga-Ergebnis', 'Die Wochenliga ist ausgewertet.', 'notif_trophy', true, false, false, 290),
       ('art_outbid', 'social', 'Überboten', 'Jemand hat dein Gebot auf ein Kunstwerk überboten.', 'notif_bell', true, true,
        false, 295),
       ('job_application', 'company', 'Neue Bewerbung', 'Jemand hat sich auf eine Stelle deiner Firma beworben.',
        'notif_briefcase', true, false, false, 225)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- One feed item of an active player (visibility friends); a known dedupe key posts nothing
create or replace function public.feed_post(p_actor uuid, p_kind text, p_payload jsonb, p_dedupe text default null)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id bigint;
begin
  if p_actor is null or p_kind is null
     or not exists (select 1 from public.profiles p where p.id = p_actor and not p.is_deactivated) then
    return null;
  end if;
  insert into public.feed_items (actor_id, kind, visibility, payload, dedupe_key)
  values (p_actor, p_kind, 'friends', coalesce(p_payload, '{}'::jsonb), p_dedupe)
  on conflict (dedupe_key) do nothing
  returning id into v_id;
  return v_id;
end;
$$;
comment on function public.feed_post(uuid, text, jsonb, text) is
  'Internal: posts a friends feed item (ADR-088); p_dedupe makes retries harmless.';

-- In-app notification unless the player switched the type off (missing preference: the type's
-- default; mandatory types always). A known (player, dedupe key) inserts nothing.
create or replace function public.social_notify(p_player uuid, p_type text, p_title text, p_body text, p_payload jsonb,
                                                p_link text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.notification_types;
begin
  select * into t from public.notification_types x where x.key = p_type;
  if t.key is null or p_player is null
     or not exists (select 1 from public.profiles p where p.id = p_player and not p.is_deactivated) then
    return;
  end if;
  if not t.is_mandatory
     and not coalesce((select np.in_app_enabled from public.notification_preferences np
                        where np.player_id = p_player and np.type_key = p_type), t.default_in_app, true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, p_type, left(p_title, 200), left(p_body, 500), coalesce(p_payload, '{}'::jsonb), p_link, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;
comment on function public.social_notify(uuid, text, text, text, jsonb, text, text) is
  'Internal: in-app notification respecting notification_preferences (ADR-088).';

-- Short German description of a feed item (body of the reaction notification)
create or replace function public.feed_item_label(p_kind text, p_payload jsonb)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_kind
    when 'level_up' then 'Level ' || coalesce(p_payload ->> 'level', '?') || ' erreicht'
    when 'big_trade' then 'Gewinn mit ' || coalesce(p_payload ->> 'ticker', 'einer Aktie')
    when 'company_founded' then coalesce(p_payload ->> 'name', 'Firma') || ' gegründet'
    when 'company_upgraded' then coalesce(p_payload ->> 'name', 'Firma') || ' aufgestiegen'
    when 'company_ipo' then coalesce(p_payload ->> 'name', 'Firma') || ' an der Börse'
    when 'company_expanded' then coalesce(p_payload ->> 'name', 'Firma') || ' erweitert'
    when 'art_won' then 'Kunstwerk „' || coalesce(p_payload ->> 'title', '?') || '“ ersteigert'
    when 'art_created' then 'Kunstwerk „' || coalesce(p_payload ->> 'title', '?') || '“ gemalt'
    when 'home_bought' then 'Neues Zuhause'
    when 'car_bought' then 'Neues Auto'
    when 'job_started' then 'Neuer Job bei ' || coalesce(p_payload ->> 'company_name', '?')
    when 'streak' then coalesce(p_payload ->> 'days', '?') || ' Tage in Folge dabei'
    when 'league_won' then 'Wochenliga gewonnen'
    when 'friends_now' then 'Jetzt befreundet mit ' || coalesce(p_payload ->> 'other_nickname', '?')
    else 'Beitrag im Feed'
  end;
$$;

-- Accepted friends of a player
create or replace function public.friend_ids(p_player uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select case when f.requester_id = p_player then f.addressee_id else f.requester_id end
    from public.friendships f
   where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id);
$$;

-- FEED_ITEM from the point of view of p_viewer
create or replace function public.feed_item_json(p_item bigint, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id',         fi.id,
    'kind',       fi.kind,
    'payload',    fi.payload,
    'created_at', fi.created_at,
    'is_me',      fi.actor_id = p_viewer,
    'actor',      jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'level', p.level),
    'reactions',  (select count(*) from public.feed_reactions r where r.item_id = fi.id)::integer,
    'reacted',    exists (select 1 from public.feed_reactions r where r.item_id = fi.id and r.player_id = p_viewer))
    from public.feed_items fi join public.profiles p on p.id = fi.actor_id
   where fi.id = p_item;
$$;

-- ---------------------------------------------------------------------------
-- C. Feed triggers (each fires only for the real event of its write path)
-- ---------------------------------------------------------------------------
create or replace function public.feed_on_level()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_every integer := greatest(1, public.config_double('social', '{feed,levelEvery}', 5)::integer);
  v_level integer := (new.level / v_every) * v_every;
begin
  if v_level > old.level and v_level >= v_every then
    perform public.feed_post(new.id, 'level_up', jsonb_build_object('level', v_level),
                             'level_up:' || new.id::text || ':' || v_level::text);
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_level on public.profiles;
create trigger feed_on_level after update of level on public.profiles
  for each row when (new.level > old.level) execute function public.feed_on_level();

-- profit_bps = realised profit / cost basis of the sold part (gross - fee - profit)
create or replace function public.feed_on_trade()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cost bigint := new.gross_cents - new.fee_cents - new.realized_pnl_cents;
  v_bps  bigint;
  s      public.securities;
begin
  if new.counterparty = 'issuer' or v_cost <= 0
     or new.realized_pnl_cents < public.config_bigint('social', '{feed,bigTradeMinProfitCents}', 100000) then
    return null;
  end if;
  v_bps := public.div_round_half_even(new.realized_pnl_cents::numeric * 10000, v_cost);
  if v_bps < public.config_bigint('social', '{feed,bigTradeMinBps}', 1500) then
    return null;
  end if;
  select * into s from public.securities x where x.id = new.security_id;
  perform public.feed_post(new.player_id, 'big_trade',
    jsonb_build_object('ticker', s.ticker, 'security_name', s.name, 'profit_cents', new.realized_pnl_cents, 'profit_bps', v_bps),
    'big_trade:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_trade on public.trades;
create trigger feed_on_trade after insert on public.trades
  for each row when (new.realized_pnl_cents is not null and new.realized_pnl_cents > 0)
  execute function public.feed_on_trade();

create or replace function public.feed_on_company()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  c public.companies;
begin
  select * into c from public.companies x where x.id = new.company_id;
  if tg_op = 'INSERT' then
    perform public.feed_post(new.founder_id, 'company_founded', jsonb_build_object('name', c.name, 'tier', new.tier),
                             'company_founded:' || new.company_id::text);
    return null;
  end if;
  if new.tier is distinct from old.tier then
    if new.tier = 'ag' then
      perform public.feed_post(new.founder_id, 'company_ipo', jsonb_build_object('name', c.name, 'ticker', c.ticker),
                               'company_ipo:' || new.company_id::text);
    else
      perform public.feed_post(new.founder_id, 'company_upgraded', jsonb_build_object('name', c.name, 'tier', new.tier),
                               'company_upgraded:' || new.company_id::text || ':' || new.tier);
    end if;
  end if;
  if new.expansion_level > old.expansion_level then
    perform public.feed_post(new.founder_id, 'company_expanded', jsonb_build_object('name', c.name, 'level', new.expansion_level),
                             'company_expanded:' || new.company_id::text || ':' || new.expansion_level::text);
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_company_insert on public.player_companies;
create trigger feed_on_company_insert after insert on public.player_companies
  for each row execute function public.feed_on_company();
drop trigger if exists feed_on_company_update on public.player_companies;
create trigger feed_on_company_update after update of tier, expansion_level on public.player_companies
  for each row when (new.tier is distinct from old.tier or new.expansion_level > old.expansion_level)
  execute function public.feed_on_company();

create or replace function public.feed_on_art_sale()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  a public.artworks;
begin
  if new.price_cents < public.config_bigint('social', '{feed,artMinPriceCents}', 1000000) then
    return null;
  end if;
  select * into a from public.artworks x where x.id = new.artwork_id;
  perform public.feed_post(new.buyer_id, 'art_won',
    jsonb_build_object('title', a.title, 'code', public.artwork_code(a.serial), 'price_cents', new.price_cents),
    'art_won:' || new.auction_id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_art_sale on public.artwork_sales;
create trigger feed_on_art_sale after insert on public.artwork_sales
  for each row execute function public.feed_on_art_sale();

create or replace function public.feed_on_art_created()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.creator_id, 'art_created',
    jsonb_build_object('title', new.title, 'code', public.artwork_code(new.serial)), 'art_created:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_art_created on public.artworks;
create trigger feed_on_art_created after insert on public.artworks
  for each row when (new.origin = 'player' and new.creator_id is not null) execute function public.feed_on_art_created();

create or replace function public.feed_on_home()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.player_id, 'home_bought', jsonb_build_object('tier', new.tier), null);
  return null;
end;
$$;
drop trigger if exists feed_on_home_insert on public.player_homes;
create trigger feed_on_home_insert after insert on public.player_homes
  for each row when (new.tier is not null) execute function public.feed_on_home();
drop trigger if exists feed_on_home_update on public.player_homes;
create trigger feed_on_home_update after update of tier on public.player_homes
  for each row when (new.tier is not null and new.tier is distinct from old.tier) execute function public.feed_on_home();

create or replace function public.feed_on_car()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.price_paid_cents >= public.config_bigint('social', '{feed,carMinPriceCents}', 10000000) then
    perform public.feed_post(new.player_id, 'car_bought', jsonb_build_object('car_key', new.car_key, 'price_cents', new.price_paid_cents),
                             'car_bought:' || new.id::text);
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_car on public.player_cars;
create trigger feed_on_car after insert on public.player_cars
  for each row execute function public.feed_on_car();

-- title as stored (custom title or the AI title key), title_key for translation (null for custom titles)
create or replace function public.feed_on_job()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.player_id, 'job_started',
    jsonb_build_object('company_name', (select c.name from public.companies c where c.id = new.company_id),
                       'title', new.title, 'title_key', new.title_key),
    'job_started:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_job on public.player_jobs;
create trigger feed_on_job after insert on public.player_jobs
  for each row when (new.application_id is not null) execute function public.feed_on_job();

create or replace function public.feed_on_streak()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from jsonb_array_elements_text(coalesce(public.config_jsonb('social', '{feed,streakMilestones}'),
                                                              '[7, 30, 100, 365]'::jsonb)) m
              where m.value ~ '^[0-9]+$' and m.value::integer = new.current_streak) then
    perform public.feed_post(new.player_id, 'streak', jsonb_build_object('days', new.current_streak),
                             'streak:' || new.player_id::text || ':' || new.current_streak::text || ':'
                             || coalesce(new.last_login_day::text, ''));
  end if;
  return null;
end;
$$;
drop trigger if exists feed_on_streak on public.login_streaks;
create trigger feed_on_streak after update of current_streak on public.login_streaks
  for each row when (new.current_streak > old.current_streak) execute function public.feed_on_streak();

create or replace function public.feed_on_friendship()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.feed_post(new.requester_id, 'friends_now',
    jsonb_build_object('other_nickname', (select p.nickname from public.profiles p where p.id = new.addressee_id)),
    'friends_now:' || new.id::text || ':' || new.requester_id::text);
  perform public.feed_post(new.addressee_id, 'friends_now',
    jsonb_build_object('other_nickname', (select p.nickname from public.profiles p where p.id = new.requester_id)),
    'friends_now:' || new.id::text || ':' || new.addressee_id::text);
  return null;
end;
$$;
drop trigger if exists feed_on_friendship on public.friendships;
create trigger feed_on_friendship after update of status on public.friendships
  for each row when (new.status = 'accepted' and old.status is distinct from 'accepted')
  execute function public.feed_on_friendship();

-- ---------------------------------------------------------------------------
-- D. Notification triggers
-- ---------------------------------------------------------------------------
-- The previous highest bidder of an artwork auction (not when the leader raises the own bid)
create or replace function public.notify_on_outbid()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  a      public.artworks;
  v_nick text;
begin
  select * into a from public.artworks x where x.id = new.artwork_id;
  select p.nickname into v_nick from public.profiles p where p.id = new.leader_id;
  perform public.social_notify(old.leader_id, 'art_outbid', v_nick || ' hat dich überboten',
    '„' || a.title || '“ (' || public.artwork_code(a.serial) || '): neues Gebot ' || public.format_eur(new.current_cents),
    jsonb_build_object('auction_id', new.id, 'artwork_id', a.id, 'code', public.artwork_code(a.serial), 'title', a.title,
                       'amount_cents', new.current_cents, 'nickname', v_nick),
    '/artworks', 'art_outbid:' || new.id::text || ':' || new.bids::text);
  return null;
end;
$$;
drop trigger if exists notify_on_outbid on public.artwork_auctions;
create trigger notify_on_outbid after update of leader_id on public.artwork_auctions
  for each row when (old.leader_id is not null and new.leader_id is not null and new.leader_id <> old.leader_id)
  execute function public.notify_on_outbid();

-- The founder of a player company receives every new application to one of its postings
create or replace function public.notify_on_application()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_founder uuid;
  v_title   text;
  v_nick    text;
begin
  select pc.founder_id, coalesce(jp.title, jp.title_key) into v_founder, v_title
    from public.job_postings jp
    join public.player_companies pc on pc.company_id = jp.company_id and pc.status = 'active'
   where jp.id = new.posting_id and not jp.is_ai;
  if v_founder is null or v_founder = new.player_id then
    return null;
  end if;
  select p.nickname into v_nick from public.profiles p where p.id = new.player_id;
  perform public.social_notify(v_founder, 'job_application', v_nick || ' hat sich beworben', 'Stelle: ' || v_title,
    jsonb_build_object('application_id', new.id, 'posting_id', new.posting_id, 'nickname', v_nick, 'title', v_title),
    '/company', 'job_application:' || new.id::text);
  return null;
end;
$$;
drop trigger if exists notify_on_application on public.job_applications;
create trigger notify_on_application after insert on public.job_applications
  for each row execute function public.notify_on_application();

-- ---------------------------------------------------------------------------
-- E. RPCs: feed
-- ---------------------------------------------------------------------------
-- My items and those of accepted friends, newest first, keyset pagination by id
create or replace function public.get_feed(p_before bigint default null, p_limit integer default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_limit  integer := least(50, greatest(1, coalesce(p_limit,
                        public.config_double('social', '{feed,pageSize}', 30)::integer)));
  v_actors uuid[];
  v_ids    bigint[];
  v_more   boolean;
begin
  select array_agg(x) into v_actors from (select v_player as x union select public.friend_ids(v_player)) f;
  select coalesce(array_agg(x.id order by x.id desc), '{}') into v_ids
    from (select fi.id
            from public.feed_items fi join public.profiles p on p.id = fi.actor_id
           where fi.actor_id = any (v_actors) and not p.is_deactivated
             and (p_before is null or fi.id < p_before)
           order by fi.id desc
           limit v_limit + 1) x;
  v_more := coalesce(array_length(v_ids, 1), 0) > v_limit;
  if v_more then
    v_ids := v_ids[1:v_limit];
  end if;
  return jsonb_build_object(
    'items', coalesce((select jsonb_agg(public.feed_item_json(i.id, v_player) order by i.id desc) from unnest(v_ids) i(id)),
                      '[]'::jsonb),
    'next_before', case when v_more then v_ids[v_limit] end);
end;
$$;
comment on function public.get_feed(bigint, integer) is
  'RPC: friends feed (own items and accepted friends), newest first; p_before = keyset cursor (ADR-088).';

-- Toggles my reaction; the actor is notified once per (item, reactor)
create or replace function public.react_feed(p_request_id uuid, p_item_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  it       public.feed_items;
  v_nick   text;
begin
  v_player := public.require_player();
  if p_request_id is null or p_item_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'react_feed');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  select fi.* into it
    from public.feed_items fi join public.profiles p on p.id = fi.actor_id
   where fi.id = p_item_id and not p.is_deactivated;
  if it.id is null or (it.actor_id <> v_player and it.actor_id not in (select public.friend_ids(v_player))) then
    perform public.api_error('feed_item_not_found');
  end if;
  delete from public.feed_reactions r where r.item_id = it.id and r.player_id = v_player;
  if not found then
    insert into public.feed_reactions (item_id, player_id) values (it.id, v_player) on conflict do nothing;
    if it.actor_id <> v_player then
      select p.nickname into v_nick from public.profiles p where p.id = v_player;
      perform public.social_notify(it.actor_id, 'feed_reaction', v_nick || ' gefällt dein Beitrag',
        public.feed_item_label(it.kind, it.payload),
        jsonb_build_object('item_id', it.id, 'kind', it.kind, 'nickname', v_nick),
        '/friends', 'feed_reaction:' || it.id::text || ':' || v_player::text);
    end if;
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('item', public.feed_item_json(it.id, v_player)));
end;
$$;
comment on function public.react_feed(uuid, bigint) is
  'RPC: toggles the caller''s reaction on a visible feed item -> {item} (ADR-088). Error feed_item_not_found.';

-- ---------------------------------------------------------------------------
-- F. RPCs: notifications
-- ---------------------------------------------------------------------------
create or replace function public.get_notifications(p_limit integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_limit  integer := least(100, greatest(1, coalesce(p_limit, 30)));
begin
  return jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.id, 'type_key', x.type_key, 'title', x.title, 'body', x.body, 'link', x.link,
                                          'payload', x.payload, 'created_at', x.created_at, 'read_at', x.read_at)
                       order by x.created_at desc, x.id)
        from (select n.* from public.notifications n
               where n.player_id = v_player and (n.expires_at is null or n.expires_at > now())
               order by n.created_at desc, n.id limit v_limit) x), '[]'::jsonb),
    'unread', (select count(*) from public.notifications n
                where n.player_id = v_player and n.read_at is null and (n.expires_at is null or n.expires_at > now()))::integer);
end;
$$;
comment on function public.get_notifications(integer) is
  'RPC: the caller''s notifications (not expired), newest first, and the unread count (ADR-088).';

-- null = all; already read rows keep their read_at (idempotent)
create or replace function public.mark_notifications_read(p_ids uuid[] default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
begin
  update public.notifications n set read_at = now()
   where n.player_id = v_player and n.read_at is null and (p_ids is null or n.id = any (p_ids));
  return jsonb_build_object('unread', (select count(*) from public.notifications n
                                        where n.player_id = v_player and n.read_at is null
                                          and (n.expires_at is null or n.expires_at > now()))::integer);
end;
$$;
comment on function public.mark_notifications_read(uuid[]) is
  'RPC: marks the caller''s notifications (all or p_ids) as read -> {unread} (ADR-088).';

-- ---------------------------------------------------------------------------
-- G. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.feed_post(uuid, text, jsonb, text)', 'public.social_notify(uuid, text, text, text, jsonb, text, text)',
    'public.feed_item_label(text, jsonb)', 'public.friend_ids(uuid)', 'public.feed_item_json(bigint, uuid)',
    'public.feed_on_level()', 'public.feed_on_trade()', 'public.feed_on_company()', 'public.feed_on_art_sale()',
    'public.feed_on_art_created()', 'public.feed_on_home()', 'public.feed_on_car()', 'public.feed_on_job()',
    'public.feed_on_streak()', 'public.feed_on_friendship()', 'public.notify_on_outbid()', 'public.notify_on_application()',
    'public.get_feed(bigint, integer)', 'public.react_feed(uuid, bigint)', 'public.get_notifications(integer)',
    'public.mark_notifications_read(uuid[])'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_feed(bigint, integer)', 'public.react_feed(uuid, bigint)', 'public.get_notifications(integer)',
    'public.mark_notifications_read(uuid[])'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261127000200_m4f_league.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4f · 0200 · Weekly league (ADR-089)
-- =============================================================================
-- Season = Berlin calendar week (Monday 00:00 to next Monday 00:00 Europe/Berlin, game time).
-- Every active player gets an entry and a baseline the first time a season is refreshed after
-- they exist: start_net_worth_cents = net worth as in the rich list (rich_list_entries()).
--   growth_bps = round_half_even((current - start - net_inflow) * 10 000 / max(start, social.league.minBaselineCents))
-- net_inflow_cents counts free money (vault basic income, daily reward cash) via triggers on
-- vault_claims and daily_reward_claims; wages, company payouts, trading and art are performance.
-- public.social_run_due() (called by run_due_jobs every minute):
--   1. closes due seasons (final recompute, status finished, winner_id = rank 1, feed item league_won,
--      notification league_result to every ranked participant),
--   2. ensures the current season, refreshes it every social.league.updateEveryMinutes,
--   3. deletes feed items older than social.feed.keepDays (with the refresh).
-- RPC get_league(scope 'all' | 'friends', week 'current' | 'last'); get_player_card gains trophies.
-- Errors: invalid_argument (unknown scope or week).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.league_seasons add column if not exists refreshed_at timestamptz;
comment on column public.league_seasons.refreshed_at is 'Game time of the last standings refresh (ADR-089); null = never.';

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
-- Monday (Europe/Berlin) of the week that contains p_at
create or replace function public.league_week_start(p_at timestamptz)
returns date
language sql
stable
set search_path = ''
as $$
  select (p_at at time zone 'Europe/Berlin')::date - (extract(isodow from (p_at at time zone 'Europe/Berlin'))::integer - 1);
$$;

-- "+3,40 %" / "-0,25 %"
create or replace function public.format_growth_bps(p_bps bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select case when p_bps < 0 then '-' else '+' end
      || replace(to_char(abs(p_bps) / 100.0, 'FM999999990.00'), '.', ',') || ' %';
$$;

-- The season of the week that contains p_at (created as active if missing)
create or replace function public.league_ensure_season(p_at timestamptz)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_week date := public.league_week_start(p_at);
  v_id   uuid;
begin
  insert into public.league_seasons (week_start, starts_at, ends_at, status)
  values (v_week, v_week::timestamp at time zone 'Europe/Berlin', (v_week + 7)::timestamp at time zone 'Europe/Berlin', 'active')
  on conflict (week_start) do nothing;
  select s.id into v_id from public.league_seasons s where s.week_start = v_week;
  return v_id;
end;
$$;

-- Free money of a player counts as inflow of every open season that has started
create or replace function public.league_add_inflow(p_player uuid, p_cents bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_player is null or coalesce(p_cents, 0) = 0 then
    return;
  end if;
  update public.league_entry_baselines b
     set net_inflow_cents = b.net_inflow_cents + p_cents, updated_at = now()
    from public.league_seasons s
   where s.id = b.season_id and b.player_id = p_player and s.status <> 'finished' and s.starts_at <= public.game_now();
end;
$$;

-- Net worth, growth and rank of one season. p_add_new: active players without an entry join
-- with their current net worth as baseline. Returns the number of ranked entries.
create or replace function public.league_refresh(p_season uuid, p_add_new boolean default true)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_min   bigint := greatest(1, public.config_bigint('social', '{league,minBaselineCents}', 1000000));
  v_count integer;
begin
  with nw as materialized (
    select e.entity_id as player_id, e.net_worth_cents as nw
      from public.rich_list_entries() e where e.entity_kind = 'player'
  ), new_entries as (
    insert into public.league_entries (season_id, player_id)
    select p_season, n.player_id from nw n
     where p_add_new
       and not exists (select 1 from public.league_entries x where x.season_id = p_season and x.player_id = n.player_id)
    on conflict do nothing
    returning player_id
  ), new_baselines as (
    insert into public.league_entry_baselines (season_id, player_id, start_net_worth_cents, current_net_worth_cents)
    select p_season, x.player_id, n.nw, n.nw from new_entries x join nw n on n.player_id = x.player_id
    on conflict do nothing
    returning player_id
  )
  update public.league_entry_baselines b
     set current_net_worth_cents = n.nw, updated_at = now()
    from nw n
   where b.season_id = p_season and b.player_id = n.player_id and b.current_net_worth_cents <> n.nw;

  update public.league_entries e
     set growth_bps = greatest(-2000000000, least(2000000000, public.div_round_half_even(
                        (b.current_net_worth_cents - b.start_net_worth_cents - b.net_inflow_cents)::numeric * 10000,
                        greatest(b.start_net_worth_cents, v_min))))::integer,
         updated_at = now()
    from public.league_entry_baselines b
   where e.season_id = p_season and b.season_id = e.season_id and b.player_id = e.player_id;

  -- rank: growth, then the earlier account, then nickname; deactivated players are not ranked
  update public.league_entries e set rank = r.rk
    from (select x.player_id,
                 (row_number() over (order by x.growth_bps desc, p.created_at, lower(p.nickname), p.id))::integer as rk
            from public.league_entries x join public.profiles p on p.id = x.player_id
           where x.season_id = p_season and not p.is_deactivated) r
   where e.season_id = p_season and e.player_id = r.player_id and e.rank is distinct from r.rk;
  update public.league_entries e set rank = null
   where e.season_id = p_season and e.rank is not null
     and exists (select 1 from public.profiles p where p.id = e.player_id and p.is_deactivated);

  update public.league_seasons set refreshed_at = public.game_now(), updated_at = now() where id = p_season;
  select count(*) into v_count from public.league_entries e where e.season_id = p_season and e.rank is not null;
  return v_count;
end;
$$;

-- Final recompute, winner, feed item league_won, league_result for every ranked participant
create or replace function public.league_close(p_season uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  s        public.league_seasons;
  v_count  integer;
  v_winner uuid;
  v_growth integer;
  r        record;
begin
  select * into s from public.league_seasons x where x.id = p_season for update;
  if s.id is null or s.status = 'finished' then
    return null;
  end if;
  v_count := public.league_refresh(p_season, false);
  select e.player_id, e.growth_bps into v_winner, v_growth
    from public.league_entries e where e.season_id = p_season and e.rank = 1;
  update public.league_seasons set status = 'finished', winner_id = v_winner, updated_at = now() where id = p_season;
  if v_winner is not null then
    perform public.feed_post(v_winner, 'league_won', jsonb_build_object('week_start', s.week_start, 'growth_bps', v_growth),
                             'league_won:' || p_season::text);
  end if;
  for r in select e.player_id, e.rank, e.growth_bps from public.league_entries e
            where e.season_id = p_season and e.rank is not null order by e.rank
  loop
    perform public.social_notify(r.player_id, 'league_result',
      case when r.rank = 1 then 'Du hast die Wochenliga gewonnen!' else 'Wochenliga: Platz ' || r.rank end,
      'Platz ' || r.rank || ' von ' || v_count || ' · ' || public.format_growth_bps(r.growth_bps),
      jsonb_build_object('week_start', s.week_start, 'rank', r.rank, 'of', v_count, 'growth_bps', r.growth_bps),
      '/friends', 'league_result:' || p_season::text);
  end loop;
  return jsonb_build_object('week_start', s.week_start, 'entries', v_count, 'winner', v_winner);
end;
$$;

-- Periodic social work, called by run_due_jobs every minute (throttled here)
create or replace function public.social_run_due()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := public.game_now();
  v_closed  jsonb := '[]'::jsonb;
  v_season  uuid;
  v_last    timestamptz;
  v_count   integer;
  v_deleted bigint := 0;
  q         record;
begin
  for q in select s.id from public.league_seasons s
            where s.status <> 'finished' and s.ends_at <= v_now order by s.ends_at limit 8
  loop
    v_closed := v_closed || coalesce(public.league_close(q.id), 'null'::jsonb);
  end loop;
  v_season := public.league_ensure_season(v_now);
  select s.refreshed_at into v_last from public.league_seasons s where s.id = v_season;
  if v_last is not null
     and v_last > v_now - make_interval(secs => greatest(1, public.config_double('social', '{league,updateEveryMinutes}', 10)) * 60 - 5) then
    return jsonb_build_object('closed', v_closed, 'skipped', 'recent');
  end if;
  v_count := public.league_refresh(v_season, true);
  delete from public.feed_items fi
   where fi.created_at < now() - make_interval(days => greatest(1, public.config_double('social', '{feed,keepDays}', 30))::integer);
  get diagnostics v_deleted = row_count;
  return jsonb_build_object('closed', v_closed, 'league_entries', v_count, 'feed_deleted', v_deleted);
end;
$$;

-- ---------------------------------------------------------------------------
-- C. Free money as league inflow
-- ---------------------------------------------------------------------------
create or replace function public.league_on_vault_claim()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.league_add_inflow(new.player_id, new.amount_cents);
  return null;
end;
$$;
drop trigger if exists league_on_vault_claim on public.vault_claims;
create trigger league_on_vault_claim after insert on public.vault_claims
  for each row when (new.amount_cents > 0) execute function public.league_on_vault_claim();

create or replace function public.league_on_daily_reward()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.league_add_inflow(new.player_id, new.cash_cents);
  return null;
end;
$$;
drop trigger if exists league_on_daily_reward on public.daily_reward_claims;
create trigger league_on_daily_reward after insert on public.daily_reward_claims
  for each row when (new.cash_cents > 0) execute function public.league_on_daily_reward();

-- ---------------------------------------------------------------------------
-- D. RPC get_league
-- ---------------------------------------------------------------------------
create or replace function public.get_league(p_scope text default 'all', p_week text default 'current')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_now     timestamptz := public.game_now();
  v_current date := public.league_week_start(v_now);
  v_week    date;
  s         public.league_seasons;
  v_entries jsonb;
  v_me      jsonb;
  v_last    jsonb;
begin
  if p_scope is null or p_scope not in ('all', 'friends') or p_week is null or p_week not in ('current', 'last') then
    perform public.api_error('invalid_argument');
  end if;
  v_week := case when p_week = 'last' then v_current - 7 else v_current end;
  select * into s from public.league_seasons x where x.week_start = v_week;

  with x as (
    select e.player_id, e.growth_bps, p.nickname, p.tag, p.avatar_key, p.level,
           (row_number() over (order by e.rank nulls last, e.growth_bps desc, p.created_at, lower(p.nickname), p.id))::integer as rk
      from public.league_entries e join public.profiles p on p.id = e.player_id
     where e.season_id = s.id and not p.is_deactivated
       and (p_scope = 'all' or e.player_id = v_player or e.player_id in (select public.friend_ids(v_player)))
  )
  select coalesce(jsonb_agg(jsonb_build_object('rank', x.rk, 'nickname', x.nickname, 'tag', x.tag, 'avatar_key', x.avatar_key,
                                               'level', x.level, 'growth_bps', x.growth_bps, 'is_me', x.player_id = v_player)
                            order by x.rk) filter (where x.rk <= 100), '[]'::jsonb),
         (select jsonb_build_object('rank', y.rk, 'growth_bps', y.growth_bps) from x y where y.player_id = v_player)
    into v_entries, v_me
    from x;

  select jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'growth_bps', e.growth_bps,
                            'week_start', ls.week_start)
    into v_last
    from public.league_seasons ls
    join public.profiles p on p.id = ls.winner_id
    join public.league_entries e on e.season_id = ls.id and e.player_id = ls.winner_id
   where ls.status = 'finished' and ls.week_start < v_current and not p.is_deactivated
   order by ls.week_start desc
   limit 1;

  return jsonb_build_object(
    'season', jsonb_build_object(
      'week_start', v_week,
      'starts_at',  coalesce(s.starts_at, v_week::timestamp at time zone 'Europe/Berlin'),
      'ends_at',    coalesce(s.ends_at, (v_week + 7)::timestamp at time zone 'Europe/Berlin'),
      'status',     coalesce(s.status::text, case when p_week = 'last' then 'finished' else 'active' end)),
    'entries', v_entries,
    'me', v_me,
    'last_winner', v_last);
end;
$$;
comment on function public.get_league(text, text) is
  'RPC: weekly league standings (ADR-089); scope all | friends (me + accepted friends, re-numbered), week current | last.';

-- ---------------------------------------------------------------------------
-- E. get_player_card as in M4d plus trophies (closed seasons, ranks 1..3 within social.league.podium)
-- ---------------------------------------------------------------------------
create or replace function public.get_player_card(p_nickname text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  p      public.profiles;
  v_job  jsonb;
  v_pod  integer := least(3, greatest(0, public.config_double('social', '{league,podium}', 3)::integer));
begin
  perform public.require_player();
  select * into p from public.profiles x where x.id = public.player_by_handle(p_nickname);
  if p.id is null then
    perform public.api_error('player_not_found');
  end if;
  select jsonb_build_object('company_name', c.name, 'title_key', j.title_key, 'title', case when j.title_key is null then j.title end,
                            'tier', j.tier, 'since', j.started_at)
    into v_job
    from public.player_jobs j join public.companies c on c.id = j.company_id
   where j.player_id = p.id and j.status = 'active';
  return jsonb_build_object(
    'nickname',        p.nickname,
    'tag',             p.tag,
    'avatar_key',      p.avatar_key,
    'level',           p.level,
    'rank',            public.player_rich_rank(p.id),
    'net_worth_cents', public.player_net_worth_cents(p.id),
    'streak_days',     public.player_streak_days(p.id),
    'skills_learned',  (select count(*) from public.player_skills s where s.player_id = p.id)::integer,
    'branch_scores',   public.player_branch_scores(p.id),
    'top_skills',      coalesce((select jsonb_agg(jsonb_build_object('key', x.skill_key, 'tier', x.tier) order by x.tier desc, x.learned_at)
                                   from (select s.skill_key, s.learned_at, (public.skill_node(s.skill_key) ->> 'tier')::integer as tier
                                           from public.player_skills s where s.player_id = p.id
                                          order by 3 desc nulls last, s.learned_at limit 3) x), '[]'::jsonb),
    'job',             v_job,
    'company',         (select jsonb_build_object('name', c.name, 'ticker', c.ticker)
                          from public.player_companies pc join public.companies c on c.id = pc.company_id
                         where pc.founder_id = p.id and pc.status = 'active'),
    'trophies',        (select jsonb_build_object('gold',   count(*) filter (where e.rank = 1),
                                                  'silver', count(*) filter (where e.rank = 2),
                                                  'bronze', count(*) filter (where e.rank = 3))
                          from public.league_entries e join public.league_seasons ls on ls.id = e.season_id
                         where e.player_id = p.id and ls.status = 'finished' and e.rank between 1 and v_pod),
    'member_since',    p.created_at);
end;
$$;

-- ---------------------------------------------------------------------------
-- F. run_due_jobs as in M4a plus the social work (league, feed clean-up)
-- ---------------------------------------------------------------------------
create or replace function public.run_due_jobs()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- player companies: operating hours (ADR-072), then every closed quarter since their founding (ADR-057)
  v_result := v_result || jsonb_build_object('player_companies', public.player_companies_run_due());

  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- jobs: AI postings of the running quarter, wages of AI-company jobs in whole hours
  v_result := v_result || jsonb_build_object('quit_notices', public.process_quit_notices(null));
  v_result := v_result || jsonb_build_object('share_offers', public.close_due_offers(null));
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  -- artworks (ADR-080): due auctions are settled, the gallery starts the auctions of the day
  v_result := v_result || jsonb_build_object('artworks', public.artworks_run_due());

  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- weekly league and feed clean-up (ADR-088, ADR-089), throttled inside
  v_result := v_result || jsonb_build_object('social', public.social_run_due());

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.league_week_start(timestamptz)', 'public.format_growth_bps(bigint)', 'public.league_ensure_season(timestamptz)',
    'public.league_add_inflow(uuid, bigint)', 'public.league_refresh(uuid, boolean)', 'public.league_close(uuid)',
    'public.social_run_due()', 'public.league_on_vault_claim()', 'public.league_on_daily_reward()',
    'public.get_league(text, text)', 'public.get_player_card(text)', 'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array['public.get_league(text, text)', 'public.get_player_card(text)'] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261128000100_m4g_events.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4g · 0100 · Announced events (ADR-090)
-- =============================================================================
-- Plans and resolves the rows of public.scheduled_events (created in 1100, unused until now):
--   opening_bell / closing_bell  daily at time.marketOpenHour / marketCloseHour (Europe/Berlin), informational
--   earnings      at the end of every game quarter for the events.schedule.earningsTopCompanies largest
--                 AI companies by market cap; outcome from company_quarter_reports (the earnings sentiment
--                 itself is applied by simulate_ai_companies at the quarter close, unchanged)
--   pharma_trial  per pharma AI company and quarter with events.pharmaTrial.probabilityPerQuarter,
--                 announced announceLeadQuarters ahead (scheduled in the middle of that quarter); the hidden
--                 success probability (by size class) lives in scheduled_event_secrets. Resolution mirrors
--                 resolvePharmaTrial (src/lib/sim/events.ts): the move is a real, persistent price shock;
--                 fair value, EMAs and the new security_sim_state.event_value_factor move by the same factor
--                 (fair_value_from_fundamentals multiplies by it), so value funds do not revert the jump
--   rate_decision on isRateDecisionQuarter quarters (src/lib/sim/central-bank.ts), announced once the
--                 quarter announceLeadQuarters before has ended; decidePolicyRate on the per-capita growth of
--                 the money supply (player + player-company accounts per active player) against the
--                 money_supply_snapshots row measurementWindowQuarters earlier (no such row: rate held)
-- Every event is planned at most events.schedule.horizonHours ahead and idempotently (dedupe_key).
-- run_due_jobs() calls events_run_due(): planning every 15 minutes, resolution of due events every
-- minute (late events after a downtime are resolved once), a money supply snapshot per closed quarter.
-- Holders of a pharma stock get the notification event_holding.
-- New RPC get_events(p_limit) -> {server_time, upcoming: [EVENT], recent: [EVENT]}
--   EVENT = {id, kind, importance, scheduled_at, announced_at, status, ticker, company_name, sector, outcome}
--   outcome null until resolved; bells {}; earnings {revenue_cents, net_income_cents, eps_e4,
--   revenue_change_bps, net_income_change_bps, surprise: beat|miss|inline}; pharma_trial {success, move_bps,
--   price_before_e4, price_after_e4}; rate_decision {old_bps, new_bps, money_growth_bps (null: no measurement)}
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.security_sim_state
  add column if not exists event_value_factor double precision not null default 1;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'security_sim_state_event_value_factor_check'
                    and conrelid = 'public.security_sim_state'::regclass) then
    alter table public.security_sim_state add constraint security_sim_state_event_value_factor_check
      check (event_value_factor > 0);
  end if;
end;
$$;
comment on column public.security_sim_state.event_value_factor is
  'Multiplier on the fair value from binary events (pharma trials, ADR-090), 1 = neutral. Mirrors eventValueFactor in src/lib/sim/fair-value.ts.';

alter table public.money_supply_snapshots add column if not exists active_players integer;
comment on column public.money_supply_snapshots.active_players is
  'Players with a daily login in the last centralBank.activePlayerWindowDays days when the snapshot was taken (per-capita money growth, ADR-090).';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('event_holding', 'market', 'Ereignis in deinem Depot', 'Ein angekündigtes Ereignis hat eine Aktie aus deinem Depot bewegt.',
        'notif_clock', true, false, false, 105)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Fair value with the event factor (as in M1, times security_sim_state.event_value_factor)
-- ---------------------------------------------------------------------------
create or replace function public.fair_value_from_fundamentals(p_company_id uuid)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c        public.companies;
  v_val    jsonb := coalesce(public.config_jsonb('valuation'), '{}'::jsonb);
  v_sec    jsonb;
  v_policy integer;
  v_pe     double precision;
  v_growth double precision := 0;
  v_recent numeric;
  v_prev   numeric;
  v_n      integer;
  v_macro  double precision;
  v_event  double precision;
  v_fv     double precision;
begin
  select * into c from public.companies where id = p_company_id;
  if c.id is null or c.shares_outstanding <= 0 or c.ttm_net_income_cents <= 0 then
    return null;
  end if;
  v_sec := coalesce(public.config_jsonb('sectors', array[c.sector_key]), '{}'::jsonb);
  v_pe := public.cfg_num(v_sec, '{peRatio}', coalesce((select s.base_pe from public.sectors s where s.key = c.sector_key), 15));
  select count(*), sum(x.revenue_cents) filter (where x.rn <= 4), sum(x.revenue_cents) filter (where x.rn > 4)
    into v_n, v_recent, v_prev
    from (select r.revenue_cents, row_number() over (order by gq.starts_at desc) as rn
            from public.company_quarter_reports r
            join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = c.id and r.published_at is not null
           order by gq.starts_at desc limit 8) x;
  if v_n >= 8 and v_prev > 0 then
    v_growth := v_recent / v_prev - 1;
  end if;
  select cb.policy_rate_bps into v_policy from public.central_bank_state cb where cb.id;
  v_macro := greatest(public.cfg_num(v_val, '{macroFactorMin}', 0.6), least(public.cfg_num(v_val, '{macroFactorMax}', 1.3),
               1 - public.cfg_num(v_val, '{macroSensitivityPer100Bps}', 0.04)
                 * public.cfg_num(v_sec, '{sensitivity,valuationRate}', 1)
                 * (coalesce(v_policy, 300) - public.config_double('centralBank', '{neutralRateBps}', 300)) / 100.0));
  -- binary events (pharma trials, ADR-090): the fair value follows the price shock
  select st.event_value_factor into v_event from public.security_sim_state st where st.security_id = c.security_id;
  v_fv := (c.ttm_net_income_cents::double precision / c.shares_outstanding)        -- EPS in cents
        * v_pe
        * greatest(public.cfg_num(v_val, '{growthFactorMin}', 0.6),
                   least(public.cfg_num(v_val, '{growthFactorMax}', 1.8), 1 + public.cfg_num(v_val, '{growthWeight}', 1) * v_growth))
        * v_macro
        * coalesce(v_event, 1)
        * 100;                                                                        -- cents -> e4
  return greatest(public.config_double('trading', '{minPriceE4}', 1)::bigint, round(v_fv)::bigint);
end;
$$;

-- ---------------------------------------------------------------------------
-- C. Helpers
-- ---------------------------------------------------------------------------
-- Game quarter by running index (0 = first quarter of game year 1), NULL row if it does not exist.
create or replace function public.game_quarter_by_index(p_index integer)
returns public.game_quarters
language sql
stable
security definer
set search_path = ''
as $$
  select gq.* from public.game_quarters gq
   where p_index >= 0 and gq.game_year = p_index / 4 + 1 and gq.quarter = p_index % 4 + 1;
$$;
comment on function public.game_quarter_by_index(integer) is
  'Internal (ADR-090): game quarter by running index (game_year - 1) * 4 + quarter - 1.';

-- Money supply sample (MoneySupplySample in src/lib/sim/central-bank.ts): all player and player-company
-- accounts (cash and reserve; AI companies are not part of the money supply), players with a daily login
-- in the last centralBank.activePlayerWindowDays days.
create or replace function public.events_money_sample(p_now timestamptz, out money_supply_cents bigint, out active_players integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_days integer := greatest(1, public.config_double('centralBank', '{activePlayerWindowDays}', 7))::integer;
begin
  select coalesce(sum(a.balance_cents), 0)::bigint into money_supply_cents
    from public.ledger_accounts a
    left join public.companies c on c.id = a.owner_company_id
   where a.kind in ('player_cash', 'player_reserve')
      or (a.kind in ('company_cash', 'company_reserve') and c.id is not null and not c.is_ai);
  select count(distinct dl.player_id)::integer into active_players
    from public.daily_logins dl
    join public.profiles p on p.id = dl.player_id
   where dl.login_day > (p_now at time zone 'Europe/Berlin')::date - v_days
     and dl.login_day <= (p_now at time zone 'Europe/Berlin')::date
     and not p.is_deactivated;
end;
$$;
comment on function public.events_money_sample(timestamptz) is
  'Internal (ADR-090): money supply of players and player companies, active players (central bank input).';

-- Snapshot of the money supply for the latest ended quarter (once per quarter; no backfill after a downtime).
create or replace function public.events_snapshot_money(p_now timestamptz)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_q      bigint;
  v_player bigint;
  v_comp   bigint;
  v_sample record;
  v_rows   integer;
begin
  select gq.id into v_q from public.game_quarters gq where gq.ends_at <= p_now order by gq.ends_at desc limit 1;
  if v_q is null or exists (select 1 from public.money_supply_snapshots m where m.game_quarter_id = v_q) then
    return null;
  end if;
  select coalesce(sum(a.balance_cents), 0)::bigint into v_player
    from public.ledger_accounts a where a.kind in ('player_cash', 'player_reserve');
  select * into v_sample from public.events_money_sample(p_now);
  v_comp := v_sample.money_supply_cents - v_player;
  insert into public.money_supply_snapshots (game_quarter_id, player_cents, company_cents, active_players)
  values (v_q, v_player, v_comp, v_sample.active_players)
  on conflict (game_quarter_id) do nothing;
  get diagnostics v_rows = row_count;
  return case when v_rows > 0 then v_q end;
end;
$$;
comment on function public.events_snapshot_money(timestamptz) is
  'Internal (ADR-090): money_supply_snapshots row of the latest ended quarter (players, player companies, active players).';

-- In-app notification, unless the player switched the type off (missing preference: the type's default)
create or replace function public.event_notify(p_player uuid, p_title text, p_body text, p_payload jsonb, p_link text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.notification_types t where t.key = 'event_holding') then
    return;
  end if;
  if not coalesce((select np.in_app_enabled from public.notification_preferences np
                    where np.player_id = p_player and np.type_key = 'event_holding'),
                  (select t.default_in_app from public.notification_types t where t.key = 'event_holding'), true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (p_player, 'event_holding', p_title, p_body, coalesce(p_payload, '{}'::jsonb), p_link, p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;
comment on function public.event_notify(uuid, text, text, jsonb, text, text) is
  'Internal (ADR-090): event_holding notification, respecting the player''s preference.';

-- Persistent price shock of one stock by (10 000 + p_move_bps) / 10 000: quote, fair value, event factor and
-- EMAs move together (no momentum signal, no value-fund reversion), plus a price tick and the candles.
create or replace function public.event_price_shock(p_security uuid, p_move_bps integer, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_epoch   constant timestamptz := '2000-01-01 00:00:00+00';
  v_min     bigint := greatest(1, public.config_double('trading', '{minPriceE4}', 1))::bigint;
  v_mult    numeric := greatest(1, 10000 + p_move_bps)::numeric;   -- MIN_EVENT_FACTOR 0.01 at -9 900 bps
  v_factor  double precision := greatest(1, 10000 + p_move_bps)::double precision / 10000;
  q         public.security_quotes;
  v_shares  bigint;
  v_before  bigint;
  v_after   bigint;
  v_bid     bigint;
  v_ask     bigint;
  v_ref     bigint;
  v_seq     bigint;
begin
  -- same lock order as market_tick_at: sim state first, then the quote
  update public.security_sim_state st
     set fair_value_e4 = greatest(v_min, public.div_round_half_even(st.fair_value_e4::numeric * v_mult, 10000)),
         event_value_factor = st.event_value_factor * v_factor,
         ema_fast = case when st.ema_fast is null then null else st.ema_fast * v_factor end,
         ema_slow = case when st.ema_slow is null then null else st.ema_slow * v_factor end,
         updated_at = now()
   where st.security_id = p_security;
  select * into q from public.security_quotes where security_id = p_security for update;
  if not found then
    return null;
  end if;
  select c.shares_outstanding into v_shares
    from public.securities s left join public.companies c on c.id = s.company_id where s.id = p_security;
  v_before := q.last_price_e4;
  v_after := greatest(v_min, public.div_round_half_even(v_before::numeric * v_mult, 10000));
  v_bid := greatest(v_min, public.div_round_half_even(coalesce(q.bid_e4, v_before)::numeric * v_mult, 10000));
  v_ask := public.div_round_half_even(coalesce(q.ask_e4, v_before)::numeric * v_mult, 10000);
  if v_ask <= v_bid then
    v_ask := v_bid + 1;
  end if;
  v_ref := coalesce(q.prev_close_e4, v_before);
  update public.security_quotes
     set last_price_e4 = v_after, bid_e4 = v_bid, ask_e4 = v_ask,
         day_high_e4 = greatest(coalesce(day_high_e4, v_after), v_after),
         day_low_e4 = least(coalesce(day_low_e4, v_after), v_after),
         change_bps = greatest(-1000000, least(1000000, round((v_after - v_ref) * 10000.0 / greatest(1, v_ref))))::integer,
         market_cap_cents = case when v_shares is null then market_cap_cents
                                 else public.div_round_half_even(v_shares::numeric * v_after, 100) end,
         updated_at = p_now
   where security_id = p_security;

  select r.tick_seq into v_seq from public.sim_runtime r where r.id;
  insert into public.price_ticks (security_id, ts, tick_seq, price_e4, volume_e6)
  values (p_security, p_now, coalesce(v_seq, 0), v_after, 0)
  on conflict do nothing;
  insert into public.candles as c (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select p_security, iv.i, iv.b, v_before, greatest(v_before, v_after), least(v_before, v_after), v_after, 0, 1
    from (values
      ('1m'::public.candle_interval, date_bin('1 minute', p_now, v_epoch)),
      ('5m'::public.candle_interval, date_bin('5 minutes', p_now, v_epoch)),
      ('1h'::public.candle_interval, date_bin('1 hour', p_now, v_epoch)),
      ('1q'::public.candle_interval, public.quarter_bucket_start(p_now)),
      ('1y'::public.candle_interval, public.game_year_bucket_start(p_now))) as iv(i, b)
  on conflict (security_id, interval, bucket_start) do update
     set high_e4 = greatest(c.high_e4, excluded.high_e4),
         low_e4 = least(c.low_e4, excluded.low_e4),
         close_e4 = excluded.close_e4,
         tick_count = c.tick_count + 1;
  return jsonb_build_object('price_before_e4', v_before, 'price_after_e4', v_after);
end;
$$;
comment on function public.event_price_shock(uuid, integer, timestamptz) is
  'Internal (ADR-090): persistent price shock; quote, fair value, event factor and EMAs move by the same factor.';

-- ---------------------------------------------------------------------------
-- D. Planning (idempotent; p_now is the game time, tests pin it)
-- ---------------------------------------------------------------------------
create or replace function public.events_plan(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ev       jsonb := coalesce(public.config_jsonb('events'), '{}'::jsonb);
  v_cb       jsonb := coalesce(public.config_jsonb('centralBank'), '{}'::jsonb);
  v_time     jsonb := coalesce(public.config_jsonb('time'), '{}'::jsonb);
  v_horizon  timestamptz := p_now + make_interval(secs => greatest(0, public.cfg_num(v_ev, '{schedule,horizonHours}', 24)) * 3600);
  v_top      integer := greatest(0, public.cfg_num(v_ev, '{schedule,earningsTopCompanies}', 3))::integer;
  v_open_h   double precision := public.cfg_num(v_time, '{marketOpenHour}', 8);
  v_close_h  double precision := public.cfg_num(v_time, '{marketCloseHour}', 22);
  v_p_trial  double precision := public.cfg_num(v_ev, '{pharmaTrial,probabilityPerQuarter}', 0.12);
  v_lead     integer := greatest(0, public.cfg_num(v_ev, '{pharmaTrial,announceLeadQuarters}', 2))::integer;
  v_warmup   integer := public.cfg_num(v_cb, '{warmupQuarters}', 56)::integer;
  v_every    integer := greatest(1, public.cfg_num(v_cb, '{decisionEveryQuarters}', 2))::integer;
  v_cb_lead  integer := greatest(0, public.cfg_num(v_cb, '{announceLeadQuarters}', 1))::integer;
  v_day      date;
  v_at       timestamptz;
  v_bells    integer := 0;
  v_earn     integer := 0;
  v_trials   integer := 0;
  v_rates    integer := 0;
  v_rows     integer;
  v_id       uuid;
  v_cur      public.game_quarters;
  v_target   public.game_quarters;
  v_ann      public.game_quarters;
  v_idx      integer;
  v_run      bigint;
  q          record;
  r          record;
begin
  -- 1. bells (Berlin wall clock, every day)
  for v_day in
    select d::date from generate_series((p_now at time zone 'Europe/Berlin')::date::timestamp,
                                        (v_horizon at time zone 'Europe/Berlin')::date::timestamp, interval '1 day') d
  loop
    for r in select * from (values ('opening_bell'::public.scheduled_event_kind, v_open_h, 'Börsenöffnung'),
                                   ('closing_bell'::public.scheduled_event_kind, v_close_h, 'Börsenschluss')) b(kind, hour, title)
    loop
      v_at := (v_day::timestamp + make_interval(secs => r.hour * 3600)) at time zone 'Europe/Berlin';
      if v_at > p_now and v_at <= v_horizon then
        insert into public.scheduled_events (kind, title, importance, game_quarter_id, dedupe_key, announced_at, scheduled_at)
        values (r.kind, r.title, 1,
                (select gq.id from public.game_quarters gq where gq.starts_at <= v_at and gq.ends_at > v_at),
                r.kind::text || ':' || to_char(v_day, 'YYYY-MM-DD'), p_now, v_at)
        on conflict (dedupe_key) do nothing;
        get diagnostics v_rows = row_count;
        v_bells := v_bells + v_rows;
      end if;
    end loop;
  end loop;

  -- 2. earnings: the largest AI companies by market cap, once per quarter
  for q in
    select gq.* from public.game_quarters gq
     where gq.ends_at > p_now and gq.ends_at <= v_horizon
       and not exists (select 1 from public.scheduled_events e where e.kind = 'earnings' and e.game_quarter_id = gq.id)
     order by gq.ends_at
  loop
    insert into public.scheduled_events (kind, title, importance, company_id, security_id, sector_key, game_quarter_id,
                                         dedupe_key, announced_at, scheduled_at)
    select 'earnings', 'Quartalszahlen ' || x.name, 2, x.id, x.security_id, x.sector_key, q.id,
           'earnings:' || q.id || ':' || x.id, p_now, q.ends_at
      from (select c.id, c.name, c.security_id, c.sector_key
              from public.companies c
              join public.securities s on s.id = c.security_id
              join public.security_quotes sq on sq.security_id = c.security_id
             where c.is_ai and c.phase = 'listed' and s.status = 'listed'
             order by sq.market_cap_cents desc nulls last, c.ticker
             limit v_top) x
    on conflict (dedupe_key) do nothing;
    get diagnostics v_rows = row_count;
    v_earn := v_earn + v_rows;
  end loop;

  -- 3. pharma trials: one roll per pharma AI company and running quarter (rollPharmaTrialAnnouncement)
  select gq.* into v_cur from public.game_quarters gq where gq.starts_at <= p_now and gq.ends_at > p_now;
  if v_cur.id is not null then
    insert into public.job_runs (job_name, run_key, status, finished_at)
    values ('events_pharma_roll', v_cur.id::text, 'succeeded', now())
    on conflict (job_name, run_key) do nothing
    returning id into v_run;
    if v_run is not null then
      v_target := public.game_quarter_by_index((v_cur.game_year - 1) * 4 + v_cur.quarter - 1 + v_lead);
      if v_target.id is not null then
        v_at := v_target.starts_at + (v_target.ends_at - v_target.starts_at) / 2;
        for r in
          select c.id, c.name, c.security_id, c.sector_key, c.tier::text as tier
            from public.companies c join public.securities s on s.id = c.security_id
           where c.is_ai and c.phase = 'listed' and s.status = 'listed' and c.sector_key = 'pharma'
             and not exists (select 1 from public.scheduled_events e
                              where e.kind = 'pharma_trial' and e.company_id = c.id and e.status in ('scheduled', 'in_progress'))
           order by c.ticker
        loop
          if v_at > p_now and v_at <= v_horizon and random() < v_p_trial then
            v_id := null;
            insert into public.scheduled_events (kind, title, importance, company_id, security_id, sector_key, game_quarter_id,
                                                 dedupe_key, announced_at, scheduled_at)
            values ('pharma_trial', 'Studienergebnis ' || r.name, 3, r.id, r.security_id, r.sector_key, v_target.id,
                    'pharma_trial:' || r.id || ':' || v_target.id, p_now, v_at)
            on conflict (dedupe_key) do nothing
            returning id into v_id;
            if v_id is not null then
              insert into public.scheduled_event_secrets (event_id, params)
              values (v_id, jsonb_build_object('success_probability',
                        public.cfg_num(v_ev, array['pharmaTrial', 'successProbability', r.tier], 0.5)));
              v_trials := v_trials + 1;
            end if;
          end if;
        end loop;
      end if;
    end if;
  end if;

  -- 4. rate decisions (isRateDecisionQuarter, rateDecisionAnnouncementQuarter)
  for q in
    select gq.*, (gq.game_year - 1) * 4 + gq.quarter - 1 as idx from public.game_quarters gq
     where gq.ends_at > p_now and gq.ends_at <= v_horizon
     order by gq.ends_at
  loop
    v_idx := q.idx;
    if v_idx < v_warmup or v_idx % v_every <> v_every - 1 then
      continue;
    end if;
    if v_cb_lead > 0 then
      v_ann := public.game_quarter_by_index(v_idx - v_cb_lead);
      if v_ann.id is null or v_ann.ends_at > p_now then
        continue;
      end if;
    end if;
    insert into public.scheduled_events (kind, title, importance, game_quarter_id, dedupe_key, announced_at, scheduled_at)
    values ('rate_decision', 'Zinsentscheid der Zentralbank', 3, q.id, 'rate_decision:' || q.id, p_now, q.ends_at)
    on conflict (dedupe_key) do nothing;
    get diagnostics v_rows = row_count;
    if v_rows > 0 then
      v_rates := v_rates + 1;
      update public.central_bank_state set next_decision_at = q.ends_at, updated_at = now() where id;
    end if;
  end loop;

  return jsonb_build_object('bells', v_bells, 'earnings', v_earn, 'pharma_trials', v_trials, 'rate_decisions', v_rates);
end;
$$;
comment on function public.events_plan(timestamptz) is
  'Internal (ADR-090): plans bells, earnings, pharma trials and rate decisions up to events.schedule.horizonHours ahead (idempotent).';

-- ---------------------------------------------------------------------------
-- E. Resolution
-- ---------------------------------------------------------------------------
-- Rate decision (decidePolicyRate, moneyGrowthBps, annualizeGrowthBps in src/lib/sim/central-bank.ts).
create or replace function public.event_rate_decision(p_quarter_id bigint, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cb      jsonb := coalesce(public.config_jsonb('centralBank'), '{}'::jsonb);
  v_window  integer := public.cfg_num(v_cb, '{measurementWindowQuarters}', 4)::integer;
  v_qpy     double precision := greatest(1, public.config_double('time', '{quartersPerGameYear}', 4));
  v_neutral integer := public.cfg_num(v_cb, '{neutralRateBps}', 300)::integer;
  v_step    integer := public.cfg_num(v_cb, '{stepBps}', 25)::integer;
  v_maxst   integer := public.cfg_num(v_cb, '{maxStepsPerDecision}', 2)::integer;
  v_band    double precision := greatest(1, public.cfg_num(v_cb, '{toleranceBandBps}', 400));
  v_tgt     integer := public.cfg_num(v_cb, '{targetMoneyGrowthBps}', 800)::integer;
  v_minr    integer := public.cfg_num(v_cb, '{minRateBps}', 50)::integer;
  v_maxr    integer := public.cfg_num(v_cb, '{maxRateBps}', 1000)::integer;
  v_sent25  double precision := public.config_double('events', '{rateDecisionSentimentPer25Bps}', -0.1);
  q         public.game_quarters;
  v_prevq   public.game_quarters;
  v_prev    public.money_supply_snapshots;
  v_cur     record;
  v_old     integer;
  v_growth  integer;
  v_annual  integer;
  v_gap     integer;
  v_steps   integer;
  v_target  integer;
  v_towards integer;
  v_drift   integer;
  v_new     integer;
  v_factor  double precision;
begin
  select * into q from public.game_quarters where id = p_quarter_id;
  select cb.policy_rate_bps into v_old from public.central_bank_state cb where cb.id for update;
  v_old := coalesce(v_old, public.cfg_num(v_cb, '{startRateBps}', 300)::integer);

  -- money growth per active player over the measurement window; without a comparable snapshot (new database,
  -- downtime) there is no measurement and the bank holds the rate
  select * into v_cur from public.events_money_sample(p_now);
  if q.id is not null and v_window > 0 then
    v_prevq := public.game_quarter_by_index((q.game_year - 1) * 4 + q.quarter - 1 - v_window);
    if v_prevq.id is not null then
      select * into v_prev from public.money_supply_snapshots m where m.game_quarter_id = v_prevq.id;
    end if;
  end if;
  if v_prev.game_quarter_id is not null and v_prev.player_cents + v_prev.company_cents > 0
     and coalesce(v_prev.active_players, 0) > 0 and v_cur.active_players > 0 then
    -- Math.round: half up
    v_growth := floor(((v_cur.money_supply_cents::double precision / v_cur.active_players)
                       / ((v_prev.player_cents + v_prev.company_cents)::double precision / v_prev.active_players) - 1) * 10000 + 0.5);
    v_factor := greatest(0, 1 + v_growth / 10000.0);
    v_annual := floor((power(v_factor, v_qpy / v_window) - 1) * 10000 + 0.5);
  end if;

  if v_annual is null then
    v_new := v_old;
  else
    v_gap := v_annual - v_tgt;
    v_steps := trunc(v_gap / v_band)::integer;
    v_steps := least(v_maxst, greatest(-v_maxst, v_steps));
    v_target := v_old + v_steps * v_step;
    if v_steps = 0 and v_old <> v_neutral then
      v_towards := sign(v_neutral - v_old)::integer * v_step;
      v_drift := v_old + v_towards;
      -- do not overshoot the neutral rate
      v_target := case when sign(v_neutral - v_drift) = -sign(v_towards) then v_neutral else v_drift end;
    end if;
    v_new := least(v_maxr, greatest(v_minr, v_target));
  end if;

  update public.central_bank_state
     set policy_rate_bps = v_new, last_decision_at = p_now, next_decision_at = null, updated_at = now()
   where id;
  insert into public.central_bank_decisions (game_quarter_id, previous_rate_bps, new_rate_bps, money_supply_cents, statement, decided_at)
  values (q.id, v_old, v_new, v_cur.money_supply_cents,
          case when v_new > v_old then 'Die Zentralbank erhöht den Leitzins.'
               when v_new < v_old then 'Die Zentralbank senkt den Leitzins.'
               else 'Die Zentralbank lässt den Leitzins unverändert.' end, p_now);
  if v_new <> v_old then
    -- sentiment shock on every listed stock (spec 16), fair values with the new macro factor
    update public.security_sim_state st
       set sentiment = greatest(-1, least(1, st.sentiment + (v_new - v_old) / 25.0 * v_sent25))
      from public.securities s
     where s.id = st.security_id and s.kind = 'stock' and s.status = 'listed';
    perform public.recompute_fair_values();
  end if;
  return jsonb_build_object('old_bps', v_old, 'new_bps', v_new, 'money_growth_bps', v_annual);
end;
$$;
comment on function public.event_rate_decision(bigint, timestamptz) is
  'Internal (ADR-090): decidePolicyRate on the per-capita money growth; updates central_bank_state.';

-- Resolves every due event (oldest first, at most 200 per call). Earnings wait for their quarter close.
create or replace function public.events_resolve_due(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ev       jsonb := coalesce(public.config_jsonb('events'), '{}'::jsonb);
  v_min_mv   double precision := public.cfg_num(v_ev, '{pharmaTrial,minMove}', 0.5);
  v_max_mv   double precision := public.cfg_num(v_ev, '{pharmaTrial,maxMove}', 0.7);
  v_per_surp double precision := greatest(1e-9, public.cfg_num(v_ev, '{earnings,sentimentPerSurprise}', 3));
  e          record;
  v_out      jsonb;
  v_status   public.scheduled_event_status;
  v_q        public.game_quarters;
  v_rep      record;
  v_prev     record;
  v_shock    double precision;
  v_p        double precision;
  v_success  boolean;
  v_move     integer;
  v_price    jsonb;
  v_pct      text;
  h          record;
  v_done     integer := 0;
  v_waiting  integer := 0;
  v_cancel   integer := 0;
begin
  for e in
    select se.*, c.name as company_name, c.phase as company_phase, s.ticker, s.status as security_status
      from public.scheduled_events se
      left join public.companies c on c.id = se.company_id
      left join public.securities s on s.id = se.security_id
     where se.status in ('scheduled', 'in_progress') and se.scheduled_at <= p_now
     order by se.scheduled_at, se.id
     limit 200
       for update of se skip locked
  loop
    v_out := null;
    v_status := 'resolved';

    if e.kind in ('opening_bell', 'closing_bell') then
      -- informational; a bell missed by more than an hour (downtime) is dropped
      if p_now - e.scheduled_at > interval '1 hour' then
        v_status := 'cancelled';
      else
        v_out := '{}'::jsonb;
      end if;

    elsif e.kind = 'earnings' then
      select * into v_q from public.game_quarters where id = e.game_quarter_id;
      if v_q.id is not null and v_q.status <> 'closed' then
        v_waiting := v_waiting + 1;
        continue;
      end if;
      select r.revenue_cents, r.net_income_cents, r.eps_e4 into v_rep
        from public.company_quarter_reports r where r.company_id = e.company_id and r.game_quarter_id = e.game_quarter_id;
      if v_rep is null or v_rep.revenue_cents is null then
        v_status := 'cancelled';
      else
        select r.revenue_cents, r.net_income_cents into v_prev
          from public.company_quarter_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
         where r.company_id = e.company_id and gq.starts_at < v_q.starts_at
         order by gq.starts_at desc limit 1;
        -- the surprise behind the sentiment shock of simulate_ai_companies (its news effect)
        select ef.sentiment into v_shock
          from public.news_items n join public.news_item_effects ef on ef.news_item_id = n.id
         where n.company_id = e.company_id and n.game_quarter_id = e.game_quarter_id and n.category = 'earnings'
         order by n.id desc limit 1;
        v_out := jsonb_build_object(
          'revenue_cents', v_rep.revenue_cents, 'net_income_cents', v_rep.net_income_cents, 'eps_e4', v_rep.eps_e4,
          'revenue_change_bps', case when coalesce(v_prev.revenue_cents, 0) <> 0
                                     then round((v_rep.revenue_cents - v_prev.revenue_cents) * 10000.0 / abs(v_prev.revenue_cents))::bigint end,
          'net_income_change_bps', case when coalesce(v_prev.net_income_cents, 0) <> 0
                                        then round((v_rep.net_income_cents - v_prev.net_income_cents) * 10000.0
                                                   / abs(v_prev.net_income_cents))::bigint end,
          'surprise', case when coalesce(v_shock, 0) / v_per_surp > 0.05 then 'beat'
                           when coalesce(v_shock, 0) / v_per_surp < -0.05 then 'miss'
                           else 'inline' end);
      end if;

    elsif e.kind = 'pharma_trial' then
      if e.security_id is null or e.security_status is distinct from 'listed' then
        v_status := 'cancelled';
      else
        -- resolvePharmaTrial: success with the hidden probability, move uniform in [minMove, maxMove]
        select (sec.params ->> 'success_probability')::double precision into v_p
          from public.scheduled_event_secrets sec where sec.event_id = e.id;
        v_success := random() < coalesce(v_p, 0.5);
        v_move := round((v_min_mv + random() * (v_max_mv - v_min_mv)) * 10000)::integer;
        v_move := case when v_success then v_move else -v_move end;
        v_price := public.event_price_shock(e.security_id, v_move, p_now);
        v_out := jsonb_build_object('success', v_success, 'move_bps', v_move) || coalesce(v_price, '{}'::jsonb);
        v_pct := replace(to_char(abs(v_move) / 100.0, 'FM990.0'), '.', ',') || ' %';
        for h in
          select distinct p.player_id from public.positions p
           where p.security_id = e.security_id and p.status = 'open' and p.quantity_e6 > 0
        loop
          perform public.event_notify(
            h.player_id,
            case when v_success then 'Studie erfolgreich: ' else 'Studie gescheitert: ' end || e.company_name,
            e.ticker || case when v_success then ' steigt um ' else ' fällt um ' end || v_pct || '.',
            jsonb_build_object('event_id', e.id, 'kind', 'pharma_trial', 'ticker', e.ticker, 'success', v_success,
                               'move_bps', v_move),
            '/markets/' || e.ticker,
            'event:' || e.id);
        end loop;
      end if;

    elsif e.kind = 'rate_decision' then
      v_out := public.event_rate_decision(e.game_quarter_id, p_now);

    else
      v_out := '{}'::jsonb;
    end if;

    update public.scheduled_events
       set status = v_status, resolved_at = p_now, outcome = case when v_status = 'resolved' then v_out end, updated_at = now()
     where id = e.id;
    if v_status = 'resolved' then
      v_done := v_done + 1;
    else
      v_cancel := v_cancel + 1;
    end if;
  end loop;
  return jsonb_build_object('resolved', v_done, 'cancelled', v_cancel, 'waiting', v_waiting);
end;
$$;
comment on function public.events_resolve_due(timestamptz) is
  'Internal (ADR-090): resolves all due events once (late ones after a downtime too); earnings wait for the quarter close.';

-- Minute job part (called by run_due_jobs): planning every 15 minutes, resolution and money snapshot every call.
create or replace function public.events_run_due()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := public.game_now();
  v_run    bigint;
  v_result jsonb := '{}'::jsonb;
  v_snap   bigint;
begin
  insert into public.job_runs (job_name, run_key, status, finished_at)
  values ('events_plan', to_char(date_bin('15 minutes', v_now, '2000-01-01 00:00:00+00'::timestamptz) at time zone 'UTC',
                                 'YYYY-MM-DD"T"HH24:MI'), 'succeeded', now())
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('planned', public.events_plan(v_now));
    delete from public.job_runs j
     where (j.job_name = 'events_plan' and j.started_at < now() - interval '1 day')
        or (j.job_name = 'events_pharma_roll' and j.started_at < now() - interval '30 days');
  end if;
  v_snap := public.events_snapshot_money(v_now);
  if v_snap is not null then
    v_result := v_result || jsonb_build_object('money_snapshot', v_snap);
  end if;
  if exists (select 1 from public.scheduled_events e where e.status in ('scheduled', 'in_progress') and e.scheduled_at <= v_now) then
    v_result := v_result || jsonb_build_object('resolved', public.events_resolve_due(v_now));
  end if;
  return v_result;
end;
$$;
comment on function public.events_run_due() is
  'Internal (run_due_jobs, ADR-090): plans events every 15 minutes, resolves due events, money supply snapshot per quarter.';

-- ---------------------------------------------------------------------------
-- F. RPC get_events
-- ---------------------------------------------------------------------------
create or replace function public.get_events(p_limit integer default 20)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := public.game_now();
  v_limit  integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_recent interval := make_interval(secs => greatest(0, public.config_double('events', '{schedule,recentHours}', 24)) * 3600);
begin
  perform public.require_player();
  return jsonb_build_object(
    'server_time', v_now,
    'upcoming', coalesce((
      select jsonb_agg(x.j order by x.scheduled_at, x.id)
        from (select e.id, e.scheduled_at,
                     jsonb_build_object('id', e.id, 'kind', e.kind, 'importance', e.importance, 'scheduled_at', e.scheduled_at,
                                        'announced_at', e.announced_at, 'status', e.status, 'ticker', s.ticker,
                                        'company_name', c.name, 'sector', e.sector_key, 'outcome', null) as j
                from public.scheduled_events e
                left join public.companies c on c.id = e.company_id
                left join public.securities s on s.id = e.security_id
               where e.status in ('scheduled', 'in_progress')
               order by e.scheduled_at, e.id
               limit v_limit) x), '[]'::jsonb),
    'recent', coalesce((
      select jsonb_agg(x.j order by x.resolved_at desc, x.scheduled_at desc, x.id)
        from (select e.id, e.scheduled_at, e.resolved_at,
                     jsonb_build_object('id', e.id, 'kind', e.kind, 'importance', e.importance, 'scheduled_at', e.scheduled_at,
                                        'announced_at', e.announced_at, 'status', e.status, 'ticker', s.ticker,
                                        'company_name', c.name, 'sector', e.sector_key, 'outcome', e.outcome) as j
                from public.scheduled_events e
                left join public.companies c on c.id = e.company_id
                left join public.securities s on s.id = e.security_id
               where e.status = 'resolved' and e.resolved_at > v_now - v_recent
               order by e.resolved_at desc, e.scheduled_at desc, e.id
               limit v_limit) x), '[]'::jsonb));
end;
$$;
comment on function public.get_events(integer) is
  'RPC (ADR-090): {server_time, upcoming, recent}; EVENT = {id, kind, importance, scheduled_at, announced_at, status, ticker, company_name, sector, outcome}.';

-- ---------------------------------------------------------------------------
-- G. run_due_jobs: call events_run_due() before the daily maintenance
-- ---------------------------------------------------------------------------
-- Injected into the current definition instead of redefining the whole function, so that other
-- additions to run_due_jobs() (migrations of the same milestone) are kept. Idempotent; fails loudly if
-- the anchor line is missing.
do $$
declare
  v_def    text;
  v_anchor constant text := '  -- daily maintenance (first run per UTC day)';
begin
  v_def := pg_get_functiondef('public.run_due_jobs()'::regprocedure);
  if position('public.events_run_due()' in v_def) > 0 then
    return;
  end if;
  if position(v_anchor in v_def) = 0 then
    raise exception 'NEXA M4g: anchor "%" not found in run_due_jobs()', v_anchor;
  end if;
  v_def := replace(v_def, v_anchor,
    '  -- announced events (ADR-090): planning, resolution of due events, money supply snapshot' || chr(10)
    || '  v_result := v_result || jsonb_build_object(''events'', public.events_run_due());' || chr(10) || chr(10)
    || v_anchor);
  execute v_def;
end;
$$;

-- ---------------------------------------------------------------------------
-- H. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.fair_value_from_fundamentals(uuid)', 'public.game_quarter_by_index(integer)',
    'public.events_money_sample(timestamptz)', 'public.events_snapshot_money(timestamptz)',
    'public.event_notify(uuid, text, text, jsonb, text, text)', 'public.event_price_shock(uuid, integer, timestamptz)',
    'public.events_plan(timestamptz)', 'public.event_rate_decision(bigint, timestamptz)',
    'public.events_resolve_due(timestamptz)', 'public.events_run_due()', 'public.get_events(integer)',
    'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.get_events(integer) to authenticated;
end;
$$;
-- ===== idempotent copy of migrations/20261129000100_m4h_company_events.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4h · 0100 · Company events, response steps and company news (ADR-091)
-- =============================================================================
-- Mirrors src/lib/sim/company-events.ts (rollCompanyEvent, rollSeverity, pickArchetype, costUnitCents,
-- stepCostCents, stepSuccessBps, canStartStep, stepSucceeds, announcementShockBps, resolutionShockBps,
-- eventPhase, eventModifiers) and the event input of closeStartupHour (src/lib/sim/startup.ts).
-- Catalog and numbers: game_config 'companyEvents' (src/config/company-events.ts). Every event stores a snapshot
-- of its archetype (player_company_events.definition), so a balancing change never breaks a running event.
--
-- Tables (RLS on, no client grants; read through the RPCs):
--   player_company_events  one crisis or chance of a player company (company_events is the older, unused timeline)
--   company_event_steps    the paid, timed and possibly failing steps of the chosen strategy
--   company_event_rolls    one roll per company and Berlin day
--   company_news           what happened in a company (events, founding, growth, IPO, hires, record hours)
--   company_ai_profiles    product words written by Claude (Edge Function, service role)
-- New columns: player_company_hours.event_id, player_companies.best_hour_profit_cents.
--
-- Jobs: company_events_run_due() (one line in run_due_jobs): due steps, deadlines, end of the effect,
-- the daily roll (at a company-specific time between rollWindowHours, default 7 to 21 o'clock Berlin), news pruning.
-- Hourly close: player_company_close_hour applies the event modifiers (demand, capacity, extra costs) and
-- writes the record_hour news. Other company news come from triggers (founded, upgraded, expanded, ipo, hired).
-- RPCs: choose_event_strategy, start_event_step, get_company_event, get_company_news, company_ai_context;
-- service role only: store_company_ai_profile, store_company_event_text, store_company_news_text.
-- New error keys: event_closed (NX081), event_needs_staff (NX082). New notification type: company_event.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
create table if not exists public.player_company_events (
  id                   uuid primary key default gen_random_uuid(),
  company_id           uuid not null references public.companies (id) on delete cascade,
  archetype            text not null check (archetype ~ '^[a-z0-9_]+$'),
  polarity             text not null check (polarity in ('crisis', 'chance')),
  severity             smallint not null check (severity between 1 and 3),
  status               text not null default 'open'
                       check (status in ('open', 'accepted', 'solved', 'in_force', 'expired', 'over')),
  definition           jsonb not null check (jsonb_typeof(definition) = 'object'),
  started_at           timestamptz not null,
  deadline_at          timestamptz not null,
  resolved_at          timestamptz,
  over_at              timestamptz,
  strategy             text,
  mitigation           double precision not null default 0 check (mitigation between 0 and 1),
  bonus_applied        boolean not null default false,
  announce_shock_bps   integer,
  resolution_shock_bps integer,
  ai_headline          text check (ai_headline is null or char_length(ai_headline) between 1 and 120),
  ai_body              text check (ai_body is null or char_length(ai_body) between 1 and 600),
  ai_cause             text check (ai_cause is null or char_length(ai_cause) between 1 and 60),
  created_at           timestamptz not null default now()
);
alter table public.player_company_events enable row level security;
create index if not exists player_company_events_company_idx on public.player_company_events (company_id, started_at desc);
-- at most one event per company that is not over yet
create unique index if not exists player_company_events_active_uq on public.player_company_events (company_id)
  where status not in ('over', 'expired');
create index if not exists player_company_events_status_idx on public.player_company_events (status, deadline_at)
  where status not in ('over', 'expired');
comment on table public.player_company_events is
  'Crises and chances of player companies (ADR-091). definition = snapshot of the archetype from game_config companyEvents; '
  'mitigation = share of the damage removed (crisis) or of the chance won; *_shock_bps = share price moves of a listed company. '
  'Internal (RPCs).';

create table if not exists public.company_event_steps (
  id           bigint generated always as identity primary key,
  event_id     uuid not null references public.player_company_events (id) on delete cascade,
  idx          integer not null check (idx >= 0),
  strategy     text not null,
  key          text not null,
  status       text not null default 'running' check (status in ('running', 'succeeded', 'failed')),
  started_at   timestamptz not null,
  ends_at      timestamptz not null,
  resolved_at  timestamptz,
  cost_cents   bigint not null default 0 check (cost_cents >= 0),
  success_bps  integer not null check (success_bps between 0 and 10000),
  retry        boolean not null default false,
  capacity_hit double precision not null default 0 check (capacity_hit between 0 and 1),
  discarded    boolean not null default false,
  request_id   uuid,
  created_at   timestamptz not null default now()
);
alter table public.company_event_steps enable row level security;
create index if not exists company_event_steps_event_idx on public.company_event_steps (event_id, id);
create unique index if not exists company_event_steps_running_uq on public.company_event_steps (event_id) where status = 'running';
create index if not exists company_event_steps_due_idx on public.company_event_steps (ends_at) where status = 'running';
comment on table public.company_event_steps is
  'Steps of an event response (ADR-091): paid from the free company cash at the start, resolved at ends_at against '
  'success_bps. discarded = progress of a strategy the founder switched away from (money spent stays spent). Internal (RPCs).';

create table if not exists public.company_event_rolls (
  company_id uuid not null references public.companies (id) on delete cascade,
  berlin_day date not null,
  rolled_at  timestamptz not null default now(),
  event_id   uuid,
  primary key (company_id, berlin_day)
);
alter table public.company_event_rolls enable row level security;
comment on table public.company_event_rolls is
  'One event roll per player company and Berlin day (ADR-091); event_id = the event it started, if any. Internal.';

create table if not exists public.company_news (
  id          bigint generated always as identity primary key,
  company_id  uuid not null references public.companies (id) on delete cascade,
  kind        text not null check (kind ~ '^[a-z0-9_]+$'),
  payload     jsonb not null default '{}'::jsonb check (jsonb_typeof(payload) = 'object'),
  ai_headline text check (ai_headline is null or char_length(ai_headline) between 1 and 120),
  ai_body     text check (ai_body is null or char_length(ai_body) between 1 and 600),
  created_at  timestamptz not null default now()
);
alter table public.company_news enable row level security;
create index if not exists company_news_company_idx on public.company_news (company_id, created_at desc, id desc);
create index if not exists company_news_created_idx on public.company_news (created_at);
comment on table public.company_news is
  'Company news feed (ADR-091): kind + payload = variables for the i18n template; ai_headline/ai_body written once by '
  'the Edge Function. Kept companyEvents.newsKeepDays (30) days. Internal (RPCs).';

create table if not exists public.company_ai_profiles (
  company_id uuid primary key references public.companies (id) on delete cascade,
  words      jsonb not null check (jsonb_typeof(words) = 'object'),
  created_at timestamptz not null default now()
);
alter table public.company_ai_profiles enable row level security;
comment on table public.company_ai_profiles is
  'Product words for the story composer, written once by Claude (store_company_ai_profile): slots product, input, tax, '
  'rule, risk, trend, buyer, critic, place, each 1..5 strings. Internal (RPCs).';

revoke all on public.player_company_events, public.company_event_steps, public.company_event_rolls, public.company_news,
              public.company_ai_profiles from anon, authenticated;

alter table public.player_company_hours add column if not exists event_id uuid;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_company_hours_event_id_fkey'
                    and conrelid = 'public.player_company_hours'::regclass) then
    alter table public.player_company_hours add constraint player_company_hours_event_id_fkey
      foreign key (event_id) references public.player_company_events (id) on delete set null;
  end if;
end;
$$;
create index if not exists player_company_hours_event_idx on public.player_company_hours (event_id) where event_id is not null;
comment on column public.player_company_hours.event_id is 'Company event that changed this hour (ADR-091), if any.';

alter table public.player_companies add column if not exists best_hour_profit_cents bigint not null default 0;
comment on column public.player_companies.best_hour_profit_cents is
  'Best hourly profit so far (record_hour news, ADR-091). Internal.';
update public.player_companies pc
   set best_hour_profit_cents = h.best
  from (select x.company_id, max(x.profit_cents) as best from public.player_company_hours x group by x.company_id) h
 where h.company_id = pc.company_id and h.best > pc.best_hour_profit_cents;

-- ---------------------------------------------------------------------------
-- B. Error keys (M4h: NX081, NX082)
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    when 'founding_locked'             then 'NX053'
    when 'not_in_company'              then 'NX054'
    when 'work_task_not_found'         then 'NX055'
    when 'work_task_expired'           then 'NX056'
    when 'work_task_done'              then 'NX057'
    when 'offer_closed'                then 'NX058'
    when 'offer_sold_out'              then 'NX059'
    when 'already_listed'              then 'NX060'
    when 'confirm_mismatch'            then 'NX061'
    when 'skill_already_covered'       then 'NX062'
    when 'training_locked'             then 'NX063'
    when 'logo_locked'                 then 'NX064'
    when 'logo_forbidden'              then 'NX065'
    when 'artworks_locked'             then 'NX066'
    when 'artwork_not_found'           then 'NX067'
    when 'auction_not_found'           then 'NX068'
    when 'auction_ended'               then 'NX069'
    when 'bid_too_low'                 then 'NX070'
    when 'own_artwork'                 then 'NX071'
    when 'already_on_auction'          then 'NX072'
    when 'auction_has_bids'            then 'NX073'
    when 'property_locked'             then 'NX074'
    when 'no_home'                     then 'NX075'
    when 'invalid_tier'                then 'NX076'
    when 'item_not_found'              then 'NX077'
    when 'layout_invalid'              then 'NX078'
    when 'floor_not_owned'             then 'NX079'
    when 'garage_full'                 then 'NX080'
    when 'event_closed'                then 'NX081'
    when 'event_needs_staff'           then 'NX082'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;
comment on function public.api_error(text) is 'Raises the API error <key> with its NX SQLSTATE. The client shows a text per key (error.message).';

-- ---------------------------------------------------------------------------
-- C. Notification type
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('company_event', 'company', 'Krise oder Chance', 'Deine Firma steht vor einer Krise oder bekommt eine Chance.',
        'notif_company', true, true, false, 205)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- D. Rules (port of src/lib/sim/company-events.ts)
-- ---------------------------------------------------------------------------
create or replace function public.company_events_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('companyEvents'), '{}'::jsonb);
$$;
comment on function public.company_events_cfg() is 'Internal: game_config companyEvents (ADR-091), {} when missing.';

-- archetypeOf
create or replace function public.company_event_archetype(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select x from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) x
   where x ->> 'key' = p_key limit 1;
$$;

-- pickArchetype: weighted pick of an archetype of the polarity that fits the sector (catalog order)
create or replace function public.company_event_pick(p_u double precision, p_sector text, p_polarity text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_total double precision;
  v_x     double precision;
  r       record;
  v_last  jsonb;
begin
  select coalesce(sum(greatest(0, public.cfg_num(t.x, '{weight}', 0))), 0) into v_total
    from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) t(x)
   where t.x ->> 'polarity' = p_polarity
     and (jsonb_typeof(t.x -> 'sectors') is distinct from 'array' or t.x -> 'sectors' ? p_sector);
  v_x := least(greatest(coalesce(p_u, 0), 0), 0.999999) * v_total;
  for r in
    select t.x
      from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) with ordinality t(x, ord)
     where t.x ->> 'polarity' = p_polarity
       and (jsonb_typeof(t.x -> 'sectors') is distinct from 'array' or t.x -> 'sectors' ? p_sector)
     order by t.ord
  loop
    v_x := v_x - greatest(0, public.cfg_num(r.x, '{weight}', 0));
    if v_x < 0 then
      return r.x;
    end if;
    v_last := r.x;
  end loop;
  return v_last;
end;
$$;

-- rollSeverity
create or replace function public.company_event_severity(p_u double precision)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select case when p_u < public.cfg_num(c, '{severityWeights,0}', 0.5) then 1
              when p_u < public.cfg_num(c, '{severityWeights,0}', 0.5) + public.cfg_num(c, '{severityWeights,1}', 0.35) then 2
              else 3 end
    from (select public.company_events_cfg() as c) x;
$$;

-- costUnitCents: max(minUnitCents, round(quarterly fixed costs × unitShareOfFixed))
create or replace function public.company_event_unit_cents(p_company uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(public.cfg_num(c, '{costUnit,minUnitCents}', 20000)::bigint,
                  round(public.company_fixed_cost_cents(pc.tier, pc.expansion_level)::numeric
                        * public.cfg_num(c, '{costUnit,unitShareOfFixed}', 0.5)::numeric)::bigint)
    from public.player_companies pc, (select public.company_events_cfg() as c) x
   where pc.company_id = p_company;
$$;

-- stepCostCents: cost × unit × (1 + 0.25 × (severity − 1)), a retry costs retryCostShare of it
create or replace function public.company_event_step_cost(p_step jsonb, p_unit bigint, p_severity integer, p_retry boolean default false)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select round(public.cfg_num(p_step, '{cost}', 0)::numeric * coalesce(p_unit, 0)
               * (1 + 0.25 * (p_severity - 1))
               * case when p_retry then public.cfg_num(public.company_events_cfg(), '{retryCostShare}', 0.5)::numeric else 1 end)::bigint;
$$;

-- stepSuccessBps: base + know-how of the team (capped) − severity penalty, between 500 and 10 000
create or replace function public.company_event_step_bps(p_step jsonb, p_severity integer, p_score double precision)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select least(10000, greatest(500, round((
           public.cfg_num(p_step, '{baseBps}', 0)
           + case when coalesce(p_step ->> 'branch', '') <> ''
                  then least(public.cfg_num(c, '{knowHow,maxBonusBps}', 2500),
                             greatest(0, coalesce(p_score, 0)) * public.cfg_num(c, '{knowHow,bpsPerPoint}', 150))
                  else 0 end
           - public.cfg_num(c, '{severityPenaltyBps}', 700) * (p_severity - 1))::numeric)::integer))
    from (select public.company_events_cfg() as c) x;
$$;

-- Team know-how: founder + current player employees, summed per branch (player_branch_scores as for jobs)
create or replace function public.company_event_team_scores(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_object_agg(b.key, coalesce(s.score, 0))
    from (values ('it'), ('finance'), ('law'), ('craft'), ('sales'), ('management'), ('science'), ('logistics')) b(key)
    left join (
      select x.key, sum(case when jsonb_typeof(x.value) = 'number' then (x.value #>> '{}')::numeric else 0 end)::integer as score
        from (select pc.founder_id as player_id from public.player_companies pc where pc.company_id = p_company
              union
              select j.player_id from public.player_jobs j where j.company_id = p_company and j.status = 'active') m
        cross join lateral jsonb_each(public.player_branch_scores(m.player_id)) x
       group by x.key) s on s.key = b.key;
$$;

-- People for canStartStep: founder + player employees + AI workers
create or replace function public.company_event_headcount(p_company uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select 1 + public.company_headcount(p_company);
$$;

-- When the effect ends: chance after a success resolved + lasts (else the deadline), crisis
-- min(deadline, resolved) + lasts
create or replace function public.company_event_ends_at(p_polarity text, p_lasts_hours double precision, p_deadline timestamptz,
                                                        p_resolved timestamptz)
returns timestamptz
language sql
immutable
set search_path = ''
as $$
  select case
    when p_polarity = 'chance' and p_resolved is null then p_deadline
    when p_polarity = 'chance' then p_resolved + make_interval(secs => greatest(0, coalesce(p_lasts_hours, 0)) * 3600)
    else least(p_deadline, coalesce(p_resolved, p_deadline)) + make_interval(secs => greatest(0, coalesce(p_lasts_hours, 0)) * 3600)
  end;
$$;

-- eventPhase
create or replace function public.company_event_phase(p_polarity text, p_lasts_hours double precision, p_deadline timestamptz,
                                                      p_resolved timestamptz, p_at timestamptz)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_polarity = 'chance' and p_resolved is null then case when p_at < p_deadline then 'open' else 'over' end
    when p_polarity = 'crisis' and p_resolved is null and p_at < p_deadline then 'open'
    when p_at < public.company_event_ends_at(p_polarity, p_lasts_hours, p_deadline, p_resolved) then 'in_force'
    else 'over'
  end;
$$;

-- eventModifiers: {demand_factor, capacity_factor, extra_cost_share}
create or replace function public.company_event_modifiers(p_def jsonb, p_severity integer, p_phase text, p_mitigation double precision,
                                                          p_capacity_hit double precision default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cfg   jsonb := public.company_events_cfg();
  v_scale double precision;
  v_share double precision := 0;
  v_s     double precision;
  v_m     double precision := least(1, greatest(0, coalesce(p_mitigation, 0)));
begin
  v_scale := public.cfg_num(v_cfg, array['severityScale', (p_severity - 1)::text],
                            case p_severity when 1 then 1 when 2 then 1.7 else 2.5 end);
  if p_def ->> 'polarity' = 'crisis' then
    if p_phase = 'open' then
      v_share := public.cfg_num(v_cfg, '{preDeadlineShare}', 0.25) * (1 - v_m);
    elsif p_phase = 'in_force' then
      v_share := 1 - v_m;
    end if;
  elsif p_phase = 'in_force' then
    v_share := v_m;
  end if;
  v_s := v_share * v_scale;
  return jsonb_build_object(
    'demand_factor', greatest(0.05, 1 + public.cfg_num(p_def, '{effect,demand}', 0) * v_s),
    'capacity_factor', greatest(0.05, (1 + public.cfg_num(p_def, '{effect,capacity}', 0) * v_s)
                                      * (1 - least(0.9, greatest(0, coalesce(p_capacity_hit, 0))))),
    'extra_cost_share', public.cfg_num(p_def, '{effect,cost}', 0) * v_s);
end;
$$;

-- The effect on one operating hour [p_from, p_to): the latest event started before the end of the hour, its phase
-- at the start of the hour, and the capacity tied up by steps in proportion to the part of the hour they ran.
create or replace function public.company_event_hour_effect(p_company uuid, p_from timestamptz, p_to timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  e       public.player_company_events;
  v_hit   double precision;
  v_phase text;
begin
  select * into e from public.player_company_events ev
   where ev.company_id = p_company and ev.started_at < p_to
   order by ev.started_at desc limit 1;
  if e.id is null then
    return jsonb_build_object('event_id', null, 'demand_factor', 1, 'capacity_factor', 1, 'extra_cost_share', 0);
  end if;
  v_phase := public.company_event_phase(e.polarity, public.cfg_num(e.definition, '{lastsHours}', 0), e.deadline_at,
                                        e.resolved_at, p_from);
  select coalesce(sum(s.capacity_hit * extract(epoch from (least(s.ends_at, p_to) - greatest(s.started_at, p_from)))
                      / greatest(1, extract(epoch from (p_to - p_from)))), 0)
    into v_hit
    from public.company_event_steps s
   where s.event_id = e.id and s.capacity_hit > 0 and s.started_at < p_to and s.ends_at > p_from;
  if v_phase = 'over' and v_hit <= 0 then
    return jsonb_build_object('event_id', null, 'demand_factor', 1, 'capacity_factor', 1, 'extra_cost_share', 0);
  end if;
  return public.company_event_modifiers(e.definition, e.severity, v_phase, e.mitigation, v_hit)
         || jsonb_build_object('event_id', e.id);
end;
$$;

-- ---------------------------------------------------------------------------
-- E. News and notifications
-- ---------------------------------------------------------------------------
create or replace function public.company_news_add(p_company uuid, p_kind text, p_payload jsonb default '{}'::jsonb)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id bigint;
begin
  if p_company is null or not exists (select 1 from public.companies c where c.id = p_company) then
    return null;
  end if;
  insert into public.company_news (company_id, kind, payload)
  values (p_company, p_kind, coalesce(p_payload, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end;
$$;
comment on function public.company_news_add(uuid, text, jsonb) is 'Internal: appends a company news item (ADR-091).';

-- In-app notification to the founder, unless switched off (missing preference: the type's default)
create or replace function public.company_event_notify(p_event uuid, p_title text, p_body text, p_dedupe text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  e         public.player_company_events;
  v_founder uuid;
begin
  select * into e from public.player_company_events where id = p_event;
  select pc.founder_id into v_founder from public.player_companies pc where pc.company_id = e.company_id;
  if v_founder is null or not exists (select 1 from public.notification_types t where t.key = 'company_event') then
    return;
  end if;
  if not coalesce((select np.in_app_enabled from public.notification_preferences np
                    where np.player_id = v_founder and np.type_key = 'company_event'),
                  (select t.default_in_app from public.notification_types t where t.key = 'company_event'), true) then
    return;
  end if;
  insert into public.notifications (player_id, type_key, title, body, payload, link, dedupe_key)
  values (v_founder, 'company_event', p_title, p_body,
          jsonb_build_object('company_id', e.company_id, 'event_id', e.id, 'archetype', e.archetype, 'polarity', e.polarity,
                             'severity', e.severity),
          '/company', p_dedupe)
  on conflict (player_id, dedupe_key) do nothing;
end;
$$;

-- founded, upgraded {tier}, expanded {level}
create or replace function public.company_news_player_company_trg()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform public.company_news_add(new.company_id, 'founded', jsonb_build_object('tier', new.tier));
    return null;
  end if;
  -- the AG comes with the IPO, which has its own news
  if new.tier is distinct from old.tier and new.tier <> 'ag' then
    perform public.company_news_add(new.company_id, 'upgraded', jsonb_build_object('tier', new.tier));
  end if;
  if new.expansion_level > old.expansion_level then
    perform public.company_news_add(new.company_id, 'expanded', jsonb_build_object('level', new.expansion_level));
  end if;
  return null;
end;
$$;
drop trigger if exists company_news_player_company on public.player_companies;
create trigger company_news_player_company
  after insert or update of tier, expansion_level on public.player_companies
  for each row execute function public.company_news_player_company_trg();

-- ipo {ticker}
create or replace function public.company_news_listing_trg()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.player_companies pc where pc.company_id = new.id) then
    perform public.company_news_add(new.id, 'ipo', jsonb_build_object('ticker', new.ticker));
  end if;
  return null;
end;
$$;
drop trigger if exists company_news_listing on public.companies;
create trigger company_news_listing
  after update of phase on public.companies
  for each row when (new.phase = 'listed' and old.phase is distinct from new.phase and not new.is_ai)
  execute function public.company_news_listing_trg();

-- hired {nickname, title}: a player signed with a player company
create or replace function public.company_news_hired_trg()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.player_companies pc where pc.company_id = new.company_id) then
    perform public.company_news_add(new.company_id, 'hired',
      jsonb_build_object('nickname', (select p.nickname from public.profiles p where p.id = new.player_id), 'title', new.title));
  end if;
  return null;
end;
$$;
drop trigger if exists company_news_hired on public.player_jobs;
create trigger company_news_hired
  after insert on public.player_jobs
  for each row when (new.status = 'active')
  execute function public.company_news_hired_trg();

-- ---------------------------------------------------------------------------
-- F. Events: share shock, start, roll, steps, solution
-- ---------------------------------------------------------------------------
-- Listed company: moves price, quote, market cap, the value fund's fair value and both EMAs by the same factor (a level
-- shift, no artificial trend). Returns the applied bps, null when the company is not listed.
create or replace function public.company_event_share_shock(p_company uuid, p_bps integer)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  c     public.companies;
  q     public.security_quotes;
  v_f   numeric;
  v_new bigint;
  v_bid bigint;
  v_ref bigint;
begin
  select * into c from public.companies where id = p_company;
  if c.id is null or c.phase <> 'listed' or c.security_id is null then
    return null;
  end if;
  select * into q from public.security_quotes where security_id = c.security_id for update;
  if q.security_id is null then
    return null;
  end if;
  if coalesce(p_bps, 0) = 0 then
    return 0;
  end if;
  v_f := 1 + p_bps / 10000.0;
  v_new := greatest(1, round(q.last_price_e4 * v_f))::bigint;
  v_bid := case when q.bid_e4 is null then null else greatest(1, round(q.bid_e4 * v_f))::bigint end;
  v_ref := coalesce(q.prev_close_e4, q.last_price_e4);
  update public.security_quotes
     set last_price_e4 = v_new,
         bid_e4 = v_bid,
         ask_e4 = case when q.ask_e4 is null then null else greatest(coalesce(v_bid, 0) + 1, round(q.ask_e4 * v_f))::bigint end,
         day_high_e4 = greatest(coalesce(q.day_high_e4, v_new), v_new),
         day_low_e4 = least(coalesce(q.day_low_e4, v_new), v_new),
         change_bps = greatest(-1000000, least(1000000, round((v_new - v_ref) * 10000.0 / greatest(1, v_ref))))::integer,
         market_cap_cents = public.div_round_half_even(c.shares_outstanding::numeric * v_new, 100),
         updated_at = now()
   where security_id = c.security_id;
  update public.security_sim_state
     set fair_value_e4 = greatest(1, round(fair_value_e4 * v_f))::bigint,
         ema_fast = ema_fast * v_f::double precision,
         ema_slow = ema_slow * v_f::double precision
   where security_id = c.security_id;
  return p_bps;
end;
$$;
comment on function public.company_event_share_shock(uuid, integer) is
  'Internal: share price shock of a listed player company (ADR-091); price, quote, market cap, fair value and EMAs move together.';

-- A new event (no gating; company_event_roll gates): deadline, news, notification, announcement shock when listed
create or replace function public.company_event_start(p_company uuid, p_archetype text, p_severity integer,
                                                      p_now timestamptz default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz := coalesce(p_now, public.game_now());
  v_def      jsonb := public.company_event_archetype(p_archetype);
  v_size     double precision;
  v_bps      integer;
  v_shock    integer;
  v_deadline timestamptz;
  v_id       uuid;
  v_name     text;
begin
  if v_def is null or coalesce(p_severity, 0) not between 1 and 3 or v_def ->> 'polarity' not in ('crisis', 'chance') then
    return null;
  end if;
  perform 1 from public.player_companies pc where pc.company_id = p_company and pc.status = 'active' for update;
  if not found or exists (select 1 from public.player_company_events ev
                           where ev.company_id = p_company and ev.status not in ('over', 'expired')) then
    return null;
  end if;
  v_deadline := v_now + make_interval(secs => greatest(0, public.cfg_num(v_def, '{deadlineHours}', 24)) * 3600);
  insert into public.player_company_events (company_id, archetype, polarity, severity, definition, started_at, deadline_at)
  values (p_company, p_archetype, v_def ->> 'polarity', p_severity, v_def, v_now, v_deadline)
  returning id into v_id;
  -- announcementShockBps: crisis −size, chance +size/2
  v_size := public.cfg_num(public.company_events_cfg(), array['shareShockBps', (p_severity - 1)::text],
                           case p_severity when 1 then 400 when 2 then 900 else 1500 end);
  v_bps := case when v_def ->> 'polarity' = 'crisis' then -round(v_size::numeric) else round((v_size / 2)::numeric) end::integer;
  v_shock := public.company_event_share_shock(p_company, v_bps);
  update public.player_company_events set announce_shock_bps = v_shock where id = v_id;
  perform public.company_news_add(p_company, 'event_started',
    jsonb_build_object('event_id', v_id, 'archetype', p_archetype, 'polarity', v_def ->> 'polarity', 'severity', p_severity,
                       'deadline_at', v_deadline, 'share_shock_bps', v_shock));
  select c.name into v_name from public.companies c where c.id = p_company;
  perform public.company_event_notify(v_id,
    case when v_def ->> 'polarity' = 'crisis' then 'Krise bei ' || v_name else 'Chance für ' || v_name end,
    'Reagiere bis ' || to_char(v_deadline at time zone 'Europe/Berlin', 'DD.MM., HH24:MI') || ' Uhr.',
    'company_event:' || v_id::text || ':start');
  return v_id;
end;
$$;

-- When the daily roll of a company happens: a fixed time per company and Berlin day between rollWindowHours
create or replace function public.company_event_roll_at(p_company uuid, p_day date)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  -- Berlin wall-clock time (also on the days the clocks change), then converted to an instant.
  select (p_day::timestamp
          + make_interval(secs => (public.cfg_num(c, '{rollWindowHours,0}', 7)
                                   + public.uniform_from_text(p_company::text || ':' || p_day::text)
                                     * greatest(0, public.cfg_num(c, '{rollWindowHours,1}', 21) - public.cfg_num(c, '{rollWindowHours,0}', 7)))
                                  * 3600)) at time zone 'Europe/Berlin'
    from (select public.company_events_cfg() as c) x;
$$;

-- rollCompanyEvent: one roll per company and Berlin day; p_u = [happens?, chance or crisis?, which?, how bad?]
-- (server randomness when null). Returns the new event or null.
create or replace function public.company_event_roll(p_company uuid, p_now timestamptz default null, p_u double precision[] default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := coalesce(p_now, public.game_now());
  v_cfg    jsonb := public.company_events_cfg();
  v_day    date := (coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date;
  v_u      double precision[] := coalesce(p_u, array[random(), random(), random(), random()]);
  c        public.companies;
  v_last   timestamptz;
  v_arch   jsonb;
  v_id     uuid;
begin
  if jsonb_typeof(v_cfg -> 'archetypes') is distinct from 'array'
     or not exists (select 1 from public.player_companies pc where pc.company_id = p_company and pc.status = 'active') then
    return null;
  end if;
  insert into public.company_event_rolls (company_id, berlin_day, rolled_at) values (p_company, v_day, v_now)
  on conflict (company_id, berlin_day) do nothing;
  if not found then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  select max(ev.started_at) into v_last from public.player_company_events ev where ev.company_id = p_company;
  if exists (select 1 from public.player_company_events ev where ev.company_id = p_company and ev.status not in ('over', 'expired'))
     or extract(epoch from (v_now - c.founded_at)) / 3600 < public.cfg_num(v_cfg, '{minAgeHours}', 6)
     or (v_last is not null and extract(epoch from (v_now - v_last)) / 3600 < public.cfg_num(v_cfg, '{minGapHours}', 22))
     or v_u[1] >= public.cfg_num(v_cfg, '{chancePerDay}', 0.6) then
    return null;
  end if;
  v_arch := public.company_event_pick(v_u[3], c.sector_key,
                                      case when v_u[2] < public.cfg_num(v_cfg, '{chanceShare}', 0.4) then 'chance' else 'crisis' end);
  if v_arch is null then
    return null;
  end if;
  v_id := public.company_event_start(p_company, v_arch ->> 'key', public.company_event_severity(v_u[4]), v_now);
  update public.company_event_rolls set event_id = v_id where company_id = p_company and berlin_day = v_day;
  return v_id;
end;
$$;

-- The chosen strategy of an event (null when none or unknown)
create or replace function public.company_event_strategy_def(p_event public.player_company_events)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select s from jsonb_array_elements(coalesce(p_event.definition -> 'strategies', '[]'::jsonb)) s
   where s ->> 'key' = p_event.strategy limit 1;
$$;

-- Succeeded steps of the current attempt of the chosen strategy (finished by p_until, if given)
create or replace function public.company_event_done_steps(p_event uuid, p_until timestamptz default null)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from public.company_event_steps s join public.player_company_events e on e.id = s.event_id
   where s.event_id = p_event and not s.discarded and s.status = 'succeeded' and s.strategy = e.strategy
     and (p_until is null or s.resolved_at <= p_until);
$$;

-- A running step stops at p_at (failed and discarded, money spent stays spent); p_all also discards the progress of
-- the current attempt (switching the strategy)
create or replace function public.company_event_discard(p_event uuid, p_at timestamptz, p_all boolean default true)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.company_event_steps
     set status = 'failed', discarded = true, ends_at = least(ends_at, greatest(started_at, p_at)), resolved_at = p_at
   where event_id = p_event and status = 'running';
  if p_all then
    update public.company_event_steps set discarded = true where event_id = p_event and not discarded;
  end if;
end;
$$;

-- Every step of the chosen strategy succeeded: solved, mitigation, bonus once, resolution shock, news, notification
create or replace function public.company_event_solve(p_event uuid, p_at timestamptz)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  e       public.player_company_events;
  v_strat jsonb;
  v_mit   double precision;
  v_size  double precision;
  v_bps   integer;
  v_shock integer;
  v_name  text;
begin
  select * into e from public.player_company_events where id = p_event for update;
  if e.id is null or e.status not in ('open', 'in_force') then
    return;
  end if;
  v_strat := public.company_event_strategy_def(e);
  v_mit := least(1, greatest(0, public.cfg_num(v_strat, '{mitigation}', 0)));
  update public.player_company_events set status = 'solved', resolved_at = p_at, mitigation = v_mit where id = e.id;
  if not e.bonus_applied then
    update public.player_companies
       set awareness = least(1, greatest(0, awareness + public.cfg_num(v_strat, '{bonus,awareness}', 0))),
           quality = least(1, greatest(0, quality + public.cfg_num(v_strat, '{bonus,quality}', 0)))
     where company_id = e.company_id;
    update public.player_company_events set bonus_applied = true where id = e.id;
  end if;
  -- resolutionShockBps: crisis size × mitigation, chance size / 2 × mitigation
  v_size := public.cfg_num(public.company_events_cfg(), array['shareShockBps', (e.severity - 1)::text],
                           case e.severity when 1 then 400 when 2 then 900 else 1500 end);
  v_bps := round((case when e.polarity = 'crisis' then v_size * v_mit else v_size / 2 * v_mit end)::numeric)::integer;
  v_shock := public.company_event_share_shock(e.company_id, v_bps);
  update public.player_company_events set resolution_shock_bps = v_shock where id = e.id;
  perform public.company_news_add(e.company_id, 'event_solved',
    jsonb_build_object('event_id', e.id, 'archetype', e.archetype, 'polarity', e.polarity, 'severity', e.severity,
                       'strategy', e.strategy, 'mitigation', round(v_mit::numeric, 4)::double precision, 'share_shock_bps', v_shock));
  select c.name into v_name from public.companies c where c.id = e.company_id;
  perform public.company_event_notify(e.id,
    case when e.polarity = 'crisis' then 'Krise gemeistert: ' || v_name else 'Chance genutzt: ' || v_name end,
    null, 'company_event:' || e.id::text || ':solved');
end;
$$;

-- stepSucceeds: u × 10 000 < success_bps (server randomness when p_u is null). Returns the outcome.
create or replace function public.company_event_resolve_step(p_step bigint, p_u double precision default null)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  st      public.company_event_steps;
  e       public.player_company_events;
  v_ok    boolean;
  v_n     integer;
  v_name  text;
  v_def   jsonb;
begin
  select * into st from public.company_event_steps where id = p_step and status = 'running' and not discarded for update;
  if st.id is null then
    return null;
  end if;
  select * into e from public.player_company_events where id = st.event_id for update;
  v_ok := coalesce(p_u, random()) * 10000 < st.success_bps;
  update public.company_event_steps
     set status = case when v_ok then 'succeeded' else 'failed' end, resolved_at = st.ends_at
   where id = st.id;
  select c.name into v_name from public.companies c where c.id = e.company_id;
  v_def := public.company_event_strategy_def(e);
  if v_ok then
    perform public.company_news_add(e.company_id, 'event_step_done',
      jsonb_build_object('event_id', e.id, 'archetype', e.archetype, 'strategy', st.strategy, 'idx', st.idx, 'step', st.key,
                         'success', true));
    v_n := jsonb_array_length(coalesce(v_def -> 'steps', '[]'::jsonb));
    if e.status in ('open', 'in_force') and st.strategy = e.strategy and public.company_event_done_steps(e.id) >= v_n then
      perform public.company_event_solve(e.id, st.ends_at);
    else
      perform public.company_event_notify(e.id, 'Schritt geschafft bei ' || v_name, null,
                                          'company_event:' || e.id::text || ':step:' || st.id::text);
    end if;
  else
    perform public.company_news_add(e.company_id, 'event_step_failed',
      jsonb_build_object('event_id', e.id, 'archetype', e.archetype, 'strategy', st.strategy, 'idx', st.idx, 'step', st.key,
                         'success', false));
    perform public.company_event_notify(e.id, 'Schritt gescheitert bei ' || v_name,
                                        'Versuch es noch einmal oder wähle einen anderen Weg.',
                                        'company_event:' || e.id::text || ':step:' || st.id::text);
  end if;
  return v_ok;
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Periodic work (run_due_jobs): steps, deadlines, end of the effect, daily roll, pruning
-- ---------------------------------------------------------------------------
create or replace function public.company_events_run_due(p_now timestamptz default null, p_roll boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz := coalesce(p_now, public.game_now());
  v_day      date := (coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date;
  v_cfg      jsonb := public.company_events_cfg();
  v_steps    integer := 0;
  v_deadline integer := 0;
  v_over     integer := 0;
  v_started  integer := 0;
  v_strat    jsonb;
  v_n        integer;
  v_mit      double precision;
  v_end      timestamptz;
  ce         public.player_company_events;
  e          record;
  s          record;
  r          record;
begin
  -- 1. events of companies that are no longer active end silently
  for e in
    select ev.id from public.player_company_events ev
      left join public.player_companies pc on pc.company_id = ev.company_id
     where ev.status not in ('over', 'expired') and coalesce(pc.status, '') <> 'active'
  loop
    perform public.company_event_discard(e.id, v_now, false);
    update public.player_company_events set status = 'over', over_at = v_now where id = e.id;
  end loop;

  -- 2. steps that ended: success or failure (a success of the last step solves the event)
  for s in
    select st.id from public.company_event_steps st
     where st.status = 'running' and not st.discarded and st.ends_at <= v_now
     order by st.ends_at, st.id
  loop
    if public.company_event_resolve_step(s.id) is not null then
      v_steps := v_steps + 1;
    end if;
  end loop;

  -- 3. deadlines: a crisis comes into force (partial credit for the steps finished by the deadline), a chance is missed
  for ce in
    select ev.* from public.player_company_events ev where ev.status = 'open' and ev.deadline_at <= v_now
     order by ev.deadline_at for update
  loop
    if ce.polarity = 'crisis' then
      v_strat := public.company_event_strategy_def(ce);
      v_n := jsonb_array_length(coalesce(v_strat -> 'steps', '[]'::jsonb));
      v_mit := case when v_strat is null or v_n = 0 then 0
                    else least(1, greatest(0, public.cfg_num(v_strat, '{mitigation}', 0) * public.company_event_done_steps(ce.id, ce.deadline_at) / v_n
                                              * public.cfg_num(v_cfg, '{partialCredit}', 0.5))) end;
      update public.player_company_events set status = 'in_force', mitigation = v_mit where id = ce.id;
      perform public.company_news_add(ce.company_id, 'event_deadline',
        jsonb_build_object('event_id', ce.id, 'archetype', ce.archetype, 'polarity', ce.polarity, 'severity', ce.severity,
                           'mitigation', round(v_mit::numeric, 4)::double precision));
    else
      perform public.company_event_discard(ce.id, ce.deadline_at, false);
      update public.player_company_events set status = 'expired', over_at = ce.deadline_at where id = ce.id;
      perform public.company_news_add(ce.company_id, 'event_expired',
        jsonb_build_object('event_id', ce.id, 'archetype', ce.archetype, 'polarity', ce.polarity, 'severity', ce.severity));
    end if;
    v_deadline := v_deadline + 1;
  end loop;

  -- 4. the effect is over (eventPhase): in force, solved or sat out
  for ce in
    select ev.* from public.player_company_events ev where ev.status in ('in_force', 'solved', 'accepted') order by ev.started_at for update
  loop
    v_end := public.company_event_ends_at(ce.polarity, public.cfg_num(ce.definition, '{lastsHours}', 0), ce.deadline_at,
                                          ce.resolved_at);
    continue when public.company_event_phase(ce.polarity, public.cfg_num(ce.definition, '{lastsHours}', 0), ce.deadline_at,
                                             ce.resolved_at, v_now) <> 'over';
    perform public.company_event_discard(ce.id, v_end, false);
    update public.player_company_events set status = 'over', over_at = v_end where id = ce.id;
    perform public.company_news_add(ce.company_id, 'event_over',
      jsonb_build_object('event_id', ce.id, 'archetype', ce.archetype, 'polarity', ce.polarity, 'severity', ce.severity,
                         'status', ce.status));
    v_over := v_over + 1;
  end loop;

  -- 5. the daily roll, at the company's time of the day
  if p_roll and jsonb_typeof(v_cfg -> 'archetypes') = 'array' then
    for r in
      select pc.company_id from public.player_companies pc
       where pc.status = 'active'
         and not exists (select 1 from public.company_event_rolls x where x.company_id = pc.company_id and x.berlin_day = v_day)
         and public.company_event_roll_at(pc.company_id, v_day) <= v_now
       order by pc.company_id
    loop
      if public.company_event_roll(r.company_id, v_now, null) is not null then
        v_started := v_started + 1;
      end if;
    end loop;
  end if;

  -- 6. news and rolls are kept newsKeepDays (30)
  delete from public.company_news
   where created_at < now() - make_interval(days => public.cfg_num(v_cfg, '{newsKeepDays}', 30)::integer);
  delete from public.company_event_rolls
   where berlin_day < v_day - public.cfg_num(v_cfg, '{newsKeepDays}', 30)::integer;
  return jsonb_build_object('steps', v_steps, 'deadlines', v_deadline, 'over', v_over, 'started', v_started);
end;
$$;
comment on function public.company_events_run_due(timestamptz, boolean) is
  'run_due_jobs (ADR-091): resolves ended steps, deadlines (crisis in force with partial credit, chance missed), ends '
  'effects, rolls once per company and Berlin day (p_roll), prunes news. p_now for tests.';

-- ---------------------------------------------------------------------------
-- H. One operating hour as in M4e, with the event modifiers and the record hour
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_ev      jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_owed    bigint;
  v_free    bigint;
  v_payout  bigint := 0;
  v_bps     integer;
  v_until   timestamptz;
  v_news    bigint;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');
  -- company event of this hour (ADR-091): demand and capacity factors, extra costs as a share of the own revenue
  v_ev := public.company_event_hour_effect(p_company, v_start, v_end);

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision
            * (v_ev ->> 'demand_factor')::double precision;
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level)
         * (v_ev ->> 'capacity_factor')::double precision / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  -- goods; an event's extra costs (or savings) move with the own revenue, goods never cost less than nothing
  v_cogs := round(greatest(0, v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5))
                              + v_own * (v_ev ->> 'extra_cost_share')::double precision)::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  v_fixed := round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  v_owed := pc.unpaid_cents + v_unpaid - v_settle;

  -- automatic CEO payout (ADR-086, founderPayoutCents): after the hour's own bookings, a share of a positive profit
  -- (rounded down) moves from the company cash to the founder's private cash like company_withdraw, never more than
  -- the free cash (cash minus open bills). A transfer, not a cost: profit_cents stays as computed above.
  v_bps := least(10000, greatest(0, coalesce(pc.founder_payout_bps, 0)));
  if v_profit > 0 and v_bps > 0 then
    select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
    v_payout := least(v_profit * v_bps / 10000, greatest(0, coalesce(v_free, 0)));
  end if;
  if v_payout > 0 then
    perform public.lock_player_accounts(pc.founder_id);
    perform public.ledger_transfer(v_acc, public.ledger_player_account(pc.founder_id, 'player_cash'), v_payout, 'transfer',
                                   'CEO-Auszahlung ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':payout', pc.founder_id);
    perform public.loan_withhold(pc.founder_id, v_payout, k || ':payout');
  end if;

  -- record hour (ADR-091): beating an earlier best hour is news, at most one item per Berlin day (updated while the
  -- day's record keeps rising and no AI text was written for it)
  if v_profit > coalesce(pc.best_hour_profit_cents, 0) and coalesce(pc.best_hour_profit_cents, 0) > 0 then
    select n.id into v_news from public.company_news n
     where n.company_id = p_company and n.kind = 'record_hour'
       and ((n.payload ->> 'hour_start')::timestamptz at time zone 'Europe/Berlin')::date
           = (v_start at time zone 'Europe/Berlin')::date
     order by n.id desc limit 1;
    if v_news is null then
      perform public.company_news_add(p_company, 'record_hour',
                                      jsonb_build_object('profit_cents', v_profit, 'hour_start', v_start));
    else
      update public.company_news set payload = jsonb_build_object('profit_cents', v_profit, 'hour_start', v_start)
       where id = v_news and ai_headline is null;
    end if;
  end if;

  update public.player_companies
     set unpaid_cents = v_owed,
         distress = v_owed > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end),
         best_hour_profit_cents = greatest(best_hour_profit_cents, v_profit)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents, founder_payout_cents, event_id)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit, v_payout,
          (v_ev ->> 'event_id')::uuid);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid,
                            'founder_payout_cents', v_payout, 'event_id', v_ev -> 'event_id');
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083) with the company event of the hour '
  '(ADR-091), pays the automatic CEO payout (ADR-086) and writes the record_hour news; idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- I. EVENT_STATE and the RPCs
-- ---------------------------------------------------------------------------
create or replace function public.company_event_company_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('id', c.id, 'name', c.name, 'idea', pc.idea, 'sector', c.sector_key,
                            'product_key', public.company_product(c.id) ->> 'key', 'tier', pc.tier)
    from public.companies c join public.player_companies pc on pc.company_id = c.id
   where c.id = p_company;
$$;

-- The company a player may look into: p_company when the player is its founder or a current employee (active
-- company), with p_company null the own company or else the player company the player works for. Null = no access.
create or replace function public.company_event_company_for(p_player uuid, p_company uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when p_company is null then coalesce(
      (select pc.company_id from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active'),
      (select j.company_id from public.player_jobs j
         join public.player_companies pc on pc.company_id = j.company_id and pc.status = 'active'
        where j.player_id = p_player and j.status = 'active' order by j.started_at desc limit 1))
    else (select pc.company_id from public.player_companies pc
           where pc.company_id = p_company and pc.status = 'active'
             and (pc.founder_id = p_player
                  or exists (select 1 from public.player_jobs j
                              where j.company_id = p_company and j.player_id = p_player and j.status = 'active')))
  end;
$$;

-- EVENT_STATE (docs/DATA_MODEL.md, Nachtrag M4h)
create or replace function public.company_event_state(p_company uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  e         public.player_company_events;
  v_unit    bigint := public.company_event_unit_cents(p_company);
  v_head    integer := public.company_event_headcount(p_company);
  v_scores  jsonb := public.company_event_team_scores(p_company);
  v_ev      jsonb;
  v_strat   jsonb;
  v_step    jsonb;
  v_next    jsonb;
  v_steps   jsonb;
  v_opts    jsonb;
  v_hist    jsonb;
  v_done    integer;
  v_n       integer;
  v_retry   boolean;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into e from public.player_company_events ev
   where ev.company_id = p_company and ev.status not in ('over', 'expired')
   order by ev.started_at desc limit 1;
  if e.id is not null then
    v_strat := public.company_event_strategy_def(e);
    select coalesce(jsonb_agg(jsonb_build_object('idx', s.idx, 'strategy', s.strategy, 'key', s.key, 'status', s.status,
                                                 'started_at', s.started_at, 'ends_at', s.ends_at, 'cost_cents', s.cost_cents,
                                                 'success_bps', s.success_bps, 'retry', s.retry) order by s.id), '[]'::jsonb)
      into v_steps
      from public.company_event_steps s where s.event_id = e.id and not s.discarded;
    -- the step that can be started now (none while one runs)
    if e.status in ('open', 'in_force') and v_strat is not null
       and not exists (select 1 from public.company_event_steps s where s.event_id = e.id and s.status = 'running') then
      v_n := jsonb_array_length(coalesce(v_strat -> 'steps', '[]'::jsonb));
      v_done := public.company_event_done_steps(e.id);
      if v_done < v_n then
        v_step := v_strat -> 'steps' -> v_done;
        v_retry := exists (select 1 from public.company_event_steps s
                            where s.event_id = e.id and not s.discarded and s.status = 'failed'
                              and s.strategy = e.strategy and s.idx = v_done);
        v_next := jsonb_build_object(
          'strategy', e.strategy, 'idx', v_done, 'key', v_step ->> 'key',
          'cost_cents', public.company_event_step_cost(v_step, v_unit, e.severity, v_retry),
          'success_bps', public.company_event_step_bps(v_step, e.severity,
                                                       coalesce((v_scores ->> (v_step ->> 'branch'))::double precision, 0)),
          'staff', coalesce((v_step ->> 'staff')::integer, 0),
          'staff_ok', v_head >= coalesce((v_step ->> 'staff')::integer, 0),
          'hours', public.cfg_num(v_step, '{hours}', 0),
          'retry', v_retry);
      end if;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
             'strategy', s.x ->> 'key',
             'first_step_cost_cents', case when jsonb_array_length(coalesce(s.x -> 'steps', '[]'::jsonb)) > 0
                                           then public.company_event_step_cost(s.x -> 'steps' -> 0, v_unit, e.severity, false) end,
             'first_step_success_bps', case when jsonb_array_length(coalesce(s.x -> 'steps', '[]'::jsonb)) > 0
                                            then public.company_event_step_bps(s.x -> 'steps' -> 0, e.severity,
                                                   coalesce((v_scores ->> (s.x -> 'steps' -> 0 ->> 'branch'))::double precision, 0)) end)
           order by s.ord), '[]'::jsonb)
      into v_opts
      from jsonb_array_elements(coalesce(e.definition -> 'strategies', '[]'::jsonb)) with ordinality s(x, ord);
    v_ev := jsonb_build_object(
      'id', e.id, 'archetype', e.archetype, 'polarity', e.polarity, 'severity', e.severity, 'status', e.status,
      'started_at', e.started_at, 'deadline_at', e.deadline_at, 'resolved_at', e.resolved_at, 'over_at', e.over_at,
      'strategy', e.strategy, 'mitigation', round(e.mitigation::numeric, 4)::double precision,
      'ai_headline', e.ai_headline, 'ai_body', e.ai_body, 'ai_cause', e.ai_cause,
      'steps', v_steps, 'next', v_next, 'options', v_opts);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'archetype', h.archetype, 'polarity', h.polarity,
                                               'severity', h.severity, 'status', h.status, 'started_at', h.started_at,
                                               'resolved_at', h.resolved_at) order by h.started_at desc), '[]'::jsonb)
    into v_hist
    from (select ev.* from public.player_company_events ev
           where ev.company_id = p_company and ev.id is distinct from e.id
           order by ev.started_at desc limit 5) h;
  return jsonb_build_object(
    'company', public.company_event_company_json(p_company),
    'can_act', pc.founder_id = p_viewer and pc.status = 'active',
    'unit_cents', v_unit,
    'headcount', v_head,
    'branch_scores', v_scores,
    'event', v_ev,
    'history', v_hist,
    'profile_words', (select p.words from public.company_ai_profiles p where p.company_id = p_company));
end;
$$;

create or replace function public.get_company_event(p_company_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_company uuid;
begin
  v_company := public.company_event_company_for(v_player, p_company_id);
  if v_company is null then
    perform public.api_error('company_not_found');
  end if;
  return public.company_event_state(v_company, v_player);
end;
$$;
comment on function public.get_company_event(uuid) is
  'RPC (founder or current employee): EVENT_STATE of the own company (null) or the given one (ADR-091); else company_not_found.';

-- The founder's event (active company) for an action, locked; company_not_found for everyone else
create or replace function public.company_event_for_founder(p_player uuid, p_event uuid)
returns public.player_company_events
language plpgsql
security definer
set search_path = ''
as $$
declare
  e public.player_company_events;
begin
  select ev.* into e from public.player_company_events ev
    join public.player_companies pc on pc.company_id = ev.company_id and pc.status = 'active' and pc.founder_id = p_player
   where ev.id = p_event
   for update of ev;
  if e.id is null then
    perform public.api_error('company_not_found');
  end if;
  return e;
end;
$$;

create or replace function public.choose_event_strategy(p_request_id uuid, p_event_id uuid, p_strategy text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  e        public.player_company_events;
  v_strat  jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_event_id is null or coalesce(p_strategy, '') = '' then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'choose_event_strategy');
  if v_replay is not null then
    return v_replay;
  end if;
  e := public.company_event_for_founder(v_player, p_event_id);
  if e.status not in ('open', 'in_force') then
    perform public.api_error('event_closed');
  end if;
  select s into v_strat from jsonb_array_elements(coalesce(e.definition -> 'strategies', '[]'::jsonb)) s
   where s ->> 'key' = p_strategy limit 1;
  if v_strat is null then
    perform public.api_error('invalid_argument');
  end if;
  -- switching discards the progress of the old strategy (money spent stays spent)
  if e.strategy is distinct from p_strategy then
    perform public.company_event_discard(e.id, public.game_now(), true);
    update public.player_company_events set strategy = p_strategy where id = e.id;
  end if;
  -- accept / pass: sat out at once
  if jsonb_array_length(coalesce(v_strat -> 'steps', '[]'::jsonb)) = 0 then
    update public.player_company_events set status = 'accepted' where id = e.id;
  end if;
  return public.request_complete(v_player, p_request_id, public.company_event_state(e.company_id, v_player));
end;
$$;
comment on function public.choose_event_strategy(uuid, uuid, text) is
  'RPC (founder): chooses the strategy of an open or in-force event (ADR-091); switching discards step progress, '
  'accept/pass sets accepted. Errors invalid_argument, company_not_found, event_closed. -> EVENT_STATE';

create or replace function public.start_event_step(p_request_id uuid, p_event_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  e        public.player_company_events;
  pc       public.player_companies;
  v_now    timestamptz := public.game_now();
  v_strat  jsonb;
  v_step   jsonb;
  v_n      integer;
  v_done   integer;
  v_retry  boolean;
  v_cost   bigint;
  v_bps    integer;
  v_free   bigint;
begin
  v_player := public.require_player();
  if p_request_id is null or p_event_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'start_event_step');
  if v_replay is not null then
    return v_replay;
  end if;
  e := public.company_event_for_founder(v_player, p_event_id);
  if e.status not in ('open', 'in_force') then
    perform public.api_error('event_closed');
  end if;
  v_strat := public.company_event_strategy_def(e);
  v_n := jsonb_array_length(coalesce(v_strat -> 'steps', '[]'::jsonb));
  v_done := public.company_event_done_steps(e.id);
  if v_strat is null or v_n = 0 or v_done >= v_n
     or exists (select 1 from public.company_event_steps s where s.event_id = e.id and s.status = 'running') then
    perform public.api_error('invalid_argument');
  end if;
  v_step := v_strat -> 'steps' -> v_done;
  -- canStartStep: founder, player employees and AI workers
  if public.company_event_headcount(e.company_id) < coalesce((v_step ->> 'staff')::integer, 0) then
    perform public.api_error('event_needs_staff');
  end if;
  v_retry := exists (select 1 from public.company_event_steps s
                      where s.event_id = e.id and not s.discarded and s.status = 'failed'
                        and s.strategy = e.strategy and s.idx = v_done);
  v_cost := public.company_event_step_cost(v_step, public.company_event_unit_cents(e.company_id), e.severity, v_retry);
  v_bps := public.company_event_step_bps(v_step, e.severity,
             coalesce((public.company_event_team_scores(e.company_id) ->> (v_step ->> 'branch'))::double precision, 0));
  -- paid from the free cash: open bills come first (as company_withdraw and expand_company)
  select * into pc from public.player_companies where company_id = e.company_id for update;
  select a.balance_cents - pc.unpaid_cents into v_free
    from public.ledger_accounts a where a.owner_company_id = e.company_id and a.kind = 'company_cash' for update;
  if coalesce(v_free, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.company_cash_account(e.company_id), public.ledger_system_account('households'), v_cost,
                                   'company_costs', 'Gegenmaßnahme', 'company', e.company_id,
                                   'event-step:' || e.id::text || ':' || p_request_id::text, v_player);
  end if;
  insert into public.company_event_steps (event_id, idx, strategy, key, status, started_at, ends_at, cost_cents, success_bps,
                                          retry, capacity_hit, request_id)
  values (e.id, v_done, e.strategy, v_step ->> 'key', 'running', v_now,
          v_now + make_interval(secs => greatest(0, public.cfg_num(v_step, '{hours}', 1)) * 3600),
          v_cost, v_bps, v_retry, least(1, greatest(0, public.cfg_num(v_step, '{capacityHit}', 0))), p_request_id);
  return public.request_complete(v_player, p_request_id, public.company_event_state(e.company_id, v_player));
end;
$$;
comment on function public.start_event_step(uuid, uuid) is
  'RPC (founder): starts the next step of the chosen strategy (ADR-091), paid from the free company cash. Errors '
  'invalid_argument, company_not_found, event_closed, event_needs_staff, insufficient_funds. -> EVENT_STATE';

create or replace function public.get_company_news(p_company_id uuid default null, p_limit integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_company uuid;
begin
  v_company := public.company_event_company_for(v_player, p_company_id);
  if v_company is null then
    perform public.api_error('company_not_found');
  end if;
  return jsonb_build_object(
    'company', public.company_event_company_json(v_company),
    'profile_words', (select p.words from public.company_ai_profiles p where p.company_id = v_company),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object('id', n.id, 'kind', n.kind, 'payload', n.payload, 'created_at', n.created_at,
                                          'ai_headline', n.ai_headline, 'ai_body', n.ai_body) order by n.created_at desc, n.id desc)
        from (select x.* from public.company_news x where x.company_id = v_company
               order by x.created_at desc, x.id desc limit least(100, greatest(1, coalesce(p_limit, 30)))) n), '[]'::jsonb));
end;
$$;
comment on function public.get_company_news(uuid, integer) is
  'RPC (founder or current employee): news of the own company (null) or the given one, newest first (ADR-091).';

