-- P. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.api_error(text)', 'public.campaigns_cfg()', 'public.campaign_kind_num(text, text)',
    'public.campaign_cost_cents(text, double precision)', 'public.campaign_luck(double precision)',
    'public.campaign_factor(text, double precision, double precision)', 'public.campaign_resonance(double precision)',
    'public.company_demand_estimate_cents(uuid)', 'public.company_campaign_base_cents(uuid)',
    'public.company_campaign_costs(uuid)', 'public.company_campaign_at(uuid, timestamptz)', 'public.campaign_json(uuid)',
    'public.start_campaign(uuid, uuid, text)', 'public.deals_cfg()', 'public.trust_cfg()', 'public.trust_delta(text)',
    'public.trust_add(uuid, uuid, text)', 'public.trust_score(uuid)', 'public.trust_band(integer)', 'public.player_trust(uuid)',
    'public.deal_term_int(jsonb, text)', 'public.deal_other_role(text)', 'public.deal_role_ok(text, text)',
    'public.deal_role_needs_company(text)', 'public.player_active_company(uuid)', 'public.deal_first_hour(timestamptz)',
    'public.deal_terms_json(public.deals)', 'public.deal_terms_error(text, jsonb, integer)',
    'public.deal_supply_prepay_cents(bigint, integer, integer, integer)', 'public.deal_stake_shares(uuid, boolean)',
    'public.deal_count_running(uuid, text)', 'public.deal_is_party(public.deals, uuid)',
    'public.deal_other_player(public.deals, uuid)', 'public.deal_player_of(public.deals, text)', 'public.player_nickname(uuid)',
    'public.deal_kind_text(text, text)', 'public.deal_pct_text(integer)', 'public.deal_hours_text(integer)',
    'public.deal_terms_text(public.deals)', 'public.deal_notify(uuid, text, uuid, text, text, text)',
    'public.deal_party_json(uuid)', 'public.deal_company_json(uuid)', 'public.deal_json(uuid, uuid)',
    'public.deal_break(uuid, uuid, timestamptz)', 'public.deal_finish_supply(uuid, timestamptz)',
    'public.deal_finish_stake(uuid, timestamptz)', 'public.deal_loan_paid(uuid, timestamptz)',
    'public.deal_settle_supply(uuid)', 'public.deal_for_action(uuid, uuid)',
    'public.propose_deal(uuid, text, text, text, jsonb, text)', 'public.respond_deal(uuid, uuid, boolean)',
    'public.cancel_deal(uuid, uuid)', 'public.break_deal(uuid, uuid)', 'public.repay_loan(uuid, uuid, bigint)',
    'public.forgive_loan(uuid, uuid)', 'public.get_deals()', 'public.get_deal_board()', 'public.deals_run_due(timestamptz)',
    'public.player_company_close_hour(uuid, timestamptz)', 'public.company_hours_json(uuid)', 'public.company_state(uuid)',
    'public.get_player_card(text)', 'public.feed_item_label(text, jsonb)', 'public.deals_wipe_player(uuid, text)',
    'public.account_wipe(uuid, text)', 'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.start_campaign(uuid, uuid, text)', 'public.propose_deal(uuid, text, text, text, jsonb, text)',
    'public.respond_deal(uuid, uuid, boolean)', 'public.cancel_deal(uuid, uuid)', 'public.break_deal(uuid, uuid)',
    'public.repay_loan(uuid, uuid, bigint)', 'public.forgive_loan(uuid, uuid)', 'public.get_deals()', 'public.get_deal_board()',
    'public.get_player_card(text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261130000300_m4j_net_worth.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4j · 0300 · Deals count in the net worth (ADR-098)
-- =============================================================================
-- A loan between players moves cash from the lender to the borrower. Without this addendum the borrower looked richer
-- and the lender poorer in the net worth, the rich list and the weekly league, so two friends could push one of them
-- up the league with a loan. From now on:
--   loans:    the lender holds what is still owed (active, overdue), the borrower owes it (also when defaulted)
--   stakes:   the investor's money counts for the investor, written off linearly over the term; the founder's company
--             owes the same amount (its cash already counts in the company value)
--   supply:   the prepayment not used yet belongs to the buyer and is owed by the supplier
-- player_net_worth_cents and rich_list_entries add player_deal_balance_cents. Idempotent.
-- =============================================================================

create or replace function public.player_deal_balance_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select
    coalesce((select sum(case when d.lender_id = p_player and d.status in ('active', 'overdue')
                               then d.due_cents - d.repaid_cents else 0 end
                          - case when d.borrower_id = p_player and d.status in ('active', 'overdue', 'defaulted')
                                 then d.due_cents - d.repaid_cents else 0 end)
                from public.deals d
               where d.kind = 'loan' and (d.lender_id = p_player or d.borrower_id = p_player)), 0)::bigint
  + coalesce((select sum((case when d.investor_id = p_player then 1 else 0 end
                          - case when pc.founder_id = p_player then 1 else 0 end)
                         * floor(d.amount_cents
                                 * greatest(0::numeric, least(1::numeric,
                                     (extract(epoch from (d.ends_at - now())) / (d.hours * 3600.0))::numeric))))
                from public.deals d
                left join public.player_companies pc on pc.company_id = d.company_id
               where d.kind = 'stake' and d.status = 'active' and d.ends_at is not null
                 and (d.investor_id = p_player or pc.founder_id = p_player)), 0)::bigint
  + coalesce((select sum(case when pb.founder_id = p_player then d.prepay_left_cents else 0 end
                         - case when ps.founder_id = p_player then d.prepay_left_cents else 0 end)
                from public.deals d
                left join public.player_companies pb on pb.company_id = d.buyer_company_id
                left join public.player_companies ps on ps.company_id = d.supplier_company_id
               where d.kind = 'supply' and d.status = 'active' and d.prepay_left_cents > 0
                 and (pb.founder_id = p_player or ps.founder_id = p_player)), 0)::bigint;
$$;
comment on function public.player_deal_balance_cents(uuid) is
  'Net worth effect of running deals (ADR-098): loans owed to and by the player, stakes written off over their term, unused supply prepayments.';

create or replace function public.player_net_worth_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select sum(a.balance_cents) from public.ledger_accounts a where a.owner_player_id = p_player), 0)::bigint
       + coalesce((select sum(public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))
                     from public.positions p join public.security_quotes q on q.security_id = p.security_id
                    where p.player_id = p_player and p.status = 'open' and p.quantity_e6 > 0), 0)::bigint
       -- founder's player company (ADR-057): cash - unpaid + earnings value
       + public.player_company_value_cents(p_player)
       -- artworks at their last sale price (ADR-080)
       + public.player_art_value_cents(p_player)
       -- home, furniture, cars and floors (ADR-082)
       + public.player_property_value_cents(p_player)
       - public.player_debt_cents(p_player)
       -- loans, stakes and prepayments between players (ADR-098)
       + public.player_deal_balance_cents(p_player);
$$;

-- rich_list_entries as in M4b plus the deals
create or replace function public.rich_list_entries()
returns table (entity_kind text, entity_id uuid, name text, description text, net_worth_cents bigint, rank_all integer, rank_players integer)
language sql
stable
security definer
set search_path = ''
as $$
  with players as (
    select p.id,
           coalesce(a.cash, 0) + coalesce(v.val, 0) + coalesce(public.company_value_cents(pc.company_id), 0)
             + coalesce(art.val, 0) + public.player_property_value_cents(p.id) - coalesce(d.debt, 0)
             + public.player_deal_balance_cents(p.id) as nw,
           p.nickname
      from public.profiles p
      left join (select owner_player_id, sum(balance_cents)::bigint as cash from public.ledger_accounts
                  where owner_player_id is not null group by owner_player_id) a on a.owner_player_id = p.id
      left join (select pos.player_id, sum(public.value_cents(pos.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))::bigint as val
                   from public.positions pos join public.security_quotes q on q.security_id = pos.security_id
                  where pos.status = 'open' and pos.quantity_e6 > 0 group by pos.player_id) v on v.player_id = p.id
      left join public.player_companies pc on pc.founder_id = p.id and pc.status = 'active'
      left join (select l.player_id, sum(l.outstanding_cents)::bigint as debt from public.player_loans l
                  where l.status = 'open' group by l.player_id) d on d.player_id = p.id
      left join (select aw.owner_id, sum(aw.value_cents)::bigint as val from public.artworks aw
                  where aw.owner_id is not null and aw.value_cents is not null group by aw.owner_id) art on art.owner_id = p.id
     where not p.is_deactivated
  ), tycoons as (
    select t.id, t.name, t.description,
           t.cash_cents + coalesce(sum(public.value_cents(h.quantity_e6, coalesce(q.bid_e4, q.last_price_e4))), 0)::bigint as nw
      from public.rich_tycoons t
      left join public.rich_tycoon_holdings h on h.tycoon_id = t.id
      left join public.security_quotes q on q.security_id = h.security_id
     group by t.id
  ), allx as (
    select 'player'::text as entity_kind, id as entity_id, nickname as name, null::text as description, nw from players
    union all
    select 'tycoon', id, name, description, nw from tycoons
  )
  select x.entity_kind, x.entity_id, x.name, x.description, x.nw,
         (row_number() over (order by x.nw desc, x.entity_kind, x.entity_id))::integer,
         case when x.entity_kind = 'player'
              then (row_number() over (partition by x.entity_kind order by x.nw desc, x.entity_id))::integer end
    from allx x;
$$;


do $$
declare
  f text;
begin
  foreach f in array array[
    'public.player_deal_balance_cents(uuid)', 'public.player_net_worth_cents(uuid)', 'public.rich_list_entries()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261201000100_m4k_upgrades_layers_names.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4k · 0100 · Upgrades with level stages, three furniture layers, unique names, deals with the company
-- =============================================================================
-- ADR-100. Mirrors src/lib/sim/upgrades.ts (upgradeStageLevel; upgradeEffects: workXpBps, artDiscountBps,
-- fixedCostDiscountBps, propertyDiscountBps), src/lib/sim/property.ts (invalidPlacements with the top layer) and
-- src/lib/sim/deals.ts (dealSizeLimitCents, supplyMaxCostCents). Numbers: game_config 'upgrades'
-- (src/config/upgrades.ts) and 'deals' (src/config/deals.ts); every helper falls back to the same defaults.
--
-- A. Schema: player_upgrades.key allows the five new upgrades (mentor, artist, efficiency, makler, crypto_wallet);
--    furniture_catalog.layer allows 'top' and gets `surface` (objects that carry small things); company names are
--    unique only among companies that still exist (partial unique index instead of companies_name_lower_uq); lookup
--    indexes on the name keys of company names and artwork titles.
-- B. Error key deal_too_big NX095 (api_error keeps every earlier key).
-- C. Upgrades: ten keys, stage n needs minLevel + (n − 1) × levelStep (buy_upgrade -> locked). Effects: mentor (work
--    XP in accrue_job_salary), artist (painting: get_art_studio, create_artwork), efficiency (fixed costs of the
--    founder's company in player_company_close_hour), makler (buy_home, buy_furniture, buy_floor, buy_car; the price
--    paid is stored). crypto_wallet is read by the crypto migration through player_upgrade_level(p, 'crypto_wallet').
-- D./E. Unique names (lookalikes count, name_key as for nicknames): artwork titles among all artworks (new RPC
--    check_artwork_title), company names among the companies that still exist (a closed or dissolved one frees its
--    name). found_company gets p_replace: an active company is closed like close_company, then the new one is founded.
-- F. Fixed costs with the efficiency upgrade in the hourly close.
-- G. Home: makler discount; save_layout checks the top layer (completely on objects with a surface, one per tile).
-- H. Deals with the company: supply contracts (their most possible cost) and stakes at most dealSizeLimitCents of
--    every company involved, at the proposal and again at the acceptance (deal_too_big). get_deals returns `limits`.
--    deals.minLevel falls back to 6 (the value comes from game_config).
-- I. Presence at work (ADR-103): profiles.last_active_at (require_player, at most every 5 minutes), player_absences;
--    accrue_job_salary pays the presence share of every minute (24 h away 75 %, 48 h 50 %, 72 h 25 %), the same for
--    work XP; after 120 h away the job ends (end_reason absent: accrue_salaries, player_company_close_hour,
--    presence_touch) with notifications job_absent / employee_absent; job_state gains presence;
--    careers.paidHoursPerDayCap falls back to 8.
-- J. New RPC get_company_org (org chart of a player company).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_upgrades drop constraint if exists player_upgrades_key_check;
alter table public.player_upgrades add constraint player_upgrades_key_check
  check (key in ('vault', 'income', 'study', 'overtime', 'rhetoric', 'mentor', 'artist', 'efficiency', 'makler', 'crypto_wallet'));
comment on table public.player_upgrades is
  'Upgrades bought with game money (ADR-093, ADR-100): one row per player and key, level 0..upgrades.<key>.maxLevel. '
  'Owner read; written only by buy_upgrade.';

-- Home catalogue: small things on top of furniture (ADR-100). The seed (supabase/seeds/furniture.sql) fills both.
alter table public.furniture_catalog add column if not exists surface boolean not null default false;
alter table public.furniture_catalog drop constraint if exists furniture_catalog_layer_check;
alter table public.furniture_catalog add constraint furniture_catalog_layer_check check (layer in ('floor', 'object', 'top'));
alter table public.furniture_catalog drop constraint if exists furniture_catalog_surface_check;
alter table public.furniture_catalog add constraint furniture_catalog_surface_check check (not surface or layer = 'object');
comment on table public.furniture_catalog is
  'Furniture of the home (ADR-082, ADR-100): size in floor tiles; layer floor = rug (lies under objects), object = '
  'furniture, top = small thing standing on objects with surface = true. Seed: supabase/seeds/furniture.sql. Internal (RPCs).';
comment on column public.furniture_catalog.surface is
  'Objects only: the top of this piece carries things of the top layer (tables, counters, desks, nightstands, dressers).';

-- Company names: unique among the companies that still exist; a closed or dissolved company frees its name (ADR-100).
create unique index if not exists companies_name_lower_live_uq on public.companies (lower(name)) where dissolved_at is null;
drop index if exists public.companies_name_lower_uq;
-- lookalike lookups (name_key as for nicknames, ADR-085); not unique: older lookalikes stay
create index if not exists companies_name_key_live_idx on public.companies (public.name_key(name))
  where dissolved_at is null and not is_ai;
create index if not exists artworks_title_key_idx on public.artworks (public.name_key(title));

-- Unlock rows at the levels of progression.unlocks (ADR-099: artworks before companies before property); seed.sql has
-- the same levels for a new database (the rows exist only after seed.sql there). Who reached a level keeps its unlocks.
update public.unlocks u set level = v.level, sort_order = v.sort_order
  from (values ('artworks', 4, 40), ('property', 8, 81), ('ipo', 9, 90), ('found_gmbh', 15, 152)) v(key, level, sort_order)
 where u.key = v.key and (u.level <> v.level or u.sort_order <> v.sort_order);
insert into public.player_unlocks (player_id, unlock_key)
select p.id, u.key from public.profiles p
  join public.unlocks u on u.key in ('artworks', 'property', 'ipo', 'found_gmbh') and u.level <= p.level
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- B. Error keys (M4k: NX095)
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    when 'founding_locked'             then 'NX053'
    when 'not_in_company'              then 'NX054'
    when 'work_task_not_found'         then 'NX055'
    when 'work_task_expired'           then 'NX056'
    when 'work_task_done'              then 'NX057'
    when 'offer_closed'                then 'NX058'
    when 'offer_sold_out'              then 'NX059'
    when 'already_listed'              then 'NX060'
    when 'confirm_mismatch'            then 'NX061'
    when 'skill_already_covered'       then 'NX062'
    when 'training_locked'             then 'NX063'
    when 'logo_locked'                 then 'NX064'
    when 'logo_forbidden'              then 'NX065'
    when 'artworks_locked'             then 'NX066'
    when 'artwork_not_found'           then 'NX067'
    when 'auction_not_found'           then 'NX068'
    when 'auction_ended'               then 'NX069'
    when 'bid_too_low'                 then 'NX070'
    when 'own_artwork'                 then 'NX071'
    when 'already_on_auction'          then 'NX072'
    when 'auction_has_bids'            then 'NX073'
    when 'property_locked'             then 'NX074'
    when 'no_home'                     then 'NX075'
    when 'invalid_tier'                then 'NX076'
    when 'item_not_found'              then 'NX077'
    when 'layout_invalid'              then 'NX078'
    when 'floor_not_owned'             then 'NX079'
    when 'garage_full'                 then 'NX080'
    when 'event_closed'                then 'NX081'
    when 'event_needs_staff'           then 'NX082'
    when 'upgrade_maxed'               then 'NX083'
    when 'promotion_not_ready'         then 'NX084'
    when 'promotion_too_soon'          then 'NX085'
    when 'promotion_pending'           then 'NX086'
    when 'campaign_running'            then 'NX087'
    when 'deal_not_found'              then 'NX088'
    when 'deal_closed'                 then 'NX089'
    when 'deal_terms'                  then 'NX090'
    when 'deal_limit'                  then 'NX091'
    when 'deal_self'                   then 'NX092'
    when 'stake_share_full'            then 'NX093'
    when 'deal_needs_company'          then 'NX094'
    when 'deal_too_big'                then 'NX095'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;
comment on function public.api_error(text) is 'Raises the API error <key> with its NX SQLSTATE. The client shows a text per key (error.message).';

-- ---------------------------------------------------------------------------
-- C. Upgrades with level stages and the five new effects (port of src/lib/sim/upgrades.ts)
-- ---------------------------------------------------------------------------
-- Config of one upgrade: the defaults of src/config/upgrades.ts, overridden by game_config upgrades.<key>; null for an
-- unknown key.
create or replace function public.upgrade_cfg(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select d.v || coalesce(case when jsonb_typeof(c.v) = 'object' then c.v end, '{}'::jsonb)
    from (select '{"vault":         {"maxLevel": 6, "minLevel": 1,  "levelStep": 2, "baseCostCents": 300000,  "costGrowth": 2,   "perLevel": 2},
                   "income":        {"maxLevel": 3, "minLevel": 3,  "levelStep": 4, "baseCostCents": 400000,  "costGrowth": 3,   "perLevel": 1000},
                   "study":         {"maxLevel": 3, "minLevel": 2,  "levelStep": 4, "baseCostCents": 800000,  "costGrowth": 3,   "perLevel": 1},
                   "mentor":        {"maxLevel": 3, "minLevel": 4,  "levelStep": 4, "baseCostCents": 600000,  "costGrowth": 3,   "perLevel": 1000},
                   "overtime":      {"maxLevel": 2, "minLevel": 5,  "levelStep": 6, "baseCostCents": 2000000, "costGrowth": 3,   "perLevel": 1},
                   "rhetoric":      {"maxLevel": 3, "minLevel": 5,  "levelStep": 5, "baseCostCents": 1000000, "costGrowth": 2.5, "perLevel": 500},
                   "artist":        {"maxLevel": 3, "minLevel": 4,  "levelStep": 3, "baseCostCents": 500000,  "costGrowth": 2.5, "perLevel": 1000},
                   "efficiency":    {"maxLevel": 3, "minLevel": 6,  "levelStep": 4, "baseCostCents": 1200000, "costGrowth": 2.5, "perLevel": 500},
                   "makler":        {"maxLevel": 3, "minLevel": 8,  "levelStep": 4, "baseCostCents": 1500000, "costGrowth": 2.5, "perLevel": 500},
                   "crypto_wallet": {"maxLevel": 2, "minLevel": 10, "levelStep": 5, "baseCostCents": 2000000, "costGrowth": 3,   "perLevel": 2500}}'::jsonb
                 -> p_key as v) d
   cross join lateral (select public.config_jsonb('upgrades', array[p_key]) as v) c
   where d.v is not null;
$$;
comment on function public.upgrade_cfg(text) is 'Internal: game_config upgrades.<key> with the defaults of src/config/upgrades.ts.';

-- upgradeStageLevel: player level the next stage needs, minLevel + stages bought × levelStep; null when maxed or unknown
create or replace function public.upgrade_stage_level(p_key text, p_level integer)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select case when x.c is null or greatest(0, coalesce(p_level, 0)) >= public.cfg_num(x.c, '{maxLevel}', 0) then null
              else (public.cfg_num(x.c, '{minLevel}', 1)
                    + greatest(0, coalesce(p_level, 0)) * public.cfg_num(x.c, '{levelStep}', 0))::integer end
    from (select public.upgrade_cfg(p_key) as c) x;
$$;
comment on function public.upgrade_stage_level(text, integer) is
  'Internal: upgradeStageLevel (ADR-100), the player level the stage after p_level needs; null when maxed or unknown.';

-- all ten keys, always
create or replace function public.player_upgrade_levels(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_object_agg(k, public.player_upgrade_level(p_player, k))
    from unnest(array['vault', 'income', 'study', 'overtime', 'rhetoric', 'mentor', 'artist', 'efficiency', 'makler',
                      'crypto_wallet']) k;
$$;
comment on function public.player_upgrade_levels(uuid) is
  'Internal: {vault, income, study, overtime, rhetoric, mentor, artist, efficiency, makler, crypto_wallet} levels of a player.';

-- upgradeEffects().workXpBps: 10 000 + mentor level × perLevel
create or replace function public.player_work_xp_bps(p_player uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0, 10000 + round(public.player_upgrade_level(p_player, 'mentor')
                                   * public.cfg_num(public.upgrade_cfg('mentor'), '{perLevel}', 1000)))::integer;
$$;

-- upgradeEffects().artDiscountBps: artist level × perLevel (0..10 000)
create or replace function public.player_art_discount_bps(p_player uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select least(10000, greatest(0, round(public.player_upgrade_level(p_player, 'artist')
                                        * public.cfg_num(public.upgrade_cfg('artist'), '{perLevel}', 1000))))::integer;
$$;

-- upgradeEffects().fixedCostDiscountBps: efficiency level × perLevel (0..10 000)
create or replace function public.player_fixed_cost_discount_bps(p_player uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select least(10000, greatest(0, round(public.player_upgrade_level(p_player, 'efficiency')
                                        * public.cfg_num(public.upgrade_cfg('efficiency'), '{perLevel}', 500))))::integer;
$$;

-- upgradeEffects().propertyDiscountBps: makler level × perLevel (0..10 000)
create or replace function public.player_property_discount_bps(p_player uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select least(10000, greatest(0, round(public.player_upgrade_level(p_player, 'makler')
                                        * public.cfg_num(public.upgrade_cfg('makler'), '{perLevel}', 500))))::integer;
$$;

create or replace function public.get_upgrades()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return jsonb_build_object('levels', public.player_upgrade_levels(public.require_player()));
end;
$$;
comment on function public.get_upgrades() is
  'RPC: {levels: {vault, income, study, overtime, rhetoric, mentor, artist, efficiency, makler, crypto_wallet}} of the '
  'caller (ADR-093, ADR-100).';

-- Buys the next stage: upgradeCheck order maxed, level (the stage's player level, ADR-100), cash; the price goes from
-- the player's cash to the treasury that pays the basic income (closed money system, ADR-041).
create or replace function public.buy_upgrade(p_request_id uuid, p_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  v_level   integer;
  v_cost    bigint;
  v_cash    bigint;
  v_old_cap double precision;
begin
  v_player := public.require_player();
  if p_request_id is null or p_key is null or p_key not in ('vault', 'income', 'study', 'overtime', 'rhetoric', 'mentor', 'artist',
                                                                  'efficiency', 'makler', 'crypto_wallet') then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_upgrade');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if p_key = 'vault' then
    perform 1 from public.vaults where player_id = v_player for update;
  end if;
  v_level := public.player_upgrade_level(v_player, p_key);
  v_cost := public.upgrade_cost_cents(p_key, v_level);
  if v_cost is null then
    perform public.api_error('upgrade_maxed');
  end if;
  -- every further stage needs a higher player level (ADR-100, upgradeStageLevel)
  if coalesce((select p.level from public.profiles p where p.id = v_player), 0) < public.upgrade_stage_level(p_key, v_level) then
    perform public.api_error('locked');
  end if;
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  v_old_cap := greatest(0, public.player_vault_cap_hours(v_player));
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('treasury'),
                                 v_cost, 'upgrade_purchase', 'Verbesserung gekauft', 'upgrade', null,
                                 'upgrade:' || v_player::text || ':' || p_key || ':' || p_request_id::text, v_player,
                                 jsonb_build_object('key', p_key, 'level', v_level + 1));
  insert into public.player_upgrades (player_id, key, level) values (v_player, p_key, v_level + 1)
  on conflict (player_id, key) do update set level = excluded.level;
  -- a bigger vault keeps what it holds and fills on from there: the time it stood full earns nothing afterwards
  if p_key = 'vault' then
    update public.vaults v
       set accrual_started_at = greatest(v.accrual_started_at, public.game_now() - make_interval(secs => v_old_cap * 3600)),
           full_notified_at = null
     where v.player_id = v_player;
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'key',        p_key,
    'level',      v_level + 1,
    'cost_cents', v_cost,
    'levels',     public.player_upgrade_levels(v_player)));
end;
$$;
comment on function public.buy_upgrade(uuid, text) is
  'RPC: buys the next stage of an upgrade (ADR-093, ADR-100) -> {key, level, cost_cents, levels}; errors '
  'invalid_argument, upgrade_maxed, locked (player level below the stage''s level), insufficient_funds.';

-- accrue_job_salary as in M4i; work XP with the mentor upgrade
create or replace function public.accrue_job_salary(p_job_id uuid, p_now timestamptz default null)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := coalesce(p_now, public.game_now());
  j         public.player_jobs;
  v_ai      boolean;
  v_day     date := (coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date;
  v_paid    integer;
  v_elapsed integer;
  v_minutes integer;
  v_amount  bigint;
  v_pay     bigint := 0;
  v_company uuid;
  v_bal     bigint;
  v_tx      uuid;
  v_xph     double precision;
  v_hours   integer;
  v_xp      integer := 0;
  v_pres    integer := 10000;
  v_hpp     double precision;
  v_nb      integer;
  v_share   integer;
  v_bwm     jsonb;
  v_base    bigint;
  v_bp      jsonb;
  v_before  integer;
  r         record;
  k         integer := 0;
begin
  select * into j from public.player_jobs where id = p_job_id and status = 'active' for update;
  if j.id is null then
    return 0;
  end if;
  v_elapsed := floor(extract(epoch from (v_now - j.last_paid_at)) / 60)::integer;
  if v_elapsed < 1 then
    return 0;
  end if;
  v_hpp := greatest(1, public.player_work_hours_per_branch_point(j.player_id));
  v_paid := case when j.paid_day = v_day then j.paid_minutes_today else 0 end;
  v_minutes := least(v_elapsed, greatest(0, (public.player_paid_hours_cap(j.player_id) * 60)::integer - v_paid));
  select c.is_ai into v_ai from public.companies c where c.id = j.company_id;

  if v_minutes > 0 then
    -- presence (ADR-103): the share of the wage for these minutes, from the hours the player had been away by then
    -- (10 000 while active); it lowers the wage, the XP and what a player company pays
    v_pres := public.presence_pay_bps_between(j.player_id, j.last_paid_at, v_minutes);
    v_base := j.salary_cents_per_hour * v_minutes * v_pres / 600000;
    -- player companies pay the contract wage x pay factor of the quarter (ADR-058)
    v_amount := v_base * coalesce((select pc.pay_factor_bps from public.player_companies pc
                                    where pc.company_id = j.company_id and pc.status = 'active'), 10000) / 10000;
    select a.id, a.balance_cents into v_company, v_bal
      from public.ledger_accounts a where a.owner_company_id = j.company_id and a.kind = 'company_cash';
    v_pay := least(v_amount, greatest(coalesce(v_bal, 0), 0));
    if v_pay > 0 then
      v_tx := public.ledger_transfer(v_company, public.ledger_player_account(j.player_id, 'player_cash'), v_pay, 'salary',
                                     'Lohn', 'player_job', j.id,
                                     'salary:' || j.id::text || ':' || to_char(v_now, 'YYYYMMDDHH24MISSUS'), j.player_id);
      perform public.loan_withhold(j.player_id, v_pay, 'salary:' || j.id::text || ':' || to_char(v_now, 'YYYYMMDDHH24MISSUS'));
    end if;
    -- work XP per full paid hour (player companies: workHour.playerCompanyMultiplier)
    v_xph := public.config_double('progression', '{xpSources,workHour,xp}', 40)
           * case when v_ai then 1 else public.config_double('progression', '{xpSources,workHour,playerCompanyMultiplier}', 1.5) end;
    v_hours := (j.experience_minutes + v_minutes) / 60 - j.experience_minutes / 60;
    if v_hours > 0 then
      -- mentor upgrade (ADR-100): work XP x workXpBps / 10 000; presence share as for the wage (ADR-103)
      v_xp := public.grant_xp(j.player_id, 'work_hour',
                              round(v_xph * v_hours * public.player_work_xp_bps(j.player_id) / 10000.0 * v_pres / 10000.0)::integer,
                              'work:' || j.id::text || ':' || ((j.experience_minutes + v_minutes) / 60), 'player_job', j.id);
    end if;
    insert into public.salary_payouts (player_job_id, player_id, pay_day, period_start, period_end, minutes_paid, amount_cents,
                                       xp_awarded, ledger_transaction_id, base_amount_cents)
    values (j.id, j.player_id, v_day, j.last_paid_at, v_now, v_minutes, v_pay, v_xp, v_tx, v_base);

    -- branch work minutes and branch points (work hours per point with the study upgrade)
    perform public.skill_points_ensure(j.player_id);
    select sp.branch_work_minutes, sp.branch_points into v_bwm, v_bp
      from public.player_skill_points sp where sp.player_id = j.player_id for update;
    v_nb := greatest(1, jsonb_array_length(j.required));
    for r in select x ->> 'branch' as branch from jsonb_array_elements(j.required) x loop
      v_share := v_minutes / v_nb + case when k = 0 then v_minutes % v_nb else 0 end;
      v_before := coalesce((v_bwm ->> r.branch)::integer, 0);
      v_bwm := jsonb_set(v_bwm, array[r.branch], to_jsonb(v_before + v_share));
      v_bp := jsonb_set(v_bp, array[r.branch], to_jsonb(coalesce((v_bp ->> r.branch)::integer, 0)
              + ((v_before + v_share) / (v_hpp * 60)::integer - v_before / (v_hpp * 60)::integer)));
      k := k + 1;
    end loop;
    update public.player_skill_points set branch_work_minutes = v_bwm, branch_points = v_bp where player_id = j.player_id;
  end if;

  update public.player_jobs
     set last_paid_at = last_paid_at + make_interval(mins => v_elapsed),
         paid_day = v_day,
         paid_minutes_today = v_paid + v_minutes,
         experience_minutes = experience_minutes + v_minutes,
         rank_minutes = least(2000000000::bigint, rank_minutes::bigint + v_minutes)::integer,
         earned_total_cents = earned_total_cents + v_pay,
         pay_factor_bps = case when v_minutes > 0 and v_amount > 0 then (v_pay * 10000 / v_amount)::integer else pay_factor_bps end
   where id = j.id;
  return v_pay;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. Artworks: artist discount, unique titles
-- ---------------------------------------------------------------------------
-- artworkCreateCostCents with the artist upgrade: price × (10 000 − artDiscountBps) / 10 000, half even
create or replace function public.player_artwork_create_cost_cents(p_player uuid, p_painted integer)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select public.apply_bps(public.artwork_create_cost_cents(p_painted), 10000 - public.player_art_discount_bps(p_player));
$$;
comment on function public.player_artwork_create_cost_cents(uuid, integer) is
  'Internal: price of the next artwork of a player with p_painted artworks, with the artist upgrade (ADR-100).';

-- A title is taken when any artwork (gallery or player) has the same name key (lookalikes, as for nicknames)
create or replace function public.artwork_title_taken(p_title text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.artworks a where public.name_key(a.title) = public.name_key(p_title));
$$;
comment on function public.artwork_title_taken(text) is 'Internal: an artwork with this title or a lookalike exists (ADR-100).';

-- -> {allowed, reason}: the title as create_artwork would store it (trimmed, single spaces)
create or replace function public.check_artwork_title(p_title text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_title  text := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g'));
  v_reason text;
begin
  perform public.require_player();
  v_reason := public.artwork_title_violation(v_title);
  if v_reason is null and public.artwork_title_taken(v_title) then
    v_reason := 'name_taken';
  end if;
  return jsonb_build_object('allowed', v_reason is null, 'reason', v_reason);
end;
$$;
comment on function public.check_artwork_title(text) is
  'RPC: {allowed, reason} for an artwork title (ADR-100); reason null or name_too_short, name_too_long, '
  'name_invalid_chars, name_profanity, name_taken.';

create or replace function public.get_art_studio()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_painted integer;
begin
  v_player := public.require_player();
  select count(*) into v_painted from public.artworks a where a.creator_id = v_player;
  return jsonb_build_object(
    'painted', v_painted,
    'next_cost_cents', public.player_artwork_create_cost_cents(v_player, v_painted),
    'unlocked', coalesce((select p.level from public.profiles p where p.id = v_player), 1) >= public.unlock_level('artworks'));
end;
$$;
comment on function public.get_art_studio() is
  'RPC: {painted, next_cost_cents, unlocked} for the art editor (ADR-080); next_cost_cents with the artist upgrade (ADR-100).';

create or replace function public.create_artwork(p_request_id uuid, p_title text, p_pixels jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  v_title   text := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g'));
  v_reason  text;
  v_painted integer;
  v_cost    bigint;
  v_cash    bigint;
  v_id      uuid := gen_random_uuid();
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or not public.artwork_valid(p_pixels) then
    perform public.api_error('invalid_argument');
  end if;
  v_reason := public.artwork_title_violation(v_title);
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'create_artwork');
  if v_replay is not null then
    return v_replay;
  end if;
  -- unique titles (ADR-100): lookalikes count as the same title; the lock serialises two painters of one title
  perform pg_advisory_xact_lock(hashtextextended('artwork_title:' || public.name_key(v_title), 0));
  if public.artwork_title_taken(v_title) then
    perform public.api_error('name_taken');
  end if;
  if public.logo_has_forbidden_symbol(p_pixels -> 'grid') then
    perform public.api_error('logo_forbidden');
  end if;
  -- one painting at a time per player (the count decides the price)
  perform 1 from public.profiles p where p.id = v_player for update;
  select count(*) into v_painted from public.artworks a where a.creator_id = v_player;
  -- artist upgrade (ADR-100): the price x (10 000 − artDiscountBps) / 10 000
  v_cost := public.player_artwork_create_cost_cents(v_player, v_painted);
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('treasury'),
                                 v_cost, 'artwork_creation', 'Kunstwerk gemalt', 'artwork', v_id,
                                 'art:create:' || v_id::text, v_player, jsonb_build_object('painted_before', v_painted,
                                                                   'discount_bps', public.player_art_discount_bps(v_player)));
  insert into public.artworks (id, title, origin, rarity, creator_id, owner_id, pixels)
  values (v_id, v_title, 'player', null, v_player, v_player,
          jsonb_build_object('palette', p_pixels -> 'palette', 'grid', p_pixels -> 'grid'));
  perform public.mission_event(v_player, 'art_painted', 1, null);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'artwork', public.artwork_json(v_id, v_player),
    'cost_cents', v_cost,
    'next_cost_cents', public.player_artwork_create_cost_cents(v_player, v_painted + 1)));
end;
$$;
comment on function public.create_artwork(uuid, text, jsonb) is
  'RPC: paints a new artwork (cost doubles per artwork, less the artist upgrade, paid to the treasury); errors artworks_locked, '
  'invalid_argument, name_* (name_taken: the title or a lookalike exists), logo_forbidden, insufficient_funds.';

-- ---------------------------------------------------------------------------
-- E. Company names: unique among the companies that still exist; replacing the own company
-- ---------------------------------------------------------------------------
-- name_violation as in M4d; companies: taken only by a company that still exists, player companies also by lookalikes
create or replace function public.name_violation(p_name text, p_kind text default 'player', p_exclude uuid default null)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_names  jsonb := coalesce(public.config_jsonb('names'), '{}'::jsonb);
  v_min    integer;
  v_max    integer;
  v_full   text;
  v_tokens text[];
  v_raw    text[];
  v_cat    text;
begin
  if p_kind = 'company' then
    v_min := 3; v_max := 30;
  else
    v_min := public.cfg_num(v_names, '{minLength}', 3)::integer;
    v_max := public.cfg_num(v_names, '{maxLength}', 20)::integer;
  end if;
  if p_name is null or char_length(p_name) < v_min then
    return 'name_too_short';
  end if;
  if char_length(p_name) > v_max then
    return 'name_too_long';
  end if;
  if p_kind = 'company' then
    if p_name !~ '^[A-Za-zÄÖÜäöüßÀ-ÿ0-9 &.''-]+$' or p_name <> btrim(p_name) or p_name ~ '  ' then
      return 'name_invalid_chars';
    end if;
  elsif p_name !~ '^[A-Za-z0-9_]+$' then
    return 'name_invalid_chars';
  end if;

  v_full := public.name_letters(p_name);
  select coalesce(array_agg(regexp_replace(t, '(.)\1+', '\1', 'g')), '{}') into v_tokens
    from regexp_split_to_table(public.name_normalize(p_name, true), '[^a-z]+') t where t <> '';
  select coalesce(array_agg(m[1]), '{}') into v_raw
    from regexp_matches(public.name_normalize(p_name, false), '([a-z]+|[0-9]+)', 'g') m;
  if v_full = '' then
    return 'name_invalid_chars';
  end if;

  select t.category into v_cat
    from public.blocked_name_terms t
   where (t.match_mode = 'substring' and strpos(v_full, t.term) > 0)
      or (t.match_mode = 'token' and (t.term = v_full or t.term = any (v_tokens) or t.term = any (v_raw)))
      or (t.match_mode = 'code' and t.term = any (v_raw))
   order by (t.category = 'reserved'), t.term
   limit 1;
  if v_cat is not null then
    return case when v_cat = 'reserved' then 'name_reserved' else 'name_profanity' end;
  end if;

  -- dynamic reserved names: AI tycoons, AI companies (with and without legal form), tickers, index keys
  if exists (select 1 from public.rich_tycoons ty where public.name_letters(ty.name) = v_full
                or (char_length(public.name_letters(ty.name)) >= 5 and strpos(v_full, public.name_letters(ty.name)) > 0))
     or exists (select 1 from public.companies c
                 where c.is_ai and c.id is distinct from p_exclude
                   and (public.name_letters(c.name) = v_full
                        or (char_length(public.name_letters(regexp_replace(c.name, '\s+(AG|SE|GmbH|KG)$', '', 'i'))) >= 5
                            and strpos(v_full, public.name_letters(regexp_replace(c.name, '\s+(AG|SE|GmbH|KG)$', '', 'i'))) > 0)))
     or exists (select 1 from public.securities s
                 where lower(s.ticker) = any (v_raw) or lower(s.ticker) = lower(p_name)
                    or public.name_letters(s.ticker) = v_full)
     or exists (select 1 from public.indices i where lower(i.key) = any (v_raw) or public.name_letters(i.key) = v_full) then
    return 'name_reserved';
  end if;

  if p_kind = 'company' then
    -- ADR-100: taken only by a company that still exists (a closed or dissolved one frees its name); among player
    -- companies lookalikes count as the same name (name_key, as for nicknames)
    if exists (select 1 from public.companies c
                where c.dissolved_at is null and c.id is distinct from p_exclude
                  and (lower(c.name) = lower(p_name)
                       or (not c.is_ai and public.name_key(c.name) = public.name_key(p_name)
                           and exists (select 1 from public.player_companies pc
                                        where pc.company_id = c.id and pc.status = 'active')))) then
      return 'name_taken';
    end if;
  elsif exists (select 1 from public.profiles p
                 where (lower(p.nickname) = lower(p_name) or public.name_key(p.nickname) = public.name_key(p_name))
                   and p.id is distinct from p_exclude) then
    -- also lookalikes (ADR-085): same name key as another player's nickname
    return 'name_taken';
  end if;
  return null;
end;
$$;

create or replace function public.check_company_name(p_name text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_reason text;
begin
  v_player := public.require_player();
  -- the caller's own company does not block its name: founding again replaces it (found_company p_replace)
  v_reason := public.name_violation(p_name, 'company', public.player_active_company(v_player));
  return jsonb_build_object('allowed', v_reason is null, 'reason', v_reason);
end;
$$;
comment on function public.check_company_name(text) is
  'RPC: {allowed, reason} for a company name (ADR-100: unique among companies that still exist, lookalikes taken; the '
  'caller''s own company does not count).';

-- found_company as in M4c plus p_replace (ADR-100): with an active company and p_replace the old company is closed
-- exactly like close_company (company_dissolve 'closed': wages, severances, rest to the founder), then the new one is
-- founded in the same transaction; without p_replace company_exists as before.
drop function if exists public.found_company(uuid, text, text, text, text, text, text);
create or replace function public.found_company(p_request_id uuid, p_name text, p_idea text, p_sector text, p_color text,
                                                p_tier text, p_product text default null, p_replace boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_idea   text := btrim(coalesce(p_idea, ''));
  v_reason text;
  v_tier   jsonb;
  v_level  integer;
  v_cost   bigint;
  v_cash   bigint;
  v_id     uuid := gen_random_uuid();
  v_acc    uuid;
  v_old    uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'found_company');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  if coalesce(p_tier, '') not in ('garage', 'small_business', 'gmbh')
     or not exists (select 1 from public.sectors s where s.key = p_sector)
     or public.config_jsonb('startups', array['capacityCentsPerProductivity', p_sector]) is null
     or coalesce(p_color, '') !~ '^#[0-9a-fA-F]{6}$'
     or char_length(v_idea) not between 1 and 120
     or (p_product is not null
         and not exists (select 1 from jsonb_array_elements(coalesce(public.config_jsonb('startups', array['products', p_sector]), '[]'::jsonb)) x
                          where x ->> 'key' = p_product)) then
    perform public.api_error('invalid_argument');
  end if;
  if public.text_has_profanity(v_idea) then
    perform public.api_error('name_profanity');
  end if;
  perform 1 from public.profiles p where p.id = v_player for update;
  -- one company at a time; with p_replace the old one is closed below exactly like close_company (ADR-100)
  select pc.company_id into v_old from public.player_companies pc where pc.founder_id = v_player and pc.status = 'active';
  if v_old is not null and not coalesce(p_replace, false) then
    perform public.api_error('company_exists');
  end if;
  if exists (select 1 from public.profiles p where p.id = v_player and p.founding_locked_until > now()) then
    perform public.api_error('founding_locked');
  end if;
  -- unique among existing companies (ADR-100); the lock serialises two foundings of one name (lookalikes share the
  -- key). The company that is replaced may hand its own name on.
  perform pg_advisory_xact_lock(hashtextextended('company_name:' || public.name_key(p_name), 0));
  v_reason := public.name_violation(p_name, 'company', v_old);
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_tier := public.company_tier_cfg(p_tier);
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < (v_tier ->> 'minLevel')::integer then
    perform public.api_error('company_level_too_low');
  end if;
  if v_old is not null then
    perform public.company_dissolve(v_old, 'closed');
  end if;
  v_cost := (v_tier ->> 'foundingCostCents')::bigint;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;

  insert into public.companies (id, name, slug, description, sector_key, is_ai, legal_form, phase, founder_id, ceo_id,
                                brand_color, shares_outstanding, max_employees, founded_quarter_id, founded_at)
  values (v_id, p_name, trim(both '-' from lower(regexp_replace(p_name, '[^A-Za-z0-9]+', '-', 'g'))) || '-' || left(v_id::text, 8),
          v_idea, p_sector, false, case when p_tier = 'gmbh' then 'gmbh' else 'small_business' end::public.legal_form, 'private', v_player, v_player, lower(p_color), 1,
          (v_tier ->> 'maxEmployees')::integer, (public.current_game_quarter()).id, now());
  insert into public.ledger_accounts (kind, owner_company_id, label) values ('company_cash', v_id, 'Firmenkasse')
  returning id into v_acc;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), v_acc, v_cost, 'company_founding',
                                   'Gründung ' || p_name, 'company', v_id, 'found:' || v_id::text, v_player);
  end if;
  insert into public.player_companies (company_id, founder_id, idea, tier, potential_annual_cents, awareness, quality, request_id,
                                       product_key)
  values (v_id, v_player, v_idea, p_tier, public.startup_potential_from_uniform(1 - random()),
          -- founding bigger buys a head start (ADR-083, initialStartup(tier))
          least(1, greatest(0, public.config_double('startups', array['foundingAwareness', p_tier],
                                                    public.config_double('startups', '{awareness,initial}', 0.03)))),
          public.config_double('startups', '{quality,base}', 0.25),
          p_request_id,
          coalesce(p_product, public.config_jsonb('startups', array['products', p_sector]) -> 0 ->> 'key'));
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_id)));
end;
$$;
comment on function public.found_company(uuid, text, text, text, text, text, text, boolean) is
  'RPC: founds a company -> {company: COMPANY}; p_replace closes the caller''s active company first (like close_company, '
  'ADR-100), else company_exists. Errors invalid_argument, rate_limited, name_*, company_exists, founding_locked, '
  'company_level_too_low, insufficient_funds.';

-- ---------------------------------------------------------------------------
-- F. Fixed costs with the efficiency upgrade (player_company_close_hour as in M4j)
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_ev      jsonb;
  v_camp    public.company_campaigns;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_owed    bigint;
  v_free    bigint;
  v_stakes  bigint := 0;
  v_sp      bigint;
  v_payout  bigint := 0;
  v_bps     integer;
  v_until   timestamptz;
  v_news    bigint;
  k         text;
  j         record;
  s         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');
  -- company event of this hour (ADR-091): demand and capacity factors, extra costs as a share of the own revenue
  v_ev := public.company_event_hour_effect(p_company, v_start, v_end);
  -- marketing campaign (ADR-097, campaignDemandFactor): its factor when the hour starts inside its window
  v_camp := public.company_campaign_at(p_company, v_start);

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision
            * (v_ev ->> 'demand_factor')::double precision
            * greatest(0, coalesce(v_camp.demand_factor, 1));
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level)
         * (v_ev ->> 'capacity_factor')::double precision / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  -- goods; an event's extra costs (or savings) move with the own revenue, goods never cost less than nothing
  v_cogs := round(greatest(0, v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5))
                              + v_own * (v_ev ->> 'extra_cost_share')::double precision)::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- presence (ADR-103): employees away for careers.inactivity.fireAfterHours lose the job first, paid up to that moment
  for j in select pj.id from public.player_jobs pj where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    perform public.job_absence_check(j.id, v_end);
  end loop;
  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  -- efficiency upgrade of the founder (ADR-100): the hour's fixed costs x (10 000 − fixedCostDiscountBps) / 10 000
  v_fixed := public.apply_bps(round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint,
                              10000 - public.player_fixed_cost_discount_bps(pc.founder_id));
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  v_owed := pc.unpaid_cents + v_unpaid - v_settle;

  -- stakes (ADR-098, stakePayoutCents): every running stake whose term holds this hour takes its share of a
  -- profitable hour (rounded down), never more than the free cash; served before the CEO payout. The hour is marked
  -- as handled (settled_until) whether it paid or not.
  for s in select x.id, x.investor_id, x.share_bps from public.deals x
            where x.kind = 'stake' and x.status = 'active' and x.company_id = p_company
              and x.settled_until <= v_start and x.ends_at > v_start
            order by x.accepted_at, x.id for update of x
  loop
    v_sp := 0;
    if v_profit > 0 then
      select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
      v_sp := least(v_profit * s.share_bps / 10000, greatest(0, coalesce(v_free, 0)));
    end if;
    if v_sp > 0 then
      perform public.lock_player_accounts(s.investor_id);
      perform public.ledger_transfer(v_acc, public.ledger_player_account(s.investor_id, 'player_cash'), v_sp, 'dividend',
                                     'Gewinnanteil ' || c.name || ' ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                     'deal', s.id, k || ':stake:' || s.id::text, s.investor_id);
      perform public.loan_withhold(s.investor_id, v_sp, k || ':stake:' || s.id::text);
      v_stakes := v_stakes + v_sp;
    end if;
    update public.deals set payouts_cents = payouts_cents + v_sp, settled_until = v_end where id = s.id;
  end loop;

  -- automatic CEO payout (ADR-086, founderPayoutCents): after the hour's own bookings and the stakes, a share of the
  -- profit left after the stake payouts (rounded down) moves from the company cash to the founder's private cash like
  -- company_withdraw, never more than the free cash. A transfer, not a cost: profit_cents stays as computed above.
  v_bps := least(10000, greatest(0, coalesce(pc.founder_payout_bps, 0)));
  if v_profit - v_stakes > 0 and v_bps > 0 then
    select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
    v_payout := least((v_profit - v_stakes) * v_bps / 10000, greatest(0, coalesce(v_free, 0)));
  end if;
  if v_payout > 0 then
    perform public.lock_player_accounts(pc.founder_id);
    perform public.ledger_transfer(v_acc, public.ledger_player_account(pc.founder_id, 'player_cash'), v_payout, 'transfer',
                                   'CEO-Auszahlung ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':payout', pc.founder_id);
    perform public.loan_withhold(pc.founder_id, v_payout, k || ':payout');
  end if;

  -- record hour (ADR-091): beating an earlier best hour is news, at most one item per Berlin day (updated while the
  -- day's record keeps rising and no AI text was written for it)
  if v_profit > coalesce(pc.best_hour_profit_cents, 0) and coalesce(pc.best_hour_profit_cents, 0) > 0 then
    select n.id into v_news from public.company_news n
     where n.company_id = p_company and n.kind = 'record_hour'
       and ((n.payload ->> 'hour_start')::timestamptz at time zone 'Europe/Berlin')::date
           = (v_start at time zone 'Europe/Berlin')::date
     order by n.id desc limit 1;
    if v_news is null then
      perform public.company_news_add(p_company, 'record_hour',
                                      jsonb_build_object('profit_cents', v_profit, 'hour_start', v_start));
    else
      update public.company_news set payload = jsonb_build_object('profit_cents', v_profit, 'hour_start', v_start)
       where id = v_news and ai_headline is null;
    end if;
  end if;

  update public.player_companies
     set unpaid_cents = v_owed,
         distress = v_owed > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end),
         best_hour_profit_cents = greatest(best_hour_profit_cents, v_profit)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents, founder_payout_cents, event_id,
                                           stake_payout_cents, campaign_id)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit, v_payout,
          (v_ev ->> 'event_id')::uuid, v_stakes, v_camp.id);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid,
                            'founder_payout_cents', v_payout, 'event_id', v_ev -> 'event_id', 'stake_payout_cents', v_stakes,
                            'campaign_id', v_camp.id);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072/083) with the company event (ADR-091) and '
  'the marketing campaign (ADR-097) of the hour, fixed costs less the founder''s efficiency upgrade (ADR-100), pays the '
  'stakes (ADR-098) and then the automatic CEO payout from the profit left (ADR-086), writes the record_hour news; '
  'idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- G. Home: makler discount on every purchase, the top layer in the layout
-- ---------------------------------------------------------------------------
create or replace function public.buy_home(p_request_id uuid, p_tier text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  h        public.player_homes;
  t        jsonb;
  cur      jsonb;
  v_cash   bigint;
  v_cost   bigint;
  v_list   bigint;
  v_disc   integer;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  t := public.property_tier(p_tier);
  if p_request_id is null or t is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_home');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  h := public.property_home_for_update(v_player);
  if coalesce((select p.level from public.profiles p where p.id = v_player), 1) < (t ->> 'minLevel')::integer then
    perform public.api_error('property_locked');
  end if;
  cur := public.property_tier(h.tier);
  if cur is not null and (t ->> 'idx')::integer <= (cur ->> 'idx')::integer then
    perform public.api_error('invalid_tier');
  end if;
  -- makler upgrade (ADR-100): what is paid (price minus trade-in) x (10 000 − propertyDiscountBps) / 10 000
  v_list := public.property_upgrade_cost_cents(case when cur is null then null else h.tier end, p_tier);
  v_disc := public.player_property_discount_bps(v_player);
  v_cost := public.apply_bps(v_list, 10000 - v_disc);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_cost, 'lifestyle_purchase',
                                   case when cur is null then 'Eigene Bleibe gekauft' else 'Umzug in eine größere Bleibe' end,
                                   'player_home', v_player, 'property:home:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('from', case when cur is null then null else h.tier end, 'to', p_tier,
                                                      'trade_in_cents', public.property_trade_in_cents(case when cur is null then null else h.tier end),
                                                      'list_cost_cents', v_list, 'discount_bps', v_disc));
  end if;
  update public.player_furniture set placed = false, x = null, y = null, rot = 0 where player_id = v_player and placed;
  update public.player_homes set tier = p_tier, updated_at = now() where player_id = v_player;
  perform public.mission_event(v_player, 'home_bought', 1, p_tier);
  if cur is not null then
    perform public.mission_event(v_player, 'home_upgraded', 1, p_tier);
  end if;
  return public.request_complete(v_player, p_request_id,
    public.property_state(v_player, v_player) || jsonb_build_object('cost_cents', v_cost));
end;
$$;
comment on function public.buy_home(uuid, text) is
  'RPC: buys the first or a bigger home (cost = (price - trade-in of the current one) less the makler upgrade; furniture '
  'back into the inventory); errors property_locked, invalid_argument, invalid_tier, insufficient_funds.';

create or replace function public.buy_furniture(p_request_id uuid, p_item_key text, p_count integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_price  bigint;
  v_cash   bigint;
  v_cost   bigint;
  v_disc   integer;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  -- docs/PROPERTY.md: 1 to 20 pieces per purchase
  if p_request_id is null or p_item_key is null or p_count is null or p_count < 1 or p_count > 20 then
    perform public.api_error('invalid_argument');
  end if;
  select c.price_cents into v_price from public.furniture_catalog c where c.key = p_item_key;
  if v_price is null then
    perform public.api_error('item_not_found');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_furniture');
  if v_replay is not null then
    return v_replay;
  end if;
  -- makler upgrade (ADR-100): the discounted unit price is the price paid (resale and net worth use it)
  v_disc := public.player_property_discount_bps(v_player);
  v_price := public.apply_bps(v_price, 10000 - v_disc);
  v_cost := v_price * p_count;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_cost, 'lifestyle_purchase', 'Möbel gekauft', 'furniture', null,
                                   'property:furniture:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('item_key', p_item_key, 'count', p_count, 'price_cents', v_price,
                                                      'discount_bps', v_disc));
  end if;
  insert into public.player_furniture (player_id, item_key, price_paid_cents)
  select v_player, p_item_key, v_price from generate_series(1, p_count);
  perform public.mission_event(v_player, 'furniture_bought', p_count, p_item_key);
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.buy_furniture(uuid, text, integer) is
  'RPC: buys 1..20 pieces of furniture into the inventory (price less the makler upgrade, stored as price paid); errors '
  'property_locked, invalid_argument, item_not_found, insufficient_funds.';

create or replace function public.buy_floor(p_request_id uuid, p_material text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_price  bigint;
  v_cash   bigint;
  h        public.player_homes;
  v_paid   bigint;
  v_disc   integer;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  v_price := public.property_floor_price_cents(p_material);
  if p_request_id is null or v_price is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_floor');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  h := public.property_home_for_update(v_player);
  if not public.property_floor_owned(h.floors_owned, p_material) then
    -- makler upgrade (ADR-100)
    v_disc := public.player_property_discount_bps(v_player);
    v_paid := public.apply_bps(v_price, 10000 - v_disc);
    if v_cash < v_paid then
      perform public.api_error('insufficient_funds');
    end if;
    if v_paid > 0 then
      perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                     v_paid, 'lifestyle_purchase', 'Bodenbelag gekauft', 'player_home', v_player,
                                     'property:floor:' || v_player::text || ':' || p_material, v_player,
                                     jsonb_build_object('material', p_material, 'list_price_cents', v_price, 'discount_bps', v_disc));
    end if;
    update public.player_homes set floors_owned = array_append(floors_owned, p_material), updated_at = now()
     where player_id = v_player;
  end if;
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.buy_floor(uuid, text) is
  'RPC: buys a floor material once (owned or free: no charge; price less the makler upgrade); errors property_locked, '
  'invalid_argument, insufficient_funds.';

create or replace function public.buy_car(p_request_id uuid, p_car_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  h        public.player_homes;
  t        jsonb;
  v_price  bigint;
  v_cash   bigint;
  v_slots  integer;
  v_slot   integer;
  v_id     uuid := gen_random_uuid();
  v_disc   integer;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  if p_request_id is null or p_car_key is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_car');
  if v_replay is not null then
    return v_replay;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  select * into h from public.player_homes where player_id = v_player for update;
  t := public.property_tier(h.tier);
  if t is null then
    perform public.api_error('no_home');
  end if;
  select c.price_cents into v_price from public.car_catalog c where c.key = p_car_key;
  if v_price is null then
    perform public.api_error('item_not_found');
  end if;
  -- makler upgrade (ADR-100): the discounted price is the price paid (resale and net worth use it)
  v_disc := public.player_property_discount_bps(v_player);
  v_price := public.apply_bps(v_price, 10000 - v_disc);
  v_slots := coalesce((t ->> 'garageSlots')::integer, 0);
  select min(s) into v_slot from generate_series(0, v_slots - 1) s
   where not exists (select 1 from public.player_cars c where c.player_id = v_player and c.slot = s);
  if v_slot is null then
    perform public.api_error('garage_full');
  end if;
  if v_cash < v_price then
    perform public.api_error('insufficient_funds');
  end if;
  if v_price > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_price, 'lifestyle_purchase', 'Auto gekauft', 'car', v_id,
                                   'property:car:' || v_id::text, v_player,
                                   jsonb_build_object('car_key', p_car_key, 'discount_bps', v_disc));
  end if;
  insert into public.player_cars (id, player_id, car_key, slot, price_paid_cents) values (v_id, v_player, p_car_key, v_slot, v_price);
  perform public.mission_event(v_player, 'car_bought', 1, p_car_key);
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.buy_car(uuid, text) is
  'RPC: buys a car into the first free garage slot (price less the makler upgrade, stored as price paid); errors '
  'property_locked, invalid_argument, no_home, item_not_found, garage_full, insufficient_funds.';

create or replace function public.save_layout(p_request_id uuid, p_wall_color text, p_floor text, p_placed jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  h        public.player_homes;
  t        jsonb;
  v_w      integer;
  v_h      integer;
  v_n      integer;
begin
  v_player := public.require_player();
  perform public.property_require_unlock(v_player);
  if p_request_id is null or p_wall_color is null or p_floor is null or jsonb_typeof(p_placed) is distinct from 'array'
     or not coalesce(public.property_config() -> 'wallColors' @> to_jsonb(lower(p_wall_color)), false) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'save_layout');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into h from public.player_homes where player_id = v_player for update;
  t := public.property_tier(h.tier);
  if t is null then
    perform public.api_error('no_home');
  end if;
  if not public.property_floor_owned(h.floors_owned, p_floor) then
    perform public.api_error('floor_not_owned');
  end if;
  v_w := (t ->> 'width')::integer;
  v_h := (t ->> 'height')::integer;

  -- shape: {id: uuid, x, y: integers >= 0, rot: 0 | 90}
  if exists (select 1 from jsonb_array_elements(p_placed) e
              where jsonb_typeof(e) is distinct from 'object'
                 or jsonb_typeof(e -> 'id') is distinct from 'string'
                 or (e ->> 'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 or jsonb_typeof(e -> 'x') is distinct from 'number' or (e ->> 'x') !~ '^[0-9]{1,4}$'
                 or jsonb_typeof(e -> 'y') is distinct from 'number' or (e ->> 'y') !~ '^[0-9]{1,4}$'
                 or jsonb_typeof(e -> 'rot') is distinct from 'number' or (e ->> 'rot') not in ('0', '90')) then
    perform public.api_error('layout_invalid');
  end if;
  -- every id once and owned by the caller
  select count(*) into v_n from jsonb_array_elements(p_placed);
  if v_n <> (select count(distinct (e ->> 'id')::uuid) from jsonb_array_elements(p_placed) e)
     or v_n <> (select count(*) from jsonb_array_elements(p_placed) e
                  join public.player_furniture f on f.id = (e ->> 'id')::uuid and f.player_id = v_player) then
    perform public.api_error('layout_invalid');
  end if;
  -- invalidPlacements: inside the floor, no two pieces of the same layer on one tile (rugs lie under objects, small
  -- things stand on objects: one per tile)
  if exists (
       with p as (
         select (e ->> 'x')::integer as x, (e ->> 'y')::integer as y, c.layer,
                case when (e ->> 'rot') = '90' then c.height else c.width end::integer as w,
                case when (e ->> 'rot') = '90' then c.width else c.height end::integer as hh
           from jsonb_array_elements(p_placed) e
           join public.player_furniture f on f.id = (e ->> 'id')::uuid
           join public.furniture_catalog c on c.key = f.item_key)
       select 1 from p where p.x + p.w > v_w or p.y + p.hh > v_h)
  then
    perform public.api_error('layout_invalid');
  end if;
  if exists (
       with p as (
         select (e ->> 'x')::integer as x, (e ->> 'y')::integer as y, c.layer,
                case when (e ->> 'rot') = '90' then c.height else c.width end::integer as w,
                case when (e ->> 'rot') = '90' then c.width else c.height end::integer as hh
           from jsonb_array_elements(p_placed) e
           join public.player_furniture f on f.id = (e ->> 'id')::uuid
           join public.furniture_catalog c on c.key = f.item_key)
       select 1 from p
         cross join lateral generate_series(p.x, p.x + p.w - 1) cx
         cross join lateral generate_series(p.y, p.y + p.hh - 1) cy
        group by p.layer, cx, cy
       having count(*) > 1)
  then
    perform public.api_error('layout_invalid');
  end if;

  -- the top layer (ADR-100): every tile of a small thing lies on a placed object with a surface
  if exists (
       with p as (
         select (e ->> 'x')::integer as x, (e ->> 'y')::integer as y, c.layer, c.surface,
                case when (e ->> 'rot') = '90' then c.height else c.width end::integer as w,
                case when (e ->> 'rot') = '90' then c.width else c.height end::integer as hh
           from jsonb_array_elements(p_placed) e
           join public.player_furniture f on f.id = (e ->> 'id')::uuid
           join public.furniture_catalog c on c.key = f.item_key),
       t as (
         select p.layer, p.surface, cx, cy from p
          cross join lateral generate_series(p.x, p.x + p.w - 1) cx
          cross join lateral generate_series(p.y, p.y + p.hh - 1) cy)
       select 1 from t
        where t.layer = 'top'
          and not exists (select 1 from t s where s.layer = 'object' and s.surface and s.cx = t.cx and s.cy = t.cy))
  then
    perform public.api_error('layout_invalid');
  end if;

  update public.player_furniture set placed = false, x = null, y = null, rot = 0 where player_id = v_player and placed;
  update public.player_furniture f
     set placed = true, x = (e ->> 'x')::smallint, y = (e ->> 'y')::smallint, rot = (e ->> 'rot')::smallint
    from jsonb_array_elements(p_placed) e
   where f.id = (e ->> 'id')::uuid and f.player_id = v_player;
  update public.player_homes set wall_color = lower(p_wall_color), floor = p_floor, updated_at = now() where player_id = v_player;
  perform public.mission_event(v_player, 'furniture_placed', v_n, null);
  return public.request_complete(v_player, p_request_id, public.property_state(v_player, v_player));
end;
$$;
comment on function public.save_layout(uuid, text, text, jsonb) is
  'RPC: replaces the layout, wall colour and floor of the home (three layers: floor, object, top on surfaces, ADR-100); '
  'errors property_locked, invalid_argument (wall colour), no_home, floor_not_owned, layout_invalid.';

-- ---------------------------------------------------------------------------
-- H. Deals with the company: size limit (port of dealSizeLimitCents, supplyMaxCostCents)
-- ---------------------------------------------------------------------------
-- supplyMaxCostCents: applyBps(volume × hours, fee), half even
create or replace function public.deal_supply_max_cost_cents(p_volume bigint, p_hours integer, p_fee_bps integer)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select public.div_round_half_even(p_volume::numeric * p_hours * p_fee_bps, 10000);
$$;

-- dealSizeLimitCents: max(minSizeCents, floor(max(0, company value) × sizeShareOfValueBps / 10 000)); null without a
-- company. Company value as in COMPANY.value_cents (company_value_cents).
create or replace function public.deal_size_limit_cents(p_company uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select case when p_company is null then null
              else greatest(public.cfg_num(x.c, '{minSizeCents}', 5000000)::bigint,
                            floor(greatest(0, coalesce(public.company_value_cents(p_company), 0))::numeric
                                  * public.cfg_num(x.c, '{sizeShareOfValueBps}', 5000)::numeric / 10000)::bigint) end
    from (select public.deals_cfg() as c) x;
$$;
comment on function public.deal_size_limit_cents(uuid) is
  'Internal: biggest supply contract (most possible cost) or stake for a company (dealSizeLimitCents, ADR-100).';

-- true when a supply contract (its most possible cost) or a stake (its amount) is bigger than the limit of p_company;
-- false for loans, without a company and for terms deal_terms_error refuses anyway
create or replace function public.deal_exceeds_size(p_kind text, p_terms jsonb, p_company uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(case
    when p_company is null then false
    when p_kind = 'supply' then public.deal_supply_max_cost_cents(public.deal_term_int(p_terms, 'volume_cents_per_hour'),
                                                                  public.deal_term_int(p_terms, 'hours')::integer,
                                                                  public.deal_term_int(p_terms, 'fee_bps')::integer)
                                > public.deal_size_limit_cents(p_company)
    when p_kind = 'stake' then public.deal_term_int(p_terms, 'amount_cents') > public.deal_size_limit_cents(p_company)
    else false end, false);
$$;
comment on function public.deal_exceeds_size(text, jsonb, uuid) is
  'Internal: the deal is bigger than the size limit of the company (ADR-100) -> deal_too_big.';

-- propose_deal as in M4j plus the size limit of the proposer's and a targeted counterparty's company
create or replace function public.propose_deal(p_request_id uuid, p_kind text, p_role text, p_counterparty text, p_terms jsonb,
                                               p_message text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player   uuid;
  v_replay   jsonb;
  v_cfg      jsonb := public.deals_cfg();
  v_now      timestamptz := public.game_now();
  v_msg      text := nullif(btrim(coalesce(p_message, '')), '');
  v_handle   text := nullif(btrim(coalesce(p_counterparty, '')), '');
  v_level    integer;
  v_target   uuid;
  v_other    text;
  v_err      text;
  v_my_co    uuid;
  v_their_co uuid;
  v_share    integer;
  v_id       uuid;
  d          public.deals;
  v_nick     text;
begin
  v_player := public.require_player();
  if p_request_id is null or coalesce(p_kind, '') not in ('loan', 'supply', 'stake') or not public.deal_role_ok(p_kind, p_role)
     or char_length(coalesce(p_counterparty, '')) > 64 then
    perform public.api_error('invalid_argument');
  end if;
  if v_msg is not null and (char_length(v_msg) > 140 or v_msg ~ '[[:cntrl:]]') then
    perform public.api_error('invalid_argument');
  end if;
  if public.text_has_profanity(v_msg) then
    perform public.api_error('name_profanity');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'propose_deal');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if coalesce(v_level, 1) < public.cfg_num(v_cfg, '{minLevel}', 6) then
    perform public.api_error('locked');
  end if;
  if v_handle is not null then
    v_target := public.player_by_handle(v_handle);
    if v_target is null then
      perform public.api_error('player_not_found');
    end if;
    if v_target = v_player then
      perform public.api_error('deal_self');
    end if;
  end if;
  v_other := public.deal_other_role(p_role);
  -- the loan cap needs the lender's level: the proposer, or a targeted lender; else at acceptance
  v_err := public.deal_terms_error(p_kind, p_terms,
             case when p_role = 'lender' then v_level
                  when p_role = 'borrower' and v_target is not null then (select p.level from public.profiles p where p.id = v_target) end);
  if v_err is not null then
    perform public.api_error('deal_terms');
  end if;
  if public.deal_role_needs_company(p_role) then
    v_my_co := public.player_active_company(v_player);
    if v_my_co is null then
      perform public.api_error('deal_needs_company');
    end if;
  end if;
  if v_target is not null and public.deal_role_needs_company(v_other) then
    v_their_co := public.player_active_company(v_target);
    if v_their_co is null then
      perform public.api_error('deal_needs_company');
    end if;
  end if;
  -- company deals grow with the company (ADR-100): at most dealSizeLimitCents of the proposer's company and of a
  -- targeted counterparty's company; checked again at acceptance
  if public.deal_exceeds_size(p_kind, p_terms, v_my_co) or public.deal_exceeds_size(p_kind, p_terms, v_their_co) then
    perform public.api_error('deal_too_big');
  end if;
  -- all stakes of a company together stay within maxTotalShareBps (company side: with its open offers)
  if p_kind = 'stake' then
    v_share := public.deal_term_int(p_terms, 'share_bps')::integer;
    if (p_role = 'company' and public.deal_stake_shares(v_my_co, true) + v_share > public.cfg_num(v_cfg, '{stake,maxTotalShareBps}', 5000))
       or (p_role = 'investor' and v_their_co is not null
           and public.deal_stake_shares(v_their_co, false) + v_share > public.cfg_num(v_cfg, '{stake,maxTotalShareBps}', 5000)) then
      perform public.api_error('stake_share_full');
    end if;
  end if;
  if (select count(*) from public.deals x where x.proposer_id = v_player and x.status = 'open' and x.expires_at > v_now)
     >= public.cfg_num(v_cfg, '{maxOpenOffers}', 5)
     or public.deal_count_running(v_player, p_kind) >= public.cfg_num(v_cfg, '{maxActivePerKind}', 5) then
    perform public.api_error('deal_limit');
  end if;

  insert into public.deals (kind, status, proposer_id, proposer_role, counterparty_id, board,
                            lender_id, borrower_id, supplier_company_id, buyer_company_id, investor_id, company_id,
                            principal_cents, interest_bps, volume_cents_per_hour, fee_bps, prepay_bps, amount_cents, share_bps,
                            hours, message, due_cents, prepay_cents, created_at, expires_at, request_id)
  values (p_kind, 'open', v_player, p_role, v_target, v_target is null,
          case p_role when 'lender' then v_player when 'borrower' then v_target end,
          case p_role when 'borrower' then v_player when 'lender' then v_target end,
          case p_role when 'supplier' then v_my_co when 'buyer' then v_their_co end,
          case p_role when 'buyer' then v_my_co when 'supplier' then v_their_co end,
          case p_role when 'investor' then v_player when 'company' then v_target end,
          case p_role when 'company' then v_my_co when 'investor' then v_their_co end,
          case when p_kind = 'loan' then public.deal_term_int(p_terms, 'principal_cents') end,
          case when p_kind = 'loan' then public.deal_term_int(p_terms, 'interest_bps')::integer end,
          case when p_kind = 'supply' then public.deal_term_int(p_terms, 'volume_cents_per_hour') end,
          case when p_kind = 'supply' then public.deal_term_int(p_terms, 'fee_bps')::integer end,
          case when p_kind = 'supply' then public.deal_term_int(p_terms, 'prepay_bps')::integer end,
          case when p_kind = 'stake' then public.deal_term_int(p_terms, 'amount_cents') end,
          case when p_kind = 'stake' then public.deal_term_int(p_terms, 'share_bps')::integer end,
          public.deal_term_int(p_terms, 'hours')::integer, v_msg,
          -- loanDueCents and supplyPrepayCents: shown with the offer, fixed at acceptance
          case when p_kind = 'loan' then public.deal_term_int(p_terms, 'principal_cents')
                                         + public.apply_bps(public.deal_term_int(p_terms, 'principal_cents'),
                                                            public.deal_term_int(p_terms, 'interest_bps'))
               else 0 end,
          case when p_kind = 'supply' then public.deal_supply_prepay_cents(public.deal_term_int(p_terms, 'volume_cents_per_hour'),
                                                                           public.deal_term_int(p_terms, 'hours')::integer,
                                                                           public.deal_term_int(p_terms, 'fee_bps')::integer,
                                                                           public.deal_term_int(p_terms, 'prepay_bps')::integer)
               else 0 end,
          v_now, v_now + make_interval(secs => greatest(1, public.cfg_num(v_cfg, '{offerValidHours}', 48)) * 3600), p_request_id)
  returning * into d;
  v_id := d.id;

  if v_target is not null then
    v_nick := public.player_nickname(v_player);
    perform public.deal_notify(v_target, 'deal_offer', v_id,
      v_nick || case p_role
                  when 'lender' then ' bietet dir einen Kredit an'
                  when 'borrower' then ' bittet dich um einen Kredit'
                  when 'supplier' then ' bietet dir einen Liefervertrag an'
                  when 'buyer' then ' möchte Ware bei dir bestellen'
                  when 'investor' then ' möchte bei deiner Firma einsteigen'
                  else ' bietet dir eine Beteiligung an' end,
      public.deal_terms_text(d) || coalesce(' – „' || v_msg || '“', ''),
      'deal:' || v_id::text || ':offer');
  end if;
  return public.request_complete(v_player, p_request_id, public.deal_json(v_id, v_player));
end;
$$;
comment on function public.propose_deal(uuid, text, text, text, jsonb, text) is
  'RPC: proposes a loan, supply contract or stake (ADR-098) to a player (nickname or tag) or, with p_counterparty null, '
  'on the deal board. No money moves. Errors invalid_argument, name_profanity, locked, player_not_found, deal_self, '
  'deal_terms, deal_needs_company, deal_too_big (ADR-100), stake_share_full, deal_limit, rate_limited. -> DEAL';

-- respond_deal as in M4j plus the size limit of both companies (supply) or the company (stake) at the acceptance
create or replace function public.respond_deal(p_request_id uuid, p_deal_id uuid, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player   uuid;
  v_replay   jsonb;
  v_cfg      jsonb := public.deals_cfg();
  v_now      timestamptz := public.game_now();
  d          public.deals;
  v_role     text;
  v_level    integer;
  v_my_co    uuid;
  v_prop_co  uuid;
  v_lender   uuid;
  v_borrower uuid;
  v_sup_co   uuid;
  v_buy_co   uuid;
  v_investor uuid;
  v_company  uuid;
  v_cash     bigint;
  v_prepay   bigint;
  v_nick     text;
begin
  v_player := public.require_player();
  if p_request_id is null or p_deal_id is null or p_accept is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'respond_deal');
  if v_replay is not null then
    return v_replay;
  end if;
  d := public.deal_for_action(v_player, p_deal_id);
  if d.proposer_id = v_player then
    perform public.api_error('deal_self');
  end if;
  if d.status <> 'open' or d.expires_at <= v_now then
    perform public.api_error('deal_closed');
  end if;
  if d.counterparty_id is not null and d.counterparty_id <> v_player then
    perform public.api_error('deal_not_found');
  end if;
  v_nick := public.player_nickname(v_player);

  if not p_accept then
    -- open board offers just stay open
    if d.counterparty_id is null then
      perform public.api_error('invalid_argument');
    end if;
    update public.deals set status = 'declined', closed_at = v_now where id = d.id;
    perform public.deal_notify(d.proposer_id, 'deal_result', d.id,
      v_nick || ' hat ' || public.deal_kind_text(d.kind, 'your') || ' abgelehnt', public.deal_terms_text(d),
      'deal:' || d.id::text || ':declined');
    return public.request_complete(v_player, p_request_id, public.deal_json(d.id, v_player));
  end if;

  -- who may accept: level, a company where the own side needs one, room for one more running deal of the kind
  v_role := public.deal_other_role(d.proposer_role);
  select p.level into v_level from public.profiles p where p.id = v_player;
  if coalesce(v_level, 1) < public.cfg_num(v_cfg, '{minLevel}', 6) then
    perform public.api_error('locked');
  end if;
  if public.deal_role_needs_company(v_role) then
    v_my_co := public.player_active_company(v_player);
    if v_my_co is null then
      perform public.api_error('deal_needs_company');
    end if;
  end if;
  if public.deal_role_needs_company(d.proposer_role) then
    v_prop_co := public.player_active_company(d.proposer_id);
    if v_prop_co is null then
      perform public.api_error('deal_needs_company');
    end if;
  end if;
  if public.deal_count_running(v_player, d.kind) >= public.cfg_num(v_cfg, '{maxActivePerKind}', 5)
     or public.deal_count_running(d.proposer_id, d.kind) >= public.cfg_num(v_cfg, '{maxActivePerKind}', 5) then
    perform public.api_error('deal_limit');
  end if;

  if d.kind = 'loan' then
    v_lender := case when d.proposer_role = 'lender' then d.proposer_id else v_player end;
    v_borrower := case when d.proposer_role = 'borrower' then d.proposer_id else v_player end;
    if public.deal_terms_error('loan', public.deal_terms_json(d),
                               (select p.level from public.profiles p where p.id = v_lender)) is not null then
      perform public.api_error('deal_terms');
    end if;
    perform public.lock_player_accounts(v_borrower);
    v_cash := public.lock_player_accounts(v_lender);
    if v_cash < d.principal_cents then
      perform public.api_error('insufficient_funds');
    end if;
    perform public.ledger_transfer(public.ledger_player_account(v_lender, 'player_cash'),
                                   public.ledger_player_account(v_borrower, 'player_cash'), d.principal_cents, 'loan_disbursement',
                                   'Kredit von ' || public.player_nickname(v_lender), 'deal', d.id,
                                   'deal:' || d.id::text || ':principal', v_player);
    update public.deals
       set lender_id = v_lender, borrower_id = v_borrower,
           due_cents = d.principal_cents + public.apply_bps(d.principal_cents, d.interest_bps)
     where id = d.id;
  elsif d.kind = 'supply' then
    v_sup_co := case when d.proposer_role = 'supplier' then v_prop_co else v_my_co end;
    v_buy_co := case when d.proposer_role = 'buyer' then v_prop_co else v_my_co end;
    -- ADR-100: the most the contract can cost fits the limit of both companies (values of today)
    if public.deal_exceeds_size('supply', public.deal_terms_json(d), v_sup_co)
       or public.deal_exceeds_size('supply', public.deal_terms_json(d), v_buy_co) then
      perform public.api_error('deal_too_big');
    end if;
    v_prepay := public.deal_supply_prepay_cents(d.volume_cents_per_hour, d.hours, d.fee_bps, d.prepay_bps);
    -- the buyer's free cash (cash − open bills)
    select a.balance_cents - pc.unpaid_cents into v_cash
      from public.ledger_accounts a join public.player_companies pc on pc.company_id = a.owner_company_id
     where a.owner_company_id = v_buy_co and a.kind = 'company_cash' for update of a;
    if coalesce(v_cash, 0) < v_prepay then
      perform public.api_error('insufficient_funds');
    end if;
    if v_prepay > 0 then
      perform public.ledger_transfer(public.company_cash_account(v_buy_co), public.company_cash_account(v_sup_co), v_prepay,
                                     'transfer', 'Anzahlung Liefervertrag', 'deal', d.id, 'deal:' || d.id::text || ':prepay',
                                     v_player);
    end if;
    update public.deals
       set supplier_company_id = v_sup_co, buyer_company_id = v_buy_co, prepay_cents = v_prepay, prepay_left_cents = v_prepay,
           settled_until = public.deal_first_hour(v_now)
     where id = d.id;
  else
    v_investor := case when d.proposer_role = 'investor' then d.proposer_id else v_player end;
    v_company := case when d.proposer_role = 'company' then v_prop_co else v_my_co end;
    -- ADR-100: the amount fits the limit of the company (value of today)
    if public.deal_exceeds_size('stake', public.deal_terms_json(d), v_company) then
      perform public.api_error('deal_too_big');
    end if;
    if public.deal_stake_shares(v_company, false) + d.share_bps > public.cfg_num(v_cfg, '{stake,maxTotalShareBps}', 5000) then
      perform public.api_error('stake_share_full');
    end if;
    v_cash := public.lock_player_accounts(v_investor);
    if v_cash < d.amount_cents then
      perform public.api_error('insufficient_funds');
    end if;
    perform public.ledger_transfer(public.ledger_player_account(v_investor, 'player_cash'), public.company_cash_account(v_company),
                                   d.amount_cents, 'angel_investment', 'Beteiligung von ' || public.player_nickname(v_investor),
                                   'deal', d.id, 'deal:' || d.id::text || ':stake', v_player);
    update public.deals
       set investor_id = v_investor, company_id = v_company, settled_until = public.deal_first_hour(v_now)
     where id = d.id;
  end if;

  update public.deals
     set status = 'active', counterparty_id = v_player, accepted_at = v_now,
         ends_at = v_now + make_interval(secs => d.hours * 3600)
   where id = d.id;
  perform public.deal_notify(d.proposer_id, 'deal_result', d.id,
    v_nick || ' hat ' || public.deal_kind_text(d.kind, 'your') || ' angenommen', public.deal_terms_text(d),
    'deal:' || d.id::text || ':accepted');
  perform public.feed_post(v_player, 'deal_signed',
    jsonb_build_object('kind', d.kind, 'with', public.player_nickname(d.proposer_id)), 'deal_signed:' || d.id::text);
  return public.request_complete(v_player, p_request_id, public.deal_json(d.id, v_player));
end;
$$;
comment on function public.respond_deal(uuid, uuid, boolean) is
  'RPC: accepts or declines an offer (ADR-098). Targeted offers: only the target; board offers: any eligible player '
  '(decline: invalid_argument). Accepting moves the money (loan principal, supply prepayment, stake amount). Errors '
  'invalid_argument, deal_not_found, deal_self, deal_closed, locked, deal_needs_company, deal_limit, deal_terms, '
  'deal_too_big (ADR-100), stake_share_full, insufficient_funds. -> DEAL';

create or replace function public.get_deals()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_now    timestamptz := public.game_now();
begin
  return jsonb_build_object(
    'incoming', coalesce((select jsonb_agg(public.deal_json(x.id, v_player) order by x.created_at desc, x.id)
                            from public.deals x
                           where x.status = 'open' and x.counterparty_id = v_player and x.expires_at > v_now), '[]'::jsonb),
    'outgoing', coalesce((select jsonb_agg(public.deal_json(x.id, v_player) order by x.created_at desc, x.id)
                            from public.deals x
                           where x.status = 'open' and x.proposer_id = v_player and x.expires_at > v_now), '[]'::jsonb),
    'running', coalesce((select jsonb_agg(public.deal_json(x.id, v_player) order by x.ends_at, x.id)
                           from public.deals x
                          where x.status in ('active', 'overdue', 'defaulted') and v_player in (x.proposer_id, x.counterparty_id)),
                        '[]'::jsonb),
    'history', coalesce((select jsonb_agg(public.deal_json(h.id, v_player) order by h.at desc, h.id)
                           from (select x.id, coalesce(x.closed_at, x.expires_at) as at from public.deals x
                                  where x.status in ('completed', 'forgiven', 'broken', 'cancelled', 'declined', 'expired')
                                    and v_player in (x.proposer_id, x.counterparty_id)
                                  order by coalesce(x.closed_at, x.expires_at) desc, x.id limit 20) h), '[]'::jsonb),
    'trust', public.player_trust(v_player),
    -- ADR-100: the biggest company deal of the caller's company (null without one) and the biggest loan they may lend
    'limits', jsonb_build_object(
      'company_deal_max_cents', case when public.player_active_company(v_player) is not null
                                     then public.deal_size_limit_cents(public.player_active_company(v_player)) end,
      'loan_max_cents', greatest(1, coalesce((select p.level from public.profiles p where p.id = v_player), 1))::bigint
                        * public.cfg_num(public.deals_cfg(), '{loan,maxPrincipalCentsPerLevel}', 2000000)::bigint));
end;
$$;
comment on function public.get_deals() is
  'RPC: the caller''s deals (ADR-098): {incoming, outgoing, running, history (last 20), trust, limits: '
  '{company_deal_max_cents (null without company), loan_max_cents}} (ADR-100).';

-- ---------------------------------------------------------------------------
-- I. Presence at work (ADR-103, port of presencePayBps and firedForAbsence in src/lib/sim/skills.ts)
-- ---------------------------------------------------------------------------
-- careers.inactivity with the defaults of balance.ts
create or replace function public.presence_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select '{"steps": [{"afterHours": 24, "payBps": 7500}, {"afterHours": 48, "payBps": 5000}, {"afterHours": 72, "payBps": 2500}],
           "fireAfterHours": 120}'::jsonb
         || coalesce(case when jsonb_typeof(public.config_jsonb('careers', '{inactivity}')) = 'object'
                          then public.config_jsonb('careers', '{inactivity}') end, '{}'::jsonb);
$$;
comment on function public.presence_cfg() is 'Internal: game_config careers.inactivity (ADR-103) with the defaults of balance.ts.';

-- presencePayBps: the last step (in order) whose afterHours ≤ hours away gives the share of the wage; 10 000 before
-- the first step
create or replace function public.presence_pay_bps(p_hours double precision, p_cfg jsonb default null)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select round(public.cfg_num(x.s, '{payBps}', 10000))::integer
                     from jsonb_array_elements(case when jsonb_typeof(y.c -> 'steps') = 'array' then y.c -> 'steps'
                                                    else '[]'::jsonb end) with ordinality x(s, ord)
                    where public.cfg_num(x.s, '{afterHours}', 1e9) <= coalesce(p_hours, 0)
                    order by x.ord desc limit 1), 10000)
    from (select coalesce(p_cfg, public.presence_cfg()) as c) y;
$$;
comment on function public.presence_pay_bps(double precision, jsonb) is
  'Internal: presencePayBps (ADR-103), share of the wage in bps after p_hours away.';

-- profiles.last_active_at: the last time the player used the game (require_player, at most every 5 minutes)
alter table public.profiles add column if not exists last_active_at timestamptz;
update public.profiles set last_active_at = public.game_now() where last_active_at is null;
alter table public.profiles alter column last_active_at set default now();
alter table public.profiles alter column last_active_at set not null;
comment on column public.profiles.last_active_at is
  'Last use of the game (ADR-103): set by require_player at most every 5 minutes; decides the presence share of job pay.';

-- Absences long enough to lower the pay (≥ the first step), kept when the player comes back: hours of the absence that
-- are paid later (the hourly close of a player company runs behind) still get the share of their time.
create table if not exists public.player_absences (
  id         bigint generated always as identity primary key,
  player_id  uuid not null references public.profiles (id) on delete cascade,
  away_from  timestamptz not null,
  away_until timestamptz not null,
  created_at timestamptz not null default now(),
  constraint player_absences_window_check check (away_until > away_from)
);
alter table public.player_absences enable row level security;
create index if not exists player_absences_player_idx on public.player_absences (player_id, away_until desc);
comment on table public.player_absences is
  'Absences from the game of at least the first careers.inactivity step (ADR-103), written by presence_touch when the '
  'player comes back; kept 30 days. Internal (no client access).';
do $$
begin
  revoke all on public.player_absences from public, anon, authenticated;
  grant all on public.player_absences to service_role;
end;
$$;

alter type public.job_end_reason add value if not exists 'absent';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('job_absent', 'career', 'Kündigung wegen Abwesenheit', 'Du warst zu lange nicht da, dein Job ist beendet.',
        'notif_briefcase', true, true, false, 146),
       ('employee_absent', 'company', 'Mitarbeiter nicht erschienen',
        'Jemand aus deinem Team war zu lange nicht da und wurde gekündigt.', 'notif_briefcase', true, false, false, 227)
on conflict (key) do nothing;

-- Hours away at p_at: after the last activity from there, earlier from the start of a recorded absence, else 0. Times
-- after now count as now (nobody is absent in the future; only tests pay hours ahead).
create or replace function public.presence_away_hours(p_player uuid, p_at timestamptz)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0, extract(epoch from (x.t - coalesce(
           case when x.t >= p.last_active_at then p.last_active_at end,
           (select a.away_from from public.player_absences a
             where a.player_id = p.id and a.away_from <= x.t and a.away_until > x.t order by a.away_from desc limit 1),
           x.t))) / 3600.0)
    from public.profiles p cross join (select least(p_at, public.game_now()) as t) x
   where p.id = p_player;
$$;
comment on function public.presence_away_hours(uuid, timestamptz) is 'Internal: hours the player had been away at p_at (ADR-103).';

-- Average presence share (bps) of the p_minutes paid from p_from on, minute by minute; 10 000 without a long absence
create or replace function public.presence_pay_bps_between(p_player uuid, p_from timestamptz, p_minutes integer)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c       jsonb := public.presence_cfg();
  v_first double precision;
  v_last  timestamptz;
  v_to    timestamptz;
begin
  if coalesce(p_minutes, 0) <= 0 or p_from is null then
    return 10000;
  end if;
  select min(public.cfg_num(s, '{afterHours}', 0)) into v_first
    from jsonb_array_elements(case when jsonb_typeof(c -> 'steps') = 'array' then c -> 'steps' else '[]'::jsonb end) s;
  select p.last_active_at into v_last from public.profiles p where p.id = p_player;
  if v_first is null or v_last is null then
    return 10000;
  end if;
  v_to := p_from + make_interval(mins => p_minutes);
  -- the usual case: the minutes end before the first step after the last activity (minutes after now count as now), no
  -- recorded absence touches them
  if least(v_to, public.game_now()) <= v_last + make_interval(secs => v_first * 3600)
     and not exists (select 1 from public.player_absences a
                      where a.player_id = p_player and a.away_from < v_to and a.away_until > p_from) then
    return 10000;
  end if;
  return coalesce((
    select round(avg(public.presence_pay_bps(public.presence_away_hours(p_player, m.t), c)))::integer
      from generate_series(p_from, v_to - interval '1 minute', interval '1 minute') m(t)), 10000);
end;
$$;
comment on function public.presence_pay_bps_between(uuid, timestamptz, integer) is
  'Internal: average presence share in bps of the minutes [p_from, p_from + p_minutes) (ADR-103).';

-- PRESENCE of job_state: {last_active_at, pay_bps (share right now), fire_at}. For the player themself a stored time
-- older than 5 minutes reads as now: require_player has just recorded the call, a stable read does not see that write.
create or replace function public.presence_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'last_active_at', x.at,
    'pay_bps', public.presence_pay_bps(extract(epoch from (public.game_now() - x.at)) / 3600.0),
    'fire_at', x.at + make_interval(secs => public.cfg_num(public.presence_cfg(), '{fireAfterHours}', 120) * 3600))
    from (select case when p.id = (select auth.uid()) and p.last_active_at < public.game_now() - interval '5 minutes'
                      then public.game_now() else p.last_active_at end as at
            from public.profiles p where p.id = p_player) x;
$$;
comment on function public.presence_json(uuid) is
  'Internal: PRESENCE {last_active_at, pay_bps, fire_at} of a player (ADR-103).';

-- firedForAbsence: a player away for fireAfterHours (from last_active_at) loses the job. The hours up to that moment
-- are paid first (with their presence share), then the job ends with end_reason 'absent'; the player and the owners of
-- a player company are told. Cheap when nothing is due (no lock). Returns whether the job ended.
create or replace function public.job_absence_check(p_job uuid, p_now timestamptz default null)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- an hour closed ahead of time (tests) cannot end a job before its time
  v_now   timestamptz := least(coalesce(p_now, public.game_now()), public.game_now());
  v_hours double precision := public.cfg_num(public.presence_cfg(), '{fireAfterHours}', 120);
  j       public.player_jobs;
  v_last  timestamptz;
  v_fire  timestamptz;
  v_nick  text;
  v_co    text;
  v_ceo   uuid;
  v_fdr   uuid;
  v_owner uuid;
begin
  select pj.* into j from public.player_jobs pj where pj.id = p_job and pj.status = 'active';
  if j.id is null then
    return false;
  end if;
  select p.last_active_at, p.nickname into v_last, v_nick from public.profiles p where p.id = j.player_id;
  v_fire := v_last + make_interval(secs => v_hours * 3600);
  if v_last is null or v_now < v_fire then
    return false;
  end if;
  perform public.lock_player_accounts(j.player_id);
  select pj.* into j from public.player_jobs pj where pj.id = p_job and pj.status = 'active' for update;
  if j.id is null then
    return false;
  end if;
  if v_fire > j.last_paid_at then
    perform public.accrue_job_salary(j.id, v_fire);
  end if;
  update public.player_jobs
     set status = 'ended', ended_at = greatest(v_fire, started_at), end_reason = 'absent'
   where id = j.id;
  select c.name, c.ceo_id into v_co, v_ceo from public.companies c where c.id = j.company_id;
  select pc.founder_id into v_fdr from public.player_companies pc where pc.company_id = j.company_id;
  perform public.company_system_message(j.company_id, coalesce(v_nick, '?') || ' ist nicht mehr erschienen und wurde gekündigt.');
  perform public.social_notify(j.player_id, 'job_absent', 'Gekündigt',
    'Du warst ' || round(v_hours / 24)::integer || ' Tage nicht da. Dein Job bei ' || coalesce(v_co, 'deiner Firma')
    || ' ist beendet.', jsonb_build_object('player_job_id', j.id, 'company', v_co), '/job', 'job_absent:' || j.id::text);
  if v_fdr is not null then
    for v_owner in select distinct x from unnest(array[v_fdr, v_ceo]) x where x is not null and x <> j.player_id loop
      perform public.social_notify(v_owner, 'employee_absent', 'Kündigung wegen Abwesenheit',
        coalesce(v_nick, '?') || ' ist nicht mehr erschienen und wurde gekündigt.',
        jsonb_build_object('player_job_id', j.id, 'nickname', v_nick), '/company', 'employee_absent:' || j.id::text);
    end loop;
  end if;
  return true;
end;
$$;
comment on function public.job_absence_check(uuid, timestamptz) is
  'Internal: ends a job whose player was away for careers.inactivity.fireAfterHours (ADR-103), paid up to that moment; '
  'called by accrue_salaries (AI jobs), player_company_close_hour and presence_touch.';

-- A use of the game: with the old last_active_at, a player away for fireAfterHours loses the jobs first; an absence of
-- at least the first step is recorded; then last_active_at = now. Throttled to once in 5 minutes (row lock: once).
create or replace function public.presence_touch(p_player uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  c       jsonb := public.presence_cfg();
  v_now   timestamptz := public.game_now();
  v_old   timestamptz;
  v_first double precision;
  r       record;
begin
  select p.last_active_at into v_old from public.profiles p where p.id = p_player;
  if v_old is null or v_old > v_now - interval '5 minutes' then
    return;
  end if;
  -- locks in the order of the job accruals (the player's accounts, then the profile in grant_xp): no deadlock with them
  perform public.lock_player_accounts(p_player);
  select p.last_active_at into v_old from public.profiles p where p.id = p_player for update;
  if v_old > v_now - interval '5 minutes' then
    return;
  end if;
  if v_now >= v_old + make_interval(secs => public.cfg_num(c, '{fireAfterHours}', 120) * 3600) then
    for r in select j.id from public.player_jobs j where j.player_id = p_player and j.status = 'active' order by j.id loop
      perform public.job_absence_check(r.id, v_now);
    end loop;
  end if;
  select min(public.cfg_num(s, '{afterHours}', 0)) into v_first
    from jsonb_array_elements(case when jsonb_typeof(c -> 'steps') = 'array' then c -> 'steps' else '[]'::jsonb end) s;
  if v_first is not null and v_now >= v_old + make_interval(secs => v_first * 3600) then
    insert into public.player_absences (player_id, away_from, away_until) values (p_player, v_old, v_now);
    delete from public.player_absences a where a.player_id = p_player and a.away_until < v_now - interval '30 days';
  end if;
  update public.profiles set last_active_at = v_now where id = p_player;
end;
$$;
comment on function public.presence_touch(uuid) is 'Internal: records a use of the game (ADR-103), see require_player.';

-- require_player as in M1 plus the presence: every RPC of a player is a use of the game. A read-only transaction (a
-- GET request) cannot record it; the next write does. A failing record never blocks the call.
create or replace function public.require_player()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid  uuid := (select auth.uid());
  v_last timestamptz;
begin
  if v_uid is not null then
    select p.last_active_at into v_last from public.profiles p where p.id = v_uid;
  end if;
  if v_uid is null or not found then
    perform public.api_error('not_authenticated');
  end if;
  if v_last < public.game_now() - interval '5 minutes' then
    begin
      perform public.presence_touch(v_uid);
    exception
      when read_only_sql_transaction then
        null;
      when others then
        raise warning 'presence_touch(%): %', v_uid, sqlerrm;
    end;
  end if;
  return v_uid;
end;
$$;

-- careers.paidHoursPerDayCap falls back to 8 (ADR-103); overtime adds its hours on top
create or replace function public.player_paid_hours_cap(p_player uuid)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select public.config_double('careers', '{paidHoursPerDayCap}', 8)
       + public.player_upgrade_level(p_player, 'overtime') * public.cfg_num(public.upgrade_cfg('overtime'), '{perLevel}', 1);
$$;

-- accrue_salaries as in M3i: AI jobs whose player was away too long end first
create or replace function public.accrue_salaries(p_now timestamptz default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now   timestamptz := coalesce(p_now, public.game_now());
  r       record;
  v_whole integer;
  v_n     integer := 0;
begin
  for r in select j.id, j.player_id, j.last_paid_at
             from public.player_jobs j join public.companies c on c.id = j.company_id
            where j.status = 'active' and c.is_ai
            order by j.player_id loop
    -- presence (ADR-103): a player away for careers.inactivity.fireAfterHours loses the job, paid up to that moment
    continue when public.job_absence_check(r.id, v_now);
    v_whole := floor(extract(epoch from (v_now - r.last_paid_at)) / 3600)::integer;
    continue when v_whole < 1;
    perform public.lock_player_accounts(r.player_id);
    if public.accrue_job_salary(r.id, r.last_paid_at + make_interval(hours => v_whole)) > 0 then
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;
comment on function public.accrue_salaries(timestamptz) is
  'run_due_jobs: pays the whole hours of every AI job; a player away for careers.inactivity.fireAfterHours loses the job '
  'first (ADR-103).';

-- job_state as in M4i plus presence (ADR-103)
create or replace function public.job_state(p_player uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  j        public.player_jobs;
  v_match  integer;
  v_base   bigint;
  v_max    integer;
  v_ai     boolean;
  v_today  date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_cool   double precision := public.config_double('jobs', '{raiseRequest,cooldownDays}', 7);
  v_factor integer;
  v_bonus  bigint;
  v_next   timestamptz;
  v_open   boolean;
begin
  select * into j from public.player_jobs where player_id = p_player and status = 'active';
  if j.id is null then
    return jsonb_build_object('job', null);
  end if;
  select c.is_ai into v_ai from public.companies c where c.id = j.company_id;
  v_match := public.job_match_score(public.player_branch_scores(p_player), j.required);
  v_max := greatest(0, public.config_double('jobs', '{raiseRequest,maxRaiseBpsPerScore}', 300)::integer * (v_match - j.raise_base_score));
  if v_ai then
    v_base := coalesce((public.career_tier(j.tier::text) ->> 'salaryCentsPerHour')::bigint, j.salary_cents_per_hour);
    v_max := least(v_max, greatest(0, floor((public.ai_salary_ceiling(v_base, v_match)::numeric / j.salary_cents_per_hour - 1) * 10000)::integer));
  end if;
  -- player companies: pay factor of the quarter x share the company could pay at the last payout
  select pc.pay_factor_bps * j.pay_factor_bps / 10000,
         coalesce((select sum(sp.bonus_cents) from public.salary_payouts sp join public.game_quarters gq on gq.id = pc.last_closed_quarter_id
                    where sp.player_job_id = j.id and sp.bonus_cents > 0 and sp.period_end = gq.ends_at), 0)
    into v_factor, v_bonus
    from public.player_companies pc where pc.company_id = j.company_id and pc.status = 'active';
  v_factor := coalesce(v_factor, j.pay_factor_bps);
  -- automatic work (ADR-064): no new work tasks
  v_next := null;
  v_open := false;
  return jsonb_build_object('job', jsonb_build_object(
    'id', j.id,
    'company', public.company_json(j.company_id),
    'tier', j.tier,
    'title_key', j.title_key,
    'title', case when j.title_key is null then j.title end,
    'required', j.required,
    'salary_cents_per_hour', j.salary_cents_per_hour,
    'pay_factor_bps', v_factor,
    'effective_salary_cents_per_hour', j.salary_cents_per_hour * v_factor / 10000,
    'last_bonus_cents', coalesce(v_bonus, 0),
    'next_work_task_at', v_next,
    'work_task_open', v_open,
    'productivity_bps', public.job_productivity_bps(v_match),
    'started_at', j.started_at,
    'paid_hours_today', case when j.paid_day = v_today then round(j.paid_minutes_today / 60.0, 2) else 0 end,
    'paid_hours_cap', public.player_paid_hours_cap(p_player),
    'earned_total_cents', j.earned_total_cents,
    'raise_available_at', case when j.raise_requested_at is null
                                    or j.raise_requested_at + make_interval(secs => v_cool * 86400) <= now() then null
                               else j.raise_requested_at + make_interval(secs => v_cool * 86400) end,
    'raise_max_bps', v_max,
    'pending_raise', case when j.pending_raise_bps is not null
                          then jsonb_build_object('requested_bps', j.pending_raise_bps, 'created_at', j.pending_raise_at) end,
    'quit_cost_cents', 0,
    'quit_now_cost_cents', round(j.salary_cents_per_hour * public.config_double('jobs', '{quitNowCostHours}', 12))::bigint,
    'notice_ends_at', j.notice_ends_at,
    'signature', j.signature,
    'rank_hours', round(j.rank_minutes / 60.0, 1),
    'promotion', public.promotion_state(j.id),
    -- ADR-103: presence and what it does to the pay
    'presence', public.presence_json(p_player)));
end;
$$;

-- ---------------------------------------------------------------------------
-- J. Org chart of a player company
-- ---------------------------------------------------------------------------
-- {company: {id, name, tier}, founder: {nickname, tag, avatar_key, is_me}, members: [{nickname, tag, avatar_key, tier,
-- title, since, is_me}] (highest rank first), ai_workers, ai_worker_skills}; for the founder, the CEO and employees
create or replace function public.get_company_org(p_company_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  pc       public.player_companies;
  c        public.companies;
begin
  select * into pc from public.player_companies where company_id = p_company_id and status = 'active';
  if pc.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  select * into c from public.companies where id = p_company_id;
  if not (v_player = pc.founder_id or v_player is not distinct from c.ceo_id
          or exists (select 1 from public.player_jobs j
                      where j.company_id = p_company_id and j.player_id = v_player and j.status = 'active')) then
    perform public.api_error('forbidden');
  end if;
  return jsonb_build_object(
    'company', jsonb_build_object('id', c.id, 'name', c.name, 'tier', pc.tier),
    'founder', (select jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key,
                                          'is_me', p.id = v_player)
                  from public.profiles p where p.id = pc.founder_id),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'tier', j.tier,
                                          'title', coalesce(j.title, j.title_key), 'since', j.started_at,
                                          'is_me', j.player_id = v_player)
                       order by case j.tier::text when 'c_level' then 5 when 'team_lead' then 4 when 'senior' then 3
                                                  when 'junior' then 2 else 1 end desc, j.started_at, p.nickname)
        from public.player_jobs j join public.profiles p on p.id = j.player_id
       where j.company_id = p_company_id and j.status = 'active'), '[]'::jsonb),
    'ai_workers', pc.ai_workers,
    'ai_worker_skills', to_jsonb(coalesce(pc.ai_worker_skills, '{}'::text[])));
end;
$$;
comment on function public.get_company_org(uuid) is
  'RPC: org chart of a player company {company, founder, members (tier, title, since), ai_workers, ai_worker_skills} '
  'for the founder, the CEO and employees; errors company_not_found, forbidden.';

-- ---------------------------------------------------------------------------
-- K. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.api_error(text)', 'public.upgrade_cfg(text)', 'public.upgrade_stage_level(text, integer)',
    'public.player_upgrade_levels(uuid)', 'public.player_work_xp_bps(uuid)', 'public.player_art_discount_bps(uuid)',
    'public.player_fixed_cost_discount_bps(uuid)', 'public.player_property_discount_bps(uuid)',
    'public.accrue_job_salary(uuid, timestamptz)', 'public.player_artwork_create_cost_cents(uuid, integer)',
    'public.artwork_title_taken(text)', 'public.name_violation(text, text, uuid)',
    'public.player_company_close_hour(uuid, timestamptz)', 'public.deal_supply_max_cost_cents(bigint, integer, integer)',
    'public.deal_size_limit_cents(uuid)', 'public.deal_exceeds_size(text, jsonb, uuid)', 'public.presence_cfg()',
    'public.presence_pay_bps(double precision, jsonb)', 'public.presence_away_hours(uuid, timestamptz)',
    'public.presence_pay_bps_between(uuid, timestamptz, integer)', 'public.presence_json(uuid)',
    'public.job_absence_check(uuid, timestamptz)', 'public.presence_touch(uuid)', 'public.require_player()',
    'public.player_paid_hours_cap(uuid)', 'public.accrue_salaries(timestamptz)', 'public.job_state(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_upgrades()', 'public.buy_upgrade(uuid, text)', 'public.check_artwork_title(text)', 'public.get_art_studio()',
    'public.create_artwork(uuid, text, jsonb)', 'public.check_company_name(text)',
    'public.found_company(uuid, text, text, text, text, text, text, boolean)', 'public.buy_home(uuid, text)',
    'public.buy_furniture(uuid, text, integer)', 'public.buy_floor(uuid, text)', 'public.buy_car(uuid, text)',
    'public.save_layout(uuid, text, text, jsonb)', 'public.propose_deal(uuid, text, text, text, jsonb, text)',
    'public.respond_deal(uuid, uuid, boolean)', 'public.get_deals()', 'public.get_company_org(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated, service_role', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261201000150_m5a_crypto_enum.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M5a · 0150 · Enum values for cryptocurrencies (ADR-101)
-- =============================================================================
-- A new enum value cannot be used in the transaction that adds it (SQLSTATE 55P04). The values live in their own
-- migration file, so a migration run with one transaction per file (supabase db push, verify_local.sh) has committed
-- them before 20261201000200_m5a_crypto.sql starts. That migration and its update copy use them only inside PL/pgSQL
-- bodies, never at the top level, so update-to-latest.sql (one transaction for everything) works as well: the coins
-- are seeded by run_due_jobs() after the commit (crypto_bootstrap()).
--   security_kind  'crypto'          coins trade as securities (positions, quotes, candles, portfolio, net worth)
--   ledger_tx_kind 'crypto_buy'      player cash -> pool (plus the order fee to the treasury)
--                  'crypto_sell'     pool -> player cash (order fee and tax to the treasury)
--                  'crypto_flow'     financial market <-> pool (seed, AI flows, dead coins), hacks: pool -> treasury
--                  'crypto_fee'      own coin: founding and development actions, player -> treasury
--                  'crypto_launch'   own coin: the creator's liquidity, player -> pool
--                  'crypto_payout'   pool -> holders when a coin is closed or delisted (tax to the treasury)
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

alter type public.security_kind add value if not exists 'crypto';
alter type public.ledger_tx_kind add value if not exists 'crypto_buy';
alter type public.ledger_tx_kind add value if not exists 'crypto_sell';
alter type public.ledger_tx_kind add value if not exists 'crypto_flow';
alter type public.ledger_tx_kind add value if not exists 'crypto_fee';
alter type public.ledger_tx_kind add value if not exists 'crypto_launch';
alter type public.ledger_tx_kind add value if not exists 'crypto_payout';
-- ===== idempotent copy of migrations/20261201000200_m5a_crypto.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M5a · 0200 · Cryptocurrencies and own coins (ADR-101)
-- =============================================================================
-- Mirrors src/lib/sim/crypto.ts (poolPriceE4, poolAt, swapBuy, swapSell, buySlippageBps, flowForReturn/applyFlow,
-- sigmaTick, tickReturn, stableReturn, pickRegime, regimeHours, playerCoinDriftDay, playerCoinSigmaDay, decayStats,
-- applyStats, actionSuccessBps, launchPool, isRugPull, discontinuePayoutCents, eventChanceBps, rollCoinEvent,
-- rollMarketEvent, eventShock, isDead, nextMemeCoin). Config: game_config 'crypto' (src/config/crypto.ts); the SQL
-- falls back to the same scalar defaults. Units: pool cash in cents, coins in millionths (E6), prices in E4,
-- price_e4 = cash_cents · 10^8 / tokens_e6. The constant product k exceeds bigint, pool math uses numeric.
--
-- Coins are securities (kind 'crypto', added in 20261201000150): positions, security_quotes, candles, price_ticks,
-- the portfolio, the net worth, the rich list and get_candles work as for stocks. No orders: crypto_trade swaps
-- against the coin's liquidity pool at once (an order and a trade row are written for the history).
--
-- Money (closed money system, ADR-041): every pool is a system ledger account 'crypto_pool:<coin id>'.
--   * seed / replacement coins: financial market ('market') -> pool
--   * AI flows every tick: market <-> pool. The tick only adds the cash difference to crypto_coins.pending_flow_cents;
--     the ledger is booked by crypto_settle_flows() (hourly, one transaction) and before any booking that touches the
--     pool (trades, hacks, closing). Invariant: ledger balance of the pool + pending_flow_cents = pool_cash_cents.
--   * trades: player cash <-> pool; the pool fee stays in the pool; order fee and tax -> treasury
--   * own coins: founding and actions player -> treasury, launch liquidity player -> pool, closing pool -> holders
--   * hacks: poolLossShare of the pool -> treasury; dead AI coins: payouts to holders, the rest -> market
--
-- Tables (RLS on, read-only for authenticated, no client writes): crypto_state, crypto_coins, crypto_coin_actions,
-- crypto_team_sales, crypto_events, crypto_volume_hours.
-- Jobs: market_tick() runs crypto_tick_at() before the stock tick (coin rows are always locked before ledger
-- accounts); run_due_jobs() runs crypto_run_due() first (seeding, due actions, the hourly part).
-- RPCs: crypto_trade, get_crypto_market, get_coin, check_coin_name, create_coin, get_my_coin, start_coin_action,
-- launch_coin, burn_coin_tokens, discontinue_coin.
-- Error keys: coin_not_found NX096, coin_exists NX097, ticker_taken NX098, coin_not_tradable NX099,
-- coin_action_running NX100, coin_tech_too_low NX101, slippage_exceeded NX102, coin_not_launched NX103
-- (plus deal_too_big NX095 of M4k). Notification type: crypto_event. Feed kinds: coin_launched, rug_pull, coin_closed.
-- Trust reason: rugPull (trust.deltas.rugPull).
-- New enum values are only used inside PL/pgSQL bodies (see 20261201000150).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
create table if not exists public.crypto_state (
  id           boolean primary key default true check (id),
  regime       text not null default 'flat' check (regime in ('bull', 'flat', 'bear')),
  regime_until timestamptz,
  seeded_at    timestamptz,
  hour_done    timestamptz,
  updated_at   timestamptz not null default now()
);
alter table public.crypto_state enable row level security;
insert into public.crypto_state (id) values (true) on conflict (id) do nothing;
comment on table public.crypto_state is
  'One row: the crypto weather (regime bull/flat/bear until regime_until, ADR-101), when the 15 coins were seeded and '
  'the last hour the hourly crypto job ran for.';

create table if not exists public.crypto_coins (
  id                 uuid primary key default gen_random_uuid(),
  security_id        uuid not null unique references public.securities (id),
  ticker             text not null check (ticker ~ '^[A-Z]{2,8}$'),
  name               text not null check (char_length(name) between 1 and 40),
  category           text not null check (category in ('stable', 'major', 'alt', 'meme', 'player')),
  status             text not null default 'listed' check (status in ('draft', 'listed', 'dead', 'closed')),
  peg_e4             bigint check (peg_e4 > 0),
  algorithmic        boolean not null default false,
  color              text,
  logo               jsonb,
  creator_id         uuid references public.profiles (id) on delete set null,
  seed_ticker        text,
  pool_account_id    uuid references public.ledger_accounts (id),
  pool_cash_cents    bigint not null default 0 check (pool_cash_cents >= 0),
  pool_tokens_e6     bigint not null default 0 check (pool_tokens_e6 >= 0),
  pending_flow_cents bigint not null default 0,
  tech               double precision not null default 0 check (tech between 0 and 100),
  hype               double precision not null default 0 check (hype between 0 and 100),
  utility            double precision not null default 0 check (utility between 0 and 100),
  stats_at           timestamptz not null default now(),
  start_price_e4     bigint check (start_price_e4 > 0),
  start_pool_cents   bigint check (start_pool_cents > 0),
  team_share_bps     integer check (team_share_bps between 0 and 9999),
  team_at_launch_e6  bigint not null default 0 check (team_at_launch_e6 >= 0),
  team_tokens_e6     bigint not null default 0 check (team_tokens_e6 >= 0),
  burned_e6          bigint not null default 0 check (burned_e6 >= 0),
  last_burn_at       timestamptz,
  last_rug_at        timestamptz,
  launched_at        timestamptz,
  dead_since         timestamptz,
  closed_at          timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint crypto_coins_peg_check check (category <> 'stable' or peg_e4 is not null)
);
alter table public.crypto_coins enable row level security;
create unique index if not exists crypto_coins_creator_open_uq on public.crypto_coins (creator_id)
  where creator_id is not null and status in ('draft', 'listed');
create unique index if not exists crypto_coins_name_open_uq on public.crypto_coins (public.name_key(name))
  where status in ('draft', 'listed');
create unique index if not exists crypto_coins_seed_uq on public.crypto_coins (seed_ticker) where seed_ticker is not null;
create index if not exists crypto_coins_status_idx on public.crypto_coins (status, category);
create index if not exists crypto_coins_pool_account_idx on public.crypto_coins (pool_account_id);
comment on table public.crypto_coins is
  'Cryptocurrencies (ADR-101): the 15 AI coins of crypto.coins, their meme replacements and player coins (category '
  'player, creator_id). ticker = the ticker when the coin was created (the security''s ticker is freed on closing). '
  'Pool: pool_cash_cents / pool_tokens_e6 (x · y = k), ledger account pool_account_id; pending_flow_cents = AI flows '
  'not yet booked (ledger balance + pending = pool cash). Stats tech/hype/utility (0..100) for player coins.';

create table if not exists public.crypto_coin_actions (
  id          uuid primary key default gen_random_uuid(),
  coin_id     uuid not null references public.crypto_coins (id) on delete cascade,
  key         text not null check (key ~ '^[a-z_]+$'),
  cost_cents  bigint not null default 0 check (cost_cents >= 0),
  success_bps integer not null check (success_bps between 0 and 10000),
  started_at  timestamptz not null default now(),
  ends_at     timestamptz not null,
  resolved_at timestamptz,
  success     boolean,
  constraint crypto_coin_actions_time_check check (ends_at >= started_at)
);
alter table public.crypto_coin_actions enable row level security;
create unique index if not exists crypto_coin_actions_running_uq on public.crypto_coin_actions (coin_id) where resolved_at is null;
create index if not exists crypto_coin_actions_due_idx on public.crypto_coin_actions (ends_at) where resolved_at is null;
create index if not exists crypto_coin_actions_coin_idx on public.crypto_coin_actions (coin_id, started_at desc);
comment on table public.crypto_coin_actions is
  'Development actions of a player coin (crypto.create.actions): one at a time, resolved by run_due_jobs() at ends_at '
  '(success with success_bps).';

create table if not exists public.crypto_team_sales (
  id          bigint generated always as identity primary key,
  coin_id     uuid not null references public.crypto_coins (id) on delete cascade,
  quantity_e6 bigint not null check (quantity_e6 > 0),
  at          timestamptz not null default now()
);
alter table public.crypto_team_sales enable row level security;
create index if not exists crypto_team_sales_coin_idx on public.crypto_team_sales (coin_id, at desc);
comment on table public.crypto_team_sales is
  'Team tokens a creator sold (rug pull check: more than rugShareBps of the team tokens at launch within rugWindowHours).';

create table if not exists public.crypto_events (
  id        bigint generated always as identity primary key,
  coin_id   uuid references public.crypto_coins (id) on delete cascade,
  key       text not null check (key ~ '^[a-z_]+$'),
  shock_bps integer,
  payload   jsonb not null default '{}'::jsonb,
  at        timestamptz not null default now()
);
alter table public.crypto_events enable row level security;
create index if not exists crypto_events_at_idx on public.crypto_events (at desc, id desc);
create index if not exists crypto_events_coin_idx on public.crypto_events (coin_id, at desc) where coin_id is not null;
comment on table public.crypto_events is
  'Event log of the crypto market: random events (crypto.events keys), market events (coin_id null), own coin results '
  '(action, exposed, launch, burn, rug_pull, closed) and AI coin life (dead, delisted, listed). shock_bps = price change.';

create table if not exists public.crypto_volume_hours (
  coin_id      uuid not null references public.crypto_coins (id) on delete cascade,
  hour         timestamptz not null,
  volume_cents bigint not null default 0 check (volume_cents >= 0),
  primary key (coin_id, hour)
);
alter table public.crypto_volume_hours enable row level security;
comment on table public.crypto_volume_hours is 'Traded cash per coin and hour (AI flows and players), for the 24 h volume. Kept 48 h.';

do $$
declare
  t text;
begin
  foreach t in array array['crypto_state', 'crypto_coins', 'crypto_coin_actions', 'crypto_team_sales', 'crypto_events',
                           'crypto_volume_hours'] loop
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('drop policy if exists "authenticated read" on public.%I', t);
    execute format('create policy "authenticated read" on public.%I for select to authenticated using (true)', t);
  end loop;
  foreach t in array array['crypto_state', 'crypto_coins'] loop
    if not exists (select 1 from pg_trigger where tgname = 'set_updated_at' and tgrelid = ('public.' || t)::regclass) then
      execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);
    end if;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- B. Error keys (M4k: deal_too_big NX095; M5a: NX096..NX103)
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    when 'founding_locked'             then 'NX053'
    when 'not_in_company'              then 'NX054'
    when 'work_task_not_found'         then 'NX055'
    when 'work_task_expired'           then 'NX056'
    when 'work_task_done'              then 'NX057'
    when 'offer_closed'                then 'NX058'
    when 'offer_sold_out'              then 'NX059'
    when 'already_listed'              then 'NX060'
    when 'confirm_mismatch'            then 'NX061'
    when 'skill_already_covered'       then 'NX062'
    when 'training_locked'             then 'NX063'
    when 'logo_locked'                 then 'NX064'
    when 'logo_forbidden'              then 'NX065'
    when 'artworks_locked'             then 'NX066'
    when 'artwork_not_found'           then 'NX067'
    when 'auction_not_found'           then 'NX068'
    when 'auction_ended'               then 'NX069'
    when 'bid_too_low'                 then 'NX070'
    when 'own_artwork'                 then 'NX071'
    when 'already_on_auction'          then 'NX072'
    when 'auction_has_bids'            then 'NX073'
    when 'property_locked'             then 'NX074'
    when 'no_home'                     then 'NX075'
    when 'invalid_tier'                then 'NX076'
    when 'item_not_found'              then 'NX077'
    when 'layout_invalid'              then 'NX078'
    when 'floor_not_owned'             then 'NX079'
    when 'garage_full'                 then 'NX080'
    when 'event_closed'                then 'NX081'
    when 'event_needs_staff'           then 'NX082'
    when 'upgrade_maxed'               then 'NX083'
    when 'promotion_not_ready'         then 'NX084'
    when 'promotion_too_soon'          then 'NX085'
    when 'promotion_pending'           then 'NX086'
    when 'campaign_running'            then 'NX087'
    when 'deal_not_found'              then 'NX088'
    when 'deal_closed'                 then 'NX089'
    when 'deal_terms'                  then 'NX090'
    when 'deal_limit'                  then 'NX091'
    when 'deal_self'                   then 'NX092'
    when 'stake_share_full'            then 'NX093'
    when 'deal_needs_company'          then 'NX094'
    when 'deal_too_big'                then 'NX095'
    when 'coin_not_found'              then 'NX096'
    when 'coin_exists'                 then 'NX097'
    when 'ticker_taken'                then 'NX098'
    when 'coin_not_tradable'           then 'NX099'
    when 'coin_action_running'         then 'NX100'
    when 'coin_tech_too_low'           then 'NX101'
    when 'slippage_exceeded'           then 'NX102'
    when 'coin_not_launched'           then 'NX103'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;
comment on function public.api_error(text) is 'Raises the API error <key> with its NX SQLSTATE. The client shows a text per key (error.message).';

-- ---------------------------------------------------------------------------
-- C. Notification type
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('crypto_event', 'market', 'Krypto-Neuigkeiten',
        'Ereignisse, Rug Pulls und Einstellungen bei Kryptowährungen, die du hältst, und Ergebnisse deiner eigenen Währung.',
        'notif_chart', true, false, false, 120)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- D. Config helpers (game_config 'crypto', fallbacks as in src/config/crypto.ts)
-- ---------------------------------------------------------------------------
create or replace function public.crypto_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('crypto'), '{}'::jsonb);
$$;
comment on function public.crypto_cfg() is 'Internal: game_config crypto (ADR-101), {} when missing.';

-- A value of crypto.categories.<category> from a loaded config document
create or replace function public.crypto_cat_val(p_cfg jsonb, p_category text, p_field text)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select public.cfg_num(p_cfg, array['categories', p_category, p_field],
    case p_field
      when 'sigmaDay' then case p_category when 'stable' then 0.002 when 'major' then 0.06 when 'alt' then 0.14
                                           when 'meme' then 0.4 else 0.35 end
      when 'beta' then case p_category when 'stable' then 0 when 'major' then 1 when 'alt' then 1.3 when 'meme' then 1.6
                                       else 1.2 end
      when 'feeBps' then case p_category when 'stable' then 5 when 'major' then 10 when 'alt' then 30 else 100 end
      when 'pegPullPerHour' then case p_category when 'stable' then 0.5 else 0 end
      else 0
    end);
$$;

-- The array crypto.<path> (events, coins, memeNames, create.actions, create.startPriceOptionsE4), [] when missing
create or replace function public.crypto_cfg_array(p_cfg jsonb, p_path text[])
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select case when jsonb_typeof(p_cfg #> p_path) = 'array' then p_cfg #> p_path else '[]'::jsonb end;
$$;

create or replace function public.crypto_event_cfg(p_cfg jsonb, p_key text)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select e from jsonb_array_elements(public.crypto_cfg_array(p_cfg, '{events}')) e where e ->> 'key' = p_key limit 1;
$$;

create or replace function public.crypto_action_cfg(p_cfg jsonb, p_key text)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select a from jsonb_array_elements(public.crypto_cfg_array(p_cfg, '{create,actions}')) a where a ->> 'key' = p_key limit 1;
$$;

-- Pool fee after the hardware wallet: fee × (10 000 − level × perLevel) / 10 000, rounded half even, never below 0
create or replace function public.crypto_discounted_fee_bps(p_fee_bps double precision, p_level integer, p_per_level double precision)
returns integer
language sql
immutable
set search_path = ''
as $$
  select greatest(0, public.div_round_half_even(
           round(p_fee_bps::numeric) * greatest(0::numeric, 10000 - least(10000::numeric, greatest(0, coalesce(p_level, 0)) * round(p_per_level::numeric))),
           10000))::integer;
$$;

-- The pool fee a player pays for a category (upgrades.crypto_wallet, M4i/M4k player_upgrade_level)
create or replace function public.crypto_player_fee_bps(p_player uuid, p_category text)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select public.crypto_discounted_fee_bps(public.crypto_cat_val(public.crypto_cfg(), p_category, 'feeBps'),
           case when p_player is null then 0 else coalesce(public.player_upgrade_level(p_player, 'crypto_wallet'), 0) end,
           public.config_double('upgrades', '{crypto_wallet,perLevel}', 2500));
$$;

-- ---------------------------------------------------------------------------
-- E. Pure math (port of src/lib/sim/crypto.ts)
-- ---------------------------------------------------------------------------
-- poolPriceE4
create or replace function public.crypto_pool_price_e4(p_cash bigint, p_tokens bigint)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select case when coalesce(p_tokens, 0) <= 0 then 0::bigint
              else public.div_round_half_even(coalesce(p_cash, 0)::numeric * 100000000, p_tokens) end;
$$;

-- poolAt: the coins of a pool holding p_cash at p_price
create or replace function public.crypto_pool_tokens_at(p_cash bigint, p_price_e4 bigint)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select case when coalesce(p_price_e4, 0) > 0 then public.div_round_half_even(p_cash::numeric * 100000000, p_price_e4)
              else 0::bigint end;
$$;

-- swapBuy: the fee stays in the pool, k holds for the rest, the pool's coins are rounded up
create or replace function public.crypto_swap_buy(p_cash bigint, p_tokens bigint, p_cash_in bigint, p_fee_bps integer,
                                                  out tokens_out_e6 bigint, out fee_cents bigint,
                                                  out cash_after_cents bigint, out tokens_after_e6 bigint)
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_k    numeric := p_cash::numeric * p_tokens;
  v_cash bigint;
begin
  fee_cents := public.div_round_half_even(p_cash_in::numeric * p_fee_bps, 10000);
  v_cash := p_cash + (p_cash_in - fee_cents);
  if v_cash <= 0 then
    tokens_out_e6 := 0;
  else
    tokens_out_e6 := greatest(0::numeric, p_tokens - div(v_k + v_cash - 1, v_cash))::bigint;
  end if;
  cash_after_cents := v_cash + fee_cents;
  tokens_after_e6 := p_tokens - tokens_out_e6;
end;
$$;

-- swapSell: the fee is kept back from the payout
create or replace function public.crypto_swap_sell(p_cash bigint, p_tokens bigint, p_tokens_in bigint, p_fee_bps integer,
                                                   out cash_out_cents bigint, out fee_cents bigint,
                                                   out cash_after_cents bigint, out tokens_after_e6 bigint)
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_k     numeric := p_cash::numeric * p_tokens;
  v_tok   bigint := p_tokens + p_tokens_in;
  v_gross bigint;
begin
  if v_tok <= 0 then
    cash_out_cents := 0; fee_cents := 0; cash_after_cents := p_cash; tokens_after_e6 := p_tokens;
    return;
  end if;
  v_gross := greatest(0::numeric, p_cash - div(v_k + v_tok - 1, v_tok))::bigint;
  fee_cents := public.div_round_half_even(v_gross::numeric * p_fee_bps, 10000);
  cash_out_cents := v_gross - fee_cents;
  cash_after_cents := p_cash - v_gross + fee_cents;
  tokens_after_e6 := v_tok;
end;
$$;

-- Slippage of a fill in bps: how much worse than p_before the average price is (buy: higher, sell: lower)
create or replace function public.crypto_slippage_bps(p_before_e4 bigint, p_avg_e4 bigint, p_side text)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case when coalesce(p_before_e4, 0) <= 0 or coalesce(p_avg_e4, 0) <= 0 then 10000
              when p_side = 'buy' then public.div_round_half_even((p_avg_e4 - p_before_e4)::numeric * 10000, p_before_e4)::integer
              else public.div_round_half_even((p_before_e4 - p_avg_e4)::numeric * 10000, p_before_e4)::integer end;
$$;

-- flowForReturn + applyFlow: the market's trade that moves the price by the log return r (no fee). Buying: the cash
-- goes up by round(cash × (e^(r/2) − 1)); selling: the coins go up by round(tokens × (e^(−r/2) − 1)); k / the other side.
create or replace function public.crypto_apply_flow(p_cash bigint, p_tokens bigint, p_r double precision,
                                                    out cash_cents bigint, out tokens_e6 bigint)
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_k numeric := p_cash::numeric * p_tokens;
  v_f double precision := exp(coalesce(p_r, 0) / 2);
begin
  if coalesce(p_r, 0) >= 0 then
    cash_cents := p_cash + floor(p_cash::double precision * (v_f - 1) + 0.5)::bigint;
    tokens_e6 := case when cash_cents > 0 then div(v_k, cash_cents)::bigint else p_tokens end;
  else
    tokens_e6 := p_tokens + floor(p_tokens::double precision * (1 / v_f - 1) + 0.5)::bigint;
    cash_cents := case when tokens_e6 > 0 then div(v_k, tokens_e6)::bigint else p_cash end;
  end if;
end;
$$;

-- tickReturn: drift and shock of the market times beta, plus the coin's own shock
create or replace function public.crypto_tick_return(p_sigma_day double precision, p_beta double precision,
                                                     p_extra_drift_day double precision, p_regime_drift_day double precision,
                                                     p_z_market double precision, p_z_own double precision,
                                                     p_tick_seconds double precision)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select (b.beta * p_regime_drift_day + coalesce(p_extra_drift_day, 0)) * (p_tick_seconds / 86400.0)
         + p_sigma_day * sqrt(p_tick_seconds / 86400.0)
           * (b.common * p_z_market + sqrt(greatest(0, 1 - b.common * b.common)) * p_z_own)
    from (select greatest(0, p_beta) as beta, least(1, greatest(0, p_beta)) as common) b;
$$;

-- stableReturn: pulled back to the peg, a little noise
create or replace function public.crypto_stable_return(p_price_e4 double precision, p_peg_e4 double precision,
                                                       p_pull_per_hour double precision, p_sigma_day double precision,
                                                       p_z double precision, p_tick_seconds double precision)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select case when coalesce(p_price_e4, 0) <= 0 or coalesce(p_peg_e4, 0) <= 0 then 0::double precision
              else -ln(p_price_e4 / p_peg_e4) * (1 - power(1 - least(1, greatest(0, p_pull_per_hour)), p_tick_seconds / 3600.0))
                   + p_sigma_day * sqrt(p_tick_seconds / 86400.0) * p_z end;
$$;

-- pickRegime: bull / flat / bear by weight
create or replace function public.crypto_pick_regime(p_cfg jsonb, p_u double precision)
returns text
language sql
immutable
set search_path = ''
as $$
  select case when x.v < w.bull then 'bull' when x.v < w.bull + w.flat then 'flat' else 'bear' end
    from (select public.cfg_num(p_cfg, '{regimes,bull,weight}', 0.3) as bull,
                 public.cfg_num(p_cfg, '{regimes,flat,weight}', 0.45) as flat,
                 public.cfg_num(p_cfg, '{regimes,bear,weight}', 0.25) as bear) w
   cross join lateral (select least(0.999999, greatest(0, coalesce(p_u, 0))) * (w.bull + w.flat + w.bear) as v) x;
$$;

-- regimeHours: min + (max − min) × u, rounded like Math.round
create or replace function public.crypto_regime_hours(p_cfg jsonb, p_u double precision)
returns integer
language sql
immutable
set search_path = ''
as $$
  select floor(public.cfg_num(p_cfg, '{regimeHoursMin}', 24)
               + (public.cfg_num(p_cfg, '{regimeHoursMax}', 72) - public.cfg_num(p_cfg, '{regimeHoursMin}', 24))
                 * least(1, greatest(0, coalesce(p_u, 0))) + 0.5)::integer;
$$;

create or replace function public.crypto_regime_drift(p_cfg jsonb, p_regime text)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select public.cfg_num(p_cfg, array['regimes', p_regime, 'driftDay'],
                        case p_regime when 'bull' then 0.03 when 'bear' then -0.03 else 0 end);
$$;

-- playerCoinDriftDay: hype and utility push, a base selling pressure pulls
create or replace function public.crypto_player_drift_day(p_cfg jsonb, p_hype double precision, p_utility double precision)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select public.cfg_num(p_cfg, '{create,driftPerHype}', 0.2) * (coalesce(p_hype, 0) / 100)
       + public.cfg_num(p_cfg, '{create,driftPerUtility}', 0.08) * (coalesce(p_utility, 0) / 100)
       + public.cfg_num(p_cfg, '{create,driftBase}', -0.06);
$$;

-- playerCoinSigmaDay: good technology calms the coin
create or replace function public.crypto_player_sigma_day(p_cfg jsonb, p_tech double precision)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select public.cfg_num(p_cfg, '{create,sigmaDay}', 0.35)
         * (1 - public.cfg_num(p_cfg, '{create,sigmaTechDamping}', 0.5) * (least(100, greatest(0, coalesce(p_tech, 0))) / 100));
$$;

-- eventChanceBps: chance per hour; own coins move it with their stats (p_tech null = no stats)
create or replace function public.crypto_event_chance_bps(p_event jsonb, p_category text, p_tech double precision,
                                                          p_hype double precision, p_utility double precision)
returns integer
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_base double precision := public.cfg_num(p_event, '{chanceBps}', 0);
  t      double precision := coalesce(p_tech, 0) / 100;
  h      double precision := coalesce(p_hype, 0) / 100;
  u      double precision := coalesce(p_utility, 0) / 100;
  f      double precision;
begin
  if p_event is null or jsonb_typeof(p_event -> 'scope') is distinct from 'array' or not ((p_event -> 'scope') ? p_category) then
    return 0;
  end if;
  if p_category <> 'player' or p_tech is null then
    return floor(v_base + 0.5)::integer;
  end if;
  f := case p_event ->> 'key'
    when 'hack' then power(1 - t, 2) * 1.5
    when 'bug' then 1.2 - t
    when 'influencer' then 0.5 + h
    when 'exchange_listing' then 0.4 + (t + u) / 2
    when 'delisting_rumor' then 1.3 - (t + u) / 2
    when 'whale_buy' then 0.5 + h
    when 'whale_dump' then 1
    when 'partnership' then 0.4 + u
    when 'fud' then 1.2 - h / 2
    else 1
  end;
  return floor(v_base * f + 0.5)::integer;
end;
$$;

-- rollCoinEvent: u0 decides whether, u1 which event (weighted by chance); null = nothing happens
create or replace function public.crypto_roll_coin_event(p_cfg jsonb, p_u0 double precision, p_u1 double precision,
                                                         p_category text, p_tech double precision, p_hype double precision,
                                                         p_utility double precision)
returns jsonb
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_total double precision := 0;
  v_x     double precision;
  v_last  jsonb;
  r       record;
begin
  for r in select e.x as ev, public.crypto_event_chance_bps(e.x, p_category, p_tech, p_hype, p_utility) as w
             from jsonb_array_elements(public.crypto_cfg_array(p_cfg, '{events}')) with ordinality e(x, ord)
            where not coalesce((e.x -> 'scope') ? 'market', false)
            order by e.ord loop
    if r.w > 0 then
      v_total := v_total + r.w;
    end if;
  end loop;
  if v_total <= 0 or coalesce(p_u0, 1) * 10000 >= v_total then
    return null;
  end if;
  v_x := coalesce(p_u1, 0) * v_total;
  for r in select e.x as ev, public.crypto_event_chance_bps(e.x, p_category, p_tech, p_hype, p_utility) as w
             from jsonb_array_elements(public.crypto_cfg_array(p_cfg, '{events}')) with ordinality e(x, ord)
            where not coalesce((e.x -> 'scope') ? 'market', false)
            order by e.ord loop
    continue when r.w <= 0;
    if v_x < r.w then
      return r.ev;
    end if;
    v_x := v_x - r.w;
    v_last := r.ev;
  end loop;
  return v_last;
end;
$$;

-- rollMarketEvent: one market-wide event per hour (meme_wave, regulation) or null
create or replace function public.crypto_roll_market_event(p_cfg jsonb, p_u0 double precision, p_u1 double precision)
returns jsonb
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_total double precision := 0;
  v_x     double precision;
  v_last  jsonb;
  r       record;
begin
  select coalesce(sum(public.cfg_num(e, '{chanceBps}', 0)), 0) into v_total
    from jsonb_array_elements(public.crypto_cfg_array(p_cfg, '{events}')) e
   where coalesce((e -> 'scope') ? 'market', false);
  if coalesce(p_u0, 1) * 10000 >= v_total then
    return null;
  end if;
  v_x := coalesce(p_u1, 0) * v_total;
  for r in select e.x as ev, public.cfg_num(e.x, '{chanceBps}', 0) as w
             from jsonb_array_elements(public.crypto_cfg_array(p_cfg, '{events}')) with ordinality e(x, ord)
            where coalesce((e.x -> 'scope') ? 'market', false)
            order by e.ord loop
    if v_x < r.w then
      return r.ev;
    end if;
    v_x := v_x - r.w;
    v_last := r.ev;
  end loop;
  return v_last;
end;
$$;

-- eventShock: a log return inside the range; algorithmic stablecoins lose their peg twice as hard
create or replace function public.crypto_event_shock(p_event jsonb, p_u double precision, p_algorithmic boolean default false)
returns double precision
language sql
immutable
set search_path = ''
as $$
  select (public.cfg_num(p_event, '{shockMin}', 0)
          + (public.cfg_num(p_event, '{shockMax}', 0) - public.cfg_num(p_event, '{shockMin}', 0))
            * least(1, greatest(0, coalesce(p_u, 0))))
         * case when p_event ->> 'key' = 'depeg' and coalesce(p_algorithmic, false) then 2 else 1 end;
$$;

-- actionSuccessBps: base plus IT skill points (always 100 % without a base)
create or replace function public.crypto_action_success_bps(p_cfg jsonb, p_action jsonb, p_it_score double precision)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case when p_action is null then 0
              when jsonb_typeof(p_action -> 'baseBps') is distinct from 'number' then 10000
              else least(10000, round(public.cfg_num(p_action, '{baseBps}', 0)
                                      + greatest(0, floor(coalesce(p_it_score, 0)))
                                        * public.cfg_num(p_cfg, '{create,itBpsPerScore}', 300)))::integer end;
$$;

-- launchPool: the team keeps its share on top of the pool's coins (team / (pool + team) = share)
create or replace function public.crypto_launch_team_e6(p_pool_tokens bigint, p_share_bps integer)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select public.div_round_half_even(p_pool_tokens::numeric * s.v, 10000 - s.v)
    from (select least(9999, greatest(0, coalesce(p_share_bps, 0)))::numeric as v) s;
$$;

-- isRugPull: more than rugShareBps of the team tokens at launch sold within the window
create or replace function public.crypto_is_rug_pull(p_cfg jsonb, p_sold_e6 bigint, p_team_at_launch_e6 bigint)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(p_team_at_launch_e6, 0) > 0
     and coalesce(p_sold_e6, 0)::numeric * 10000
         > p_team_at_launch_e6::numeric * round(public.cfg_num(p_cfg, '{create,rugShareBps}', 2000))::numeric;
$$;

-- discontinuePayoutCents: the pool's cash by coins
create or replace function public.crypto_discontinue_payout_cents(p_pool_cash bigint, p_holder_e6 bigint, p_circulating_e6 bigint)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select case when coalesce(p_circulating_e6, 0) <= 0 then 0::bigint
              else div(p_pool_cash::numeric * p_holder_e6, p_circulating_e6)::bigint end;
$$;

-- nextMemeCoin: the first unused name of crypto.memeNames, the ticker from its consonants (unused among securities)
create or replace function public.crypto_next_meme_coin(out name text, out ticker text)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_name    text;
  v_letters text;
  v_cons    text;
  v_t       text;
begin
  name := null;
  ticker := null;
  for v_name in select x #>> '{}' from jsonb_array_elements(public.crypto_cfg_array(public.crypto_cfg(), '{memeNames}'))
                       with ordinality a(x, ord) order by a.ord loop
    continue when exists (select 1 from public.crypto_coins c where c.name = v_name);
    v_letters := regexp_replace(upper(v_name), '[^A-Z]', '', 'g');
    v_cons := regexp_replace(v_letters, '[AEIOU]', '', 'g');
    foreach v_t in array array[left(v_cons, 3), left(v_letters, 3), left(v_letters, 4), left(v_cons, 4)] loop
      if char_length(v_t) >= 3 and not exists (select 1 from public.securities s where s.ticker = v_t) then
        name := v_name;
        ticker := v_t;
        return;
      end if;
    end loop;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Coin helpers: pool account, quote and candles, settlement, texts
-- ---------------------------------------------------------------------------
-- The pool's ledger account (system account 'crypto_pool:<coin id>', never negative)
create or replace function public.crypto_pool_account(p_coin uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id     uuid;
  v_ticker text;
begin
  select c.pool_account_id, c.ticker into v_id, v_ticker from public.crypto_coins c where c.id = p_coin;
  if v_id is not null then
    return v_id;
  end if;
  insert into public.ledger_accounts (kind, system_key, label, allow_negative)
  values ('system', 'crypto_pool:' || p_coin::text, 'Crypto pool ' || coalesce(v_ticker, '?') || ' (ADR-101)', false)
  on conflict do nothing;
  v_id := public.ledger_system_account('crypto_pool:' || p_coin::text);
  update public.crypto_coins set pool_account_id = v_id where id = p_coin;
  return v_id;
end;
$$;

-- Coins in circulation: held by players (open positions)
create or replace function public.crypto_held_e6(p_security uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(p.quantity_e6), 0)::bigint from public.positions p
   where p.security_id = p_security and p.status = 'open' and p.quantity_e6 > 0;
$$;

-- Quote, candles and hourly volume after the pool of a coin changed outside the tick (trades, events, launch).
-- bid/ask = price ∓ the category fee; market cap = (pool + held coins) × price.
create or replace function public.crypto_mark(p_coin uuid, p_now timestamptz, p_volume_e6 bigint default 0,
                                              p_volume_cents bigint default 0)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  c       public.crypto_coins;
  v_epoch constant timestamptz := '2000-01-01 00:00:00+00';
  v_price bigint;
  v_half  bigint;
  v_mcap  bigint;
  v_seq   bigint;
  v_vol   bigint := greatest(0, coalesce(p_volume_e6, 0));
  v_cents bigint := greatest(0, coalesce(p_volume_cents, 0));
begin
  select * into c from public.crypto_coins where id = p_coin;
  if c.id is null or c.pool_tokens_e6 <= 0 then
    return null;
  end if;
  v_price := greatest(1, public.crypto_pool_price_e4(c.pool_cash_cents, c.pool_tokens_e6));
  v_half := greatest(1, public.div_round_half_even(v_price::numeric * public.crypto_cat_val(public.crypto_cfg(), c.category, 'feeBps')::numeric, 10000));
  v_mcap := public.value_cents(c.pool_tokens_e6 + public.crypto_held_e6(c.security_id), v_price);
  select r.tick_seq into v_seq from public.sim_runtime r where r.id;

  insert into public.security_quotes as q (security_id, last_price_e4, bid_e4, ask_e4, prev_close_e4, day_open_e4, day_high_e4,
                                           day_low_e4, day_volume_e6, day_turnover_cents, change_bps, market_cap_cents,
                                           tick_seq, updated_at)
  values (c.security_id, v_price, greatest(1, v_price - v_half), v_price + v_half, v_price, v_price, v_price, v_price,
          v_vol, v_cents, 0, v_mcap, coalesce(v_seq, 0), p_now)
  on conflict (security_id) do update
     set last_price_e4 = excluded.last_price_e4,
         bid_e4 = excluded.bid_e4,
         ask_e4 = excluded.ask_e4,
         day_high_e4 = greatest(coalesce(q.day_high_e4, excluded.last_price_e4), excluded.last_price_e4),
         day_low_e4 = least(coalesce(q.day_low_e4, excluded.last_price_e4), excluded.last_price_e4),
         day_volume_e6 = q.day_volume_e6 + excluded.day_volume_e6,
         day_turnover_cents = q.day_turnover_cents + excluded.day_turnover_cents,
         change_bps = greatest(-1000000, least(1000000, round((excluded.last_price_e4 - coalesce(q.prev_close_e4, excluded.last_price_e4))
                                                               * 10000.0 / greatest(1, coalesce(q.prev_close_e4, excluded.last_price_e4)))))::integer,
         market_cap_cents = excluded.market_cap_cents,
         updated_at = excluded.updated_at;

  insert into public.candles as k (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select c.security_id, iv.i, iv.b, v_price, v_price, v_price, v_price, v_vol, 1
    from (values
      ('1m'::public.candle_interval, date_bin('1 minute', p_now, v_epoch)),
      ('5m'::public.candle_interval, date_bin('5 minutes', p_now, v_epoch)),
      ('1h'::public.candle_interval, date_bin('1 hour', p_now, v_epoch)),
      ('1q'::public.candle_interval, public.quarter_bucket_start(p_now)),
      ('1y'::public.candle_interval, public.game_year_bucket_start(p_now))) as iv(i, b)
  on conflict (security_id, interval, bucket_start) do update
     set high_e4 = greatest(k.high_e4, excluded.high_e4),
         low_e4 = least(k.low_e4, excluded.low_e4),
         close_e4 = excluded.close_e4,
         volume_e6 = k.volume_e6 + excluded.volume_e6,
         tick_count = k.tick_count + 1;

  if v_cents > 0 then
    insert into public.crypto_volume_hours as h (coin_id, hour, volume_cents)
    values (c.id, date_bin('1 hour', p_now, v_epoch), v_cents)
    on conflict (coin_id, hour) do update set volume_cents = h.volume_cents + excluded.volume_cents;
  end if;
  return v_price;
end;
$$;

-- Books the AI flows of one coin that the ticks collected (market <-> pool). The caller holds the coin row lock.
create or replace function public.crypto_pool_settle(p_coin uuid)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  c public.crypto_coins;
begin
  select * into c from public.crypto_coins where id = p_coin;
  if c.id is null or c.pending_flow_cents = 0 or c.pool_account_id is null then
    return 0;
  end if;
  perform public.ledger_post('crypto_flow', jsonb_build_array(
      jsonb_build_object('account_id', public.ledger_system_account('market'), 'amount_cents', -c.pending_flow_cents),
      jsonb_build_object('account_id', c.pool_account_id, 'amount_cents', c.pending_flow_cents)),
    'Krypto-Markt: Handel mit ' || c.ticker, 'crypto_coin', c.id, null, null,
    jsonb_build_object('flow_cents', c.pending_flow_cents));
  update public.crypto_coins set pending_flow_cents = 0 where id = p_coin;
  return c.pending_flow_cents;
end;
$$;

-- Books the AI flows of all coins in one transaction (hourly). Coins are locked by the caller.
create or replace function public.crypto_settle_flows()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entries jsonb;
  v_sum     bigint;
  v_n       integer;
begin
  select coalesce(jsonb_agg(jsonb_build_object('account_id', c.pool_account_id, 'amount_cents', c.pending_flow_cents)
                            order by c.pool_account_id), '[]'::jsonb),
         coalesce(sum(c.pending_flow_cents), 0)::bigint, count(*)::integer
    into v_entries, v_sum, v_n
    from public.crypto_coins c
   where c.pending_flow_cents <> 0 and c.pool_account_id is not null;
  if v_n = 0 then
    return jsonb_build_object('coins', 0, 'net_cents', 0);
  end if;
  if v_sum <> 0 then
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', public.ledger_system_account('market'), 'amount_cents', -v_sum));
  end if;
  perform public.ledger_post('crypto_flow', v_entries, 'Krypto-Markt: Handel der KI-Händler', 'crypto', null, null, null,
                             jsonb_build_object('coins', v_n, 'net_cents', v_sum));
  update public.crypto_coins set pending_flow_cents = 0 where pending_flow_cents <> 0 and pool_account_id is not null;
  return jsonb_build_object('coins', v_n, 'net_cents', v_sum);
end;
$$;

-- Frees the ticker of a closed coin's security: TICKER1, TICKER2, ... (digits never occur in coin tickers)
create or replace function public.crypto_tombstone_ticker(p_security uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ticker text;
  v_new    text;
  i        integer := 1;
begin
  select s.ticker into v_ticker from public.securities s where s.id = p_security;
  if v_ticker is null or v_ticker ~ '[0-9]' then
    return v_ticker;
  end if;
  loop
    v_new := left(v_ticker, 8 - char_length(i::text)) || i::text;
    exit when not exists (select 1 from public.securities s where s.ticker = v_new);
    i := i + 1;
  end loop;
  update public.securities set ticker = v_new where id = p_security;
  return v_new;
end;
$$;

-- German name of an action (notifications)
create or replace function public.crypto_action_label(p_key text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_key
    when 'smart_contract' then 'Smart Contract'
    when 'audit' then 'Security-Audit'
    when 'community' then 'Community-Aufbau'
    when 'influencer' then 'Influencer-Kampagne'
    when 'partnership' then 'Partnerschaft'
    when 'staking' then 'Staking'
    when 'bugfix' then 'Bugfix'
    when 'marketing_burn' then 'Token-Verbrennung'
    else coalesce(p_key, 'Aktion')
  end;
$$;

-- German title and body of a crypto event about a coin (notification type crypto_event)
create or replace function public.crypto_event_text(p_key text, p_name text)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select case p_key
    when 'hack' then jsonb_build_object('title', 'Hack bei ' || n, 'body', 'Angreifer haben Geld aus dem Pool gestohlen. Der Kurs bricht ein.')
    when 'bug' then jsonb_build_object('title', 'Bug bei ' || n, 'body', 'Ein Fehler im Smart Contract verunsichert die Halter.')
    when 'influencer' then jsonb_build_object('title', 'Influencer feiert ' || n, 'body', 'Ein bekannter Influencer schwärmt von der Währung. Der Kurs springt.')
    when 'exchange_listing' then jsonb_build_object('title', n || ' an einer Börse gelistet', 'body', 'Eine große Krypto-Börse nimmt die Währung auf.')
    when 'delisting_rumor' then jsonb_build_object('title', 'Delisting-Gerücht um ' || n, 'body', 'Es heißt, eine Börse wolle die Währung streichen.')
    when 'whale_buy' then jsonb_build_object('title', 'Wal kauft ' || n, 'body', 'Ein Großanleger kauft in großem Stil.')
    when 'whale_dump' then jsonb_build_object('title', 'Wal verkauft ' || n, 'body', 'Ein Großanleger wirft seine Coins auf den Markt.')
    when 'partnership' then jsonb_build_object('title', 'Partnerschaft für ' || n, 'body', 'Ein Unternehmen will die Währung nutzen.')
    when 'fud' then jsonb_build_object('title', 'Angstmache um ' || n, 'body', 'Gerüchte und Panik drücken den Kurs.')
    when 'network_upgrade' then jsonb_build_object('title', 'Netzwerk-Upgrade bei ' || n, 'body', 'Das Netzwerk wird schneller und günstiger.')
    when 'depeg' then jsonb_build_object('title', n || ' verliert die Bindung', 'body', 'Der Stablecoin ist nicht mehr 1 € wert.')
    when 'meme_wave' then jsonb_build_object('title', 'Meme-Welle', 'body', 'Shitcoins sind plötzlich überall gefragt.')
    when 'regulation' then jsonb_build_object('title', 'Regulierung trifft ' || n, 'body', 'Neue Regeln für Kryptowährungen drücken den ganzen Markt.')
    when 'rug_pull' then jsonb_build_object('title', 'Rug Pull bei ' || n, 'body', 'Die Macher haben in großem Stil Coins verkauft. Der Kurs stürzt ab.')
    when 'exposed' then jsonb_build_object('title', 'Werbedeal von ' || n || ' aufgeflogen', 'body', 'Die bezahlte Influencer-Werbung ist aufgeflogen: Der Hype ist weg, der Kurs fällt.')
    when 'dead' then jsonb_build_object('title', n || ' ist tot', 'body', 'Der Kurs ist fast null. In einem Tag wird die Währung gestrichen.')
    when 'delisted' then jsonb_build_object('title', n || ' gestrichen', 'body', 'Die Währung ist vom Markt verschwunden.')
    when 'closed' then jsonb_build_object('title', n || ' eingestellt', 'body', 'Der Pool wurde nach Coins an alle Halter ausgezahlt.')
    else jsonb_build_object('title', 'Neuigkeit zu ' || n, 'body', 'Bei der Währung hat sich etwas getan.')
  end
  from (select coalesce(p_name, 'einer Kryptowährung') as n) x;
$$;

-- In-app notification to every holder of a coin (open position) and, if wanted, its creator
create or replace function public.crypto_notify(p_coin uuid, p_title text, p_body text, p_payload jsonb, p_dedupe text,
                                                p_creator boolean default true, p_holders boolean default true,
                                                p_except uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  c   public.crypto_coins;
  s   public.securities;
  r   record;
  v_n integer := 0;
begin
  select * into c from public.crypto_coins where id = p_coin;
  select * into s from public.securities where id = c.security_id;
  for r in select x.player_id from (
             select p.player_id from public.positions p
              where p_holders and p.security_id = c.security_id and p.status = 'open' and p.quantity_e6 > 0
             union
             select c.creator_id where p_creator and c.creator_id is not null) x
            where x.player_id is distinct from p_except
            order by x.player_id loop
    perform public.social_notify(r.player_id, 'crypto_event', p_title, p_body,
                                 jsonb_build_object('ticker', s.ticker, 'name', c.name) || coalesce(p_payload, '{}'::jsonb),
                                 '/crypto/' || s.ticker, p_dedupe);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;

-- One crypto event row
create or replace function public.crypto_log(p_coin uuid, p_key text, p_shock_bps integer, p_payload jsonb, p_at timestamptz)
returns bigint
language sql
security definer
set search_path = ''
as $$
  insert into public.crypto_events (coin_id, key, shock_bps, payload, at)
  values (p_coin, p_key, p_shock_bps, coalesce(p_payload, '{}'::jsonb), coalesce(p_at, now()))
  returning id;
$$;

-- Capital gains tax of a realised result, exactly as execute_fill: losses fill the loss pot, gains are offset against
-- it first, then taxed with trading.capitalGainsTaxBps; the game year's tax row is updated. Returns the tax.
create or replace function public.crypto_realise(p_player uuid, p_pnl bigint)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_pot    bigint;
  v_offset bigint;
  v_tax    bigint := 0;
  v_year   integer;
begin
  select pp.tax_loss_pot_cents into v_pot from public.player_private pp where pp.player_id = p_player for update;
  v_pot := coalesce(v_pot, 0);
  if p_pnl <= 0 then
    v_pot := v_pot - p_pnl;
  else
    v_offset := least(p_pnl, v_pot);
    v_tax := public.apply_bps(p_pnl - v_offset, public.config_double('trading', '{capitalGainsTaxBps}', 2500)::numeric);
    v_pot := v_pot - v_offset;
  end if;
  update public.player_private set tax_loss_pot_cents = v_pot where player_id = p_player;
  v_year := coalesce((select q.game_year from public.current_game_quarter() q), 0);
  insert into public.player_tax_years as t (player_id, game_year, realized_gains_cents, realized_losses_cents, tax_paid_cents)
  values (p_player, v_year, greatest(p_pnl, 0), greatest(-p_pnl, 0), v_tax)
  on conflict (player_id, game_year) do update
    set realized_gains_cents  = t.realized_gains_cents + excluded.realized_gains_cents,
        realized_losses_cents = t.realized_losses_cents + excluded.realized_losses_cents,
        tax_paid_cents        = t.tax_paid_cents + excluded.tax_paid_cents,
        updated_at            = now();
  return v_tax;
end;
$$;

-- Closes a whole position of a coin with a payout from the pool (coin closed, dead coin delisted): realised result and
-- tax like a sale, a system order and a trade for the history (counterparty issuer). The coin row is locked and its
-- pending flows are settled by the caller.
create or replace function public.crypto_close_position(p_position uuid, p_payout_cents bigint, p_key text, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pos      public.positions;
  c        public.crypto_coins;
  v_payout bigint := greatest(0, coalesce(p_payout_cents, 0));
  v_pnl    bigint;
  v_tax    bigint;
  v_net    bigint;
  v_tx     uuid;
  v_order  uuid := gen_random_uuid();
  v_trade  uuid := gen_random_uuid();
  v_price  bigint;
  v_seq    bigint;
begin
  select * into pos from public.positions where id = p_position for update;
  if pos.id is null or pos.status <> 'open' or pos.quantity_e6 <= 0 then
    return null;
  end if;
  select * into c from public.crypto_coins where security_id = pos.security_id;
  perform public.lock_player_accounts(pos.player_id);
  v_pnl := v_payout - pos.cost_basis_cents;
  v_tax := least(public.crypto_realise(pos.player_id, v_pnl), v_payout);
  v_net := v_payout - v_tax;
  if v_payout > 0 then
    v_tx := public.ledger_post('crypto_payout',
      (select jsonb_agg(jsonb_build_object('account_id', x.a, 'amount_cents', x.v))
         from (values (c.pool_account_id, -v_payout),
                      (public.ledger_player_account(pos.player_id, 'player_cash'), v_net),
                      (public.ledger_system_account('treasury'), v_tax)) as x(a, v)
        where x.v <> 0),
      'Auszahlung ' || c.ticker, 'crypto_coin', c.id, p_key || ':' || pos.id::text, pos.player_id,
      jsonb_build_object('quantity_e6', pos.quantity_e6, 'payout_cents', v_payout, 'tax_cents', v_tax));
  else
    v_tx := null;
  end if;
  v_price := greatest(1, public.div_round_half_even(v_payout::numeric * 100000000, pos.quantity_e6));
  select r.tick_seq into v_seq from public.sim_runtime r where r.id;
  insert into public.orders (id, player_id, security_id, request_id, source, side, type, quantity_e6, filled_quantity_e6,
                             status, avg_fill_price_e4, fee_cents, filled_at)
  values (v_order, pos.player_id, pos.security_id, gen_random_uuid(), 'system', 'sell', 'market', pos.quantity_e6,
          pos.quantity_e6, 'filled', v_price, 0, p_now);
  insert into public.trades (id, order_id, player_id, security_id, position_id, side, quantity_e6, price_e4, gross_cents,
                             fee_cents, tax_cents, realized_pnl_cents, counterparty, ledger_transaction_id, tick_seq, executed_at)
  values (v_trade, v_order, pos.player_id, pos.security_id, pos.id, 'sell', pos.quantity_e6, v_price, v_payout, 0, v_tax,
          v_pnl, 'issuer', v_tx, v_seq, p_now);
  update public.positions
     set quantity_e6 = 0, reserved_quantity_e6 = 0, cost_basis_cents = 0, status = 'closed', closed_at = p_now,
         realized_pnl_cents = realized_pnl_cents + v_pnl
   where id = pos.id;
  if v_net > 0 then
    perform public.loan_withhold(pos.player_id, v_net, p_key || ':' || pos.id::text);
  end if;
  return jsonb_build_object('player_id', pos.player_id, 'quantity_e6', pos.quantity_e6, 'payout_cents', v_payout,
                            'tax_cents', v_tax, 'realized_pnl_cents', v_pnl);
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Listing coins and seeding the market
-- ---------------------------------------------------------------------------
-- A light price history for a new AI coin: a bounded random walk that ends at the current price (1 minute steps for
-- the last hour, 5 minute steps for three days before), as candles 1m, 5m, 1h, 1q and 1y.
create or replace function public.crypto_seed_history(p_coin uuid, p_now timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  c        public.crypto_coins;
  v_cfg    jsonb := public.crypto_cfg();
  v_epoch  constant timestamptz := '2000-01-01 00:00:00+00';
  v_m1_end timestamptz := date_bin('1 minute', p_now, '2000-01-01 00:00:00+00'::timestamptz);
  v_fine   timestamptz := date_bin('5 minutes', p_now - interval '1 hour', '2000-01-01 00:00:00+00'::timestamptz);
  v_sigma  double precision;
  v_band   double precision;
  v_price  double precision;
  v_vol    double precision;
  v_n      integer;
begin
  select * into c from public.crypto_coins where id = p_coin;
  if c.id is null or c.pool_tokens_e6 <= 0
     or exists (select 1 from public.candles k
                 where k.security_id = c.security_id and k.interval = '5m' and k.bucket_start < p_now - interval '1 hour'
                 limit 1) then
    return 0;
  end if;
  -- only the candles of the listing itself exist: the history replaces them
  delete from public.candles k where k.security_id = c.security_id;
  v_sigma := greatest(1e-6, public.crypto_cat_val(v_cfg, c.category, 'sigmaDay'));
  v_band := v_sigma * sqrt(3.0) * 1.5;
  v_price := public.crypto_pool_price_e4(c.pool_cash_cents, c.pool_tokens_e6);
  v_vol := c.pool_tokens_e6 * 0.0005;

  if to_regclass('pg_temp.nexa_crypto_bf') is not null then
    drop table pg_temp.nexa_crypto_bf;
  end if;
  create temporary table nexa_crypto_bf (
    k integer, iv text, bucket_start timestamptz, minutes integer, sigma double precision,
    close_e4 bigint, open_e4 bigint, high_e4 bigint, low_e4 bigint, volume bigint
  ) on commit drop;
  insert into pg_temp.nexa_crypto_bf (k, iv, bucket_start, minutes, sigma)
  select (row_number() over (order by s.b desc) - 1)::integer, s.iv, s.b, s.m, v_sigma * sqrt(s.m / 1440.0)
    from (select 'm'::text as iv, g as b, 1 as m from generate_series(v_m1_end, v_fine, interval '-1 minute') g
          union all
          select '5', g, 5 from generate_series(v_fine - interval '5 minutes', v_fine - interval '3 days', interval '-5 minutes') g) s;

  update pg_temp.nexa_crypto_bf t
     set close_e4 = x.c
    from (select y.k, greatest(1, round(v_price * exp(v_band * tanh(y.s_cum / v_band))))::bigint as c
            from (select b.k, sum(case when b.k = 0 then 0 else b.sigma * public.gauss_random() end) over (order by b.k) as s_cum
                    from pg_temp.nexa_crypto_bf b) y) x
   where t.k = x.k;
  update pg_temp.nexa_crypto_bf t
     set open_e4 = x.o,
         high_e4 = ceil(greatest(x.o, t.close_e4) * exp(abs(public.gauss_random()) * t.sigma * 0.5))::bigint,
         low_e4  = greatest(1, floor(least(x.o, t.close_e4) * exp(-abs(public.gauss_random()) * t.sigma * 0.5)))::bigint,
         volume  = round(v_vol * t.minutes * (0.5 + random()))::bigint
    from (select b.k, coalesce(lead(b.close_e4) over (order by b.k), b.close_e4) as o from pg_temp.nexa_crypto_bf b) x
   where t.k = x.k;

  insert into public.candles (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select c.security_id, '1m', b.bucket_start, b.open_e4, b.high_e4, b.low_e4, b.close_e4, b.volume, 12
    from pg_temp.nexa_crypto_bf b where b.iv = 'm'
  on conflict do nothing;
  insert into public.candles (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select c.security_id, g.target_iv::public.candle_interval, g.bucket,
         (array_agg(g.open_e4 order by g.bucket_start))[1], max(g.high_e4), min(g.low_e4),
         (array_agg(g.close_e4 order by g.bucket_start desc))[1], sum(g.volume), sum(g.minutes * 12)
    from (select b.*, '5m' as target_iv, date_bin('5 minutes', b.bucket_start, v_epoch) as bucket from pg_temp.nexa_crypto_bf b
          union all
          select b.*, '1h', date_bin('1 hour', b.bucket_start, v_epoch) from pg_temp.nexa_crypto_bf b
          union all
          select b.*, '1q', public.quarter_bucket_start(b.bucket_start) from pg_temp.nexa_crypto_bf b
          union all
          select b.*, '1y', public.game_year_bucket_start(b.bucket_start) from pg_temp.nexa_crypto_bf b) g
   group by g.target_iv, g.bucket
  on conflict do nothing;
  get diagnostics v_n = row_count;

  -- the day's statistics since the last bell, like market_bootstrap does for stocks
  update public.security_quotes q
     set prev_close_e4 = coalesce((select k.close_e4 from public.candles k
                                    where k.security_id = q.security_id and k.interval = '5m'
                                      and k.bucket_start < public.trading_day_start(p_now)
                                    order by k.bucket_start desc limit 1), q.last_price_e4),
         day_high_e4 = greatest(q.last_price_e4, coalesce((select max(k.high_e4) from public.candles k
                                    where k.security_id = q.security_id and k.interval = '5m'
                                      and k.bucket_start >= public.trading_day_start(p_now)), q.last_price_e4)),
         day_low_e4 = least(q.last_price_e4, coalesce((select min(k.low_e4) from public.candles k
                                    where k.security_id = q.security_id and k.interval = '5m'
                                      and k.bucket_start >= public.trading_day_start(p_now)), q.last_price_e4))
   where q.security_id = c.security_id;
  update public.security_quotes q
     set change_bps = round((q.last_price_e4 - q.prev_close_e4) * 10000.0 / greatest(1, q.prev_close_e4))::integer
   where q.security_id = c.security_id and q.prev_close_e4 is not null;
  drop table pg_temp.nexa_crypto_bf;
  return v_n;
end;
$$;

-- Lists an AI coin: security, coin, pool funded from the financial market at p_price, quote. Null if the ticker is
-- taken or the market cannot pay.
create or replace function public.crypto_list_ai_coin(p_ticker text, p_name text, p_category text, p_price_e4 bigint,
                                                      p_pool_cents bigint, p_algorithmic boolean, p_color text,
                                                      p_seed_ticker text, p_now timestamptz)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sec    uuid;
  v_coin   uuid;
  v_acc    uuid;
  v_market bigint;
  v_tokens bigint;
begin
  if p_ticker is null or p_ticker !~ '^[A-Z]{2,8}$' or p_price_e4 is null or p_price_e4 <= 0 or p_pool_cents is null
     or p_pool_cents <= 0 or p_category not in ('stable', 'major', 'alt', 'meme')
     or exists (select 1 from public.securities s where s.ticker = p_ticker) then
    return null;
  end if;
  select a.balance_cents into v_market from public.ledger_accounts a where a.system_key = 'market';
  if coalesce(v_market, 0) - coalesce((select sum(greatest(c.pending_flow_cents, 0)) from public.crypto_coins c), 0) < p_pool_cents then
    return null;
  end if;
  v_tokens := public.crypto_pool_tokens_at(p_pool_cents, p_price_e4);
  if v_tokens <= 0 then
    return null;
  end if;
  insert into public.securities (kind, ticker, name, status, tick_size_e4, is_tradable, is_shortable, max_leverage, listed_at)
  values ('crypto', p_ticker, p_name, 'listed', 1, true, false, 1, p_now)
  returning id into v_sec;
  insert into public.crypto_coins (security_id, ticker, name, category, status, peg_e4, algorithmic, color, seed_ticker,
                                   start_price_e4, start_pool_cents, launched_at, stats_at)
  values (v_sec, p_ticker, p_name, p_category, 'listed', case when p_category = 'stable' then p_price_e4 end,
          coalesce(p_algorithmic, false), p_color, p_seed_ticker, p_price_e4, p_pool_cents, p_now, p_now)
  returning id into v_coin;
  v_acc := public.crypto_pool_account(v_coin);
  perform public.ledger_transfer(public.ledger_system_account('market'), v_acc, p_pool_cents, 'crypto_flow',
                                 'Krypto-Pool ' || p_ticker || ': Startkapital vom Finanzmarkt', 'crypto_coin', v_coin,
                                 'crypto:fund:' || v_coin::text);
  update public.crypto_coins set pool_cash_cents = p_pool_cents, pool_tokens_e6 = v_tokens where id = v_coin;
  perform public.crypto_mark(v_coin, p_now, 0, 0);
  return v_coin;
end;
$$;

-- Seeds the coins of crypto.coins once (after the money genesis). Run by run_due_jobs() (crypto_run_due). Inside the
-- transaction that added the enum value 'crypto' (update-to-latest.sql) it skips and the next run seeds.
create or replace function public.crypto_bootstrap()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  st      public.crypto_state;
  v_cfg   jsonb := public.crypto_cfg();
  v_now   timestamptz := public.game_now();
  v_coin  uuid;
  v_n     integer := 0;
  v_skip  jsonb := '[]'::jsonb;
  v_t     text;
  r       record;
begin
  select * into st from public.crypto_state where id for update;
  if st.seeded_at is not null then
    return jsonb_build_object('skipped', 'seeded');
  end if;
  if not public.money_genesis_done() then
    return jsonb_build_object('skipped', 'no_genesis');
  end if;
  if jsonb_array_length(public.crypto_cfg_array(v_cfg, '{coins}')) = 0 then
    return jsonb_build_object('skipped', 'no_config');
  end if;
  begin
    for r in select x, ord from jsonb_array_elements(public.crypto_cfg_array(v_cfg, '{coins}')) with ordinality a(x, ord)
              order by a.ord loop
      v_t := upper(coalesce(r.x ->> 'ticker', ''));
      continue when exists (select 1 from public.crypto_coins c where c.seed_ticker = v_t);
      v_coin := public.crypto_list_ai_coin(v_t, r.x ->> 'name', r.x ->> 'category',
                                           public.cfg_num(r.x, '{priceE4}', 0)::bigint, public.cfg_num(r.x, '{poolCents}', 0)::bigint,
                                           coalesce((r.x ->> 'algorithmic')::boolean, false), r.x ->> 'color', v_t, v_now);
      if v_coin is null then
        v_skip := v_skip || to_jsonb(v_t);
      else
        perform public.crypto_seed_history(v_coin, v_now);
        v_n := v_n + 1;
      end if;
    end loop;
    update public.crypto_state
       set seeded_at = now(),
           regime = public.crypto_pick_regime(v_cfg, random()),
           regime_until = v_now + make_interval(hours => public.crypto_regime_hours(v_cfg, random()))
     where id;
  exception when sqlstate '55P04' then
    -- unsafe use of the new enum value 'crypto': it was added in this very transaction
    return jsonb_build_object('skipped', 'enum_not_committed');
  end;
  return jsonb_build_object('seeded', v_n, 'skipped_tickers', v_skip);
end;
$$;
comment on function public.crypto_bootstrap() is
  'Seeds the AI coins of crypto.coins once (ADR-101): securities (kind crypto), pools funded by the financial market, quotes and a light price history.';

-- ---------------------------------------------------------------------------
-- H. Tick: the AI traders trade against every pool (from market_tick(), every crypto.tickSeconds)
-- ---------------------------------------------------------------------------
create or replace function public.crypto_tick_at(p_now timestamptz, p_seq bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cfg     jsonb := public.crypto_cfg();
  v_tick    double precision := greatest(1, public.cfg_num(v_cfg, '{tickSeconds}', 5));
  v_epoch   constant timestamptz := '2000-01-01 00:00:00+00';
  st        public.crypto_state;
  v_regime  text;
  v_drift   double precision;
  v_zm      double precision := public.gauss_random();
  v_bell    timestamptz := public.trading_day_start(p_now);
  v_qstart  timestamptz := public.quarter_bucket_start(p_now);
  v_ystart  timestamptz := public.game_year_bucket_start(p_now);
  v_new_day boolean;
  v_free    bigint;
  r         record;
  v_r       double precision;
  v_cash    bigint;
  v_tok     bigint;
  v_delta   bigint;
  v_price   bigint;
  v_half    bigint;
  a_coin uuid[] := '{}';   a_sec uuid[] := '{}';
  a_cash bigint[] := '{}'; a_tok bigint[] := '{}';  a_flow bigint[] := '{}';
  a_p bigint[] := '{}';    a_b bigint[] := '{}';    a_a bigint[] := '{}';
  a_v bigint[] := '{}';    a_vc bigint[] := '{}';   a_mc bigint[] := '{}';
begin
  select * into st from public.crypto_state where id for update;
  if st.id is null or st.seeded_at is null then
    return jsonb_build_object('skipped', 'not_seeded');
  end if;
  -- crypto weather: a new regime when the old one ran out
  if st.regime_until is null or st.regime_until <= p_now then
    v_regime := public.crypto_pick_regime(v_cfg, random());
    update public.crypto_state
       set regime = v_regime, regime_until = p_now + make_interval(hours => public.crypto_regime_hours(v_cfg, random()))
     where id;
  else
    v_regime := st.regime;
  end if;
  v_drift := public.crypto_regime_drift(v_cfg, v_regime);
  v_new_day := coalesce((select (rt.state ->> 'day_start')::timestamptz from public.sim_runtime rt where rt.id),
                        '-infinity'::timestamptz) < v_bell;
  -- the financial market pays for buying flows: its balance minus what the ticks already owe the pools
  select a.balance_cents into v_free from public.ledger_accounts a where a.system_key = 'market';
  v_free := coalesce(v_free, 0) - coalesce((select sum(greatest(c.pending_flow_cents, 0)) from public.crypto_coins c), 0);

  perform 1 from public.crypto_coins c where c.status = 'listed' order by c.id for update;
  for r in select c.id, c.security_id, c.category, c.peg_e4, c.pool_cash_cents, c.pool_tokens_e6, c.tech, c.hype, c.utility,
                  public.crypto_held_e6(c.security_id) as held
             from public.crypto_coins c
             join public.security_quotes q on q.security_id = c.security_id
            where c.status = 'listed' and c.pool_cash_cents > 0 and c.pool_tokens_e6 > 0
            order by c.id loop
    if r.category = 'stable' then
      v_r := public.crypto_stable_return(public.crypto_pool_price_e4(r.pool_cash_cents, r.pool_tokens_e6)::double precision,
                                         coalesce(r.peg_e4, public.crypto_pool_price_e4(r.pool_cash_cents, r.pool_tokens_e6))::double precision,
                                         public.crypto_cat_val(v_cfg, 'stable', 'pegPullPerHour'),
                                         public.crypto_cat_val(v_cfg, 'stable', 'sigmaDay'), public.gauss_random(), v_tick);
    elsif r.category = 'player' then
      v_r := public.crypto_tick_return(public.crypto_player_sigma_day(v_cfg, r.tech), public.crypto_cat_val(v_cfg, 'player', 'beta'),
                                       public.crypto_player_drift_day(v_cfg, r.hype, r.utility), v_drift, v_zm,
                                       public.gauss_random(), v_tick);
    else
      v_r := public.crypto_tick_return(public.crypto_cat_val(v_cfg, r.category, 'sigmaDay'),
                                       public.crypto_cat_val(v_cfg, r.category, 'beta'), 0, v_drift, v_zm,
                                       public.gauss_random(), v_tick);
    end if;
    select f.cash_cents, f.tokens_e6 into v_cash, v_tok from public.crypto_apply_flow(r.pool_cash_cents, r.pool_tokens_e6, v_r) f;
    v_delta := v_cash - r.pool_cash_cents;
    if v_cash <= 0 or v_tok <= 0 or (v_delta > 0 and v_delta > v_free) then
      -- nothing moves (the financial market cannot pay, or the pool would empty)
      v_cash := r.pool_cash_cents;
      v_tok := r.pool_tokens_e6;
      v_delta := 0;
    end if;
    v_free := v_free - v_delta;
    v_price := greatest(1, public.crypto_pool_price_e4(v_cash, v_tok));
    v_half := greatest(1, public.div_round_half_even(v_price::numeric * public.crypto_cat_val(v_cfg, r.category, 'feeBps')::numeric, 10000));
    a_coin := a_coin || r.id;            a_sec := a_sec || r.security_id;
    a_cash := a_cash || v_cash;          a_tok := a_tok || v_tok;          a_flow := a_flow || v_delta;
    a_p := a_p || v_price;               a_b := a_b || greatest(1, v_price - v_half);
    a_a := a_a || (v_price + v_half);    a_v := a_v || abs(v_tok - r.pool_tokens_e6);
    a_vc := a_vc || abs(v_delta);        a_mc := a_mc || public.value_cents(v_tok + r.held, v_price);
  end loop;

  update public.crypto_coins c
     set pool_cash_cents = u.cash, pool_tokens_e6 = u.tok, pending_flow_cents = c.pending_flow_cents + u.flow
    from unnest(a_coin, a_cash, a_tok, a_flow) as u(id, cash, tok, flow)
   where c.id = u.id;

  update public.security_quotes q
     set last_price_e4 = u.p,
         bid_e4 = u.b,
         ask_e4 = u.a,
         prev_close_e4 = case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end,
         day_open_e4 = case when v_new_day then u.p else coalesce(q.day_open_e4, u.p) end,
         day_high_e4 = case when v_new_day then u.p else greatest(coalesce(q.day_high_e4, u.p), u.p) end,
         day_low_e4 = case when v_new_day then u.p else least(coalesce(q.day_low_e4, u.p), u.p) end,
         day_volume_e6 = case when v_new_day then u.v else q.day_volume_e6 + u.v end,
         day_turnover_cents = case when v_new_day then u.vc else q.day_turnover_cents + u.vc end,
         change_bps = greatest(-1000000, least(1000000, round(
                        (u.p - case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end) * 10000.0
                        / greatest(1, case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end))))::integer,
         market_cap_cents = u.mc,
         tick_seq = p_seq,
         updated_at = p_now
    from unnest(a_sec, a_p, a_b, a_a, a_v, a_vc, a_mc) as u(id, p, b, a, v, vc, mc)
   where q.security_id = u.id;

  insert into public.price_ticks (security_id, ts, tick_seq, price_e4, volume_e6)
  select u.id, p_now, p_seq, u.p, u.v from unnest(a_sec, a_p, a_v) as u(id, p, v)
  on conflict do nothing;

  insert into public.candles as k (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume_e6, tick_count)
  select u.id, iv.i, iv.b, u.p, u.p, u.p, u.p, u.v, 1
    from unnest(a_sec, a_p, a_v) as u(id, p, v)
   cross join (values
     ('1m'::public.candle_interval, date_bin('1 minute', p_now, v_epoch)),
     ('5m'::public.candle_interval, date_bin('5 minutes', p_now, v_epoch)),
     ('1h'::public.candle_interval, date_bin('1 hour', p_now, v_epoch)),
     ('1q'::public.candle_interval, v_qstart),
     ('1y'::public.candle_interval, v_ystart)) as iv(i, b)
  on conflict (security_id, interval, bucket_start) do update
     set high_e4 = greatest(k.high_e4, excluded.high_e4),
         low_e4 = least(k.low_e4, excluded.low_e4),
         close_e4 = excluded.close_e4,
         volume_e6 = k.volume_e6 + excluded.volume_e6,
         tick_count = k.tick_count + 1;

  insert into public.crypto_volume_hours as h (coin_id, hour, volume_cents)
  select u.id, date_bin('1 hour', p_now, v_epoch), u.vc from unnest(a_coin, a_vc) as u(id, vc) where u.vc > 0
  on conflict (coin_id, hour) do update set volume_cents = h.volume_cents + excluded.volume_cents;

  return jsonb_build_object('coins', coalesce(array_length(a_coin, 1), 0), 'regime', v_regime);
end;
$$;
comment on function public.crypto_tick_at(timestamptz, bigint) is
  'Internal: one crypto tick (ADR-101): tickReturn/stableReturn per listed coin as the market''s flow against the pool (applyFlow); the cash difference goes to pending_flow_cents.';

-- ---------------------------------------------------------------------------
-- I. Events, actions, rug pulls, closing coins and the minute/hourly job
-- ---------------------------------------------------------------------------
-- Applies an event to a listed coin: hack = poolLossShare of the pool's cash to the treasury first, then the rest of the
-- shock as the market's flow (applyFlow); stats of player coins move; log row (not for market events: those have one
-- row with coin_id null, p_market_event); holders and creator of a player coin are notified.
create or replace function public.crypto_apply_event(p_coin uuid, p_event jsonb, p_shock double precision, p_now timestamptz,
                                                     p_market_event bigint default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  c        public.crypto_coins;
  v_key    text := p_event ->> 'key';
  v_before bigint;
  v_after  bigint;
  v_r      double precision := coalesce(p_shock, 0);
  v_loss   bigint := 0;
  v_cash   bigint;
  v_tok    bigint;
  v_delta  bigint;
  v_free   bigint;
  v_bps    integer;
  v_id     bigint;
  v_txt    jsonb;
begin
  select * into c from public.crypto_coins where id = p_coin for update;
  if c.id is null or c.status <> 'listed' or c.pool_tokens_e6 <= 0 or c.pool_cash_cents <= 0 then
    return null;
  end if;
  v_before := public.crypto_pool_price_e4(c.pool_cash_cents, c.pool_tokens_e6);
  if v_key = 'hack' then
    v_loss := floor(c.pool_cash_cents::numeric
                    * least(0.99, greatest(0, public.cfg_num(p_event, '{poolLossShare}', 0)))::numeric)::bigint;
    if v_loss > 0 then
      perform public.crypto_pool_settle(c.id);
      perform public.ledger_transfer(c.pool_account_id, public.ledger_system_account('treasury'), v_loss, 'crypto_flow',
                                     'Hack bei ' || c.name, 'crypto_coin', c.id, null);
      -- the stolen cash already moves the price; the flow does the rest of the shock
      v_r := v_r - ln((c.pool_cash_cents - v_loss)::double precision / c.pool_cash_cents);
      c.pool_cash_cents := c.pool_cash_cents - v_loss;
      c.pending_flow_cents := 0;
    end if;
  end if;
  select f.cash_cents, f.tokens_e6 into v_cash, v_tok from public.crypto_apply_flow(c.pool_cash_cents, c.pool_tokens_e6, v_r) f;
  v_delta := v_cash - c.pool_cash_cents;
  if v_delta > 0 then
    select a.balance_cents into v_free from public.ledger_accounts a where a.system_key = 'market';
    v_free := coalesce(v_free, 0) - coalesce((select sum(greatest(x.pending_flow_cents, 0)) from public.crypto_coins x), 0);
    if v_delta > v_free then
      v_cash := c.pool_cash_cents;
      v_tok := c.pool_tokens_e6;
      v_delta := 0;
    end if;
  end if;
  if v_cash <= 0 or v_tok <= 0 then
    v_cash := c.pool_cash_cents;
    v_tok := c.pool_tokens_e6;
    v_delta := 0;
  end if;
  update public.crypto_coins x
     set pool_cash_cents = v_cash, pool_tokens_e6 = v_tok, pending_flow_cents = c.pending_flow_cents + v_delta,
         tech = case when x.category = 'player' then least(100, greatest(0, x.tech + public.cfg_num(p_event, '{tech}', 0))) else x.tech end,
         hype = case when x.category = 'player' then least(100, greatest(0, x.hype + public.cfg_num(p_event, '{hype}', 0))) else x.hype end,
         utility = case when x.category = 'player' then least(100, greatest(0, x.utility + public.cfg_num(p_event, '{utility}', 0)))
                        else x.utility end
   where x.id = c.id;
  v_after := public.crypto_pool_price_e4(v_cash, v_tok);
  v_bps := greatest(-1000000, least(1000000, round((v_after - v_before) * 10000.0 / greatest(1, v_before))))::integer;
  if p_market_event is null then
    v_id := public.crypto_log(c.id, v_key, v_bps,
      jsonb_build_object('shock', round(coalesce(p_shock, 0)::numeric, 4))
      || case when v_loss > 0 then jsonb_build_object('loss_cents', v_loss) else '{}'::jsonb end, p_now);
  end if;
  perform public.crypto_mark(c.id, p_now, abs(v_tok - c.pool_tokens_e6), abs(v_delta));
  if c.category = 'player' then
    v_txt := public.crypto_event_text(v_key, c.name);
    perform public.crypto_notify(c.id, v_txt ->> 'title', v_txt ->> 'body', jsonb_build_object('key', v_key, 'shock_bps', v_bps),
                                 'crypto:ev:' || coalesce(v_id, p_market_event)::text || ':' || c.id::text);
  end if;
  return jsonb_build_object('ticker', c.ticker, 'key', v_key, 'shock_bps', v_bps, 'loss_cents', v_loss);
end;
$$;

-- Rug pull by a creator (more than rugShareBps of the team tokens sold within rugWindowHours): trust rugPull, hype 0,
-- friends feed, holders notified. Once per window (last_rug_at). The coin row is locked by the caller.
create or replace function public.crypto_rug_pull(p_coin uuid, p_now timestamptz, p_sold_e6 bigint)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  c    public.crypto_coins;
  s    public.securities;
  v_id bigint;
begin
  select * into c from public.crypto_coins where id = p_coin;
  select * into s from public.securities where id = c.security_id;
  if c.creator_id is null then
    return null;
  end if;
  perform public.trust_add(c.creator_id, null, 'rugPull');
  update public.crypto_coins set hype = 0, last_rug_at = p_now where id = c.id;
  v_id := public.crypto_log(c.id, 'rug_pull', null, jsonb_build_object('by_creator', true, 'sold_e6', p_sold_e6), p_now);
  perform public.feed_post(c.creator_id, 'rug_pull', jsonb_build_object('ticker', s.ticker, 'name', c.name),
                           'rug_pull:' || c.id::text || ':' || v_id::text);
  perform public.crypto_notify(c.id, 'Rug Pull bei ' || c.name,
                               'Der Gründer hat in kurzer Zeit einen großen Teil seiner Team-Coins verkauft.',
                               jsonb_build_object('key', 'rug_pull'), 'crypto:ev:' || v_id::text, false, true, c.creator_id);
  return v_id;
end;
$$;

-- Resolves a development action at its end: success roll with success_bps, stats on success; a failed influencer deal
-- is exposed (create.exposedHype, create.exposedShock as an event). Log row, notification to the creator.
create or replace function public.crypto_resolve_action(p_action uuid, p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  a      public.crypto_coin_actions;
  c      public.crypto_coins;
  v_cfg  jsonb := public.crypto_cfg();
  v_act  jsonb;
  v_ok   boolean;
  v_dt   double precision;
  v_dh   double precision;
  v_du   double precision;
  v_gain text;
begin
  select * into a from public.crypto_coin_actions where id = p_action for update;
  if a.id is null or a.resolved_at is not null then
    return null;
  end if;
  select * into c from public.crypto_coins where id = a.coin_id for update;
  if c.id is null or c.status not in ('draft', 'listed') then
    update public.crypto_coin_actions set resolved_at = p_now where id = a.id;
    return null;
  end if;
  v_act := public.crypto_action_cfg(v_cfg, a.key);
  v_ok := random() * 10000 < a.success_bps;
  v_dt := public.cfg_num(v_act, '{tech}', 0);
  v_dh := public.cfg_num(v_act, '{hype}', 0);
  v_du := public.cfg_num(v_act, '{utility}', 0);
  if v_ok then
    update public.crypto_coins
       set tech = least(100, greatest(0, tech + v_dt)), hype = least(100, greatest(0, hype + v_dh)),
           utility = least(100, greatest(0, utility + v_du))
     where id = c.id;
  elsif a.key = 'influencer' then
    update public.crypto_coins
       set hype = least(100, greatest(0, hype + public.cfg_num(v_cfg, '{create,exposedHype}', -20)))
     where id = c.id;
    if c.status = 'listed' then
      perform public.crypto_apply_event(c.id, '{"key": "exposed"}'::jsonb,
                                        public.cfg_num(v_cfg, '{create,exposedShock}', ln(0.85)), p_now);
    else
      perform public.crypto_log(c.id, 'exposed', null, '{}'::jsonb, p_now);
    end if;
  end if;
  update public.crypto_coin_actions set resolved_at = p_now, success = v_ok where id = a.id;
  perform public.crypto_log(c.id, 'action', null, jsonb_build_object('action', a.key, 'success', v_ok), p_now);
  v_gain := concat_ws(', ',
    case when v_dt <> 0 then to_char(v_dt, 'FMS999') || ' Technik' end,
    case when v_dh <> 0 then to_char(v_dh, 'FMS999') || ' Hype' end,
    case when v_du <> 0 then to_char(v_du, 'FMS999') || ' Nutzen' end);
  perform public.crypto_notify(c.id,
    public.crypto_action_label(a.key) || case when v_ok then ' geschafft' else ' gescheitert' end,
    case when v_ok then c.name || ': ' || coalesce(nullif(v_gain, ''), 'erledigt') || '.'
         when a.key = 'influencer' then 'Der bezahlte Post ist aufgeflogen. Der Hype ist weg.'
         else 'Diesmal hat es nicht geklappt. Das Geld ist weg.' end,
    jsonb_build_object('key', 'action', 'action', a.key, 'success', v_ok), 'crypto:action:' || a.id::text, true, false);
  return jsonb_build_object('action', a.key, 'success', v_ok);
end;
$$;

-- Ends a coin. Player coin (p_dead false): the pool's cash goes to all holders by their coins (discontinuePayoutCents,
-- creator included), the rounding rest to the treasury. Dead AI coin (p_dead true): holders get their coins at the dead
-- price (at most the pool), the rest goes back to the financial market. Positions are closed like a sale (tax), the
-- security is delisted and its ticker freed, the coin is closed. Draft coins simply close.
create or replace function public.crypto_close_coin(p_coin uuid, p_key text, p_now timestamptz, p_dead boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  c        public.crypto_coins;
  r        record;
  v_circ   bigint;
  v_price  bigint;
  v_left   bigint;
  v_pay    bigint;
  v_paid   bigint := 0;
  v_n      integer := 0;
  v_ticker text;
begin
  select * into c from public.crypto_coins where id = p_coin for update;
  if c.id is null or c.status not in ('draft', 'listed', 'dead') then
    return null;
  end if;
  update public.crypto_coin_actions set resolved_at = p_now where coin_id = c.id and resolved_at is null;
  if c.status in ('listed', 'dead') then
    perform public.crypto_pool_settle(c.id);
    select * into c from public.crypto_coins where id = p_coin;
    v_circ := public.crypto_held_e6(c.security_id);
    v_price := public.crypto_pool_price_e4(c.pool_cash_cents, c.pool_tokens_e6);
    v_left := c.pool_cash_cents;
    for r in select p.id, p.player_id, p.quantity_e6 from public.positions p
              where p.security_id = c.security_id and p.status = 'open' and p.quantity_e6 > 0
              order by p.player_id, p.id loop
      v_pay := least(v_left, case when p_dead then public.value_cents(r.quantity_e6, v_price)
                                  else public.crypto_discontinue_payout_cents(c.pool_cash_cents, r.quantity_e6, v_circ) end);
      perform public.crypto_close_position(r.id, v_pay, p_key, p_now);
      v_left := v_left - v_pay;
      v_paid := v_paid + v_pay;
      v_n := v_n + 1;
      if r.player_id is distinct from c.creator_id then
        perform public.social_notify(r.player_id, 'crypto_event',
          c.name || case when p_dead then ' gestrichen' else ' eingestellt' end,
          case when v_pay > 0 then 'Für deine Coins hast du ' || public.format_eur(v_pay) || ' aus dem Pool bekommen.'
               else 'Deine Coins sind wertlos verfallen.' end,
          jsonb_build_object('ticker', c.ticker, 'name', c.name, 'key', case when p_dead then 'delisted' else 'closed' end,
                             'payout_cents', v_pay),
          '/crypto', 'crypto:closed:' || c.id::text || ':' || r.player_id::text);
      end if;
    end loop;
    if v_left > 0 then
      perform public.ledger_transfer(c.pool_account_id,
                                     public.ledger_system_account(case when p_dead then 'market' else 'treasury' end), v_left,
                                     'crypto_flow', 'Rest des Pools ' || c.ticker, 'crypto_coin', c.id, p_key || ':rest');
    end if;
  end if;
  update public.crypto_coins
     set status = 'closed', closed_at = p_now, pool_cash_cents = 0, pool_tokens_e6 = 0, pending_flow_cents = 0,
         team_tokens_e6 = 0
   where id = c.id;
  update public.securities set status = 'delisted', is_tradable = false, delisted_at = p_now where id = c.security_id;
  v_ticker := public.crypto_tombstone_ticker(c.security_id);
  perform public.crypto_log(c.id, case when p_dead then 'delisted' else 'closed' end, null,
                            jsonb_build_object('paid_cents', v_paid, 'holders', v_n), p_now);
  return jsonb_build_object('ticker', c.ticker, 'paid_cents', v_paid, 'holders', v_n, 'rest_cents', greatest(0, coalesce(v_left, 0)));
end;
$$;

-- Minute job (from run_due_jobs): seeding, due actions; once per hour: stats fade, events, dead coins, settlement
create or replace function public.crypto_run_due(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz := coalesce(p_now, public.game_now());
  v_epoch    constant timestamptz := '2000-01-01 00:00:00+00';
  v_cfg      jsonb := public.crypto_cfg();
  v_hour     timestamptz;
  st         public.crypto_state;
  v_out      jsonb := '{}'::jsonb;
  v_n        integer := 0;
  v_events   integer := 0;
  v_dead     integer := 0;
  v_repl     integer := 0;
  v_ev       jsonb;
  v_shock    double precision;
  v_mid      bigint;
  v_txt      jsonb;
  v_coin     uuid;
  v_new      record;
  r          record;
begin
  v_hour := date_bin('1 hour', v_now, v_epoch);
  select * into st from public.crypto_state where id for update;
  if st.id is null then
    return jsonb_build_object('skipped', 'no_state');
  end if;
  if st.seeded_at is null then
    v_out := v_out || jsonb_build_object('bootstrap', public.crypto_bootstrap());
    select * into st from public.crypto_state where id;
    if st.seeded_at is null then
      return v_out;
    end if;
  end if;
  -- coin rows first, in id order: the same lock order as trades and ticks (coins, then ledger accounts)
  perform 1 from public.crypto_coins c where c.status in ('draft', 'listed', 'dead') order by c.id for update;

  for r in select a.id from public.crypto_coin_actions a
            where a.resolved_at is null and a.ends_at <= v_now order by a.ends_at, a.id loop
    perform public.crypto_resolve_action(r.id, v_now);
    v_n := v_n + 1;
  end loop;
  v_out := v_out || jsonb_build_object('actions', v_n);
  if st.hour_done is not null and st.hour_done >= v_hour then
    return v_out;
  end if;

  -- 1. hype and utility of player coins fade (decayStats for the hours since the last time)
  update public.crypto_coins c
     set hype = c.hype * power(public.cfg_num(v_cfg, '{create,hypeDecayPerHour}', 0.97), d.h),
         utility = c.utility * power(public.cfg_num(v_cfg, '{create,utilityDecayPerHour}', 0.995), d.h),
         stats_at = v_now
    from (select x.id, extract(epoch from (v_now - x.stats_at)) / 3600.0 as h from public.crypto_coins x
           where x.category = 'player' and x.status in ('draft', 'listed') and x.stats_at < v_now) d
   where c.id = d.id;

  -- 2. one event roll per listed coin
  for r in select c.id, c.category, c.tech, c.hype, c.utility, c.algorithmic from public.crypto_coins c
            where c.status = 'listed' order by c.id loop
    v_ev := public.crypto_roll_coin_event(v_cfg, random(), random(), r.category,
                                          case when r.category = 'player' then r.tech end, r.hype, r.utility);
    if v_ev is not null then
      perform public.crypto_apply_event(r.id, v_ev, public.crypto_event_shock(v_ev, random(), r.algorithmic), v_now);
      v_events := v_events + 1;
    end if;
  end loop;

  -- 3. one market event: meme_wave moves the meme coins, every other market event all coins but stablecoins
  v_ev := public.crypto_roll_market_event(v_cfg, random(), random());
  if v_ev is not null then
    v_shock := public.crypto_event_shock(v_ev, random(), false);
    v_mid := public.crypto_log(null, v_ev ->> 'key', round((exp(v_shock) - 1) * 10000)::integer,
                               jsonb_build_object('shock', round(v_shock::numeric, 4)), v_now);
    for r in select c.id from public.crypto_coins c
              where c.status = 'listed'
                and case when v_ev ->> 'key' = 'meme_wave' then c.category = 'meme' else c.category <> 'stable' end
              order by c.id loop
      perform public.crypto_apply_event(r.id, v_ev, v_shock, v_now, v_mid);
    end loop;
    v_events := v_events + 1;
  end if;

  -- 4. AI meme coins at or below deadPriceE4 are dead (no trading, frozen)
  for r in select c.id, c.name, c.security_id from public.crypto_coins c
            where c.status = 'listed' and c.category = 'meme' and c.creator_id is null
              and public.crypto_pool_price_e4(c.pool_cash_cents, c.pool_tokens_e6) <= public.cfg_num(v_cfg, '{deadPriceE4}', 2)
            order by c.id loop
    update public.crypto_coins set status = 'dead', dead_since = v_now where id = r.id;
    update public.securities set status = 'halted', is_tradable = false where id = r.security_id;
    v_mid := public.crypto_log(r.id, 'dead', null, '{}'::jsonb, v_now);
    v_txt := public.crypto_event_text('dead', r.name);
    perform public.crypto_notify(r.id, v_txt ->> 'title', v_txt ->> 'body', jsonb_build_object('key', 'dead'),
                                 'crypto:ev:' || v_mid::text, false, true);
    v_dead := v_dead + 1;
  end loop;

  -- 5. dead for deadCoinReplaceHours: delisted (holders get the dead price), a new meme coin takes the place
  for r in select c.* from public.crypto_coins c
            where c.status = 'dead'
              and c.dead_since <= v_now - make_interval(hours => public.cfg_num(v_cfg, '{deadCoinReplaceHours}', 24)::integer)
            order by c.dead_since, c.id loop
    perform public.crypto_close_coin(r.id, 'crypto:delist:' || r.id::text, v_now, true);
    select x.name, x.ticker into v_new from public.crypto_next_meme_coin() x;
    if v_new.name is not null then
      v_coin := public.crypto_list_ai_coin(v_new.ticker, v_new.name, 'meme', r.start_price_e4, r.start_pool_cents, false,
                                           r.color, null, v_now);
      if v_coin is not null then
        perform public.crypto_log(v_coin, 'listed', null, jsonb_build_object('replaces', r.ticker), v_now);
        v_repl := v_repl + 1;
      end if;
    end if;
  end loop;

  -- 6. the AI flows of the hour in one ledger transaction
  v_out := v_out || jsonb_build_object('settled', public.crypto_settle_flows());

  -- 7. housekeeping
  delete from public.crypto_volume_hours where hour < v_now - interval '48 hours';
  delete from public.crypto_team_sales
   where at < v_now - make_interval(hours => 2 * public.cfg_num(v_cfg, '{create,rugWindowHours}', 24)::integer);
  delete from public.crypto_events where at < v_now - interval '30 days';
  update public.crypto_state set hour_done = v_hour where id;
  return v_out || jsonb_build_object('events', v_events, 'dead', v_dead, 'replaced', v_repl);
end;
$$;
comment on function public.crypto_run_due(timestamptz) is
  'Crypto job (run_due_jobs, every minute): seeding, due coin actions; once per hour stats fade, events, market event, dead coins, replacement, settlement of the AI flows.';

-- ---------------------------------------------------------------------------
-- J. Read model
-- ---------------------------------------------------------------------------
-- COIN_ROW = {ticker, name, category, status, price_e4, change_24h_bps, high_24h_e4, low_24h_e4, pool_cents,
--             market_cap_cents, volume_24h_cents, fee_bps, color, logo|null, creator: {nickname, tag, trust: {score, band}}|null,
--             stats: {tech, hype, utility}|null, my_quantity_e6}
create or replace function public.crypto_coin_row(p_coin uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c         public.crypto_coins;
  q         public.security_quotes;
  v_from    timestamptz := date_bin('1 hour', public.game_now() - interval '24 hours', '2000-01-01 00:00:00+00'::timestamptz);
  v_price   bigint;
  v_ref     bigint;
  v_hi      bigint;
  v_lo      bigint;
  v_vol     bigint := 0;
  v_creator jsonb;
begin
  select * into c from public.crypto_coins where id = p_coin;
  if c.id is null then
    return null;
  end if;
  select * into q from public.security_quotes where security_id = c.security_id;
  if c.status in ('listed', 'dead') then
    v_price := q.last_price_e4;
  end if;
  if v_price is not null then
    select k.open_e4 into v_ref from public.candles k
     where k.security_id = c.security_id and k.interval = '1h' and k.bucket_start >= v_from
     order by k.bucket_start limit 1;
    select max(k.high_e4), min(k.low_e4) into v_hi, v_lo from public.candles k
     where k.security_id = c.security_id and k.interval = '1h' and k.bucket_start >= v_from;
    v_hi := greatest(coalesce(v_hi, v_price), v_price);
    v_lo := least(coalesce(v_lo, v_price), v_price);
    select coalesce(sum(h.volume_cents), 0)::bigint into v_vol from public.crypto_volume_hours h
     where h.coin_id = c.id and h.hour >= v_from;
  end if;
  if c.creator_id is not null then
    select jsonb_build_object('nickname', p.nickname, 'tag', p.tag,
                              'trust', jsonb_build_object('score', t.v -> 'score', 'band', t.v -> 'band'))
      into v_creator
      from public.profiles p cross join lateral (select public.player_trust(p.id) as v) t
     where p.id = c.creator_id;
  end if;
  return jsonb_build_object(
    'ticker',           c.ticker,
    'name',             c.name,
    'category',         c.category,
    'status',           c.status,
    'price_e4',         v_price,
    'change_24h_bps',   case when v_price is not null and coalesce(v_ref, 0) > 0
                             then greatest(-1000000, least(1000000, round((v_price - v_ref) * 10000.0 / v_ref)))::integer
                             else 0 end,
    'high_24h_e4',      v_hi,
    'low_24h_e4',       v_lo,
    'pool_cents',       c.pool_cash_cents,
    'market_cap_cents', case when v_price is not null then coalesce(q.market_cap_cents, 0) else 0 end,
    'volume_24h_cents', v_vol,
    'fee_bps',          public.crypto_player_fee_bps(p_viewer, c.category),
    'color',            c.color,
    'logo',             case when c.category = 'player' then c.logo end,
    'creator',          v_creator,
    'stats',            case when c.category = 'player'
                             then jsonb_build_object('tech', round(c.tech::numeric, 1), 'hype', round(c.hype::numeric, 1),
                                                     'utility', round(c.utility::numeric, 1)) end,
    'my_quantity_e6',   coalesce((select sum(p.quantity_e6) from public.positions p
                                   where p.player_id = p_viewer and p.security_id = c.security_id and p.status = 'open'), 0)::bigint);
end;
$$;

-- CRYPTO_EVENT = {ticker, name, key, shock_bps, at, payload}; market events: ticker and name null
create or replace function public.crypto_event_json(p_event bigint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('ticker', c.ticker, 'name', c.name, 'key', e.key, 'shock_bps', e.shock_bps, 'at', e.at,
                            'payload', e.payload)
    from public.crypto_events e left join public.crypto_coins c on c.id = e.coin_id
   where e.id = p_event;
$$;

-- MY_COIN = COIN_ROW + {id, status, stats, action, actions, team_tokens_e6, team_at_launch_e6, team_sold_window_e6,
--                       rug_limit_e6, launch, created_at, burn_hype, burn_min_e6, burn_available_at}
create or replace function public.crypto_my_coin(p_coin uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c        public.crypto_coins;
  v_cfg    jsonb := public.crypto_cfg();
  v_now    timestamptz := public.game_now();
  v_it     double precision;
  v_run    jsonb;
  v_acts   jsonb;
  v_window bigint;
  v_burn   jsonb;
begin
  select * into c from public.crypto_coins where id = p_coin;
  if c.id is null then
    return null;
  end if;
  v_it := coalesce((public.player_branch_scores(c.creator_id) ->> 'it')::double precision, 0);
  select jsonb_build_object('key', a.key, 'started_at', a.started_at, 'ends_at', a.ends_at) into v_run
    from public.crypto_coin_actions a where a.coin_id = c.id and a.resolved_at is null;
  select coalesce(jsonb_agg(jsonb_build_object(
           'key', x.a ->> 'key',
           'cost_cents', public.cfg_num(x.a, '{costCents}', 0)::bigint,
           'hours', public.cfg_num(x.a, '{hours}', 1),
           'success_bps', public.crypto_action_success_bps(v_cfg, x.a, v_it),
           'available', c.status in ('draft', 'listed') and v_run is null
                        and (c.status = 'listed' or not coalesce((x.a ->> 'afterLaunch')::boolean, false)))
           order by x.ord), '[]'::jsonb)
    into v_acts
    from jsonb_array_elements(public.crypto_cfg_array(v_cfg, '{create,actions}')) with ordinality x(a, ord)
   where x.a ->> 'key' <> 'marketing_burn';
  select coalesce(sum(t.quantity_e6), 0)::bigint into v_window from public.crypto_team_sales t
   where t.coin_id = c.id and t.at > v_now - make_interval(hours => public.cfg_num(v_cfg, '{create,rugWindowHours}', 24)::integer);
  v_burn := public.crypto_action_cfg(v_cfg, 'marketing_burn');
  return public.crypto_coin_row(c.id, c.creator_id) || jsonb_build_object(
    'id',                  c.id,
    'status',              c.status,
    'stats',               jsonb_build_object('tech', round(c.tech::numeric, 1), 'hype', round(c.hype::numeric, 1),
                                              'utility', round(c.utility::numeric, 1)),
    'action',              v_run,
    'actions',             v_acts,
    'team_tokens_e6',      c.team_tokens_e6,
    'team_at_launch_e6',   c.team_at_launch_e6,
    'team_sold_window_e6', v_window,
    'rug_limit_e6',        public.div_round_half_even(c.team_at_launch_e6::numeric
                                                      * round(public.cfg_num(v_cfg, '{create,rugShareBps}', 2000))::numeric, 10000),
    'launch',              case when c.launched_at is not null
                                then jsonb_build_object('start_price_e4', c.start_price_e4, 'liquidity_cents', c.start_pool_cents,
                                                        'team_share_bps', c.team_share_bps, 'at', c.launched_at) end,
    'created_at',          c.created_at,
    'burn_hype',           public.cfg_num(v_burn, '{hype}', 8),
    'burn_min_e6',         least(c.team_tokens_e6, greatest(1, public.div_round_half_even(c.team_at_launch_e6::numeric
                                 * round(public.cfg_num(v_cfg, '{create,burnMinBps}', 100))::numeric, 10000))),
    'burn_available_at',   case when c.last_burn_at is not null
                                 and c.last_burn_at + make_interval(secs => public.cfg_num(v_burn, '{hours}', 1) * 3600) > v_now
                                then c.last_burn_at + make_interval(secs => public.cfg_num(v_burn, '{hours}', 1) * 3600) end);
end;
$$;

create or replace function public.get_crypto_market()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  st       public.crypto_state;
  v_coins  jsonb;
  v_events jsonb;
begin
  v_player := public.require_player();
  select * into st from public.crypto_state where id;
  select coalesce(jsonb_agg(public.crypto_coin_row(x.id, v_player) order by x.rank, x.mcap desc, x.name), '[]'::jsonb)
    into v_coins
    from (select c.id, c.name, coalesce(q.market_cap_cents, 0) as mcap,
                 case c.category when 'stable' then 0 when 'major' then 1 when 'alt' then 2 when 'meme' then 3 else 4 end as rank
            from public.crypto_coins c left join public.security_quotes q on q.security_id = c.security_id
           where c.status in ('listed', 'dead')) x;
  select coalesce(jsonb_agg(public.crypto_event_json(e.id) order by e.at desc, e.id desc), '[]'::jsonb)
    into v_events
    from (select e.id, e.at from public.crypto_events e
           where e.key not in ('action', 'created')
           order by e.at desc, e.id desc limit 20) e;
  return jsonb_build_object(
    'regime', jsonb_build_object('kind', coalesce(st.regime, 'flat'), 'until', st.regime_until),
    'coins',  v_coins,
    'events', v_events);
end;
$$;

-- COIN_ROW + {pool: {cash_cents, tokens_e6}, supply_e6, team_tokens_e6|null, holders, my_position|null, events}
create or replace function public.get_coin(p_ticker text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  c        public.crypto_coins;
  v_price  bigint;
  v_pos    jsonb;
  v_events jsonb;
begin
  v_player := public.require_player();
  select x.* into c from public.crypto_coins x join public.securities s on s.id = x.security_id
   where s.ticker = upper(btrim(coalesce(p_ticker, ''))) and x.status <> 'closed';
  if c.id is null then
    perform public.api_error('coin_not_found');
  end if;
  select q.last_price_e4 into v_price from public.security_quotes q where q.security_id = c.security_id;
  select jsonb_build_object('quantity_e6', p.quantity_e6, 'avg_price_e4', p.avg_entry_price_e4,
                            'value_cents', public.value_cents(p.quantity_e6, coalesce(v_price, 0)))
    into v_pos
    from public.positions p
   where p.player_id = v_player and p.security_id = c.security_id and p.status = 'open' and p.quantity_e6 > 0
   limit 1;
  select coalesce(jsonb_agg(public.crypto_event_json(e.id) order by e.at desc, e.id desc), '[]'::jsonb)
    into v_events
    from (select e.id, e.at from public.crypto_events e
           where e.coin_id = c.id
              or (e.coin_id is null and e.at >= c.created_at and c.status in ('listed', 'dead')
                  and case when e.key = 'meme_wave' then c.category = 'meme' else c.category <> 'stable' end)
           order by e.at desc, e.id desc limit 20) e;
  return public.crypto_coin_row(c.id, v_player) || jsonb_build_object(
    'pool',           jsonb_build_object('cash_cents', c.pool_cash_cents, 'tokens_e6', c.pool_tokens_e6),
    'supply_e6',      c.pool_tokens_e6 + public.crypto_held_e6(c.security_id),
    'team_tokens_e6', case when c.category = 'player' then c.team_tokens_e6 end,
    'holders',        (select count(distinct p.player_id) from public.positions p
                        where p.security_id = c.security_id and p.status = 'open' and p.quantity_e6 > 0)::integer,
    'my_position',    v_pos,
    'events',         v_events);
end;
$$;

-- ---------------------------------------------------------------------------
-- K. Own coins
-- ---------------------------------------------------------------------------
-- Why a coin name / ticker is not allowed (null = allowed): name length (create.nameMinLength..nameMaxLength), the
-- company name filter (characters, profanity, reserved names), unique among draft and listed coins with the lookalike
-- key of player names (name_key); ticker 3..5 letters A-Z, free among all securities and index keys, no profanity.
create or replace function public.crypto_coin_name_violation(p_name text, p_ticker text)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cfg    jsonb := public.crypto_cfg();
  v_t      text := upper(btrim(coalesce(p_ticker, '')));
  v_reason text;
begin
  if p_name is null or char_length(p_name) < public.cfg_num(v_cfg, '{create,nameMinLength}', 3) then
    return 'name_too_short';
  end if;
  if char_length(p_name) > public.cfg_num(v_cfg, '{create,nameMaxLength}', 24) then
    return 'name_too_long';
  end if;
  v_reason := public.name_violation(p_name, 'company');
  if v_reason is not null and v_reason <> 'name_taken' then
    return v_reason;
  end if;
  if exists (select 1 from public.crypto_coins c
              where c.status in ('draft', 'listed') and public.name_key(c.name) = public.name_key(p_name)) then
    return 'name_taken';
  end if;
  if v_t !~ '^[A-Z]+$' or char_length(v_t) < public.cfg_num(v_cfg, '{create,tickerMinLength}', 3)
     or char_length(v_t) > public.cfg_num(v_cfg, '{create,tickerMaxLength}', 5) then
    return 'invalid_argument';
  end if;
  if exists (select 1 from public.securities s where s.ticker = v_t)
     or exists (select 1 from public.indices i where upper(i.key) = v_t) then
    return 'ticker_taken';
  end if;
  if public.name_violation(v_t, 'company') = 'name_profanity' then
    return 'name_profanity';
  end if;
  return null;
end;
$$;

create or replace function public.check_coin_name(p_name text, p_ticker text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_reason text;
begin
  perform public.require_player();
  v_reason := public.crypto_coin_name_violation(p_name, p_ticker);
  return jsonb_build_object('allowed', v_reason is null, 'reason', v_reason);
end;
$$;

-- The caller's draft or listed coin, locked
create or replace function public.crypto_own_coin(p_player uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  select c.id into v_id from public.crypto_coins c
   where c.creator_id = p_player and c.status in ('draft', 'listed')
   for update;
  if v_id is null then
    perform public.api_error('coin_not_found');
  end if;
  return v_id;
end;
$$;

create or replace function public.create_coin(p_request_id uuid, p_name text, p_ticker text, p_logo jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_cfg    jsonb := public.crypto_cfg();
  v_now    timestamptz := public.game_now();
  v_level  integer;
  v_reason text;
  v_ticker text := upper(btrim(coalesce(p_ticker, '')));
  v_cost   bigint;
  v_cash   bigint;
  v_sec    uuid;
  v_coin   uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'create_coin');
  if v_replay is not null then
    return v_replay;
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < public.cfg_num(v_cfg, '{createMinLevel}', 14) then
    perform public.api_error('locked');
  end if;
  if exists (select 1 from public.crypto_coins c where c.creator_id = v_player and c.status in ('draft', 'listed')) then
    perform public.api_error('coin_exists');
  end if;
  v_reason := public.crypto_coin_name_violation(p_name, p_ticker);
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  if p_logo is null or not public.logo_valid(p_logo) then
    perform public.api_error('invalid_argument');
  end if;
  if public.logo_has_forbidden_symbol(p_logo -> 'grid') then
    perform public.api_error('logo_forbidden');
  end if;
  v_cost := greatest(0, public.cfg_num(v_cfg, '{create,costCents}', 2500000))::bigint;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('treasury'),
                                   v_cost, 'crypto_fee', 'Gründung der Kryptowährung ' || v_ticker, 'crypto_coin', null,
                                   'crypto:create:' || p_request_id::text, v_player);
  end if;
  insert into public.securities (kind, ticker, name, status, tick_size_e4, is_tradable, is_shortable, max_leverage)
  values ('crypto', v_ticker, p_name, 'pending', 1, false, false, 1)
  returning id into v_sec;
  insert into public.crypto_coins (security_id, ticker, name, category, status, color, logo, creator_id, stats_at, created_at)
  values (v_sec, v_ticker, p_name, 'player', 'draft', p_logo -> 'palette' ->> 0,
          jsonb_build_object('palette', p_logo -> 'palette', 'grid', p_logo -> 'grid'), v_player, v_now, v_now)
  returning id into v_coin;
  perform public.crypto_log(v_coin, 'created', null, '{}'::jsonb, v_now);
  return public.request_complete(v_player, p_request_id, public.crypto_my_coin(v_coin));
end;
$$;

create or replace function public.get_my_coin()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_coin   uuid;
begin
  v_player := public.require_player();
  select c.id into v_coin from public.crypto_coins c
   where c.creator_id = v_player and c.status in ('draft', 'listed')
   order by c.created_at desc limit 1;
  return jsonb_build_object('coin', case when v_coin is not null then public.crypto_my_coin(v_coin) end);
end;
$$;

create or replace function public.start_coin_action(p_request_id uuid, p_action text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_cfg    jsonb := public.crypto_cfg();
  v_now    timestamptz := public.game_now();
  v_coin   uuid;
  c        public.crypto_coins;
  v_act    jsonb;
  v_cost   bigint;
  v_cash   bigint;
  v_it     double precision;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'start_coin_action');
  if v_replay is not null then
    return v_replay;
  end if;
  v_coin := public.crypto_own_coin(v_player);
  select * into c from public.crypto_coins where id = v_coin;
  v_act := public.crypto_action_cfg(v_cfg, p_action);
  if v_act is null or p_action = 'marketing_burn' then
    perform public.api_error('invalid_argument');
  end if;
  if coalesce((v_act ->> 'afterLaunch')::boolean, false) and c.status <> 'listed' then
    perform public.api_error('coin_not_launched');
  end if;
  if exists (select 1 from public.crypto_coin_actions a where a.coin_id = c.id and a.resolved_at is null) then
    perform public.api_error('coin_action_running');
  end if;
  v_cost := greatest(0, public.cfg_num(v_act, '{costCents}', 0))::bigint;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('treasury'),
                                   v_cost, 'crypto_fee', c.name || ': ' || public.crypto_action_label(p_action), 'crypto_coin', c.id,
                                   'crypto:action:' || p_request_id::text, v_player);
  end if;
  v_it := coalesce((public.player_branch_scores(v_player) ->> 'it')::double precision, 0);
  insert into public.crypto_coin_actions (coin_id, key, cost_cents, success_bps, started_at, ends_at)
  values (c.id, p_action, v_cost, public.crypto_action_success_bps(v_cfg, v_act, v_it), v_now,
          v_now + make_interval(secs => public.cfg_num(v_act, '{hours}', 1) * 3600));
  return public.request_complete(v_player, p_request_id, public.crypto_my_coin(c.id));
end;
$$;

create or replace function public.launch_coin(p_request_id uuid, p_start_price_e4 bigint, p_liquidity_cents bigint,
                                               p_team_share_bps integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_cfg    jsonb := public.crypto_cfg();
  v_now    timestamptz := public.game_now();
  v_coin   uuid;
  c        public.crypto_coins;
  v_cash   bigint;
  v_tokens bigint;
  v_team   bigint;
  v_acc    uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'launch_coin');
  if v_replay is not null then
    return v_replay;
  end if;
  v_coin := public.crypto_own_coin(v_player);
  select * into c from public.crypto_coins where id = v_coin;
  if c.status <> 'draft' then
    perform public.api_error('already_listed');
  end if;
  if c.tech < public.cfg_num(v_cfg, '{create,launchMinTech}', 20) then
    perform public.api_error('coin_tech_too_low');
  end if;
  if p_start_price_e4 is null
     or not exists (select 1 from jsonb_array_elements(public.crypto_cfg_array(v_cfg, '{create,startPriceOptionsE4}')) o
                     where jsonb_typeof(o) = 'number' and (o #>> '{}')::numeric = p_start_price_e4)
     or p_liquidity_cents is null or p_liquidity_cents < public.cfg_num(v_cfg, '{create,minLiquidityCents}', 500000)
     or p_team_share_bps is null or p_team_share_bps < public.cfg_num(v_cfg, '{create,teamShareMinBps}', 1000)
     or p_team_share_bps > public.cfg_num(v_cfg, '{create,teamShareMaxBps}', 5000) then
    perform public.api_error('invalid_argument');
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < p_liquidity_cents then
    perform public.api_error('insufficient_funds');
  end if;
  v_tokens := public.crypto_pool_tokens_at(p_liquidity_cents, p_start_price_e4);
  v_team := public.crypto_launch_team_e6(v_tokens, p_team_share_bps);
  if v_tokens <= 0 or v_team <= 0 then
    perform public.api_error('invalid_argument');
  end if;
  v_acc := public.crypto_pool_account(c.id);
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), v_acc, p_liquidity_cents, 'crypto_launch',
                                 'Start von ' || c.name || ': Liquidität für den Pool', 'crypto_coin', c.id,
                                 'crypto:launch:' || c.id::text, v_player);
  update public.crypto_coins
     set status = 'listed', pool_cash_cents = p_liquidity_cents, pool_tokens_e6 = v_tokens, start_price_e4 = p_start_price_e4,
         start_pool_cents = p_liquidity_cents, team_share_bps = p_team_share_bps, team_at_launch_e6 = v_team,
         team_tokens_e6 = v_team, launched_at = v_now
   where id = c.id;
  update public.securities set status = 'listed', is_tradable = true, listed_at = now() where id = c.security_id;
  -- the team tokens are the creator's position, cost basis 0
  insert into public.positions (player_id, security_id, quantity_e6, avg_entry_price_e4, cost_basis_cents, opened_at)
  values (v_player, c.security_id, v_team, 0, 0, v_now);
  perform public.crypto_mark(c.id, v_now, 0, 0);
  perform public.crypto_log(c.id, 'launch', null,
    jsonb_build_object('start_price_e4', p_start_price_e4, 'liquidity_cents', p_liquidity_cents, 'team_share_bps', p_team_share_bps),
    v_now);
  perform public.feed_post(v_player, 'coin_launched', jsonb_build_object('ticker', c.ticker, 'name', c.name),
                           'coin_launched:' || c.id::text);
  return public.request_complete(v_player, p_request_id, public.crypto_my_coin(c.id));
end;
$$;

create or replace function public.burn_coin_tokens(p_request_id uuid, p_quantity_e6 bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_cfg    jsonb := public.crypto_cfg();
  v_now    timestamptz := public.game_now();
  v_coin   uuid;
  c        public.crypto_coins;
  pos      public.positions;
  v_burn   jsonb;
  v_min    bigint;
begin
  v_player := public.require_player();
  if p_request_id is null or p_quantity_e6 is null or p_quantity_e6 < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'burn_coin_tokens');
  if v_replay is not null then
    return v_replay;
  end if;
  v_coin := public.crypto_own_coin(v_player);
  select * into c from public.crypto_coins where id = v_coin;
  if c.status <> 'listed' then
    perform public.api_error('coin_not_launched');
  end if;
  v_burn := public.crypto_action_cfg(v_cfg, 'marketing_burn');
  if c.last_burn_at is not null and c.last_burn_at + make_interval(secs => public.cfg_num(v_burn, '{hours}', 1) * 3600) > v_now then
    perform public.api_error('rate_limited');
  end if;
  select * into pos from public.positions p
   where p.player_id = v_player and p.security_id = c.security_id and p.side = 'long' and p.leverage = 1 and p.status = 'open'
   for update;
  if pos.id is null or p_quantity_e6 > c.team_tokens_e6 or p_quantity_e6 > pos.quantity_e6 - pos.reserved_quantity_e6 then
    perform public.api_error('insufficient_position');
  end if;
  v_min := greatest(1, public.div_round_half_even(c.team_at_launch_e6::numeric
                                                  * round(public.cfg_num(v_cfg, '{create,burnMinBps}', 100))::numeric, 10000));
  if p_quantity_e6 < v_min and p_quantity_e6 < c.team_tokens_e6 then
    perform public.api_error('invalid_quantity');
  end if;
  if pos.quantity_e6 - p_quantity_e6 = 0 then
    -- nothing left: whatever cost basis remains is a realised loss
    if pos.cost_basis_cents > 0 then
      perform public.crypto_realise(v_player, -pos.cost_basis_cents);
    end if;
    update public.positions
       set quantity_e6 = 0, cost_basis_cents = 0, status = 'closed', closed_at = v_now,
           realized_pnl_cents = realized_pnl_cents - cost_basis_cents
     where id = pos.id;
  else
    -- burnt team tokens cost nothing: the cost basis stays with the remaining coins
    update public.positions
       set quantity_e6 = quantity_e6 - p_quantity_e6,
           avg_entry_price_e4 = public.div_round_half_even(cost_basis_cents::numeric * 100000000, quantity_e6 - p_quantity_e6)
     where id = pos.id;
  end if;
  update public.crypto_coins
     set team_tokens_e6 = team_tokens_e6 - p_quantity_e6, burned_e6 = burned_e6 + p_quantity_e6,
         hype = least(100, greatest(0, hype + public.cfg_num(v_burn, '{hype}', 8))), last_burn_at = v_now
   where id = c.id;
  perform public.crypto_mark(c.id, v_now, 0, 0);
  perform public.crypto_log(c.id, 'burn', null, jsonb_build_object('quantity_e6', p_quantity_e6), v_now);
  return public.request_complete(v_player, p_request_id, public.crypto_my_coin(c.id));
end;
$$;

create or replace function public.discontinue_coin(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_now    timestamptz := public.game_now();
  v_coin   uuid;
  c        public.crypto_coins;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'discontinue_coin');
  if v_replay is not null then
    return v_replay;
  end if;
  v_coin := public.crypto_own_coin(v_player);
  select * into c from public.crypto_coins where id = v_coin;
  perform public.crypto_close_coin(c.id, 'crypto:close:' || c.id::text, v_now, false);
  if c.status = 'listed' then
    perform public.feed_post(v_player, 'coin_closed', jsonb_build_object('ticker', c.ticker, 'name', c.name),
                             'coin_closed:' || c.id::text);
  end if;
  return public.request_complete(v_player, p_request_id, public.crypto_my_coin(c.id));
end;
$$;

-- ---------------------------------------------------------------------------
-- L. Trading against the pool
-- ---------------------------------------------------------------------------
-- buy: p_amount_cents in total (order fee trading.orderFeeCents included, like place_order with an amount), the rest is
-- swapped (swapBuy, pool fee of the category minus the hardware wallet). sell: p_quantity_e6 coins (≥ 99.9 % of the
-- free position = all of it), swapSell. Average cost basis (exact cents), realised result and tax like stocks.
create or replace function public.crypto_trade(p_request_id uuid, p_ticker text, p_side text, p_amount_cents bigint default null,
                                               p_quantity_e6 bigint default null, p_max_slippage_bps integer default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player   uuid;
  v_replay   jsonb;
  v_cfg      jsonb := public.crypto_cfg();
  v_trading  jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_abuse    jsonb := coalesce(public.config_jsonb('abuse'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_side     text := lower(coalesce(p_side, ''));
  v_level    integer;
  v_coin     uuid;
  c          public.crypto_coins;
  s          public.securities;
  pos        public.positions;
  v_cash     bigint;
  v_fee_bps  integer;
  v_ofee     bigint;
  v_min      bigint;
  v_before   bigint;
  v_after    bigint;
  v_avg      bigint;
  v_slip     integer;
  v_qty      bigint;
  v_swap     bigint;
  v_pool_fee bigint;
  v_new_cash bigint;
  v_new_tok  bigint;
  v_net      bigint := 0;
  v_tax      bigint := 0;
  v_pnl      bigint;
  v_cost     bigint;
  v_avail    bigint;
  v_after_q  bigint;
  v_tx       uuid;
  v_order    uuid := gen_random_uuid();
  v_trade    uuid := gen_random_uuid();
  v_xp       integer := 0;
  v_wash     boolean := false;
  v_seq      bigint;
  v_team     bigint;
  v_window   bigint;
  v_rug      boolean := false;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'crypto_trade');
  if v_replay is not null then
    return v_replay;
  end if;
  if v_side not in ('buy', 'sell') or (p_max_slippage_bps is not null and p_max_slippage_bps < 0)
     or (v_side = 'buy' and (p_amount_cents is null or p_amount_cents < 1))
     or (v_side = 'sell' and (p_quantity_e6 is null or p_quantity_e6 < 1)) then
    perform public.api_error('invalid_argument');
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < public.cfg_num(v_cfg, '{minLevel}', 10) then
    perform public.api_error('locked');
  end if;
  if (select r.is_paused from public.sim_runtime r where r.id) then
    perform public.api_error('market_paused');
  end if;
  if not public.rate_limit_hit(v_player, 'place_order',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerMinute}', 20))::integer, 60)
     or not public.rate_limit_hit(v_player, 'place_order_day',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerDay}', 500))::integer, 86400) then
    perform public.api_error('rate_limited');
  end if;

  -- the coin first (lock order everywhere: coin rows, then ledger accounts)
  select x.id into v_coin from public.crypto_coins x join public.securities sx on sx.id = x.security_id
   where sx.ticker = upper(btrim(coalesce(p_ticker, ''))) and x.status <> 'closed'
   for update of x;
  if v_coin is null then
    perform public.api_error('coin_not_found');
  end if;
  select * into c from public.crypto_coins where id = v_coin;
  if c.status <> 'listed' or c.pool_cash_cents <= 0 or c.pool_tokens_e6 <= 0 then
    perform public.api_error('coin_not_tradable');
  end if;
  select * into s from public.securities where id = c.security_id;
  v_cash := public.lock_player_accounts(v_player);
  perform public.crypto_pool_settle(c.id);
  select * into c from public.crypto_coins where id = v_coin;

  v_fee_bps := public.crypto_player_fee_bps(v_player, c.category);
  v_ofee := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min := greatest(1, public.cfg_num(v_trading, '{minOrderValueCents}', 100))::bigint;
  v_before := public.crypto_pool_price_e4(c.pool_cash_cents, c.pool_tokens_e6);
  select * into pos from public.positions p
   where p.player_id = v_player and p.security_id = c.security_id and p.side = 'long' and p.leverage = 1 and p.status = 'open'
   for update;

  if v_side = 'buy' then
    v_swap := p_amount_cents - v_ofee;
    if v_swap < v_min then
      perform public.api_error('order_too_small');
    end if;
    if p_amount_cents > v_cash then
      perform public.api_error('insufficient_funds');
    end if;
    select b.tokens_out_e6, b.fee_cents, b.cash_after_cents, b.tokens_after_e6 into v_qty, v_pool_fee, v_new_cash, v_new_tok
      from public.crypto_swap_buy(c.pool_cash_cents, c.pool_tokens_e6, v_swap, v_fee_bps) b;
    if v_qty < 1 then
      perform public.api_error('order_too_small');
    end if;
    v_avg := greatest(1, public.div_round_half_even(v_swap::numeric * 100000000, v_qty));
    v_slip := public.crypto_slippage_bps(v_before, v_avg, 'buy');
    if p_max_slippage_bps is not null and v_slip > p_max_slippage_bps then
      perform public.api_error('slippage_exceeded');
    end if;
    v_tx := public.ledger_post('crypto_buy',
      (select jsonb_agg(jsonb_build_object('account_id', x.a, 'amount_cents', x.v))
         from (values (public.ledger_player_account(v_player, 'player_cash'), -p_amount_cents),
                      (c.pool_account_id, v_swap),
                      (public.ledger_system_account('treasury'), v_ofee)) as x(a, v)
        where x.v <> 0),
      'Kauf ' || s.ticker, 'order', v_order, 'crypto:' || v_order::text, v_player,
      jsonb_build_object('quantity_e6', v_qty, 'price_e4', v_avg, 'pool_fee_cents', v_pool_fee, 'trade_id', v_trade));
    if pos.id is null then
      insert into public.positions (player_id, security_id, quantity_e6, avg_entry_price_e4, cost_basis_cents, opened_at)
      values (v_player, c.security_id, v_qty, v_avg, v_swap, v_now)
      returning * into pos;
      v_after_q := v_qty;
    else
      update public.positions
         set quantity_e6 = quantity_e6 + v_qty, cost_basis_cents = cost_basis_cents + v_swap,
             avg_entry_price_e4 = public.div_round_half_even((cost_basis_cents + v_swap)::numeric * 100000000, quantity_e6 + v_qty)
       where id = pos.id;
      v_after_q := pos.quantity_e6 + v_qty;
    end if;
    v_net := -p_amount_cents;
  else
    v_avail := coalesce(pos.quantity_e6 - pos.reserved_quantity_e6, 0);
    v_qty := p_quantity_e6;
    if v_qty < v_avail and v_qty * 1000 >= v_avail * 999 then
      v_qty := v_avail;
    end if;
    if v_avail < v_qty then
      perform public.api_error('insufficient_position');
    end if;
    select x.cash_out_cents, x.fee_cents, x.cash_after_cents, x.tokens_after_e6 into v_swap, v_pool_fee, v_new_cash, v_new_tok
      from public.crypto_swap_sell(c.pool_cash_cents, c.pool_tokens_e6, v_qty, v_fee_bps) x;
    if v_swap < v_min and v_qty <> v_avail then
      perform public.api_error('order_too_small');
    end if;
    v_avg := greatest(1, public.div_round_half_even(v_swap::numeric * 100000000, v_qty));
    v_slip := public.crypto_slippage_bps(v_before, v_avg, 'sell');
    if p_max_slippage_bps is not null and v_slip > p_max_slippage_bps then
      perform public.api_error('slippage_exceeded');
    end if;
    v_cost := case when v_qty = pos.quantity_e6 then pos.cost_basis_cents
                   else public.div_round_half_even(pos.cost_basis_cents::numeric * v_qty, pos.quantity_e6) end;
    v_pnl := v_swap - v_ofee - v_cost;
    v_tax := public.crypto_realise(v_player, v_pnl);
    v_net := v_swap - v_ofee - v_tax;
    if v_cash + v_net < 0 then
      perform public.api_error('insufficient_funds');
    end if;
    if v_swap <> 0 or v_ofee + v_tax <> 0 then
      v_tx := public.ledger_post('crypto_sell',
        (select jsonb_agg(jsonb_build_object('account_id', x.a, 'amount_cents', x.v))
           from (select y.a, sum(y.v)::bigint as v
                   from (values (c.pool_account_id, -v_swap),
                                (public.ledger_player_account(v_player, 'player_cash'), v_net),
                                (public.ledger_system_account('treasury'), v_ofee + v_tax)) as y(a, v)
                  group by y.a) x
          where x.v <> 0),
        'Verkauf ' || s.ticker, 'order', v_order, 'crypto:' || v_order::text, v_player,
        jsonb_build_object('quantity_e6', v_qty, 'price_e4', v_avg, 'pool_fee_cents', v_pool_fee, 'trade_id', v_trade));
    end if;
    update public.positions
       set quantity_e6 = quantity_e6 - v_qty,
           cost_basis_cents = cost_basis_cents - v_cost,
           realized_pnl_cents = realized_pnl_cents + v_pnl,
           avg_entry_price_e4 = case when quantity_e6 - v_qty = 0 then avg_entry_price_e4
                                     else public.div_round_half_even((cost_basis_cents - v_cost)::numeric * 100000000,
                                                                     quantity_e6 - v_qty) end,
           status = case when quantity_e6 - v_qty = 0 then 'closed'::public.position_status else status end,
           closed_at = case when quantity_e6 - v_qty = 0 then v_now else closed_at end
     where id = pos.id;
    v_after_q := pos.quantity_e6 - v_qty;
    v_wash := exists (
      select 1 from public.trades t
       where t.player_id = v_player and t.security_id = c.security_id and t.side = 'buy'
         and t.executed_at > v_now - make_interval(secs => public.cfg_num(v_trading, '{washTradeWindowSeconds}', 600)));
    if v_net > 0 then
      perform public.loan_withhold(v_player, v_net, 'crypto:' || v_order::text);
    end if;
  end if;

  update public.crypto_coins set pool_cash_cents = v_new_cash, pool_tokens_e6 = v_new_tok where id = c.id;
  v_after := public.crypto_pool_price_e4(v_new_cash, v_new_tok);

  -- the creator's team tokens: the coins held beyond them are sold first; selling below counts as team sales
  if v_side = 'sell' and c.creator_id = v_player and c.team_tokens_e6 > 0 then
    v_team := least(c.team_tokens_e6, v_after_q);
    if v_team < c.team_tokens_e6 then
      insert into public.crypto_team_sales (coin_id, quantity_e6, at) values (c.id, c.team_tokens_e6 - v_team, v_now);
      update public.crypto_coins set team_tokens_e6 = v_team where id = c.id;
      select coalesce(sum(t.quantity_e6), 0)::bigint into v_window from public.crypto_team_sales t
       where t.coin_id = c.id
         and t.at > v_now - make_interval(hours => public.cfg_num(v_cfg, '{create,rugWindowHours}', 24)::integer);
      if public.crypto_is_rug_pull(v_cfg, v_window, c.team_at_launch_e6)
         and (c.last_rug_at is null
              or c.last_rug_at <= v_now - make_interval(hours => public.cfg_num(v_cfg, '{create,rugWindowHours}', 24)::integer)) then
        perform public.crypto_rug_pull(c.id, v_now, v_window);
        v_rug := true;
      end if;
    end if;
  end if;

  -- trade XP like stocks (one per trade, daily cap in grant_xp, not for closing inside the wash-trade window)
  if not v_wash and v_swap >= public.cfg_num(v_prog, '{xpSources,trade,minOrderValueCents}', 10000) then
    v_xp := public.grant_xp(v_player, 'trade', public.cfg_num(v_prog, '{xpSources,trade,xp}', 10)::integer,
                            'trade:' || v_order::text, 'trade', v_trade);
  end if;

  -- history: one filled market order and its trade (counterparty: the pool, an automated market maker)
  select r.tick_seq into v_seq from public.sim_runtime r where r.id;
  insert into public.orders (id, player_id, security_id, request_id, side, type, quantity_e6, filled_quantity_e6, status,
                             avg_fill_price_e4, fee_cents, filled_at)
  values (v_order, v_player, c.security_id, p_request_id, v_side::public.order_side, 'market', v_qty, v_qty, 'filled',
          v_avg, v_ofee, v_now);
  insert into public.trades (id, order_id, player_id, security_id, position_id, side, quantity_e6, price_e4, gross_cents,
                             fee_cents, tax_cents, realized_pnl_cents, counterparty, ledger_transaction_id, tick_seq,
                             is_wash_trade, xp_awarded, executed_at)
  values (v_trade, v_order, v_player, c.security_id, pos.id, v_side::public.order_side, v_qty, v_avg, v_swap, v_ofee, v_tax,
          case when v_side = 'sell' then v_pnl end, 'market_maker', v_tx, v_seq, v_wash, v_xp, v_now);

  perform public.crypto_mark(c.id, v_now, v_qty, v_swap);

  -- missions as for stocks
  perform public.mission_event(v_player, 'trade', 1, null);
  perform public.mission_event(v_player, v_side, 1, null);
  perform public.mission_event(v_player, 'trade_value', v_swap, null);
  perform public.mission_event(v_player, 'trading_day', 1, to_char(v_now at time zone 'Europe/Berlin', 'YYYY-MM-DD'));
  perform public.mission_event(v_player, 'distinct_security', 1, s.ticker);
  if v_side = 'buy' then
    perform public.mission_event(v_player, 'buy_value', v_swap, null);
  elsif v_pnl > 0 then
    perform public.mission_event(v_player, 'realized_profit', v_pnl, null);
  end if;

  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'side',               v_side,
    'ticker',             s.ticker,
    'quantity_e6',        v_qty,
    'cash_cents',         case when v_side = 'buy' then p_amount_cents else v_net end,
    'fee_cents',          v_pool_fee + v_ofee,
    'pool_fee_cents',     v_pool_fee,
    'order_fee_cents',    v_ofee,
    'tax_cents',          v_tax,
    'realized_pnl_cents', case when v_side = 'sell' then v_pnl end,
    'price_e4',           v_after,
    'avg_price_e4',       v_avg,
    'slippage_bps',       v_slip,
    'position_e6',        v_after_q,
    'cash_after_cents',   (select a.balance_cents from public.ledger_accounts a
                            where a.owner_player_id = v_player and a.kind = 'player_cash'),
    'xp_awarded',         v_xp,
    'rug_pull',           v_rug));
end;
$$;

-- ---------------------------------------------------------------------------
-- M. Trust reason rugPull, feed labels
-- ---------------------------------------------------------------------------
create or replace function public.trust_delta(p_reason text)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select round(public.cfg_num(public.trust_cfg(), array['deltas', p_reason],
    case p_reason
      when 'loanRepaidOnTime' then 4 when 'loanRepaidLate' then 2 when 'loanOverdue' then -6 when 'loanDefaulted' then -12
      when 'loanLent' then 1 when 'loanForgiven' then 2 when 'supplyKept' then 3 when 'supplyShort' then -4
      when 'stakeKept' then 3 when 'dealBroken' then -12 when 'rugPull' then -20 else 0
    end)::numeric)::integer;
$$;

-- Short German description of a feed item (body of the reaction notification), as in M4j plus the crypto kinds
create or replace function public.feed_item_label(p_kind text, p_payload jsonb)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_kind
    when 'level_up' then 'Level ' || coalesce(p_payload ->> 'level', '?') || ' erreicht'
    when 'big_trade' then 'Gewinn mit ' || coalesce(p_payload ->> 'ticker', 'einer Aktie')
    when 'company_founded' then coalesce(p_payload ->> 'name', 'Firma') || ' gegründet'
    when 'company_upgraded' then coalesce(p_payload ->> 'name', 'Firma') || ' aufgestiegen'
    when 'company_ipo' then coalesce(p_payload ->> 'name', 'Firma') || ' an der Börse'
    when 'company_expanded' then coalesce(p_payload ->> 'name', 'Firma') || ' erweitert'
    when 'art_won' then 'Kunstwerk „' || coalesce(p_payload ->> 'title', '?') || '“ ersteigert'
    when 'art_created' then 'Kunstwerk „' || coalesce(p_payload ->> 'title', '?') || '“ gemalt'
    when 'home_bought' then 'Neues Zuhause'
    when 'car_bought' then 'Neues Auto'
    when 'job_started' then 'Neuer Job bei ' || coalesce(p_payload ->> 'company_name', '?')
    when 'streak' then coalesce(p_payload ->> 'days', '?') || ' Tage in Folge dabei'
    when 'league_won' then 'Wochenliga gewonnen'
    when 'friends_now' then 'Jetzt befreundet mit ' || coalesce(p_payload ->> 'other_nickname', '?')
    -- M4i (migration 0100): promotion {tier, company}
    when 'promoted' then 'Befördert bei ' || coalesce(p_payload ->> 'company', '?')
    -- M4j: deals
    when 'deal_signed' then 'Deal mit ' || coalesce(p_payload ->> 'with', '?') || ' per Handschlag'
    when 'deal_broken' then 'Deal mit ' || coalesce(p_payload ->> 'with', '?') || ' gebrochen'
    when 'loan_defaulted' then 'Kredit von ' || coalesce(p_payload ->> 'with', '?') || ' geplatzt'
    -- M5a: own cryptocurrencies {ticker, name}
    when 'coin_launched' then 'Kryptowährung ' || coalesce(p_payload ->> 'name', '?') || ' gestartet'
    when 'rug_pull' then 'Rug Pull bei ' || coalesce(p_payload ->> 'name', '?')
    when 'coin_closed' then coalesce(p_payload ->> 'name', 'Kryptowährung') || ' eingestellt'
    else 'Beitrag im Feed'
  end;
$$;

-- ---------------------------------------------------------------------------
-- N. Account reset/delete: the player's own coin is closed first (holders paid), then the crypto rows go
-- ---------------------------------------------------------------------------
create or replace function public.crypto_wipe_player(p_player uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
begin
  for r in select c.id from public.crypto_coins c
            where c.creator_id = p_player and c.status in ('draft', 'listed')
            order by c.id for update loop
    perform public.crypto_close_coin(r.id, p_key || ':coin:' || r.id::text, public.game_now(), false);
  end loop;
  delete from public.crypto_team_sales t using public.crypto_coins c where c.id = t.coin_id and c.creator_id = p_player;
  delete from public.crypto_coin_actions a using public.crypto_coins c where c.id = a.coin_id and c.creator_id = p_player;
  -- drafts that never traded disappear with their reserved security
  for r in select c.id, c.security_id from public.crypto_coins c
            where c.creator_id = p_player and c.launched_at is null and c.status = 'closed'
              and not exists (select 1 from public.trades t where t.security_id = c.security_id)
              and not exists (select 1 from public.positions p where p.security_id = c.security_id) loop
    delete from public.crypto_coins where id = r.id;
    delete from public.security_quotes where security_id = r.security_id;
    delete from public.securities where id = r.security_id;
  end loop;
  update public.crypto_coins set creator_id = null where creator_id = p_player;
end;
$$;
comment on function public.crypto_wipe_player(uuid, text) is
  'Internal (account_wipe): closes the player''s own coin like discontinue_coin (holders paid), deletes its actions and team sales; drafts disappear, closed coins stay without creator.';

create or replace function public.account_wipe(p_player uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nick    text;
  v_company uuid;
  v_state   uuid := public.ledger_system_account(case when public.money_genesis_done() then 'treasury' else 'mint' end);
  v_bal     bigint;
  r         record;
begin
  -- M5a: the own coin first (coin rows are locked before ledger accounts); its holders, the player included, are paid
  perform public.crypto_wipe_player(p_player, p_key);

  perform public.lock_player_accounts(p_player);
  select p.nickname into v_nick from public.profiles p where p.id = p_player for update;

  -- artworks (ADR-080): back to the gallery, auctions cancelled, reserved bids back to the cash
  perform public.artworks_wipe_player(p_player, p_key);

  -- deals (ADR-098): debts as a borrower are collected first, then the deals end
  perform public.deals_wipe_player(p_player, p_key);

  -- own company: open share offers are settled first, then it is dissolved like close_company
  select pc.company_id into v_company from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active';
  if v_company is not null then
    for r in select o.id from public.company_share_offers o where o.company_id = v_company and o.status = 'open' order by o.id loop
      perform public.close_share_offer(r.id);
    end loop;
    perform public.company_dissolve(v_company, 'closed');
  end if;

  -- subscriptions to other companies' open offers lapse (the money stays with the company)
  for r in select s.offer_id, sum(s.shares_e6)::bigint as q from public.offer_subscriptions s
            join public.company_share_offers o on o.id = s.offer_id and o.status = 'open'
           where s.player_id = p_player group by s.offer_id order by s.offer_id loop
    update public.company_share_offers set shares_subscribed_e6 = greatest(0, shares_subscribed_e6 - r.q) where id = r.offer_id;
  end loop;

  -- job: wages up to now, then ended without notice or fee
  for r in select pj.id, pj.company_id from public.player_jobs pj where pj.player_id = p_player and pj.status = 'active' order by pj.id loop
    perform public.accrue_job_salary(r.id);
    update public.player_jobs set status = 'ended', ended_at = now(), end_reason = 'quit', notice_ends_at = null where id = r.id;
    perform public.company_system_message(r.company_id, v_nick || ' hat das Unternehmen verlassen.');
  end loop;

  -- open orders release their reservations; holdings (stocks, bonds and coins) are given up
  for r in select o.id from public.orders o
            where o.player_id = p_player and o.status in ('pending', 'open', 'partially_filled') order by o.id loop
    perform public.cancel_order_internal(r.id);
  end loop;
  update public.positions
     set status = 'closed', closed_at = now(), quantity_e6 = 0, reserved_quantity_e6 = 0, cost_basis_cents = 0,
         margin_cents = 0, borrowed_cents = 0, liquidation_price_e4 = null
   where player_id = p_player and status = 'open';

  -- game state of the player (M4b: home, furniture and cars are given up without a refund)
  for r in select * from (values
             ('position_lots', 'player_id'), ('xp_events', 'player_id'), ('xp_daily_counters', 'player_id'),
             ('vault_claims', 'player_id'), ('daily_logins', 'player_id'), ('player_missions', 'player_id'),
             ('player_achievements', 'player_id'), ('player_cosmetics', 'player_id'), ('player_lifestyle_items', 'player_id'),
             ('player_random_events', 'player_id'), ('player_bankruptcies', 'player_id'), ('margin_events', 'player_id'),
             ('financing_charges', 'player_id'), ('player_tax_years', 'player_id'), ('distribution_payouts', 'player_id'),
             ('watchlist_items', 'player_id'), ('portfolio_snapshots', 'player_id'), ('stock_option_grants', 'player_id'),
             ('loans', 'player_id'), ('cap_table_entries', 'player_id'), ('share_lockups', 'player_id'),
             ('capital_injections', 'player_id'), ('takeover_offers', 'bidder_player_id'), ('angel_offers', 'investor_player_id'),
             ('ipo_subscriptions', 'player_id'), ('shareholder_vote_ballots', 'player_id'), ('reputation_events', 'player_id'),
             ('insider_violations', 'player_id'), ('salary_payouts', 'player_id'), ('work_tasks', 'player_id'),
             ('salary_negotiations', 'player_id'), ('player_work_tasks', 'player_id'), ('player_jobs', 'player_id'),
             ('job_offers', 'to_player_id'), ('job_applications', 'player_id'), ('player_skills', 'player_id'),
             ('player_skill_points', 'player_id'), ('daily_reward_claims', 'player_id'), ('player_loans', 'player_id'),
             ('offer_subscriptions', 'player_id'), ('notifications', 'player_id'), ('feed_items', 'actor_id'),
             ('league_entries', 'player_id'), ('league_entry_baselines', 'player_id'), ('company_logo_reports', 'reporter_id'),
             ('player_unlocks', 'player_id'), ('player_furniture', 'player_id'), ('player_cars', 'player_id'),
             ('player_homes', 'player_id'), ('trust_events', 'player_id')
           ) as t(tbl, col) loop
    execute format('delete from public.%I where %I = $1', r.tbl, r.col) using p_player;
  end loop;
  -- M4i (upgrades, migration 0100) when present
  if to_regclass('public.player_upgrades') is not null
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'player_upgrades' and column_name = 'player_id') then
    execute 'delete from public.player_upgrades where player_id = $1' using p_player;
  end if;
  delete from public.rich_list_snapshots where entity_kind = 'player' and entity_id = p_player;

  -- money back to the state: one balanced posting per account
  for r in select a.id from public.ledger_accounts a where a.owner_player_id = p_player and a.balance_cents > 0 order by a.id loop
    select a.balance_cents into v_bal from public.ledger_accounts a where a.id = r.id;
    perform public.ledger_transfer(r.id, v_state, v_bal, 'transfer', 'Konto zurückgesetzt', 'profile', p_player,
                                   p_key || ':' || r.id::text, p_player);
  end loop;

  update public.profiles
     set level = 1, xp_total = 0, reputation = 50, title_key = null, frame_key = null,
         bankrupt_until = null, founding_locked_until = null
   where id = p_player;
  update public.player_private
     set founding_ban_until = null, bankruptcy_count = 0, career_experience_minutes = 0, ipo_investment_limit_cents = null,
         tutorial_completed_at = null, tax_loss_pot_cents = 0
   where player_id = p_player;
end;
$$;
comment on function public.account_wipe(uuid, text) is 'Internal: cleanup shared by reset_account() and delete_account().';

-- ---------------------------------------------------------------------------
-- O. Jobs: market_tick() with the crypto tick, run_due_jobs() with the crypto job
-- ---------------------------------------------------------------------------
create or replace function public.market_tick()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := public.game_now();
  v_crypto jsonb;
begin
  if not pg_try_advisory_xact_lock(7311001) then
    return jsonb_build_object('skipped', 'busy');
  end if;
  if coalesce((select r.is_paused from public.sim_runtime r where r.id), false) then
    return public.market_tick_at(v_now);
  end if;
  -- coins first: the crypto tick locks coin rows before the stock tick books fills (same order as crypto_trade)
  v_crypto := public.crypto_tick_at(v_now, coalesce((select r.tick_seq from public.sim_runtime r where r.id), 0) + 1);
  return public.market_tick_at(v_now) || jsonb_build_object('crypto', v_crypto);
end;
$$;
comment on function public.market_tick() is
  'pg_cron every 5 seconds: one crypto tick (ADR-101) and one market tick at game_now(). Skips while paused or while another tick holds the lock.';

create or replace function public.run_due_jobs()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- cryptocurrencies (ADR-101) first: coin rows are locked before any ledger account (same order as trades)
  v_result := v_result || jsonb_build_object('crypto', public.crypto_run_due(v_now));

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- player companies: operating hours (ADR-072), then every closed quarter since their founding (ADR-057)
  v_result := v_result || jsonb_build_object('player_companies', public.player_companies_run_due());
  v_result := v_result || jsonb_build_object('company_events', public.company_events_run_due());
  -- deals between players (ADR-098): after the company hours, so supply contracts see both companies' hours
  v_result := v_result || jsonb_build_object('deals', public.deals_run_due());

  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- jobs: AI postings of the running quarter, wages of AI-company jobs in whole hours
  v_result := v_result || jsonb_build_object('quit_notices', public.process_quit_notices(null));
  v_result := v_result || jsonb_build_object('share_offers', public.close_due_offers(null));
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  -- artworks (ADR-080): due auctions are settled, the gallery starts the auctions of the day
  v_result := v_result || jsonb_build_object('artworks', public.artworks_run_due());

  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- weekly league and feed upkeep (M4f, ADR-088/089) and announced events (M4g, ADR-090): kept in this redefinition
  v_result := v_result || jsonb_build_object('social', public.social_run_due());
  v_result := v_result || jsonb_build_object('events', public.events_run_due());

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  return v_result;
end;
$$;

